function Shell({ children }) {
  return (
    <div className="min-h-screen bg-zinc-950 text-zinc-100">
      <style>{`
        @keyframes pop { 0%{transform:scale(.7);opacity:0} 60%{transform:scale(1.05)} 100%{transform:scale(1);opacity:1} }
        .anim-pop { animation: pop .28s ease-out both }
        @keyframes bigpop { 0%{transform:scale(.4);opacity:0} 55%{transform:scale(1.08)} 100%{transform:scale(1);opacity:1} }
        .anim-bigpop { animation: bigpop .45s cubic-bezier(.2,.9,.3,1.2) both }
        @media (prefers-reduced-motion: reduce) { .anim-pop,.anim-bigpop { animation: none } }
      `}</style>
      <div className="max-w-md mx-auto relative">{children}</div>
    </div>
  );
}

/* ───────────────────────── Onboarding (click-driven) ───────────────────────── */

/* One chip row, one choice. Module level so that typing in a neighbouring input does not remount it. */
function OptRow({ label, opts, val, set, getK = (o) => o.k, getT = (o) => o.t }) {
  return (
    <div>
      <div className="text-xs font-bold tracking-widest text-zinc-500 mb-1.5">{label}</div>
      <div className="flex flex-wrap gap-1.5">
        {opts.map((o) => (
          <Chip key={getK(o)} on={val === getK(o)} onClick={() => set(getK(o))}>{getT(o)}</Chip>
        ))}
      </div>
    </div>
  );
}

/* ── CV records (education, career) ──
   One entry row and one add form serve onboarding and the profile screen, so the fields, the order and the
   validation messages cannot drift apart. `kind` is "edu" or "career". Nothing here computes a grade. */
function CvEntryRow({ entry, kind, onRemove }) {
  const edu = kind === "edu";
  const head = edu ? entry.school : entry.company;
  const sub = edu
    ? [EDU_LEVELS.find((l) => l.k === entry.degree)?.t, EDU_STATUS.find((s) => s.k === entry.status)?.t, entry.major, entry.field]
    : [EMP_KINDS.find((e) => e.k === entry.emp)?.t, entry.role];
  // A career entry with no end month is still running; an education entry simply prints what it has.
  const span = [entry.from, edu ? entry.to : entry.to || "재직 중"].filter(Boolean).join(" ~ ");
  return (
    <div className="flex items-start gap-2 bg-zinc-950 border border-zinc-800 rounded-xl px-3 py-2">
      <div className="min-w-0 flex-1">
        <div className="text-sm font-semibold truncate">{head}</div>
        <div className="text-xs text-zinc-500">{sub.filter(Boolean).join(" · ")}</div>
        {span && <div className="text-xs text-zinc-600 font-mono">{span}</div>}
      </div>
      <button onClick={onRemove} className="text-zinc-600 p-1"><X size={13} /></button>
    </div>
  );
}

function CvAddForm({ kind, onAdd }) {
  const edu = kind === "edu";
  const [main, setMain] = useState("");      // school | company
  const [sub, setSub] = useState("");        // major | role
  const [lvl, setLvl] = useState(null);      // degree | employment kind
  const [stat, setStat] = useState(null);    // education status
  const [field, setField] = useState(null);  // MAJOR_FIELDS, education only
  const [from, setFrom] = useState("");
  const [to, setTo] = useState("");
  const [current, setCurrent] = useState(false); // still employed — an entry with no end month
  const [err, setErr] = useState("");

  const submit = () => {
    const a = main.trim(), b = sub.trim();
    if (edu) {
      if (!a) { setErr("학교 이름을 입력해 주세요."); return; }
      if (!lvl || !stat) { setErr("학위와 상태를 선택해 주세요."); return; }
      if (from && to && monthsBetween(from, to) < 0) { setErr("졸업 연월이 입학 연월보다 앞서요."); return; }
      onAdd({ id: uid(), school: a, degree: lvl, status: stat, ...(b ? { major: b } : {}), ...(field ? { field } : {}), ...(from ? { from } : {}), ...(to ? { to } : {}) });
    } else {
      if (!a || !b) { setErr("회사 이름과 직책을 입력해 주세요."); return; }
      if (!lvl) { setErr("고용 형태를 선택해 주세요."); return; }
      if (!from) { setErr("입사 연월을 입력해 주세요."); return; }
      if (!current && to && monthsBetween(from, to) < 0) { setErr("퇴사 연월이 입사 연월보다 앞서요."); return; }
      onAdd({ id: uid(), company: a, role: b, emp: lvl, from, ...(current || !to ? {} : { to }) });
    }
    setMain(""); setSub(""); setLvl(null); setStat(null); setField(null); setFrom(""); setTo(""); setCurrent(false); setErr("");
  };

  return (
    <div className="bg-zinc-950 border border-zinc-800 rounded-xl p-3 space-y-2">
      <input value={main} onChange={(e) => setMain(e.target.value)}
        placeholder={edu ? "학교 이름 — 예: 한국대학교" : "회사·조직 이름 — 예: 한국부품"}
        className="w-full bg-zinc-900 border border-zinc-700 rounded-lg px-2.5 py-2 text-sm outline-none focus:border-cyan-500" />
      <input value={sub} onChange={(e) => setSub(e.target.value)}
        placeholder={edu ? "전공·학과 (선택) — 예: 기계공학" : "직책·직무 — 예: 설계 엔지니어"}
        className="w-full bg-zinc-900 border border-zinc-700 rounded-lg px-2.5 py-2 text-sm outline-none focus:border-cyan-500" />
      <OptRow label={edu ? "학위" : "고용 형태"} opts={edu ? EDU_LEVELS : EMP_KINDS} val={lvl} set={setLvl} />
      {edu && <OptRow label="상태" opts={EDU_STATUS} val={stat} set={setStat} />}
      {edu && <OptRow label="계열 (선택)" opts={MAJOR_FIELDS} val={field} set={setField} getK={(o) => o} getT={(o) => o} />}
      {!edu && (
        <Chip on={current} onClick={() => { setCurrent((c) => !c); setTo(""); }}>재직 중</Chip>
      )}
      <div className="flex items-center gap-2">
        <input type="month" value={from} onChange={(e) => setFrom(e.target.value)}
          className="flex-1 w-0 bg-zinc-900 border border-zinc-700 rounded-lg px-2.5 py-2 text-sm font-mono" />
        <span className="text-xs text-zinc-500">~</span>
        <input type="month" value={to} onChange={(e) => setTo(e.target.value)} disabled={!edu && current}
          className="flex-1 w-0 bg-zinc-900 border border-zinc-700 rounded-lg px-2.5 py-2 text-sm font-mono disabled:opacity-30" />
      </div>
      {err && <div className="text-xs text-rose-400">{err}</div>}
      <button onClick={submit} className="w-full py-2 rounded-lg bg-zinc-800 text-zinc-200 text-xs font-bold">
        {edu ? "학력 추가" : "경력 추가"}
      </button>
    </div>
  );
}

function CvSection({ kind, label, note, entries, onChange }) {
  return (
    <div>
      <div className="text-xs font-bold tracking-widest text-zinc-500 mb-1.5">{label}</div>
      <div className="space-y-1.5">
        {entries.map((e) => (
          <CvEntryRow key={e.id} entry={e} kind={kind} onRemove={() => onChange(entries.filter((x) => x.id !== e.id))} />
        ))}
        {entries.length === 0 && <p className="text-xs text-zinc-600">{note}</p>}
        <CvAddForm kind={kind} onAdd={(e) => onChange([...entries, e])} />
      </div>
    </div>
  );
}

function Onboarding({ onStart, onDemo }) {
  const [step, setStep] = useState("title");
  const [err, setErr] = useState("");
  // Basic info
  const [name, setName] = useState("");
  const [nick, setNick] = useState("");
  const [birth, setBirth] = useState("");
  const [gender, setGender] = useState(null);
  const [status, setStatus] = useState(null);
  const [edus, setEdus] = useState([]);
  // Appearance
  const [look, setLook] = useState({ skin: 0, hair: 0, hairColor: 0, outfit: 0, face: 1 });
  const setL = (k, v) => setLook((s) => ({ ...s, [k]: v }));
  const randomLook = () => setLook({
    skin: Math.floor(Math.random() * SKINS.length),
    hair: Math.floor(Math.random() * HAIR_STYLES.length),
    hairColor: Math.floor(Math.random() * HAIR_COLORS.length),
    outfit: Math.floor(Math.random() * OUTFITS.length),
    face: Math.floor(Math.random() * FACES.length),
  });
  // Areas + directions
  const [selected, setSelected] = useState(["사업", "직업·커리어", "기본지식"]);
  const [customs, setCustoms] = useState([]);
  const [customInput, setCustomInput] = useState("");
  const [directions, setDirections] = useState([]);
  // Held certifications
  const [certSel, setCertSel] = useState([]);
  const [examOwnFam, setExamOwnFam] = useState(null);
  const [examsOwned, setExamsOwned] = useState([]);
  const [cat, setCat] = useState("전체");
  const [gradeF, setGradeF] = useState("전체");
  const [query, setQuery] = useState("");
  // Experience
  const [careers, setCareers] = useState([]);
  const [lead, setLead] = useState(null);
  const [biz, setBiz] = useState(null);
  const [output, setOutput] = useState(null);

  const areaNames = [...AREA_PRESETS.filter((p) => selected.includes(p)), ...customs];
  const hasJob = areaNames.includes("직업·커리어");
  const hasBiz = areaNames.includes("사업");

  const togglePreset = (name) =>
    setSelected((s) => (s.includes(name) ? s.filter((x) => x !== name) : [...s, name]));
  const addCustom = () => {
    const n = customInput.trim();
    if (!n) return;
    if (!customs.includes(n) && !AREA_PRESETS.includes(n)) setCustoms((c) => [...c, n]);
    setCustomInput("");
  };
  const toggleCert = (n) =>
    setCertSel((s) => (s.includes(n) ? s.filter((x) => x !== n) : [...s, n]));
  const toggleDir = (d) =>
    setDirections((s) => (s.includes(d) ? s.filter((x) => x !== d) : s.length < 3 ? [...s, d] : s));

  const certSetSel = useMemo(() => new Set(certSel), [certSel]);
  const filtered = useMemo(() => {
    const kw = query.trim();
    return CERTS.filter((c) =>
      (cat === "전체" || c.c === cat) &&
      (gradeF === "전체" || achGrade(c.d) === gradeF) &&
      (!kw || c.n.includes(kw))
    );
  }, [cat, gradeF, query]);
  // Render at most 60 rows (never mount all 1,011). Already-selected certs are pinned first so they cannot be pushed past the cap and become un-deselectable.
  const shown = useMemo(() => {
    const picked = filtered.filter((c) => certSetSel.has(c.n));
    const rest = filtered.filter((c) => !certSetSel.has(c.n));
    return [...picked, ...rest].slice(0, 60);
  }, [filtered, certSetSel]);

  // The one and only call site of eduKeyOf / careerKeyOf: the keys are a snapshot of the CV as it stands when
  // the app starts, and the grades they produce are never recomputed afterwards (rules 4, 11).
  const profile = {
    name: name.trim(), nick: nick.trim(), birth, gender, status, email: "", phone: "",
    edus, careers, directions, look, examsOwned, certs: certSel,
    edu: eduKeyOf(edus), career: careerKeyOf(careers, dstr()),
    lead: lead ?? "no", biz: biz ?? "none", output: output ?? "none",
  };
  const results = computeGrades(profile, areaNames);
  const eduLabel = EDU_OPTS.find((e) => e.k === profile.edu)?.t;
  const careerLabel = CAREER_OPTS.find((c) => c.k === profile.career)?.t;

  const next = () => {
    setErr("");
    if (step === 0) {
      if (!name.trim()) { setErr("이름을 입력해 주세요."); return; }
      if (!birth) { setErr("생년월일을 입력해 주세요."); return; }
      if (!/^\d{4}-\d{2}-\d{2}$/.test(birth)) { setErr("생년월일 형식이 올바르지 않아요 — YYYY-MM-DD로 입력해요."); return; }
      if (birth > dstr()) { setErr("생년월일이 오늘보다 뒤예요."); return; }
      if (!gender || !status) { setErr("성별과 현재 신분을 선택해 주세요."); return; }
      if (edus.length === 0) { setErr("학력을 1개 이상 추가해 주세요."); return; }
    }
    if (step === 2) {
      if (areaNames.length === 0) { setErr("영역을 하나 이상 선택해 주세요."); return; }
      if (areaNames.includes("기본지식") && directions.length === 0) { setErr("기본지식이 향할 방향을 1개 이상 선택해 주세요."); return; }
    }
    if (step === 4) {
      if (hasJob && !lead) { setErr("리드 경험을 선택해 주세요."); return; }
      if (hasBiz && !biz) { setErr("사업 경험을 선택해 주세요."); return; }
      if (!output) { setErr("산출물 항목을 선택해 주세요."); return; }
    }
    setStep((s) => s + 1);
  };

  const start = () => {
    const finalized = results.map((r) => {
      const ach = [];
      if (r.grade > 0) ach.push({ id: uid(), text: `초기 산정 — ${r.why}`, date: dstr(), grade: r.grade });
      if (r.name === "기본지식" && certSel.length > 0)
        ach.push({ id: uid(), text: `보유 자격: ${certSel.join(", ")}`, date: dstr(), grade: r.grade });
      if (r.name === "어학" && examsOwned.length > 0)
        ach.push({ id: uid(), text: `보유 성적: ${examsOwned.map((o) => `${o.famN} ${o.label}`).join(", ")}`, date: dstr(), grade: r.grade });
      const area = { id: uid(), name: r.name, grade: r.grade, achievements: ach };
      if (r.name === "기본지식") area.dir = directions;
      return area;
    });
    /* Exam state prefill — decay locked in registration order, specialisation verdict */
    const ex = { best: {}, dim: {}, spec: {}, policy: POINT_POLICY_VERSION };
    for (const o of examsOwned) {
      const fam = examOf(o.famId);
      if (!fam) continue;
      const r = calcExamPayout(ex, fam, { label: o.label, d: o.d, p: o.p });
      ex.dim[fam.id] = r.mult;
      ex.best[fam.id] = { label: o.label, d: o.d, p: o.p, ver: POINT_POLICY_VERSION, date: dstr() };
    }
    for (const lang of ["English", "Japanese", "Chinese"]) {
      const highs = Object.entries(ex.best).filter(([id2, b]) => {
        const e2 = examOf(id2);
        return e2 && e2.lang === lang && b.d >= 75;
      });
      if (highs.length >= 2) {
        ex.spec[lang] = true;
        const lp = finalized.find((x) => x.name === "어학");
        if (lp && lp.grade < 5) {
          lp.grade = 5;
          lp.achievements.push({ id: uid(), text: `🎖 ${LANG_KO[lang]} 전문화 — 고난도 시험(D75+) 2종 보유`, date: dstr(), grade: 5 });
        }
      }
    }
    /* Stage-group certification best-record prefill */
    const cb = {};
    for (const nm of certSel) {
      const c = certOf(nm);
      if (c?.sg) {
        const p = certP(c.d);
        if (!cb[c.sg] || p > cb[c.sg].p) cb[c.sg] = { p, name: c.n, d: c.d };
      }
    }
    onStart({ areas: finalized, profile: { ...profile, startDate: dstr() }, exams: ex, certBest: cb });
  };

  const Swatch = ({ label, colors, val, set }) => (
    <div>
      <div className="text-xs font-bold tracking-widest text-zinc-500 mb-1.5">{label}</div>
      <div className="flex gap-2 flex-wrap">
        {colors.map((c, i) => (
          <button key={c} onClick={() => set(i)}
            className={`w-7 h-7 rounded-full border-2 transition-transform ${val === i ? "border-cyan-400 scale-110" : "border-zinc-700"}`}
            style={{ backgroundColor: c }} />
        ))}
      </div>
    </div>
  );

  return (
    <div className="px-5 py-8 pb-16">
      <div className="text-xs tracking-widest text-zinc-500 font-mono">PROFILE SETUP</div>
      {step === "title" && <h1 className="text-3xl font-black mt-1 mb-1">인생 <span className="text-cyan-400">관리</span></h1>}

      {step === "title" && (
        <div className="pt-4 pb-6 text-center space-y-6">
          <div className="w-full bg-zinc-950 rounded-2xl py-4 flex justify-center">
            <OnboardingHeroSvg />
          </div>
          <p className="text-sm text-zinc-400">지금 위치를 숫자로 확인하세요. 평가는 시장 기준입니다.</p>
          <button onClick={() => setStep(0)}
            className="w-full py-4 rounded-2xl bg-amber-400 text-zinc-950 font-black text-base border-b-4 border-amber-600 active:border-b-0 active:translate-y-1 transition-all">
            시작하기
          </button>
          <button onClick={onDemo} className="w-full py-2 text-xs text-zinc-500 underline underline-offset-2">
            먼저 화면만 볼래요 — 데모 데이터로 둘러보기
          </button>
        </div>
      )}

      {step !== "title" && (
        <div className="flex gap-1 mb-5">
          {[0, 1, 2, 3, 4, 5].map((i) => (
            <div key={i} className={`h-1 flex-1 rounded-full ${i <= step ? "bg-cyan-400" : "bg-zinc-800"}`} />
          ))}
        </div>
      )}

      {step === 0 && (
        <div className="space-y-4">
          <div>
            <span className="font-mono text-xs font-bold text-cyan-400">1 / 6</span><span className="text-lg font-black ml-1.5">기본 정보</span>
            <p className="text-xs text-zinc-400 mt-1">입력한 학력·경력으로 시작 등급이 산정돼요.</p>
          </div>
          <input value={name} onChange={(e) => setName(e.target.value)}
            placeholder="이름"
            className="w-full bg-zinc-900 border border-zinc-800 rounded-xl px-3 py-2.5 text-sm outline-none focus:border-cyan-500" />
          <input value={nick} onChange={(e) => setNick(e.target.value)}
            placeholder="닉네임 (선택)"
            className="w-full bg-zinc-900 border border-zinc-800 rounded-xl px-3 py-2.5 text-sm outline-none focus:border-cyan-500" />
          <div>
            <div className="text-xs font-bold tracking-widest text-zinc-500 mb-1.5">생년월일</div>
            <input type="date" value={birth} onChange={(e) => setBirth(e.target.value)}
              className="w-full bg-zinc-900 border border-zinc-800 rounded-xl px-3 py-2.5 text-sm font-mono outline-none focus:border-cyan-500" />
          </div>
          <OptRow label="성별" opts={["남성", "여성", "선택 안 함"]} val={gender} set={setGender} getK={(o) => o} getT={(o) => o} />
          <OptRow label="현재 신분" opts={STATUS_OPTS} val={status} set={setStatus} getK={(o) => o} getT={(o) => o} />
          <CvSection kind="edu" label="학력" entries={edus} onChange={setEdus}
            note="학력을 1개 이상 추가해요. 최종 학력이 기본지식 시작 등급의 근거가 돼요." />
        </div>
      )}

      {step === 1 && (
        <div className="space-y-4">
          <div><span className="font-mono text-xs font-bold text-cyan-400">2 / 6</span><span className="text-lg font-black ml-1.5">프로필 외형</span></div>
          <div className="bg-zinc-900 border border-zinc-800 rounded-2xl p-4 flex items-center gap-4">
            <div className="rounded-2xl overflow-hidden bg-zinc-950 border border-zinc-800 shrink-0">
              <PortraitSprite look={look} gender={gender} size={84} />
            </div>
            <div className="flex flex-col gap-2 min-w-0 flex-1">
              <div className="font-bold text-sm truncate">{displayName({ nick, name })}</div>
              <button onClick={randomLook}
                className="px-3 py-2 rounded-xl bg-zinc-800 text-zinc-300 text-xs font-medium self-start">무작위</button>
            </div>
          </div>
          <p className="text-xs text-zinc-600">사진은 시작한 뒤 프로필 탭의 프로필 편집에서 등록해요.</p>
          <Swatch label="피부" colors={SKINS} val={look.skin} set={(v) => setL("skin", v)} />
          <Swatch label="머리색" colors={HAIR_COLORS} val={look.hairColor} set={(v) => setL("hairColor", v)} />
          <Swatch label="옷 색상" colors={OUTFITS} val={look.outfit} set={(v) => setL("outfit", v)} />
          <OptRow label="헤어스타일" opts={HAIR_STYLES} val={HAIR_STYLES[look.hair]} set={(v) => setL("hair", HAIR_STYLES.indexOf(v))} getK={(o) => o} getT={(o) => o} />
          <OptRow label="표정" opts={FACES} val={FACES[look.face]} set={(v) => setL("face", FACES.indexOf(v))} getK={(o) => o} getT={(o) => o} />
        </div>
      )}

      {step === 2 && (
        <div className="space-y-4">
          <div><span className="font-mono text-xs font-bold text-cyan-400">3 / 6</span><span className="text-lg font-black ml-1.5">성장시킬 영역</span></div>
          <div className="flex flex-wrap gap-1.5">
            {AREA_PRESETS.map((p) => (
              <Chip key={p} on={selected.includes(p)} onClick={() => togglePreset(p)}>{p}</Chip>
            ))}
            {customs.map((c) => (
              <Chip key={c} on onClick={() => setCustoms((s) => s.filter((x) => x !== c))}>{c} ✕</Chip>
            ))}
          </div>
          <div className="flex gap-2">
            <input value={customInput} onChange={(e) => setCustomInput(e.target.value)}
              placeholder="직접 추가 (선택)"
              className="flex-1 bg-zinc-900 border border-zinc-800 rounded-xl px-3 py-2 text-xs outline-none focus:border-cyan-500" />
            <button onClick={addCustom} className="px-3 rounded-xl border border-zinc-700 text-zinc-400"><Plus size={15} /></button>
          </div>
          <p className="text-xs text-zinc-600">직접 추가한 영역은 측정 항목이 없어 지망생부터 시작해요.</p>
          {selected.includes("기본지식") && (
            <div className="bg-zinc-900 border border-zinc-800 rounded-2xl p-4">
              <div className="text-xs text-zinc-400 mb-1 font-semibold">기본지식이 향할 방향 <span className="text-cyan-400">(1~3개)</span></div>
              <p className="text-xs text-zinc-600 mb-2">지금 업무와 무관해도 돼요. 앞으로 나아갈 분야를 고르면 추천과 성장 방향이 여기에 맞춰집니다.</p>
              <div className="flex flex-wrap gap-1.5">
                {KNOWLEDGE_FIELDS.map((d) => (
                  <Chip key={d} on={directions.includes(d)} onClick={() => toggleDir(d)}>{d}</Chip>
                ))}
              </div>
            </div>
          )}
        </div>
      )}

      {step === 3 && (
        <div className="space-y-3">
          <div><span className="font-mono text-xs font-bold text-cyan-400">4 / 6</span><span className="text-lg font-black ml-1.5">보유 자격·어학</span> <span className="text-xs text-zinc-500">({certSel.length}개 선택)</span></div>
          <div className="flex gap-1.5 overflow-x-auto pb-1.5 -mx-1 px-1">
            {["전체", ...CERT_CATS].map((c) => (
              <button key={c} onClick={() => setCat(c)}
                className={`shrink-0 px-2.5 py-1.5 rounded-lg text-xs font-semibold border ${
                  cat === c ? "bg-zinc-100 text-zinc-950 border-zinc-200" : "bg-zinc-950 text-zinc-500 border-zinc-800"}`}>
                {c}
              </button>
            ))}
          </div>
          <div className="flex gap-1.5">
            {["전체", "A", "B", "C", "D", "E"].map((g) => (
              <button key={g} onClick={() => setGradeF(g)}
                className={`flex-1 py-1.5 rounded-lg text-xs font-mono font-bold border ${
                  gradeF === g ? "bg-zinc-100 text-zinc-950 border-zinc-200" : `bg-zinc-950 border-zinc-800 ${g === "전체" ? "text-zinc-500" : GRADE_TEXT[g]}`}`}>
                {g}
              </button>
            ))}
          </div>
          <input value={query} onChange={(e) => setQuery(e.target.value)}
            placeholder="자격증 검색"
            className="w-full bg-zinc-950 border border-zinc-800 rounded-xl px-3 py-2 text-xs outline-none focus:border-cyan-500" />
          <div className="max-h-56 overflow-y-auto space-y-1 pr-1">
            {shown.map((c) => {
              const on = certSetSel.has(c.n);
              return (
              <button key={c.n} onClick={() => toggleCert(c.n)}
                className={`w-full px-3 py-2 rounded-lg text-xs border text-left flex items-center gap-2 ${
                  on ? "bg-cyan-500 text-zinc-950 border-cyan-400" : "bg-zinc-950 text-zinc-300 border-zinc-800"}`}>
                <span className={`font-mono font-bold w-3 ${on ? "" : GRADE_TEXT[achGrade(c.d)]}`}>{achGrade(c.d)}</span>
                <span className="flex-1 truncate font-semibold">{c.n}</span>
                <span className={`text-xs ${on ? "text-zinc-800" : "text-zinc-600"}`}>{c.l}</span>
                {on && <Check size={13} strokeWidth={3} />}
              </button>
              );
            })}
            {shown.length === 0 && <div className="text-xs text-zinc-600 py-3 text-center">검색 결과 없음</div>}
            {filtered.length > shown.length && (
              <div className="text-xs text-zinc-600 py-2 text-center">{filtered.length - shown.length}종 더 있음 — 검색어로 좁혀요</div>
            )}
          </div>
          <p className="text-xs text-zinc-600">없으면 그냥 다음으로. 취득 예정인 건 나중에 자격증 실행으로 등록해요.</p>
          <div className="bg-zinc-900 border border-zinc-800 rounded-2xl p-3">
            <div className="text-xs text-zinc-400 font-semibold mb-1.5">보유 시험 성적 <span className="text-cyan-400">({examsOwned.length})</span></div>
            <div className="flex gap-1.5 overflow-x-auto pb-1.5 -mx-1 px-1">
              {EXAMS.map((e) => (
                <button key={e.id} onClick={() => setExamOwnFam(examOwnFam?.id === e.id ? null : e)}
                  className={`shrink-0 px-2.5 py-1.5 rounded-lg text-xs font-semibold border ${
                    examOwnFam?.id === e.id ? "bg-zinc-100 text-zinc-950 border-zinc-200" : "bg-zinc-950 text-zinc-500 border-zinc-800"}`}>
                  {e.n}
                </button>
              ))}
            </div>
            {examOwnFam && (
              <div className="flex flex-wrap gap-1.5 mt-1">
                {examOwnFam.bands.map(([label, d, p]) => (
                  <Chip key={label} on={examsOwned.some((o) => o.famId === examOwnFam.id && o.label === label)}
                    onClick={() => setExamsOwned((prev) => [...prev.filter((o) => o.famId !== examOwnFam.id), { famId: examOwnFam.id, famN: examOwnFam.n, label, d, p }])}>
                    {label}
                  </Chip>
                ))}
              </div>
            )}
            {examsOwned.length > 0 && (
              <div className="space-y-1 mt-2">
                {examsOwned.map((o) => (
                  <div key={o.famId} className="flex items-center justify-between text-xs bg-zinc-950 rounded-lg px-2.5 py-1.5">
                    <span className="text-zinc-300">{o.famN} <b className="text-cyan-300">{o.label}</b> <span className="text-zinc-600">D{o.d}</span></span>
                    <button onClick={() => setExamsOwned((p) => p.filter((x) => x.famId !== o.famId))} className="text-zinc-600"><X size={12} /></button>
                  </div>
                ))}
              </div>
            )}
            <p className="text-xs text-zinc-600 mt-1.5">여기 등록한 성적은 시작 기록으로 저장되고, 이후 상향 시 차액만 지급돼요.</p>
          </div>
        </div>
      )}

      {step === 4 && (
        <div className="space-y-4">
          <div>
            <span className="font-mono text-xs font-bold text-cyan-400">5 / 6</span><span className="text-lg font-black ml-1.5">경력·경험</span>
            <p className="text-xs text-zinc-400 mt-1">정직하게, 상향 없이.</p>
          </div>
          <CvSection kind="career" label="경력" entries={careers} onChange={setCareers}
            note="경력이 없으면 비워 둬요. 직업·커리어 시작 등급은 경력 없음 기준이에요." />
          <p className="text-xs text-zinc-500">합산 실무 {careerText(careerMonths(careers, dstr()))} · 시작 등급 기준 {careerLabel}</p>
          {hasJob && <OptRow label="리드 경험" opts={LEAD_OPTS} val={lead} set={setLead} />}
          {hasBiz && <OptRow label="사업 경험" opts={BIZ_OPTS} val={biz} set={setBiz} />}
          <OptRow label="산출물·포트폴리오" opts={OUTPUT_OPTS} val={output} set={setOutput} />
        </div>
      )}

      {step === 5 && (
        <div className="space-y-3">
          <div><span className="font-mono text-xs font-bold text-cyan-400">6 / 6</span><span className="text-lg font-black ml-1.5">설정 완료</span></div>
          <div className="bg-zinc-900 border-2 border-cyan-500 border-opacity-30 rounded-2xl p-4 flex items-center gap-3">
            <div className="rounded-xl overflow-hidden bg-zinc-950 border border-zinc-700 shrink-0">
              <PortraitSprite look={look} gender={gender} size={60} />
            </div>
            <div className="min-w-0">
              <div className="font-black text-base truncate">{displayName({ nick, name })}</div>
              <div className="text-xs text-zinc-500">{ageText({ birth }, dstr())} · {status}{directions.length ? ` · ${directions.join("·")}` : ""}</div>
            </div>
          </div>
          <p className="text-xs text-zinc-500">학력 {eduLabel} · 경력 {careerLabel}</p>
          {results.map((r) => (
            <div key={r.name} className="bg-zinc-900 border border-zinc-800 rounded-2xl p-4">
              <div className="flex items-center justify-between mb-1.5">
                <div className="font-bold text-sm">{r.name}{r.name === "기본지식" && directions.length ? <span className="text-zinc-500 font-normal"> · {directions.join("·")}</span> : null}</div>
                <div className="text-cyan-300 font-black">{RANKS[r.grade].name}</div>
              </div>
              <Bar ratio={r.grade / (RANKS.length - 1)} color="bg-cyan-400" />
              <div className="text-xs text-zinc-500 mt-2">근거: {r.why}</div>
            </div>
          ))}
          <p className="text-xs text-zinc-600">선택지 조합으로 자동 산정된 시작점이에요. 이후 승급은 오직 관문 통과로만 가능합니다.</p>
        </div>
      )}

      {err && <div className="text-xs text-rose-400 mt-3">{err}</div>}

      {step !== "title" && (
        <div className="flex gap-2 mt-5">
          {step > 0 && (
            <button onClick={() => { setErr(""); setStep((s) => s - 1); }}
              className="flex-1 py-3 rounded-xl bg-zinc-800 text-zinc-300 font-bold text-sm">이전</button>
          )}
          {step < 5 ? (
            <button onClick={next} className="flex-1 py-3.5 rounded-xl bg-cyan-400 text-zinc-950 font-bold text-sm active:opacity-80 transition-all">다음</button>
          ) : (
            <button onClick={start} className="flex-1 py-3 rounded-xl bg-amber-400 text-zinc-950 font-black text-sm border-b-4 border-amber-600 active:border-b-0 active:translate-y-1 transition-all">이 설정으로 시작</button>
          )}
        </div>
      )}
    </div>
  );
}

/* ───────────────────────── Home — the CV ───────────────────────── */
/* Home is one CV that evaluates the account in numbers and grades, with the role-model proximity line under it
   (2026-09-15). A row is admitted when its value is a number, a grade or an ordinal credential level; a name
   appears only as the label of such a value. The `자격` and `시험` rows print a count and then names (an exam with its
   exact recorded score, or its band label for a record from before v22 — `examBestText`) without their D figures (2026-09-16): they stay sorted highest D first, and the D that explains a
   payout is on the wall sheet. Everything is derived at render and stored nowhere (rule 9), and a
   zero is stated, never hidden (rule 13). Today's cards left home: the briefing opens from the `할 일` header, goal
   progress and pace live in `목표`, today's tasks are the `할 일` list. The tab is labelled `프로필` (2026-09-16);
   its internal key stays `home`. */

// Label/value row shared by the CV and the detail sheets: a fixed-width label and a one-line value (`wrap` lets a
// long value break over lines instead of truncating). A button only when the row opens something.
// `wide` widens the label column for a five-syllable label (`단계 변경일`), which wraps in the default w-16 at 390 px.
function CvFact({ label, children, onClick, wrap = false, wide = false }) {
  const cls = "flex items-baseline gap-2 text-xs w-full text-left";
  const body = (
    <>
      <span className={`${wide ? "w-20" : "w-16"} shrink-0 text-zinc-500`}>{label}</span>
      <span className={`min-w-0 flex-1 ${wrap ? "break-words" : "truncate"} text-zinc-300`}>{children}</span>
    </>
  );
  return onClick
    ? <button onClick={onClick} className={`${cls} active:opacity-70`}>{body}</button>
    : <div className={cls}>{body}</div>;
}

/* One area as one row, moved from the growth tab: grade box, name, rank and next gate, `{grade}/9`. The row's only
   behaviour is opening `PromoteModal` — nothing else on home promotes, so submitting gate evidence stays the single
   path up (rules 10, 11). */
function AreaGradeRow({ area: p, onPromote }) {
  const cur = RANKS[p.grade];
  const next = RANKS[p.grade + 1];
  const body = (
    <>
      <span className="w-7 h-7 shrink-0 rounded-lg border border-zinc-700 bg-zinc-900 flex items-center justify-center font-mono font-bold text-xs text-cyan-300">{p.grade}</span>
      <div className="flex-1 min-w-0">
        <div className="text-sm font-semibold truncate">{p.name}</div>
        <div className="text-xs text-zinc-500 truncate">{next ? `등급 ${cur.name} · 다음 관문 ${next.name}` : "정점 도달"}</div>
      </div>
      <span className="text-xs font-mono text-zinc-600 shrink-0">{p.grade}/9</span>
    </>
  );
  // Grade 9: `PromoteModal` returns null, so the row is not a button and nothing can be tapped.
  if (!next) return (
    <div className="w-full text-left flex items-center gap-2.5 bg-zinc-950 rounded-xl px-3 py-2.5">
      {body}<Trophy size={13} className="text-amber-300 shrink-0" />
    </div>
  );
  return (
    <button onClick={() => onPromote(p)}
      className="w-full text-left flex items-center gap-2.5 bg-zinc-950 rounded-xl px-3 py-2.5 active:opacity-70">
      {body}<Lock size={13} className="text-zinc-500 shrink-0" /><span className="text-zinc-600 shrink-0">›</span>
    </button>
  );
}

function HomeTab({ state, today, imgs, onProfile, onSettings, onPromote, onRoleAdvice, onWall, onReader }) {
  const cv = cvSummaryOf(state.profile, today);
  const held = heldCertsOf(state);
  const bests = Object.entries(state.exams?.best || {})
    .sort(([ia, a], [ib, b]) => (b?.d ?? -1) - (a?.d ?? -1) || ia.localeCompare(ib));
  const trophies = (state.room?.trophies || []).length;
  const achTotal = (state.areas || []).reduce((n, p) => n + (p.achievements || []).length, 0);
  const rg = roleGap(state);
  const sp = stageProgressOf(state, today);
  const last = lastVerdictOf(state);
  return (
    <>
      <section className="bg-zinc-900 border border-zinc-800 rounded-2xl p-4 space-y-3">
        <div className="flex items-start gap-3">
          <div className="rounded-2xl overflow-hidden bg-zinc-950 border border-zinc-700 shrink-0">
            <Portrait img={imgs?.profile} look={state.profile.look} gender={state.profile.gender} size={64} />
          </div>
          <div className="flex-1 min-w-0">
            <div className="font-black text-base truncate">{displayName(state.profile)}</div>
            <div className="text-xs text-zinc-500 mt-0.5 truncate">{ageText(state.profile, today)}</div>
            {/* The one edit control on the CV. The photo, the personal facts and the records are all edited in the
                screen this opens, so the card only states facts and points at the screen that owns them. */}
            <button onClick={onProfile}
              className="bg-zinc-800 text-zinc-300 rounded-lg px-2.5 py-1.5 text-xs font-medium mt-2">프로필 편집</button>
            {/* The daily reader, any time — it also opens by itself once a day */}
            <button onClick={onReader}
              className="bg-zinc-800 text-zinc-300 rounded-lg px-2.5 py-1.5 text-xs font-medium mt-2 ml-1.5">오늘 읽을 것 ›</button>
          </div>
          {/* Role model, backup and reset — set rarely, so they sit behind one icon in the corner of the card */}
          <button onClick={onSettings} aria-label="설정" title="설정"
            className="shrink-0 p-1.5 rounded-lg border border-zinc-700 text-zinc-400 active:opacity-70">
            <Settings size={15} />
          </button>
        </div>

        {/* A truncated row is never the only place a name lives: `ProfileModal` lists every held certification and
            exam best in full, and the wall sheet lists every earned item. */}
        <div className="space-y-1">
          <CvFact label="학력">{cv.edu}</CvFact>
          <CvFact label="경력">{cv.career}</CvFact>
          <CvFact label="자격">
            <span className="font-mono">{held.length}건</span>
            {held.map((c) => <span key={c.n}> · {c.n}</span>)}
          </CvFact>
          <CvFact label="시험">
            <span className="font-mono">{bests.length}건</span>
            {bests.map(([id, b]) => (
              <span key={id}> · {examBestText(id, b)}</span>
            ))}
          </CvFact>
          <CvFact label="포트폴리오"><span className="font-mono">{(state.folio || []).length}건</span></CvFact>
          <CvFact label="성취" onClick={onWall}>
            트로피 <span className="font-mono">{trophies}개</span> · 검증된 성취 <span className="font-mono">{achTotal}건</span> ›
          </CvFact>
        </div>

        <div>
          <SectionLabel tone="text-cyan-400">영역 등급</SectionLabel>
          <div className="space-y-1.5">
            {state.areas.map((p) => <AreaGradeRow key={p.id} area={p} onPromote={onPromote} />)}
          </div>
        </div>
      </section>

      {/* The stage headline (2026-09-18): the current stage, its progress and the last AI verdict's caption. The stage
          percentage is a second figure under its own label — it never enters, scales or is averaged with the proximity
          below (rule 14); `pct` is derived at render (rule 9). The condition count and the quit text stay on `title`. */}
      {sp && (
        <button onClick={onRoleAdvice} title={stageLine(sp.rs)} className="w-full text-left px-1 active:opacity-70">
          <div className="flex items-center gap-1.5 text-sm">
            <span className="text-zinc-500 shrink-0">단계</span>
            <span className="font-mono font-bold text-cyan-300 shrink-0">{sp.k}/{sp.n}</span>
            <span className="text-zinc-200 truncate">{sp.name}</span>
            <span className="font-mono text-cyan-300 shrink-0 ml-auto">· 진행 {sp.pct}%</span>
            <span className="text-zinc-600 shrink-0">›</span>
          </div>
          <div className="mt-1"><Bar ratio={sp.pct / 100} color="bg-cyan-400" h="h-1.5" /></div>
          {last && <div className="text-xs font-mono text-zinc-500 mt-1">{probText(last.probability)} · {last.date}</div>}
        </button>
      )}
      {/* Proximity is computed from the verified grades above (rule 14) — the smaller line beneath the headline. Without
          a role model it is an inert fact: the role model is set in settings, and direction advice has nothing to explain. */}
      {rg ? (
        <button onClick={onRoleAdvice} className="w-full text-left flex items-center gap-1.5 px-1 text-xs active:opacity-70">
          <span className="text-zinc-500 shrink-0">롤모델 근접도</span>
          <span className="font-mono font-bold text-cyan-300 shrink-0">{rg.match}%</span>
          <span className="text-zinc-500 truncate">· {rg.name}</span>
          <span className="text-zinc-600 shrink-0">›</span>
        </button>
      ) : (
        <p className="px-1 text-xs text-zinc-500">롤모델 미설정 — 근접도 계산 대상 없음</p>
      )}
    </>
  );
}

/* ── Profile — the CV as a screen: the photo, the personal facts, and the education and career records the
   app asked for once at onboarding. A modal rather than a seventh tab: it is opened occasionally, and the
   `Modal` shell already scrolls and sits as a bottom sheet on a phone.
   Nothing here computes a grade. `profile.edu` and `profile.career` were the inputs of the one-time starting
   grade computation and are left exactly as onboarding wrote them (rules 4, 11) — this modal never writes
   them — so a degree added years later moves no area; only the evidence gate does. `보유 기록` is read-only
   for the same reason: certifications, exam bests and portfolio entries are registered where they are paid
   for, and re-typing them here would be a second, unpaid record of the same fact.
   The photo has no file input of its own: it calls the root's `askUpload("profile")`, whose input is mounted
   on `Shell` and therefore survives this modal closing mid-pick. ── */
function ProfileModal({ profile, state, img, today, onUpload, onClearImg, onSave, onClose }) {
  const [name, setName] = useState(profile.name || "");
  const [nick, setNick] = useState(profile.nick || "");
  const [birth, setBirth] = useState(profile.birth || "");
  const [gender, setGender] = useState(profile.gender || null);
  const [status, setStatus] = useState(profile.status || null);
  const [email, setEmail] = useState(profile.email || "");
  const [phone, setPhone] = useState(profile.phone || "");
  const [edus, setEdus] = useState(profile.edus || []);
  const [careers, setCareers] = useState(profile.careers || []);
  const [err, setErr] = useState("");

  // Declared and earned certifications together — the same list the home CV counts, so the two cannot disagree
  const certs = heldCertsOf(state).map((c) => c.n);
  const bests = Object.entries(state.exams?.best || {});
  const field = "w-full bg-zinc-950 border border-zinc-700 rounded-xl px-3 py-2.5 text-sm outline-none focus:border-cyan-500";

  const submit = () => {
    if (!name.trim()) { setErr("이름을 입력해 주세요."); return; }
    if (!birth) { setErr("생년월일을 입력해 주세요."); return; }
    if (!/^\d{4}-\d{2}-\d{2}$/.test(birth)) { setErr("생년월일 형식이 올바르지 않아요 — YYYY-MM-DD로 입력해요."); return; }
    if (birth > today) { setErr("생년월일이 오늘보다 뒤예요."); return; }
    if (!gender || !status) { setErr("성별과 현재 신분을 선택해 주세요."); return; }
    if (!edus.length) { setErr("학력을 1개 이상 추가해 주세요."); return; }
    if (email.trim() && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.trim())) { setErr("이메일 형식이 올바르지 않아요."); return; }
    // Exactly the fields this screen owns. `edu`, `career`, `certs`, `examsOwned`, `look` and the areas are
    // not in this object and are not touched by the handler that receives it.
    onSave({ name: name.trim(), nick: nick.trim(), birth, gender, status, email: email.trim(), phone: phone.trim(), edus, careers });
  };

  return (
    <Modal title="프로필" onClose={onClose}>
      <div className="space-y-4">
        <p className="text-xs text-zinc-500">학력·경력을 고쳐도 시작 등급은 바뀌지 않아요. 승급은 관문 증거로만 올라가요.</p>

        <div>
          <div className="text-xs font-bold tracking-widest text-zinc-500 mb-1.5">사진</div>
          <div className="flex items-center gap-3">
            <div className="rounded-2xl overflow-hidden bg-zinc-950 border border-zinc-700 shrink-0">
              <Portrait img={img} look={profile.look} gender={gender} size={64} />
            </div>
            <div className="flex flex-wrap gap-1.5">
              <button onClick={onUpload}
                className="flex items-center gap-1 bg-zinc-800 text-zinc-300 rounded-lg px-2.5 py-1.5 text-xs font-medium">
                <Camera size={13} /> 사진 등록
              </button>
              {img && (
                <button onClick={onClearImg}
                  className="border border-zinc-700 text-zinc-400 rounded-lg px-2.5 py-1.5 text-xs font-medium">사진 삭제</button>
              )}
            </div>
          </div>
        </div>

        <div className="space-y-2">
          <div className="text-xs font-bold tracking-widest text-zinc-500">인적사항</div>
          <input value={name} onChange={(e) => setName(e.target.value)} placeholder="이름" className={field} />
          <input value={nick} onChange={(e) => setNick(e.target.value)} placeholder="닉네임 (선택)" className={field} />
          <div>
            <div className="text-xs font-bold tracking-widest text-zinc-500 mb-1.5">생년월일</div>
            <input type="date" value={birth} onChange={(e) => setBirth(e.target.value)} className={`${field} font-mono`} />
            {/* Derived at render from the date beside it — the age itself is never stored (rule 9) */}
            <div className="text-xs text-zinc-500 mt-1">{ageText({ birth }, today)}</div>
          </div>
          <OptRow label="성별" opts={["남성", "여성", "선택 안 함"]} val={gender} set={setGender} getK={(o) => o} getT={(o) => o} />
          <OptRow label="현재 신분" opts={STATUS_OPTS} val={status} set={setStatus} getK={(o) => o} getT={(o) => o} />
          <input value={email} onChange={(e) => setEmail(e.target.value)} placeholder="이메일 (선택)" className={field} />
          <input value={phone} onChange={(e) => setPhone(e.target.value)} placeholder="연락처 (선택)" className={field} />
        </div>

        <CvSection kind="edu" label="학력" entries={edus} onChange={setEdus}
          note="학력을 1개 이상 추가해요. 최종 학력이 기본지식 시작 등급의 근거가 돼요." />

        <div>
          <CvSection kind="career" label="경력" entries={careers} onChange={setCareers}
            note="경력이 없으면 비워 둬요. 직업·커리어 시작 등급은 경력 없음 기준이에요." />
          {/* The months are counted here and nowhere else; no grade reads them (rules 4, 9) */}
          <p className="text-xs text-zinc-500 mt-1.5">합산 실무 {careerText(careerMonths(careers, today))}</p>
        </div>

        <div>
          <div className="text-xs font-bold tracking-widest text-zinc-500 mb-1.5">보유 기록</div>
          <div className="space-y-1.5">
            <div className="bg-zinc-950 border border-zinc-800 rounded-xl px-3 py-2">
              <div className="text-xs font-mono text-zinc-500">자격 {certs.length}건</div>
              <div className="text-xs text-zinc-300 break-words">{certs.length ? certs.join(" · ") : "없음"}</div>
            </div>
            <div className="bg-zinc-950 border border-zinc-800 rounded-xl px-3 py-2">
              <div className="text-xs font-mono text-zinc-500">시험 성적 {bests.length}건</div>
              <div className="text-xs text-zinc-300 break-words">
                {bests.length ? bests.map(([id, b]) => examBestText(id, b)).join(" · ") : "없음"}
              </div>
            </div>
            <div className="bg-zinc-950 border border-zinc-800 rounded-xl px-3 py-2">
              <div className="text-xs font-mono text-zinc-500">포트폴리오 {(state.folio || []).length}건</div>
            </div>
            <p className="text-xs text-zinc-600">여기서는 고칠 수 없어요 — 자격·시험은 목표의 핵심결과에서, 포트폴리오는 사업 탭에서 관리해요.</p>
          </div>
        </div>

        {err && <div className="text-xs text-rose-400">{err}</div>}
        <button onClick={submit} className="w-full py-3 rounded-xl bg-cyan-400 text-zinc-950 font-black text-sm">저장</button>
        <p className="text-xs text-zinc-600 text-center">창을 닫으면 저장되지 않아요.</p>
      </div>
    </Modal>
  );
}

/* ───────────────────────── Goals tab (OKR) ───────────────────────── */
function GoalsTab({ state, onAddGoal, onCheckin, onGoalStatus, onRemoveGoal, onAddQuestFor }) {
  const groups = [
    ["active", "진행 중"],
    ["done", "달성"],
  ];
  return (
    <>
      <section className="bg-zinc-900 border border-zinc-800 rounded-2xl p-4">
        <div className="flex items-center justify-between">
          <div>
            <SectionLabel tone="text-cyan-400">목표 (OKR)</SectionLabel>
            <p className="text-xs text-zinc-500 mt-0.5">목표를 세우고, 핵심결과 수치로 진행을 측정해요.</p>
          </div>
          <button onClick={onAddGoal}
            className="shrink-0 px-3.5 py-2.5 rounded-xl bg-cyan-400 text-zinc-950 text-sm font-bold flex items-center gap-1 active:translate-y-0.5">
            <Plus size={14} /> 새 목표
          </button>
        </div>
      </section>

      {groups.map(([st, label]) => {
        const list = (state.goals || []).filter((g) => g.status === st);
        if (!list.length) return null;
        return (
          <div key={st} className="space-y-3">
            <div className="flex items-center gap-2">
              <SectionLabel tone={st === "active" ? "text-zinc-400" : "text-emerald-400"}>{label}</SectionLabel>
              <span className="flex-1 h-px bg-zinc-800 mb-2" />
            </div>
            {list.map((g) => {
              const pc = paceOf(g, state);
              const pr = pc.p; // paceOf already computed the progress — no duplicate call
              const area = state.areas.find((p) => p.id === g.areaId);
              return (
                <section key={g.id} className={`bg-zinc-900 border border-zinc-800 rounded-2xl p-4 ${st === "done" ? "opacity-75" : ""}`}>
                  <div className="flex items-start justify-between gap-2">
                    <div className="min-w-0">
                      <div className="font-black text-base">{g.title}</div>
                      <div className="text-xs text-zinc-500 mt-0.5">
                        {area?.name || "일반"} · {g.deadline ? `${g.deadline} (${ddayStr(g.deadline)})` : "기한 없음"}
                      </div>
                      {st === "active" && (
                        <div className="text-xs mt-0.5 font-mono text-zinc-500">
                          {pc.el != null ? <>진행 {Math.round(pc.p * 100)}% · 시간 경과 {Math.round(pc.el * 100)}% · <span className={`font-bold ${pc.cls}`}>{pc.label}</span></> : "기한 없음 — 페이스 계산 불가"}
                        </div>
                      )}
                    </div>
                    <span className={`text-2xl font-mono font-black shrink-0 ${st === "done" ? "text-emerald-400" : "text-cyan-300"}`}>{Math.round(pr * 100)}%</span>
                  </div>
                  <div className="mt-2"><Bar ratio={pr} color={st === "done" ? "bg-emerald-400" : "bg-cyan-400"} /></div>

                  <div className="space-y-2 mt-3">
                    {(g.krs || []).map((kr) => {
                      const kp = krProgress(kr, g, state);
                      return (
                        <div key={kr.id} className="bg-zinc-950 rounded-xl p-3">
                          <div className="flex items-center justify-between gap-2">
                            <span className="flex items-center gap-1.5 min-w-0">
                              <span className={`text-xs font-mono font-bold border rounded px-1 shrink-0 ${KR_CHIP[kr.type]?.[1] || "text-zinc-400 border-zinc-700"}`}>{KR_CHIP[kr.type]?.[0] || kr.type}</span>
                              <span className="text-sm font-semibold truncate">{kr.title}</span>
                            </span>
                            <span className="text-xs font-mono text-zinc-500 shrink-0">{Math.round(kp * 100)}% · {krRemainText(kr, g, state)}</span>
                          </div>
                          <div className="mt-1.5"><Bar ratio={kp} color="bg-cyan-400" h="h-1.5" /></div>
                          <div className="flex items-center justify-between gap-2 mt-2 text-xs">
                            {kr.type === "metric" && (
                              <>
                                <span className="text-zinc-600 font-mono">{kr.start}{kr.unit} → 목표 {kr.target}{kr.unit}</span>
                                <span className="flex items-center gap-1">
                                  <input type="number" defaultValue={kr.current ?? kr.start} key={`${kr.id}-${kr.current}`}
                                    onBlur={(e) => onCheckin(g.id, kr.id, Number(e.target.value))}
                                    className="w-20 bg-zinc-900 border border-zinc-700 rounded-lg px-2 py-1 text-right font-mono" />
                                  <span className="text-zinc-600">{kr.unit}</span>
                                </span>
                              </>
                            )}
                            {kr.type === "exam" && (
                              <span className="text-zinc-600">
                                내 최고 <b className="text-cyan-300 font-mono">{state.exams?.best?.[kr.famId]?.label || "—"}</b>
                                {" → 목표 "}<b className="text-zinc-300 font-mono">{kr.band?.label}</b>
                                <span className="text-zinc-700"> · 시험 실행으로 자동 반영</span>
                              </span>
                            )}
                            {kr.type === "exam" && !kr.done && (
                              <button onClick={() => onAddQuestFor(g.id)} className="text-sky-300 text-xs font-medium shrink-0">등록 ›</button>
                            )}
                            {kr.type === "cert" && (
                              <span className="text-zinc-600">
                                {kr.certName} — {kr.done ? "취득 완료" : "마일스톤 실행에서 합격증 제출로 완료"}
                              </span>
                            )}
                            {kr.type === "cert" && (() => { const c = certByTitle(kr.certName); return c ? <CertBadge g={achGrade(c.d)} /> : null; })()}
                            {kr.type === "count" && (
                              <>
                                <span className="text-zinc-600 font-mono">{krDoneCount(g, state)} / {kr.need}회 (연결 실행)</span>
                                <button onClick={() => onAddQuestFor(g.id)}
                                  className="text-cyan-300 border border-cyan-800 rounded-lg px-2 py-1">실행 추가</button>
                              </>
                            )}
                          </div>
                        </div>
                      );
                    })}
                  </div>

                  {st === "active" && (
                    <div className="flex items-center gap-2 mt-3">
                      <button onClick={() => onAddQuestFor(g.id)}
                        className="flex-1 py-2.5 rounded-xl border border-dashed border-zinc-700 text-zinc-400 text-xs font-medium">＋ 실행 연결</button>
                      {pr >= 1 && (
                        <button onClick={() => onGoalStatus(g.id, "done")}
                          className="py-2 px-3 rounded-xl bg-emerald-500 bg-opacity-10 text-emerald-300 border border-emerald-700 text-xs font-bold">달성 처리</button>
                      )}
                    </div>
                  )}
                  {st === "done" && (
                    <button onClick={() => onRemoveGoal(g.id)} className="mt-3 text-xs text-zinc-600">기록에서 제거</button>
                  )}
                  {st === "active" && (
                    <button onClick={() => onRemoveGoal(g.id)} className="mt-3 text-xs text-rose-400">목표 삭제</button>
                  )}

                </section>
              );
            })}
          </div>
        );
      })}
      {(state.goals || []).length === 0 && (
        <div className="text-center py-6">
          <EmptyGoalSvg />
          <p className="text-sm text-zinc-600 mt-1">목표가 없습니다. 모든 진행 측정은 목표에서 시작됩니다.</p>
        </div>
      )}
    </>
  );
}

/* ── New goal modal (OKR builder) ── */
function AddGoalModal({ areas, onClose, onAdd }) {
  const [title, setTitle] = useState("");
  const [areaId, setPartId] = useState(areas[0]?.id);
  const [deadline, setDeadline] = useState("");
  const [note, setNote] = useState("");
  const [krs, setKrs] = useState([]);
  const [krType, setKrType] = useState("metric");
  const [mTitle, setMTitle] = useState(""); const [mStart, setMStart] = useState(""); const [mTarget, setMTarget] = useState(""); const [mUnit, setMUnit] = useState("");
  const [cTitle, setCTitle] = useState(""); const [cNeed, setCNeed] = useState("");
  const [exFam, setExFam] = useState(null); const [exBand, setExBand] = useState(null);
  const [certQ, setCertQ] = useState("");
  const [err, setErr] = useState("");

  const addKr = () => {
    setErr("");
    if (krType === "metric") {
      if (!mTitle.trim() || mStart === "" || mTarget === "") { setErr("지표명·시작값·목표값을 입력해 주세요."); return; }
      setKrs([...krs, { id: uid(), type: "metric", title: mTitle.trim(), start: Number(mStart), target: Number(mTarget), current: Number(mStart), unit: mUnit.trim() }]);
      setMTitle(""); setMStart(""); setMTarget(""); setMUnit("");
    } else if (krType === "count") {
      if (!cTitle.trim() || !cNeed) { setErr("행동명과 목표 횟수를 입력해 주세요."); return; }
      setKrs([...krs, { id: uid(), type: "count", title: cTitle.trim(), need: Number(cNeed) }]);
      setCTitle(""); setCNeed("");
    } else if (krType === "exam") {
      if (!exFam || !exBand) { setErr("시험과 목표 밴드를 선택해 주세요."); return; }
      setKrs([...krs, { id: uid(), type: "exam", title: `${exFam.n} ${exBand.label} 달성`, famId: exFam.id, band: exBand }]);
      setExFam(null); setExBand(null);
    } else if (krType === "cert") {
      if (!certQ.trim()) { setErr("자격증 이름을 입력해 주세요."); return; }
      setKrs([...krs, { id: uid(), type: "cert", title: `${certQ.trim()} 취득`, certName: certQ.trim() }]);
      setCertQ("");
    }
  };
  const submit = () => {
    if (!title.trim()) { setErr("목표 이름을 입력해 주세요."); return; }
    onAdd({ id: uid(), title: title.trim(), areaId, deadline: deadline || null, note: note.trim(), status: "active", createdAt: dstr(), krs });
  };
  const certHits = useMemo(() => (certQ.trim() ? CERTS.filter((c) => c.n.includes(certQ.trim())).slice(0, 5) : []), [certQ]);

  return (
    <Modal title="새 목표 (OKR)" onClose={onClose}>
      <div className="space-y-3">
        <input value={title} onChange={(e) => setTitle(e.target.value)} placeholder="목표 — 예: 영어 실전 수준 만들기"
          className="w-full bg-zinc-950 border border-zinc-700 rounded-xl px-3 py-2.5 text-sm" />
        <div className="flex gap-2">
          <select value={areaId} onChange={(e) => setPartId(e.target.value)}
            className="flex-1 bg-zinc-950 border border-zinc-700 rounded-xl px-3 py-2.5 text-sm">
            {areas.map((p) => <option key={p.id} value={p.id}>{p.name}</option>)}
          </select>
          <input type="date" value={deadline} onChange={(e) => setDeadline(e.target.value)}
            className="bg-zinc-950 border border-zinc-700 rounded-xl px-3 py-2 text-sm" />
        </div>
        <input value={note} onChange={(e) => setNote(e.target.value)} placeholder="메모 (선택) — 왜 이 목표인가"
          className="w-full bg-zinc-950 border border-zinc-700 rounded-xl px-3 py-2.5 text-sm" />

        <div className="bg-zinc-950 border border-zinc-800 rounded-xl p-3">
          <div className="text-xs font-bold text-zinc-400 mb-2">핵심결과(KR) 추가 — {krs.length}개</div>
          <div className="flex gap-1.5 mb-2">
            {[["metric", "수치"], ["count", "횟수"], ["exam", "시험"], ["cert", "자격"]].map(([k, t]) => (
              <Chip key={k} on={krType === k} onClick={() => { setKrType(k); setErr(""); }}>{t}</Chip>
            ))}
          </div>
          {krType === "metric" && (
            <div className="space-y-1.5">
              <input value={mTitle} onChange={(e) => setMTitle(e.target.value)} placeholder="지표명 — 예: 체지방률"
                className="w-full bg-zinc-900 border border-zinc-700 rounded-lg px-2.5 py-2 text-sm" />
              <div className="flex gap-1.5">
                <input value={mStart} onChange={(e) => setMStart(e.target.value)} type="number" placeholder="시작"
                  className="flex-1 w-0 bg-zinc-900 border border-zinc-700 rounded-lg px-2.5 py-2 text-sm font-mono" />
                <input value={mTarget} onChange={(e) => setMTarget(e.target.value)} type="number" placeholder="목표"
                  className="flex-1 w-0 bg-zinc-900 border border-zinc-700 rounded-lg px-2.5 py-2 text-sm font-mono" />
                <input value={mUnit} onChange={(e) => setMUnit(e.target.value)} placeholder="단위"
                  className="w-16 bg-zinc-900 border border-zinc-700 rounded-lg px-2.5 py-2 text-sm" />
              </div>
            </div>
          )}
          {krType === "count" && (
            <div className="flex gap-1.5">
              <input value={cTitle} onChange={(e) => setCTitle(e.target.value)} placeholder="행동 — 예: 스터디 참석"
                className="flex-1 bg-zinc-900 border border-zinc-700 rounded-lg px-2.5 py-2 text-sm" />
              <input value={cNeed} onChange={(e) => setCNeed(e.target.value)} type="number" placeholder="횟수"
                className="w-20 bg-zinc-900 border border-zinc-700 rounded-lg px-2.5 py-2 text-sm font-mono" />
            </div>
          )}
          {krType === "exam" && (
            <div>
              <div className="flex gap-1.5 overflow-x-auto pb-1.5">
                {EXAMS.map((e) => (
                  <button key={e.id} onClick={() => { setExFam(e); setExBand(null); }}
                    className={`shrink-0 px-2.5 py-1.5 rounded-lg text-xs font-semibold border ${exFam?.id === e.id ? "bg-zinc-100 text-zinc-950 border-zinc-200" : "bg-zinc-900 text-zinc-500 border-zinc-700"}`}>
                    {e.n}
                  </button>
                ))}
              </div>
              {exFam && (
                <div className="flex flex-wrap gap-1.5 mt-1">
                  {exFam.bands.map(([label, d, p, conf]) => (
                    <Chip key={label} on={exBand?.label === label}
                      onClick={() => setExBand({ label, d, p, conf })}>{label}</Chip>
                  ))}
                </div>
              )}
              <p className="text-xs text-zinc-600 mt-1.5">달성 여부는 시험 실행 완료 기록에서 자동 계산돼요.</p>
            </div>
          )}
          {krType === "cert" && (
            <div>
              <input value={certQ} onChange={(e) => setCertQ(e.target.value)} placeholder="자격증 검색 — 예: 정보처리기사"
                className="w-full bg-zinc-900 border border-zinc-700 rounded-lg px-2.5 py-2 text-sm" />
              {certHits.length > 0 && (
                <div className="flex flex-wrap gap-1.5 mt-1.5">
                  {certHits.map((c) => <Chip key={c.n} on={certQ === c.n} onClick={() => setCertQ(c.n)}>{c.n}</Chip>)}
                </div>
              )}
            </div>
          )}
          <button onClick={addKr} className="w-full mt-2 py-2 rounded-lg border border-cyan-700 text-cyan-300 text-xs font-bold">＋ 이 핵심결과 추가</button>
          {krs.length > 0 && (
            <div className="space-y-1 mt-2">
              {krs.map((kr) => (
                <div key={kr.id} className="flex items-center justify-between text-xs bg-zinc-900 rounded-lg px-2.5 py-1.5">
                  <span className="text-zinc-300 truncate">{kr.title}</span>
                  <button onClick={() => setKrs(krs.filter((x) => x.id !== kr.id))} className="text-zinc-600"><X size={12} /></button>
                </div>
              ))}
            </div>
          )}
        </div>

        {err && <p className="text-xs text-rose-400">{err}</p>}
        <button onClick={submit} className="w-full py-3 rounded-xl bg-cyan-500 text-zinc-950 font-black text-sm active:translate-y-0.5">
          목표 만들기
        </button>
        <p className="text-xs text-zinc-600">KR이 없으면 진행률은 0%로 고정됩니다 — 측정할 수 없는 목표는 관리되지 않습니다.</p>
      </div>
    </Modal>
  );
}

/* ── Daily briefing — what the saved state says about today (rules 9, 13) ── */
const SEV_CLS = { 3: "text-rose-400", 2: "text-amber-300", 1: "text-zinc-300" };
function BriefingModal({ state, today, onClose, onAction }) {
  const { sections } = buildBriefing(state, today);
  return (
    <Modal title={`오늘 브리핑 — ${today}`} onClose={onClose}>
      <div className="space-y-3">
        {sections.map((s) => (
          <div key={s.key} className="bg-zinc-950 rounded-xl p-3">
            <SectionLabel tone="text-zinc-400">{s.title}</SectionLabel>
            <div className="space-y-1 mt-1.5">
              {s.items.map((it, n) => (it.action ? (
                <button key={n} onClick={() => onAction(it.action)}
                  className={`w-full text-left text-xs ${SEV_CLS[it.severity]} active:opacity-70`}>
                  {/* The count lines (v28 per-track counts) break only between their fragments at 390 px */}
                  {it.kind === "prep" || it.kind === "work"
                    ? it.text.split(" · ").map((part, k) => <span key={k}>{k > 0 && " · "}<span className="whitespace-nowrap">{part}</span></span>)
                    : it.text} ›
                </button>
              ) : (
                <div key={n} className={`text-xs ${SEV_CLS[it.severity]}`}>{it.text}</div>
              )))}
            </div>
          </div>
        ))}
        <button onClick={() => onAction({ type: "reader" })}
          className="w-full py-2.5 rounded-xl border border-zinc-700 text-zinc-300 font-bold text-xs">오늘 읽을 것 ›</button>
        <div className="flex gap-1.5">
          <button onClick={() => onAction({ type: "bridge", mode: "send" })}
            className="flex-1 py-2.5 rounded-xl bg-amber-400 text-zinc-950 font-black text-xs">AI에게 보내기</button>
          <button onClick={() => onAction({ type: "bridge", mode: "paste" })}
            className="flex-1 py-2.5 rounded-xl border border-amber-700 text-amber-300 font-bold text-xs">AI 답변 붙여넣기</button>
        </div>
        <div className="flex gap-1.5">
          <button onClick={() => onAction({ type: "journal" })}
            className="flex-1 py-2.5 rounded-xl border border-zinc-700 text-zinc-300 font-bold text-xs">일지 쓰기</button>
          <button onClick={onClose}
            className="flex-1 py-2.5 rounded-xl bg-cyan-500 text-zinc-950 font-black text-xs">닫기</button>
        </div>
      </div>
    </Modal>
  );
}

/* ── Daily reader — the full content of `buildReader`, one block per section. Nothing here is a checkbox, a toggle or
   a store (the user declined a confirm feature, 2026-09-17); every close goes through `closeBriefing`, which stamps the
   day. ── */
function DailyReaderModal({ state, today, onClose, onAction }) {
  const { sections } = useMemo(() => buildReader(state, today), [state, today]);
  return (
    <Modal title={`오늘 읽을 것 — ${today}`} onClose={onClose}>
      <div className="space-y-3">
        {sections.map((s) => (
          <div key={s.key} className="bg-zinc-950 rounded-xl p-3">
            <div className="flex items-start justify-between gap-2">
              <SectionLabel tone="text-zinc-400">{s.title}</SectionLabel>
              <button onClick={() => onAction(s.action)} aria-label={`${s.title} 열기`}
                className="shrink-0 px-1 text-xs text-zinc-400 active:opacity-70">›</button>
            </div>
            <div className="space-y-1.5">
              {s.items.map((it, n) => (it.head ? (
                <div key={n} className="text-xs font-bold text-zinc-500 pt-1">{it.text}</div>
              ) : (
                <div key={n}>
                  <div className={`text-xs break-words ${it.text === "없음" && !it.sub ? "text-zinc-500" : "text-zinc-300"}`}>{it.text}</div>
                  {(it.sub || []).map((line, k) => (
                    <div key={k} className="pl-3 text-xs text-zinc-400 break-words">{line}</div>
                  ))}
                </div>
              )))}
              {s.more > 0 && <div className="text-xs text-zinc-500 font-mono">{s.more}건 더</div>}
            </div>
          </div>
        ))}
        <button onClick={() => onAction({ type: "briefing" })}
          className="w-full py-2.5 rounded-xl border border-zinc-700 text-zinc-300 font-bold text-xs">브리핑 ›</button>
        <button onClick={onClose}
          className="w-full py-2.5 rounded-xl bg-cyan-500 text-zinc-950 font-black text-xs">닫기</button>
      </div>
    </Modal>
  );
}

/* ── Journal — a free-text record per day; the assistant reply is stored beside it ── */
function JournalModal({ state, today, onClose, onSave }) {
  const entries = [...(state.journal || [])].sort((a, b) => b.date.localeCompare(a.date));
  const mine = entries.find((e) => e.date === today);
  const [text, setText] = useState(mine?.text || "");
  const [open, setOpen] = useState(null);
  const close = () => { if (text.trim() !== (mine?.text || "").trim()) onSave(text, true); onClose(); };
  return (
    <Modal title={`일지 — ${today}`} onClose={close}>
      <div className="space-y-3">
        <textarea value={text} onChange={(e) => setText(e.target.value)} rows={5}
          placeholder="오늘 한 일 · 수치 · 막힌 것 — 사실만 적어요"
          className="w-full bg-zinc-950 border border-zinc-700 rounded-xl px-3 py-2.5 text-sm" />
        {mine?.ai && (
          <div className="bg-zinc-950 border border-zinc-800 rounded-xl p-3">
            <div className="text-xs text-zinc-500 mb-1">AI 답변 · {mine.aiDate}</div>
            <p className="text-xs text-zinc-300 whitespace-pre-wrap break-words">{mine.ai}</p>
          </div>
        )}
        <button onClick={() => onSave(text)} className="w-full py-3 rounded-xl bg-cyan-500 text-zinc-950 font-black text-sm">저장</button>
        <div>
          <SectionLabel tone="text-zinc-400">최근 7일</SectionLabel>
          {entries.filter((e) => e.date !== today).length === 0 ? (
            <p className="text-xs text-zinc-600 mt-1.5">일지 기록 없음</p>
          ) : (
            <div className="space-y-1 mt-1.5">
              {entries.filter((e) => e.date !== today).slice(0, 7).map((e) => (
                <button key={e.id} onClick={() => setOpen(open === e.id ? null : e.id)}
                  className="w-full text-left bg-zinc-950 rounded-lg px-3 py-2">
                  <div className="text-xs text-zinc-400 truncate">{e.date} · {open === e.id ? "" : e.text.slice(0, 40)}</div>
                  {open === e.id && <p className="text-xs text-zinc-300 mt-1 whitespace-pre-wrap break-words">{e.text}{e.ai ? `\n\nAI 답변 · ${e.aiDate}\n${e.ai}` : ""}</p>}
                </button>
              ))}
            </div>
          )}
        </div>
      </div>
    </Modal>
  );
}

/* ── Assistant bridge — copy the packet out, paste the reply back. The send pane, the paste pane and the copy routine
   are shared by `BridgeModal` (the daily check-in) and `WorkBridgeModal` (`오늘 업무 만들기`); each modal owns its
   packet, its parser and its confirm view. ── */
// Copies the packet text: the clipboard API first, then `select()` + `execCommand("copy")` on the read-only textarea.
const copyPacket = async (taRef, text, onToast) => {
  const ta = taRef.current;
  try {
    if (navigator.clipboard?.writeText) { await navigator.clipboard.writeText(text); onToast("복사했어요 — AI 채팅에 붙여넣어요"); return; }
    throw new Error("no clipboard");
  } catch {
    try { ta?.select(); document.execCommand("copy"); onToast("복사했어요 — AI 채팅에 붙여넣어요"); }
    catch { onToast("자동 복사 불가 — 글을 길게 눌러 복사해요"); }
  }
};
function PacketSendPane({ packet, caption, taRef, onCopy, onPaste }) {
  return (
    <div className="space-y-3">
      <p className="text-xs text-zinc-500">{caption}</p>
      <textarea ref={taRef} readOnly value={packet} rows={9}
        className="w-full bg-zinc-950 border border-zinc-700 rounded-xl px-3 py-2.5 text-xs font-mono" />
      <div className="flex gap-1.5">
        <button onClick={onCopy} className="flex-1 py-3 rounded-xl bg-cyan-500 text-zinc-950 font-black text-sm">복사</button>
        <button onClick={onPaste} className="flex-1 py-3 rounded-xl border border-zinc-700 text-zinc-300 font-bold text-sm">AI 답변 붙여넣기 ›</button>
      </div>
    </div>
  );
}
function ReplyPastePane({ reply, setReply, onCheck }) {
  return (
    <div className="space-y-3">
      <textarea value={reply} onChange={(e) => setReply(e.target.value)} rows={9}
        placeholder="AI 답변을 여기에 붙여넣어요"
        className="w-full bg-zinc-950 border border-zinc-700 rounded-xl px-3 py-2.5 text-sm" />
      <button onClick={onCheck} className="w-full py-3 rounded-xl bg-cyan-500 text-zinc-950 font-black text-sm">답변 확인</button>
    </div>
  );
}

function BridgeModal({ state, today, initialMode, onClose, onImport, onStoreReply }) {
  const [mode, setMode] = useState(initialMode || "send");
  const [reply, setReply] = useState("");
  const [parsed, setParsed] = useState(null);
  const [picked, setPicked] = useState({});
  const [goalSel, setGoalSel] = useState({});
  const taRef = useRef(null);
  const packet = useMemo(() => buildAssistantPacket(state, today), [state, today]);
  const active = (state.goals || []).filter((g) => g.status === "active");

  const copy = () => copyPacket(taRef, packet, (msg) => onStoreReply(null, msg));
  const check = () => {
    const r = parseAssistantReply(reply, state);
    setParsed(r);
    setPicked(Object.fromEntries(r.proposals.filter((p) => !p.reject && p.goalId).map((p) => [p.key, true])));
  };
  const confirm = () => {
    const list = (parsed?.proposals || [])
      .filter((p) => picked[p.key] && !p.reject)
      .map((p) => ({ ...p, goalId: p.goalId || goalSel[p.key] }))
      .filter((p) => p.goalId);
    onImport(list, parsed.raw);
  };

  return (
    <Modal title={mode === "send" ? "AI에게 보내기" : "AI 답변 붙여넣기"} onClose={onClose}>
      {mode === "send" ? (
        <PacketSendPane packet={packet} taRef={taRef} onCopy={copy} onPaste={() => setMode("paste")}
          caption="아래 글을 복사해 Claude·ChatGPT 채팅에 붙여넣고, 답변을 받아 다시 붙여넣어요. 앱은 네트워크를 쓰지 않아요. 직장 트랙 기록은 실리지 않아요." />
      ) : !parsed ? (
        <ReplyPastePane reply={reply} setReply={setReply} onCheck={check} />
      ) : (
        <div className="space-y-3">
          <div className="text-sm font-bold">제안 실행 확인 — {parsed.proposals.length}건</div>
          {parsed.note && <p className="text-xs text-zinc-400">{parsed.note}</p>}
          {parsed.proposals.length === 0 ? (
            <p className="text-xs text-zinc-500">제안 실행 없음 — 답변은 일지에 저장돼요.</p>
          ) : parsed.proposals.map((p) => (
            <div key={p.key} className={`bg-zinc-950 rounded-xl p-3 ${p.reject ? "opacity-50" : ""}`}>
              <label className="flex items-start gap-2">
                <input type="checkbox" disabled={!!p.reject || !(p.goalId || goalSel[p.key])} checked={!!picked[p.key]}
                  onChange={(e) => setPicked((s) => ({ ...s, [p.key]: e.target.checked }))} className="mt-0.5" />
                <span className="flex-1 min-w-0">
                  <span className="block text-sm font-semibold truncate">{p.title}</span>
                  <span className="block text-xs text-zinc-500">{p.goalTitle} · {p.diff} · {p.type === "daily" ? "매일" : "1회"}{p.due ? ` · 기한 ${p.due}` : ""}</span>
                  {p.reject && <span className="block text-xs text-rose-400 mt-0.5">{p.reject}</span>}
                </span>
              </label>
              {!p.reject && !p.goalId && (
                <select value={goalSel[p.key] || ""} onChange={(e) => setGoalSel((s) => ({ ...s, [p.key]: e.target.value }))}
                  className="w-full mt-2 bg-zinc-900 border border-zinc-700 rounded-lg px-2 py-1.5 text-xs">
                  <option value="">목표 선택</option>
                  {active.map((g) => <option key={g.id} value={g.id}>{g.title}</option>)}
                </select>
              )}
            </div>
          ))}
          <button onClick={confirm} className="w-full py-3 rounded-xl bg-cyan-500 text-zinc-950 font-black text-sm">선택한 실행 등록</button>
        </div>
      )}
    </Modal>
  );
}

/* ── Weekly review — what worked, what blocked, beside the numbers of that week ── */
function ReviewModal({ state, today, onClose, onSave, onReviewBridge }) {
  const weekOf = mondayOf(today);
  const mine = (state.reviews || []).find((r) => r.weekOf === weekOf);
  const rows = weekFactRows(weekFacts(state, weekOf));
  const [wins, setWins] = useState(mine?.wins || "");
  const [blocks, setBlocks] = useState(mine?.blocks || "");
  const [err, setErr] = useState("");
  const doneThisWeek = (state.tasks || []).reduce((n, q) => n + (q.type === "daily"
    ? (q.doneDates || []).filter((d) => d >= weekOf).length
    : q.doneAt && q.doneAt >= weekOf ? 1 : 0), 0);
  const achThisWeek = (state.areas || []).reduce((n, p) => n + (p.achievements || []).filter((a) => a.date >= weekOf).length, 0);
  const submit = () => {
    if (!wins.trim() && !blocks.trim()) { setErr("잘된 것 또는 막힌 것을 한 줄 이상 적어요."); return; }
    onSave({ wins: wins.trim(), blocks: blocks.trim() });
  };
  return (
    <Modal title={`주간 리뷰 — ${weekOf} 주`} onClose={onClose}>
      <div className="space-y-3">
        <p className="text-xs font-mono text-zinc-400">이번 주 완료 {doneThisWeek}건 · 성취 기록 {achThisWeek}건</p>
        <div className="space-y-0.5">
          {TRACKS.map((t) => (
            <p key={t} className="text-xs font-mono text-zinc-400">
              {rows[t].map((frag, i) => <span key={i}>{i > 0 && " · "}<span className="whitespace-nowrap">{frag}</span></span>)}
            </p>
          ))}
        </div>
        <textarea value={wins} onChange={(e) => setWins(e.target.value)} rows={3}
          placeholder="잘된 것 — 사실·수치로" className="w-full bg-zinc-950 border border-zinc-700 rounded-xl px-3 py-2.5 text-sm" />
        <textarea value={blocks} onChange={(e) => setBlocks(e.target.value)} rows={3}
          placeholder="막힌 것 — 원인" className="w-full bg-zinc-950 border border-zinc-700 rounded-xl px-3 py-2.5 text-sm" />
        {err && <p className="text-xs text-rose-400">{err}</p>}
        <button onClick={() => submit()} className="w-full py-3 rounded-xl bg-cyan-500 text-zinc-950 font-black text-sm">리뷰 저장</button>
        <button onClick={onReviewBridge} disabled={!mine}
          className="w-full py-2.5 rounded-xl border border-zinc-700 text-zinc-300 font-bold text-sm disabled:opacity-30">AI에게 회고 묻기 ›</button>
        {!mine && <p className="text-xs text-zinc-500">먼저 리뷰를 저장해요 — 저장된 리뷰가 패킷에 실려요.</p>}
      </div>
    </Modal>
  );
}

/* ── Toast — separate component with its own state. Showing and expiring never re-render App ── */
const ToastHost = forwardRef(function ToastHost(_, ref) {
  const [toast, setToast] = useState(null);
  const timer = useRef(null);
  useImperativeHandle(ref, () => ({
    show(t) {
      setToast(t);
      clearTimeout(timer.current);
      timer.current = setTimeout(() => setToast(null), 2600);
    },
  }), []);
  useEffect(() => () => clearTimeout(timer.current), []);
  if (!toast) return null;
  return (
    <div className="fixed bottom-16 inset-x-0 flex justify-center px-4 z-50 pointer-events-none">
      <div className="bg-zinc-900 border border-zinc-700 rounded-full px-4 py-2 text-xs font-medium text-zinc-300 shadow-lg anim-pop max-w-sm text-center">
        {toast.msg}
      </div>
    </div>
  );
});

/* ── Evidence viewer — shows the text and photo stored with a completed record (reader side of the rule 16 key convention) ── */
function EvidenceViewModal({ task, onClose }) {
  const [imgs, setImgs] = useState(null);
  useEffect(() => {
    let alive = true;
    (async () => {
      const keys = [`liferpg-img-ev-${task.id}`, `liferpg-img-study-${task.id}-1`, `liferpg-img-study-${task.id}-2`];
      const got = [];
      for (const k of keys) { const v = await store.get(k).catch(() => null); if (v) got.push(v); }
      if (alive) setImgs(got);
    })();
    return () => { alive = false; };
  }, [task.id]);
  const doc = task.isCert ? "합격증" : task.isExam ? "성적표" : task.isStudy ? "산출물" : "증거";
  return (
    <Modal title={`증거 — ${task.title}`} onClose={onClose}>
      <div className="space-y-3">
        <div className="bg-zinc-950 border border-zinc-800 rounded-xl p-3">
          <div className="text-xs text-zinc-500 mb-1">완료일 {task.doneAt || (task.doneDates || []).slice(-1)[0] || "-"}</div>
          <p className="text-sm text-zinc-200 whitespace-pre-wrap break-words">{task.evidence || "기록된 텍스트 없음"}</p>
        </div>
        {imgs === null ? (
          <p className="text-xs text-zinc-600">사진 불러오는 중...</p>
        ) : imgs.length ? (
          <div className="space-y-2">
            <div className="text-xs text-zinc-500">{doc} 사진 {imgs.length}장</div>
            {imgs.map((src, i) => (
              <img key={i} src={src} alt={`${doc} ${i + 1}`} className="w-full max-h-80 object-contain bg-zinc-950 rounded-xl border border-zinc-800" />
            ))}
          </div>
        ) : (
          <p className="text-xs text-zinc-600">첨부된 사진이 없습니다 — 텍스트 증거만 기록됐어요.</p>
        )}
      </div>
    </Modal>
  );
}

/* ── Achievement catalogue — actual payout P for certifications and exams ── */
function CatalogModal({ state, initialCat, onClose }) {
  const [mode, setMode] = useState("cert");
  const [cat, setCat] = useState(initialCat || "전체");
  const [q, setQ] = useState("");
  const [fam, setFam] = useState(EXAMS[0]);
  const hits = useMemo(() => {
    const kw = q.trim().toLowerCase();
    return CERTS.filter((c) => (cat === "전체" || c.c === cat) && (!kw || CERT_NAME_LC.get(c).includes(kw)));
  }, [cat, q]);
  const list = hits.slice(0, 60);
  const total = hits.length;
  // Certification task titles are "<name> 취득" (name + suffix), so an exact match fails — certByTitle traces the qualification back.
  const ownedCerts = useMemo(
    () => new Set(state.tasks.filter((x) => x.isCert && x.status === "done").map((x) => certByTitle(x.title)?.n).filter(Boolean)),
    [state.tasks]);
  return (
    <Modal title="성취 도감" onClose={onClose}>
      <div className="flex gap-1.5 mb-3">
        <Chip on={mode === "cert"} onClick={() => setMode("cert")}>자격증 {CERTS.length}</Chip>
        <Chip on={mode === "exam"} onClick={() => setMode("exam")}>시험 {EXAMS.length}</Chip>
      </div>
      {mode === "cert" ? (<>
        <input value={q} onChange={(e) => setQ(e.target.value)} placeholder="자격증 검색"
          className="w-full bg-zinc-950 border border-zinc-700 rounded-xl px-3 py-2.5 text-sm mb-2" />
        <div className="flex gap-1.5 overflow-x-auto pb-2">
          {["전체", ...CERT_CATS].map((c) => (
            <button key={c} onClick={() => setCat(c)}
              className={`shrink-0 px-2.5 py-1.5 rounded-lg text-xs font-semibold border ${cat === c ? "bg-zinc-100 text-zinc-950 border-zinc-200" : "bg-zinc-950 text-zinc-500 border-zinc-700"}`}>
              {c}
            </button>
          ))}
        </div>
        <div className="space-y-1.5 mt-1">
          {list.map((c) => {
            const gain = certGainOf(state, c);
            const base = certP(c.d);
            const owned = ownedCerts.has(c.n);
            return (
              <div key={c.n} className="flex items-center justify-between gap-2 bg-zinc-950 rounded-xl px-3 py-2.5">
                <div className="min-w-0">
                  <div className="text-sm font-semibold truncate">{c.n}</div>
                  <div className="text-xs text-zinc-600">{c.c} · {c.l}</div>
                </div>
                <div className="text-right shrink-0">
                  <div className="text-xs font-mono text-zinc-400">D{c.d} <CertBadge g={achGrade(c.d)} /></div>
                  <div className={`text-xs font-mono ${owned ? "text-emerald-400" : gain > 0 ? "text-amber-300" : "text-zinc-600"}`}>
                    {owned ? "취득 완료" : gain > 0 ? `+${gain.toLocaleString()}P${gain < base ? " 차액" : ""}` : "0P · 보유 단계 이하"}
                  </div>
                </div>
              </div>
            );
          })}
          {list.length === 0 && <p className="text-xs text-zinc-600 text-center py-3">검색 결과 없음</p>}
          {total > list.length && <p className="text-xs text-zinc-600 text-center py-2">{total - list.length}종 더 있음 — 검색어로 좁혀요</p>}
        </div>
      </>) : (<>
        <div className="flex gap-1.5 overflow-x-auto pb-2">
          {EXAMS.map((e) => (
            <button key={e.id} onClick={() => setFam(e)}
              className={`shrink-0 px-2.5 py-1.5 rounded-lg text-xs font-semibold border ${fam?.id === e.id ? "bg-zinc-100 text-zinc-950 border-zinc-200" : "bg-zinc-950 text-zinc-500 border-zinc-700"}`}>
              {e.n}
            </button>
          ))}
        </div>
        <div className="text-xs text-zinc-600 mb-2">{fam.cat} · 내 최고: <b className="text-cyan-300 font-mono">{state.exams?.best?.[fam.id]?.label || "없음"}</b></div>
        <div className="space-y-1.5">
          {fam.bands.map((b) => {
            const { band, payout, mult } = examBandGain(state, fam, b);
            const owned = (state.exams?.best?.[fam.id]?.p || 0) >= band.p;
            return (
              <div key={band.label} className="flex items-center justify-between gap-2 bg-zinc-950 rounded-xl px-3 py-2">
                <span className="text-sm font-semibold w-14">{band.label}</span>
                <span className="text-xs font-mono text-zinc-500">D{band.d}</span>
                <span className={`text-xs font-mono ${owned ? "text-zinc-600" : "text-amber-300"}`}>
                  {owned ? "보유" : `+${payout.toLocaleString()}P${mult < 1 ? ` ×${mult}` : ""}`}
                </span>
              </div>
            );
          })}
        </div>
      </>)}
      <p className="text-xs text-zinc-600 mt-3">표시된 P는 내 기록 기준 실지급액입니다(차액·감쇠 반영). 자격은 완료 시 등록 영역의 직무 가중(S/A/B = ×1.0/0.8/0.5, C 무관 = 지급 0)이 곱해집니다. 등록은 목표에 자격·시험 KR을 추가한 뒤, 실행 모달의 원클릭 연결로 합니다.</p>
    </Modal>
  );
}

/* ── Role-model direction advice ── */
/* The current stage, its conditions with a bar each, the progress and journey figures, and the next milestone — the
   advice sheet's stage block and the business area's gap block print the same lines. Every line is derived at render
   (rule 9); unmet conditions are rose, met emerald. `sp` is `stageProgressOf`, whose `conds` carry each ratio; the
   journey figure is printed here and nowhere else. */
function RoleStageLines({ state, sp, today }) {
  const rs = sp.rs;
  const next = (state.milestones || []).filter((m) => m.status !== "done").sort(milestoneOrder)[0];
  return (
    <div className="space-y-1">
      <div className="text-xs text-zinc-300">
        {rs.current
          ? <><span className="font-mono">{rs.k}/{rs.n}</span>단계 · {rs.current.s.name}</>
          : <>전환 조건 충족 — <span className="font-mono">{rs.n}/{rs.n}</span>단계</>}
      </div>
      {sp.conds.map((r, j) => (
        <div key={j}>
          <div className={`text-xs font-mono ${r.met ? "text-emerald-400" : "text-rose-400"}`}>- {r.text}</div>
          <Bar ratio={r.ratio} color={r.met ? "bg-emerald-400" : "bg-rose-400"} h="h-1" />
        </div>
      ))}
      <div className="text-xs font-mono text-zinc-400">진행 {sp.pct}% · 전체 {sp.journey}%</div>
      <div className="text-xs font-mono text-zinc-500">{stageLine(rs)}</div>
      <div className="text-xs text-zinc-500">
        {next ? <>다음 마일스톤: {milestoneLine(state, next, today)}</> : "다음 마일스톤 없음 — 로드맵에서 추가해요"}
      </div>
    </div>
  );
}

function RoleAdviceModal({ state, today, onClose, onOpenCatalog, onSetDir, onOpenRoadmap, onAskVerdict }) {
  const { rg, gaps } = roleRecommendations(state);
  const sp = stageProgressOf(state, today);
  const verdicts = (state.role?.verdicts || []).slice(0, ROLE_VERDICTS_MAX);
  // Verdict history (2026-09-18): the entry to the fifth packet — the story is the one text sent verbatim, so without
  // it the button is off — then the delta between the two newest verdicts and the dated list, newest first. Every line
  // is the AI's own statement, labelled as unverified; the app adds nothing to it.
  const stageText = (v) => `단계 ${Math.min(v.stageK, v.stageN)}/${v.stageN}`;
  const pctText = (p) => (Number.isFinite(p) ? `${p}%` : "확률 미제시");
  const delta = verdicts.length >= 2 ? { a: verdicts[1], b: verdicts[0] } : null;
  const verdictBlock = (
    <div className="bg-zinc-950 rounded-xl p-3 mb-3">
      <SectionLabel>AI 판정 기록</SectionLabel>
      <button onClick={onAskVerdict} disabled={!state.role?.story}
        className="px-2.5 py-1 rounded-lg border border-zinc-700 text-xs text-zinc-300 active:opacity-70 disabled:opacity-30">AI에게 판정 묻기 ›</button>
      {!state.role?.story && <p className="text-xs text-zinc-600 mt-1">먼저 롤모델 설정에서 원하는 모습을 적어요 — 적은 글이 패킷에 실려요.</p>}
      {delta && (
        <div className="font-mono text-xs text-cyan-300 mt-2">
          확률 {pctText(delta.a.probability)} → {pctText(delta.b.probability)} ({delta.a.date} → {delta.b.date}) · 단계 {Math.min(delta.a.stageK, delta.a.stageN)} → {Math.min(delta.b.stageK, delta.b.stageN)}
        </div>
      )}
      {verdicts.length ? (
        <div className="mt-2 space-y-2">
          {verdicts.map((v, i) => (
            <div key={v.id}>
              <div className="text-xs font-mono text-zinc-500">AI 판단 · 검증되지 않음 · {v.date}</div>
              <div className="text-xs font-mono text-zinc-300">{probText(v.probability)} · {stageText(v)}</div>
              <div className="text-xs text-zinc-300 break-words">{v.summary || "요약 없음"}</div>
              {i === 0 && (
                <>
                  <div className="text-xs text-zinc-400 break-words">근거: {v.basis || "없음"}</div>
                  <div className="text-xs text-zinc-400 break-words">현재 위치: {v.position || "없음"}</div>
                  {(v.gaps || []).map((g, j) => <div key={j} className="text-xs text-zinc-400 break-words">- {g}</div>)}
                </>
              )}
            </div>
          ))}
        </div>
      ) : (
        <p className="text-xs text-zinc-500 mt-2">AI 판정 없음</p>
      )}
    </div>
  );
  // The one surface that draws and explains the proximity bars, one tap from the home line that states the number (rule 14).
  const legend = <p className="text-xs text-zinc-600">칸 하나 = 등급 한 단계, 칸 너비 = 그 단계의 비중. 하위 등급은 좁고 상위 등급은 넓어, 상위 승급 없이는 근접도가 오르지 않습니다. 롤모델 요구에 없는 영역의 활동은 반영되지 않습니다.</p>;
  return (
    <Modal title={`방향 제안 — ${rg?.name || "롤모델"}`} onClose={onClose}>
      {/* Per-area requirement lines and segmented bars, moved from the growth headline, with the legend once under them */}
      <div className="space-y-2 mb-3">
        {(rg?.items || []).map((i) => (
          <div key={i.area.id}>
            <div className="flex items-center justify-between gap-2 text-xs">
              <span className="text-zinc-100 font-medium truncate">{i.area.name}</span>
              <span className={`font-mono text-right shrink-0 ${i.gap === 0 ? "text-emerald-400" : "text-rose-400"}`}>
                {RANKS[i.have].name} / 요구 {RANKS[i.need].name}{i.gap > 0 ? ` · ${i.gap}단계 부족` : " · 충족"}
              </span>
            </div>
            {/* Cell widths are the squared curve itself — the same formula as `roleGap` (rule 14) */}
            <div className="flex h-2 gap-0.5 mt-1">
              {Array.from({ length: i.need }, (_, k) => {
                const w = (Math.pow((k + 1) / i.need, 2) - Math.pow(k / i.need, 2)) * 100;
                return (
                  <div key={k} style={{ width: `${w}%` }}
                    className={`rounded border ${k < Math.min(i.have, i.need) ? "bg-cyan-400 border-cyan-300" : "bg-zinc-900 border-zinc-800"}`} />
                );
              })}
            </div>
          </div>
        ))}
        {legend}
      </div>
      {sp && (
        <div className="bg-zinc-950 rounded-xl p-3 mb-3">
          <SectionLabel>단계</SectionLabel>
          <RoleStageLines state={state} sp={sp} today={today} />
          <button onClick={onOpenRoadmap}
            className="mt-2 px-2.5 py-1 rounded-lg border border-zinc-700 text-xs text-zinc-300 active:opacity-70">로드맵 열기 ›</button>
        </div>
      )}
      {verdictBlock}
      {gaps.length === 0 ? (
        <div className="space-y-2">
          <p className="text-sm text-zinc-400">모든 요구 영역을 충족했습니다. 근접도 {rg?.match}%.</p>
        </div>
      ) : (
        <div className="space-y-3">
          {gaps.map((i) => {
            const { h, recs, examRecs } = i;
            // With stages, the business area is advanced by records, not certifications: the stage lines replace them
            const staged = sp && i.area.name === "사업";
            return (
              <div key={i.area.id} className="bg-zinc-950 rounded-xl p-3">
                <div className="flex items-center justify-between gap-2 text-sm">
                  <span className="font-bold">{i.area.name}</span>
                  <span className="font-mono text-xs text-rose-400 shrink-0">{RANKS[i.have].name} → {RANKS[i.need].name} · {i.gap}단계</span>
                </div>
                <div className="text-xs text-zinc-600 mt-1">다음 관문: {RANKS[i.have + 1].name} 승급 — 이 영역의 성취·증거가 필요합니다.</div>
                {staged && <div className="mt-2"><RoleStageLines state={state} sp={sp} today={today} /></div>}
                <div className="flex flex-wrap gap-1 mt-2">
                  {JOB_FIELDS.map((d) => {
                    const on = normDirs(i.area).includes(d);
                    return (
                      <button key={d}
                        onClick={() => onSetDir(i.area.id, on ? (i.area.dir || []).filter((x) => x !== d && DIR_ALIAS[x] !== d) : [...(i.area.dir || []), d])}
                        className={`px-2 py-0.5 rounded text-xs border ${on ? "bg-cyan-500 text-zinc-950 border-cyan-400" : "bg-zinc-900 text-zinc-500 border-zinc-800"}`}>
                        {d}
                      </button>
                    );
                  })}
                </div>
                <p className="text-xs text-zinc-700 mt-1">복수 선택 시 교집합으로 평가합니다 — 지정한 모든 직무에서 통하는 자격이 상위에 옵니다.</p>
                {!staged && recs.length > 0 && (
                  <div className="mt-2 space-y-1">
                    {recs.map(({ c, jw, gain }) => (
                      <div key={c.n} className="flex items-center justify-between gap-2 text-xs">
                        <span className="text-zinc-300 truncate">
                          {jw && <span className={`mr-1 font-mono font-bold ${TIER_CLS[jw.tier]}`}>{jw.tier}</span>}{c.n}
                        </span>
                        <span className="font-mono text-zinc-500 shrink-0">D{c.d} · <span className="text-amber-300">+{gain.toLocaleString()}P</span></span>
                      </div>
                    ))}
                  </div>
                )}
                {!staged && examRecs.length > 0 && (
                  <div className="mt-2 space-y-1">
                    {examRecs.map(({ e, band, payout }) => (
                      <div key={e.id} className="flex items-center justify-between gap-2 text-xs">
                        <span className="text-zinc-300 truncate">{e.n} {band.label} — 다음 밴드</span>
                        <span className="font-mono text-zinc-500 shrink-0">D{band.d} · <span className="text-amber-300">+{payout.toLocaleString()}P</span></span>
                      </div>
                    ))}
                  </div>
                )}
                {!staged && recs.length === 0 && examRecs.length === 0 && (
                  <p className="text-xs text-zinc-600 mt-2">매칭되는 표준 성취가 없습니다 — 이 영역은 프로젝트·실적 증거로 승급을 진행하세요.</p>
                )}
                {!staged && h.cats.length > 0 && (
                  <button onClick={() => onOpenCatalog(i.area.dir?.length === 1 ? h.cats[0] : null)} className="mt-2 text-xs text-cyan-300">도감에서 더 보기 ›</button>
                )}
              </div>
            );
          })}
          <p className="text-xs text-zinc-600">추천은 직무 분야 매칭과 직무 가중 기준입니다.</p>
        </div>
      )}
    </Modal>
  );
}

/* ───────────────────────── Tasks tab — one time-ordered list of tasks, schedule and business rows ───────────────────────── */
const TODO_TONE = { overdue: "text-rose-400", today: "text-amber-300", tomorrow: "text-zinc-400", week: "text-zinc-400", later: "text-zinc-500" };
const TODO_DONE_MAX = 40; // rows the `완료` archive keeps, newest first — the count line still states the full total

const LEAD_DONE = "text-emerald-400 border-emerald-800";
const LEAD_TODAY = "text-amber-300 border-amber-700";
const LEAD_NONE = "text-zinc-500 border-zinc-700";
/* The one lead chip of a to-do row, `{ text, tone }`, derived at render (rule 9); first match wins. `r` is a `todoOf`
   row (`{ kind, date, time, task | ev, done }`); `archived` marks a row of the `완료` view. */
const todoLeadOf = (r, today, archived = false) => {
  const q = r.kind === "task" ? r.task : null;
  if (archived) return { text: ((q ? lastDoneDate(q) : r.date) || "").slice(5) || "날짜 없음", tone: LEAD_DONE };
  const doneToday = q ? (q.type === "daily" ? (q.doneDates || []).includes(today) : q.status === "done") : false;
  if (r.done || doneToday) return { text: "완료", tone: LEAD_DONE };
  // Today's group already names the day, so a timed appointment of today leads with its clock time instead.
  if (r.kind === "event" && r.ev?.kind !== "due" && r.date === today && r.time) return { text: r.time, tone: LEAD_TODAY };
  if (r.date) {
    if (r.date < today) return { text: "기한 지남", tone: "text-rose-400 border-rose-800" };
    if (r.date === today) return { text: ddayStr(r.date), tone: LEAD_TODAY };
    return { text: ddayStr(r.date), tone: "text-zinc-400 border-zinc-700" };
  }
  return { text: q?.type === "daily" ? "매일" : "기한 없음", tone: LEAD_NONE };
};

/* One to-do row for every kind: the lead chip, the title and at most one marker. The row is a single button that
   opens the item's detail sheet — it holds no checkbox, no nested control and no completion path of its own. The
   meetings tab reuses the same shell for its minutes rows (date chip, title, no marker). */
function TodoRow({ lead, title, done = false, marker = null, onOpen }) {
  return (
    <button onClick={onOpen}
      className={`w-full text-left flex items-center gap-2.5 bg-zinc-950 rounded-xl px-3 py-2.5 active:opacity-70 ${done ? "opacity-50" : ""}`}>
      <span className={`font-mono text-xs font-bold border rounded-lg px-1.5 py-1 bg-zinc-900 shrink-0 ${lead.tone}`}>{lead.text}</span>
      <div className={`flex-1 min-w-0 text-sm font-semibold truncate ${done ? "line-through" : ""}`}>{title}</div>
      {marker}
    </button>
  );
}

const NO_GOAL_MARKER = <span className="text-xs text-zinc-600 shrink-0">목표 기여 없음</span>;

/* The list is a view over `todoOf`: the groups, their order and the sort are decided there, so this component only
   builds one compact row per item. Every row opens a detail sheet; completion is reachable only from the task sheet,
   which calls `tryComplete` (rules 10, 16, 17). An event sheet keeps the schedule's own buttons (they pay nothing and
   move no goal) and a business sheet has no control but a link into `사업` (rules 1, 18). A row that serves no goal
   says so (rule 13). New tasks are created in `목표` only (rules 18, 19). */
function TaskTab({ state, today, onOpenTask, onOpenEvent, onOpenBiz, onCatalog, onGoGoals, onGoBiz, onBriefing }) {
  const [view, setView] = useState("todo"); // open list or completed archive — a view preference, never stored (rule 9)
  const td = useMemo(() => todoOf(state, today), [state, today]);
  const biz = useMemo(() => bizSummary(state, today), [state, today]);
  // The archive: completed tasks, dated by their last completion, and every ticked event occurrence, dated by the
  // occurrence — one list, newest first. Derived at render, never stored (rule 9).
  const doneAll = useMemo(() => [
    ...(state.tasks || [])
      .filter((q) => (q.type === "daily" ? (q.doneDates || []).length : q.status === "done"))
      .map((q) => ({ key: `t:${q.id}`, kind: "task", date: lastDoneDate(q), title: q.title, task: q, done: true })),
    ...(state.events || []).flatMap((ev) => (ev.doneDates || [])
      .map((d) => ({ key: `e:${ev.id}-${d}`, kind: "event", date: d, title: ev.title || "", ev, done: true }))),
  ].sort((a, b) => (b.date || "").localeCompare(a.date || "") || a.title.localeCompare(b.title)), [state.tasks, state.events]);
  const doneShown = doneAll.slice(0, TODO_DONE_MAX);
  const activeGoals = (state.goals || []).filter((g) => g.status === "active");
  // A task row's marker: the goal marker when its goal is gone, otherwise a lock on an open gated task — tapping it
  // leads to an evidence gate, not a one-tap completion (rules 10, 16).
  const taskMarker = (q, closed) => {
    if (!(q.goalId && state.goals.some((g) => g.id === q.goalId))) return NO_GOAL_MARKER;
    if (!closed && (q.isCert || q.isExam || q.isStudy || needsEvidence(q))) return <Lock size={13} className="text-zinc-500 shrink-0" aria-label="증거 필요" />;
    return null;
  };
  const rowOf = (r) => {
    const lead = todoLeadOf(r, today);
    if (r.kind === "task") {
      const q = r.task;
      const closed = !!r.done || (q.type === "daily" ? (q.doneDates || []).includes(today) : q.status === "done");
      return <TodoRow key={r.key} lead={lead} title={q.title} done={closed} marker={taskMarker(q, closed)} onOpen={() => onOpenTask(q.id)} />;
    }
    if (r.kind === "event") {
      return <TodoRow key={r.key} lead={lead} title={r.title} done={!!r.done} marker={NO_GOAL_MARKER} onOpen={() => onOpenEvent(r.ev.id, r.date)} />;
    }
    return <TodoRow key={r.key} lead={lead} title={r.title} marker={NO_GOAL_MARKER} onOpen={() => onOpenBiz(r)} />;
  };
  const onlyBiz = td.counts.open > 0 && td.groups.every((g) => g.rows.every((r) => r.done || r.kind === "biz"));

  return (
    <>
      <section className="bg-zinc-900 border border-zinc-800 rounded-2xl p-4">
        <div className="flex items-center justify-between gap-2">
          <div className="min-w-0">
            <SectionLabel tone="text-zinc-400">할 일 — 시간순</SectionLabel>
            <p className="text-xs text-zinc-600 mt-0.5">실행·일정·사업을 시간순으로 모아요. 항목을 누르면 상세가 열려요. 새 실행은 목표 탭에서 만들어요.</p>
          </div>
          <button onClick={onCatalog}
            className="shrink-0 px-3 py-2 rounded-xl border border-zinc-700 text-zinc-300 text-xs font-bold active:translate-y-0.5">도감</button>
        </div>
        <p className="text-xs font-mono text-zinc-400 mt-2">
          기한 지남 {td.counts.overdue} · 오늘 {td.counts.today} · 이번 주 {td.counts.week}
        </p>
        {/* The list names at most BIZ_ALERT_MAX business months and no undated quote at all, so the full counts
            stay on screen and the cap can never hide an outstanding payment (rule 13). */}
        {(biz.counts.unpaid > 0 || biz.counts.quote > 0) && (
          <button onClick={onGoBiz} className="block text-left text-xs font-mono text-zinc-400 mt-1 active:opacity-70">
            사업 <span className={biz.counts.unpaid > 0 ? "text-rose-400" : ""}>입금 미확인 {biz.counts.unpaid}건</span> · 견적 대기 {biz.counts.quote}건 ›
          </button>
        )}
        {/* The manual way back into the briefing once its daily auto-open is dismissed — and through it the journal,
            the weekly review and the assistant bridge. It sits on this tab because the briefing opens with today's tasks. */}
        <div className="flex items-center justify-between gap-2 mt-2.5">
          <div className="flex gap-1.5">
            <Chip on={view === "todo"} onClick={() => setView("todo")}>할 일</Chip>
            <Chip on={view === "done"} onClick={() => setView("done")}>완료</Chip>
          </div>
          <button onClick={onBriefing}
            className="shrink-0 px-3 py-1.5 rounded-xl border border-zinc-700 text-zinc-300 text-xs font-bold">브리핑 열기 ›</button>
        </div>
      </section>

      {view === "todo" ? (
        <>
          {td.counts.open === 0 && (
            <section className="bg-zinc-900 border border-zinc-800 rounded-2xl p-6 text-center">
              <EmptyQuestSvg />
              {activeGoals.length === 0 ? (
                <>
                  <p className="text-sm text-zinc-500">실행은 목표의 실행 단위입니다 — 목표가 먼저예요.</p>
                  <button onClick={onGoGoals} className="mt-3 px-4 py-2 rounded-xl bg-cyan-500 text-zinc-950 text-xs font-black">목표 먼저 세우기 ›</button>
                </>
              ) : (
                <p className="text-sm text-zinc-500">예정된 항목이 없어요 — 실행·일정·사업 모두 0건이에요.</p>
              )}
            </section>
          )}

          {td.groups.map((g) => g.rows.length > 0 && (
            <section key={g.key} className="bg-zinc-900 border border-zinc-800 rounded-2xl p-4">
              <SectionLabel tone={TODO_TONE[g.key]}>{g.label}</SectionLabel>
              <div className="space-y-1.5">{g.rows.map(rowOf)}</div>
            </section>
          ))}

          {/* Business rows complete nothing, so a list made only of them is not a list of open work */}
          {onlyBiz && <p className="text-xs text-zinc-500">완료할 실행·일정이 없어요 — 남은 항목은 사업 기록이에요.</p>}

        </>
      ) : (
        /* The archive keeps `증거 보기` reachable (inside the task sheet) for anything completed before today; a ticked
           event occurrence opens its event sheet for that date, which pays nothing and moves no goal (rule 1) */
        <section className="bg-zinc-900 border border-zinc-800 rounded-2xl p-4">
          <p className="text-xs font-mono text-zinc-400">완료 {doneAll.length}건 · 최근 {doneShown.length}건</p>
          {doneShown.length === 0
            ? <p className="text-sm text-zinc-500 text-center py-3">완료한 항목이 없어요.</p>
            : <div className="space-y-1.5 mt-2.5">{doneShown.map((r) => (r.kind === "task"
              ? <TodoRow key={r.key} lead={todoLeadOf(r, today, true)} title={r.title} done
                marker={taskMarker(r.task, true)} onOpen={() => onOpenTask(r.task.id)} />
              : <TodoRow key={r.key} lead={todoLeadOf(r, today, true)} title={r.title} done
                marker={NO_GOAL_MARKER} onOpen={() => onOpenEvent(r.ev.id, r.date)} />
            ))}</div>}
        </section>
      )}
    </>
  );
}

/* ── Task detail sheet — everything a compact row leaves out, and the one place a task completes. `완료하기` calls
   `onComplete`, which the root wires to `tryComplete` and nothing else, so the study, activity and evidence gates
   stay exactly where they were (rules 10, 11, 16, 17). A closed task (done today, or a finished once task) shows no
   completion control: the archive stays a record. The sheet reads the live task, so it disappears with it. ── */
function TaskDetailModal({ state, taskId, today, onClose, onComplete, onRemove, onViewEvidence, onOpenMeeting }) {
  const q = (state.tasks || []).find((x) => x.id === taskId);
  if (!q) return null;
  const minutes = meetingsOfTask(state, q.id); // derived at render; the section is hidden when empty
  const daily = q.type === "daily";
  const doneToday = daily && (q.doneDates || []).includes(today);
  const closed = daily ? doneToday : q.status === "done";
  const goal = q.goalId ? (state.goals || []).find((g) => g.id === q.goalId) : null;
  const area = (state.areas || []).find((x) => x.id === q.areaId);
  const status = daily
    ? <>매일 · 완료 <span className="font-mono">{(q.doneDates || []).length}회</span>{doneToday ? " · 오늘 완료" : ""}</>
    : q.status === "done" ? <>완료 <span className="font-mono">{q.doneAt || "날짜 없음"}</span></> : "할 일";
  const due = q.due
    ? <span className="font-mono">{q.due} · {q.due < today ? "기한 지남" : ddayStr(q.due)}</span>
    : daily ? "매일" : "기한 없음";
  const type = q.isCert ? "자격 마일스톤" : q.isExam ? "시험 마일스톤" : q.isStudy ? "📖 학습"
    : q.kind === "book" ? "📚 독서" : q.kind === "fit" ? "💪 운동" : "일반";
  const jw = q.isCert ? jobWeightForCert(state, q.areaId, certByTitle(q.title)) : null;
  const diff = q.isCert ? (
    <span className="inline-flex items-center gap-1.5">
      <CertBadge g={q.certD != null ? achGrade(q.certD) : legacyCertGrade(q.pts ?? 0)} />
      {q.certD != null && <span className="font-mono">D{q.certD}</span>}
      {jw && <span> · 직무 적합 <b className={`font-mono ${TIER_CLS[jw.tier]}`}>{jw.tier}</b></span>}
    </span>
  ) : q.isExam ? (
    <span>{examOf(q.famId)?.n || q.famId} {q.band?.label} 구간 · <span className="font-mono">D{q.band?.d}</span></span>
  ) : <DiffBadge d={q.diff} />;
  const evidence = q.isCert ? "합격증 사진 필수" : q.isExam ? "성적표 사진 + 점수 필수" : q.isStudy ? `산출물 검증 — ${q.diff}급 기준`
    : q.kind === "book" ? "독후감 기록" : q.kind === "fit" ? "운동 기록" : needsEvidence(q) ? "증거 필요" : "없음";
  return (
    <Modal title={q.title} onClose={onClose}>
      <div className="space-y-3">
        <div className="space-y-1.5">
          <CvFact label="상태">{status}</CvFact>
          <CvFact label="기한">{due}</CvFact>
          <CvFact label="목표" wrap>{goal ? goal.title : "목표 기여 없음"}</CvFact>
          <CvFact label="영역">{area?.name || "영역 없음"}</CvFact>
          <CvFact label="유형">{type}</CvFact>
          <CvFact label="난이도" wrap>{diff}</CvFact>
          <CvFact label="증거" wrap>{evidence}</CvFact>
          {q.score && <CvFact label="점수" wrap><span className="font-mono">{q.score}</span></CvFact>}
          {q.evidence && (
            <CvFact label="증거 기록" wrap>
              {q.evidence}{" "}
              <button onClick={() => onViewEvidence(q)} className="underline underline-offset-2 text-zinc-400">증거 보기</button>
            </CvFact>
          )}
        </div>
        {minutes.length > 0 && (
          <div>
            <SectionLabel>관련 회의록</SectionLabel>
            <div className="space-y-1.5">
              {minutes.map((m) => (
                <TodoRow key={m.id} lead={{ text: m.date, tone: "text-zinc-400 border-zinc-700" }} title={m.title}
                  onOpen={() => onOpenMeeting(m.id)} />
              ))}
            </div>
          </div>
        )}
        {!closed && (
          <button onClick={() => onComplete(q)}
            className="w-full py-3 rounded-xl bg-cyan-500 text-zinc-950 text-sm font-black active:translate-y-0.5">완료하기</button>
        )}
        <button onClick={() => onRemove(q.id)}
          className="w-full py-2.5 rounded-xl border border-rose-800 text-rose-300 text-sm font-bold active:translate-y-0.5">삭제</button>
      </div>
    </Modal>
  );
}

/* ── Event detail sheet — one occurrence, opened from the to-do list. Its only actions are the schedule's own
   `EventRow` buttons: an event is a record that pays nothing and moves no goal (rules 1, 13). ── */
function EventDetailModal({ state, eventId, date, today, onClose, onToggleDone, onSkip, onEdit, onAddCheck, onToggleCheck, onRemoveCheck }) {
  const ev = (state.events || []).find((x) => x.id === eventId);
  if (!ev) return null;
  // The `확인할 것` checklist (v27) belongs to an event of a meeting project only; a plain appointment's sheet is unchanged.
  const project = eventProjectOf(state, ev);
  return (
    <Modal title={`일정 — ${ev.title}`} onClose={onClose}>
      <div className="space-y-3">
        <EventRow ev={ev} date={date} done={(ev.doneDates || []).includes(date)} today={today}
          onToggleDone={onToggleDone} onSkip={onSkip} onEdit={onEdit} />
        {project && (
          <>
            <p className="text-xs text-zinc-500 break-words">프로젝트 · {project.name}</p>
            <EventChecks ev={ev} onAdd={onAddCheck} onToggle={onToggleCheck} onRemove={onRemoveCheck} />
          </>
        )}
        <p className="text-xs text-zinc-500">목표 기여 없음 — 일정은 기록이라 점수와 목표에 반영되지 않아요.</p>
      </div>
    </Modal>
  );
}

/* ── Business detail sheet — a render-time snapshot of one `todoOf` business row, held in the modal slot and never
   stored (rule 9). No payment control: the payment chip stays in `사업` (rules 1, 18). ── */
function BizTodoModal({ row, onClose, onOpen }) {
  return (
    <Modal title={`사업 — ${row.title}`} onClose={onClose}>
      <div className="space-y-3">
        <CvFact label="월"><span className="font-mono">{row.month}</span></CvFact>
        <p className="text-xs text-zinc-400 break-words">{row.text}</p>
        <button onClick={onOpen}
          className="w-full py-2.5 rounded-xl border border-zinc-700 text-zinc-300 text-sm font-bold active:translate-y-0.5">사업 탭에서 보기 ›</button>
      </div>
    </Modal>
  );
}

function AddTaskModal({ areas, exams, certBest, tasks, goalId, goal, onClose, onAdd }) {
  const [mode, setMode] = useState("normal");
  const [title, setTitle] = useState("");
  const [kind, setKind] = useState("");
  const [krId, setKrId] = useState(null); // which count KR this task fills — form state only, never part of the task (rule 9)
  const [diff, setDiff] = useState("D");
  const [type, setType] = useState("daily");
  const [sDiff, setSDiff] = useState("D");
  const [sScope, setSScope] = useState("");
  const [due, setDue] = useState("");
  const [err, setErr] = useState("");
  const areaId = goal?.areaId || areas[0]?.id;
  const areaName = areas.find((p) => p.id === areaId)?.name || "—";
  const gk = goalKinds(goal);
  const kindChips = [["book", "📚 독서"], ["fit", "💪 운동"]];
  const scoped = kindChips.filter(([k]) => gk.kinds.has(k));
  // A goal that matches no kind keyword (a revenue goal with only a metric KR, for example) would have no chip to pick, so an empty scope falls back to both kinds.
  const kindOpts = scoped.length ? scoped : kindChips;
  const hasExamQ = (famId, label) => (tasks || []).some((q) => q.goalId === goalId && q.isExam && q.famId === famId && q.band?.label === label);
  const hasCertQ = (name) => (tasks || []).some((q) => q.isCert && q.title.includes(name));

  const addExamKR = (kr) => {
    const fam = examOf(kr.famId);
    onAdd({ goalId, title: `${fam?.n || "시험"} ${kr.band.label} 달성`, areaId, diff: scoreTier(kr.band.p), pts: kr.band.p, type: "once", ...(goal?.deadline ? { due: goal.deadline } : {}), isExam: true, famId: kr.famId, band: kr.band });
  };
  const addCertKR = (c) => {
    onAdd({ goalId, title: `${c.n} 취득`, areaId, diff: scoreTier(certP(c.d)), pts: certP(c.d), certD: c.d, ...(c.sg ? { sg: c.sg } : {}), type: "once", ...(goal?.deadline ? { due: goal.deadline } : {}), isCert: true });
  };
  const fillCount = (kr) => {
    setMode("normal"); setTitle(kr.title);
    setKind(detectKind(kr.title)); setDiff("E"); setType("daily"); setErr(""); setKrId(kr.id);
  };
  const submitNormal = () => {
    setErr("");
    if (!title.trim()) { setErr("실행 이름을 입력해 주세요."); return; }
    const dk = detectKind(title);
    const nm = { book: "📚 독서", fit: "💪 운동" };
    if (dk && kind && dk !== kind) { setErr(`제목은 ${nm[dk]} 활동으로 보이는데 유형이 ${nm[kind]}(으)로 선택돼 있어요 — 맞춰 주세요.`); return; }
    const ek = kind || dk;
    // A count KR is the goal's own measured action, so the task that fills it is the one task a goal takes without an activity kind.
    if (!ek && !krId) { setErr("활동 유형을 골라 주세요 — 📚 독서·💪 운동만 목표에 등록돼요. 공부는 '학습', 자격·시험은 핵심결과, 약속·미팅은 일정 탭에서 만들어요."); return; }
    onAdd({ goalId, ...(ek ? { kind: ek } : {}), title: title.trim(), areaId, diff, pts: DIFFS[diff].pts, type, ...(due && type === "once" ? { due } : {}) });
  };
  const submitStudy = () => {
    setErr("");
    if (!title.trim()) { setErr("책·논문·강의명을 입력해 주세요."); return; }
    onAdd({ goalId, title: title.trim(), areaId, diff: sDiff, pts: DIFFS[sDiff].pts, type: "once", ...(due ? { due } : {}), isStudy: true, source: title.trim(), scope: sScope.trim() || undefined });
  };

  return (
    <Modal title="실행 추가" onClose={onClose}>
      <div className="space-y-4">
        <div className="bg-zinc-950 border border-cyan-900 rounded-xl px-3 py-2.5">
          <div className="text-sm font-bold text-cyan-300 truncate">🎯 {goal?.title || "목표"}</div>
          <div className="text-xs text-zinc-500 mt-0.5">영역: {areaName} (목표에서 상속)</div>
        </div>

        {goal?.krs?.length > 0 && (
          <div className="bg-zinc-950 rounded-xl p-3">
            <div className="text-xs font-bold tracking-widest text-zinc-500 mb-2">이 목표의 핵심결과 — 클릭해서 바로 연결</div>
            <div className="space-y-1.5">
              {goal.krs.map((kr) => {
                if (kr.type === "exam") {
                  const fam = examOf(kr.famId);
                  const achieved = (exams?.best?.[kr.famId]?.p || 0) >= (kr.band?.p || 0);
                  const reg = hasExamQ(kr.famId, kr.band?.label);
                  return (
                    <button key={kr.id} disabled={achieved || reg} onClick={() => addExamKR(kr)}
                      className={`w-full flex items-center justify-between gap-2 rounded-lg px-3 py-2 text-xs border ${
                        achieved || reg ? "border-zinc-800 text-zinc-600" : "border-zinc-800 text-zinc-300 active:translate-y-0.5"}`}>
                      <span className="truncate">🎓 {fam?.n} {kr.band?.label} — 시험 마일스톤 · <span className="font-mono">D{kr.band?.d}</span></span>
                      <span className={`font-mono font-bold shrink-0 ${achieved || reg ? "text-zinc-600" : "text-sky-300"}`}>{achieved ? "달성" : reg ? "등록됨" : "등록 ›"}</span>
                    </button>
                  );
                }
                if (kr.type === "cert") {
                  const c = certOf(kr.certName) || certByTitle(kr.certName);
                  if (!c) return <div key={kr.id} className="text-xs text-zinc-600 px-1">📜 {kr.certName} — 도감에 없는 명칭이라 자동 연결 불가(KR 이름을 표준 명칭으로 맞춰 주세요)</div>;
                  const reg = hasCertQ(kr.certName);
                  const jw = jobWeightForCert({ areas }, areaId, c);
                  const gain = Math.round(certGainOf({ certBest }, c) * (jw?.mult ?? 1) / 10) * 10;
                  return (
                    <button key={kr.id} disabled={kr.done || reg} onClick={() => addCertKR(c)}
                      className={`w-full flex items-center justify-between gap-2 rounded-lg px-3 py-2 text-xs border ${
                        kr.done || reg ? "border-zinc-800 text-zinc-600" : "border-zinc-800 text-zinc-300 active:translate-y-0.5"}`}>
                      <span className="truncate">📜 {c.n} — 자격 마일스톤{jw ? <> · 적합 <b className={kr.done || reg ? "" : TIER_CLS[jw.tier]}>{jw.tier}</b></> : null} · <span className="font-mono">+{gain.toLocaleString()}P</span></span>
                      <span className={`font-mono font-bold shrink-0 ${kr.done || reg ? "text-zinc-600" : "text-violet-300"}`}>{kr.done ? "취득" : reg ? "등록됨" : "등록 ›"}</span>
                    </button>
                  );
                }
                if (kr.type === "count") {
                  return (
                    <button key={kr.id} onClick={() => fillCount(kr)}
                      className="w-full flex items-center justify-between gap-2 rounded-lg px-3 py-2 text-xs border border-zinc-800 text-zinc-300 active:translate-y-0.5">
                      <span className="truncate">🔁 {kr.title} — 일일 실행으로 채우기 · <span className="font-mono">{krDoneCount(goal, { tasks: tasks || [] })}/{kr.need}</span></span>
                      <span className="font-mono font-bold text-cyan-300 shrink-0">채우기 ›</span>
                    </button>
                  );
                }
                return (
                  <div key={kr.id} className="flex items-center gap-2 rounded-lg border border-zinc-800 px-3 py-2 text-xs text-zinc-400 opacity-60">📈 {kr.title} — 목표 탭 체크인으로 관리 (운동 기록의 측정값도 자동 반영)</div>
                );
              })}
            </div>
          </div>
        )}

        {gk.study && (
          <div className="flex gap-1.5">
            <button onClick={() => { setMode("normal"); setErr(""); }}
              className={`flex-1 py-2 rounded-lg text-xs ${mode === "normal" ? "bg-cyan-400 text-zinc-950 font-bold" : "bg-zinc-950 border border-zinc-700 text-zinc-400 font-medium"}`}>일일 실행</button>
            <button onClick={() => { setMode("study"); setTitle(""); setErr(""); setKrId(null); }}
              className={`flex-1 py-2 rounded-lg text-xs ${mode === "study" ? "bg-violet-500 text-zinc-950 font-bold" : "bg-zinc-950 border border-zinc-700 text-violet-300 font-medium"}`}>학습 (하루분량)</button>
          </div>
        )}

        {mode === "normal" && (<>
          {TASK_TEMPLATES.some((tp) => tp.kind && gk.kinds.has(tp.kind)) && (
            <div className="flex flex-wrap gap-1.5">
              {TASK_TEMPLATES.filter((tp) => tp.kind && gk.kinds.has(tp.kind)).map((tp) => (
                <Chip key={tp.t} tone="amber" on={title === tp.t}
                  onClick={() => { setTitle(tp.t); setKind(tp.kind); setDiff(tp.diff); setType(tp.type); setErr(""); }}>
                  {tp.t}
                </Chip>
              ))}
            </div>
          )}
          <input value={title} onChange={(e) => setTitle(e.target.value)}
            placeholder="무엇을 하나요? — 하루 안에 끝나는 크기로"
            className="w-full bg-zinc-950 border border-zinc-800 rounded-xl px-3 py-2.5 text-sm outline-none focus:border-cyan-400" />
          <div>
            <div className="text-xs text-zinc-500 mb-1.5">{krId ? "활동 유형 (선택) — 횟수 핵심결과를 채우는 실행이에요" : "활동 유형 (필수) — 독서·운동만 목표에 등록돼요"}</div>
            <div className="flex gap-1.5">
              {kindOpts.map(([k, t]) => (
                <Chip key={k} on={kind === k} onClick={() => setKind(kind === k ? "" : k)}>{t}</Chip>
              ))}
            </div>
            {kind && (
              <p className="text-xs text-zinc-600 mt-1.5">
                {kind === "book" ? "완료 시 독후감(별점·한 줄 감상) 기록 — 교양 독서용. 실력 목적 독서는 '학습'으로."
                  : "완료 시 운동·측정 기록(선택). 체중·골격근량은 이 목표의 같은 이름 수치 KR에 자동 반영돼요."}
              </p>
            )}
          </div>
          <div>
            <div className="text-xs text-zinc-500 mb-1.5">
              난이도 — <span className={`font-mono font-bold ${DIFF_PT_TEXT[diff] || "text-zinc-300"}`}>{DIFFS[diff].pts}pt</span> <span className="text-zinc-600">· 하루분량 상한 C</span>
            </div>
            <div className="flex gap-1.5">
              {["E", "D", "C"].map((d) => (
                <button key={d} onClick={() => setDiff(d)}
                  className={`flex-1 py-2 rounded-lg text-sm font-mono font-bold bg-zinc-900 ${
                    diff === d ? `border-2 ${DIFF_SEL[d]}` : `border ${DIFF_TONE[d]}`}`}>
                  {d}
                </button>
              ))}
            </div>
          </div>
          <div className="flex gap-1.5">
            <Chip on={type === "daily"} onClick={() => setType("daily")}>매일 반복</Chip>
            <Chip on={type === "once"} onClick={() => setType("once")}>오늘 1회</Chip>
          </div>
          {type === "once" && (
            <div>
              <div className="text-xs text-zinc-500 mb-1">기한 (선택)</div>
              <input type="date" value={due} onChange={(e) => setDue(e.target.value)}
                className="w-full bg-zinc-950 border border-zinc-700 rounded-xl px-3 py-2.5 text-sm" />
            </div>
          )}
          {err && <p className="text-xs text-rose-400">{err}</p>}
          <button onClick={submitNormal}
            className="w-full py-3 rounded-xl bg-cyan-400 text-zinc-950 font-black text-sm active:translate-y-0.5 transition-all">
            등록
          </button>
        </>)}

        {mode === "study" && (<>
          <input value={title} onChange={(e) => setTitle(e.target.value)}
            placeholder="책·논문·강의명"
            className="w-full bg-zinc-950 border border-zinc-700 rounded-xl px-3 py-2.5 text-sm outline-none focus:border-violet-400" />
          <input value={sScope} onChange={(e) => setSScope(e.target.value)} placeholder="오늘 범위 — 예: 3장, 강의 5강"
            className="w-full bg-zinc-950 border border-zinc-700 rounded-xl px-3 py-2.5 text-sm" />
          <div>
            <div className="text-xs text-zinc-500 mb-1">분량 등급 — <span className={`font-mono font-bold ${DIFF_PT_TEXT[sDiff] || "text-zinc-300"}`}>{DIFFS[sDiff].pts}pt</span></div>
            <div className="flex gap-1.5">
              {["E", "D"].map((d) => <Chip key={d} on={sDiff === d} onClick={() => setSDiff(d)}>{d}</Chip>)}
            </div>
            <p className="text-xs text-zinc-600 mt-1">하루 학습 분량만: 아티클 E · 챕터/강의 1개 D. 책 한 권은 매일 챕터(D)로 쪼개고, 완독은 목표의 횟수 KR로 측정하세요.</p>
          </div>
          <p className="text-xs text-zinc-500">완료 검증: E = 요약·새 지식 기재 · D = 기재 + 산출물 1건(정리 사진/링크).</p>
          <div>
            <div className="text-xs text-zinc-500 mb-1">기한 (선택)</div>
            <input type="date" value={due} onChange={(e) => setDue(e.target.value)}
              className="w-full bg-zinc-950 border border-zinc-700 rounded-xl px-3 py-2.5 text-sm" />
          </div>
          {err && <p className="text-xs text-rose-400">{err}</p>}
          <button onClick={submitStudy}
            className="w-full py-3 rounded-xl bg-violet-500 text-zinc-950 font-black text-sm active:translate-y-0.5">
            학습 실행 추가 (산출물 검증)
          </button>
        </>)}
      </div>
    </Modal>
  );
}

function EvidenceModal({ task, onClose, onSubmit }) {
  const [sel, setSel] = useState([]);
  const [memo, setMemo] = useState("");
  const [img, setImg] = useState(null);
  const [score, setScore] = useState(""); // exam milestones only — the exact score, recorded for display (schema v22)
  const [err, setErr] = useState("");
  const fileRef = useRef(null);
  const needPhoto = task.isCert || task.isExam;
  const docName = task.isExam ? "성적표" : "합격증";
  const fam = task.isExam ? examOf(task.famId) : null;
  const numeric = examScoreNumeric(fam);
  const onFile = async (e) => {
    const fl = e.target.files?.[0]; e.target.value = "";
    if (!fl) return;
    try { setImg(await resizeImage(fl)); setErr(""); } catch { setErr("이미지를 읽지 못했어요."); }
  };
  const submit = () => {
    if (needPhoto && !img) { setErr(`${docName} 사진을 첨부해야 완료할 수 있어요.`); return; }
    if (!needPhoto && !sel.length) { setErr("증거 항목을 하나 이상 선택해 주세요."); return; }
    // The score is an extra requirement on top of the photo, checked before anything is written: a refused score
    // leaves no evidence image behind and the task open (rules 10, 16).
    const se = task.isExam ? examScoreError(fam, task.band, score) : "";
    if (se) { setErr(se); return; }
    if (img) store.set(`liferpg-img-ev-${task.id}`, img);
    const bits = [];
    if (img) bits.push(`📎 ${needPhoto ? docName : "사진"} 첨부`);
    if (sel.length) bits.push(sel.join(" · "));
    onSubmit(bits.join(" · ") + (memo.trim() ? ` — ${memo.trim()}` : ""), task.isExam ? score.trim() : undefined);
  };
  return (
    <Modal title={task.isExam ? "시험 성적 — 성적표 제출" : task.isCert ? "자격증 취득 — 합격증 제출" : `${task.diff}급 완료 — 증거 선택`} onClose={onClose}>
      <p className="text-sm text-zinc-400 mb-3">
        {needPhoto
          ? `「${task.title}」 — ${docName} 사진을 첨부해야만 완료됩니다. 텍스트만으로는 인정되지 않아요.`
          : `「${task.title}」 — 이 등급은 증거 없이는 완료되지 않아요. 해당하는 항목을 골라 주세요.`}
      </p>
      {needPhoto && (
        <div className="mb-3">
          <input ref={fileRef} type="file" accept="image/*" className="hidden" onChange={onFile} />
          {img ? (
            <div>
              <div className="relative rounded-xl overflow-hidden border border-emerald-700">
                <img src={img} alt="증거" className="w-full max-h-48 object-contain bg-zinc-950" />
                <button onClick={() => setImg(null)}
                  className="absolute top-1.5 right-1.5 w-6 h-6 rounded-md bg-zinc-950 bg-opacity-80 text-xs text-zinc-300">✕</button>
              </div>
              <div className="mt-2 flex items-center gap-2 rounded-lg border border-emerald-700 bg-emerald-500 bg-opacity-10 px-3 py-2">
                <Check size={14} className="text-emerald-400 shrink-0" />
                <span className="text-xs font-medium text-emerald-300">첨부 완료 — 제출 시 기록에 저장됩니다</span>
              </div>
            </div>
          ) : (
            <button onClick={() => fileRef.current?.click()}
              className="w-full py-7 rounded-xl border-2 border-dashed border-zinc-700 flex flex-col items-center gap-1.5 active:border-cyan-600">
              <Paperclip size={20} className="text-zinc-500" />
              <span className="text-xs font-medium text-zinc-400">📎 {docName} 사진 첨부 (필수)</span>
              <span className="text-xs text-zinc-600">JPG·PNG · 기록에 원본 저장</span>
            </button>
          )}
        </div>
      )}
      {task.isExam && (
        <div className="mb-3">
          <div className="text-xs font-bold tracking-widest text-zinc-500 mb-1.5">점수</div>
          <input value={score} onChange={(e) => setScore(e.target.value)}
            placeholder={numeric ? "성적표에 적힌 점수 — 숫자만" : "성적표에 적힌 등급·점수 그대로"}
            inputMode={numeric ? "decimal" : "text"}
            className="w-full bg-zinc-950 border border-zinc-700 rounded-xl px-3 py-2.5 text-sm font-mono" />
          <p className="text-xs text-zinc-500 mt-1">점수는 기록용이에요 — 지급 P·등급·난이도는 {task.band?.label} 구간 기준 그대로예요.</p>
        </div>
      )}
      <EvidencePicker
        chips={TASK_EV_CHIPS}
        selected={sel}
        onToggle={(c) => setSel((s) => (s.includes(c) ? s.filter((x) => x !== c) : [...s, c]))}
        memo={memo} setMemo={setMemo}
      />
      {err && <div className="text-xs text-rose-400 mt-2">{err}</div>}
      <button onClick={submit} disabled={needPhoto && !img}
        className={`w-full py-3 rounded-xl font-black text-sm mt-3 ${needPhoto ? (img ? "bg-emerald-400 text-zinc-950" : "bg-zinc-800 bg-opacity-50 text-zinc-600") : "bg-cyan-500 text-zinc-950"}`}>
        {needPhoto && !img ? "제출하고 완료 — 첨부 필요" : "제출하고 완료"}
      </button>
    </Modal>
  );
}

/* ── Daily activity log modal — reading and exercise ── */
function ActivityLogModal({ task, onClose, onDone }) {
  const k = task.kind;
  const [rating, setRating] = useState(0);
  const [review, setReview] = useState("");
  const [quote, setQuote] = useState("");
  const [workout, setWorkout] = useState("");
  const [weight, setWeight] = useState("");
  const [muscle, setMuscle] = useState("");
  const [err, setErr] = useState("");
  const submit = () => {
    setErr("");
    if (k === "book") {
      if (!rating) { setErr("별점을 선택해 주세요."); return; }
      if (review.trim().length < 15) { setErr("한 줄 감상을 15자 이상 적어 주세요."); return; }
      onDone(`독후감 ★${rating} · ${review.trim().slice(0, 60)}${quote.trim() ? ` · "${quote.trim().slice(0, 40)}"` : ""}`, null);
    } else if (k === "fit") {
      const w = Number(weight), m = Number(muscle);
      const ms = {};
      if (weight !== "" && Number.isFinite(w)) ms["체중"] = w;
      if (muscle !== "" && Number.isFinite(m)) ms["골격근량"] = m;
      const bits = [];
      if (workout.trim()) bits.push(workout.trim().slice(0, 40));
      if (ms["체중"] != null) bits.push(`체중 ${ms["체중"]}kg`);
      if (ms["골격근량"] != null) bits.push(`골격근량 ${ms["골격근량"]}kg`);
      onDone(bits.length ? `운동 기록 · ${bits.join(" · ")}` : null, Object.keys(ms).length ? ms : null);
    }
  };
  return (
    <Modal title={k === "book" ? `독후감 — ${task.title}` : `운동 기록 — ${task.title}`} onClose={onClose}>
      <div className="space-y-3">
        {k === "book" && (<>
          <div>
            <div className="text-xs text-zinc-500 mb-1">별점</div>
            <div className="flex gap-1">
              {[1, 2, 3, 4, 5].map((n) => (
                <button key={n} onClick={() => setRating(n)} className={`text-xl ${n <= rating ? "" : "opacity-25"}`}>⭐</button>
              ))}
            </div>
          </div>
          <div>
            <div className="text-xs text-zinc-500 mb-1">한 줄 감상 (15자 이상)</div>
            <textarea value={review} onChange={(e) => setReview(e.target.value)} rows={3}
              placeholder="어떤 책이었고, 무엇이 남았는지"
              className="w-full bg-zinc-950 border border-zinc-700 rounded-xl px-3 py-2.5 text-sm resize-none" />
          </div>
          <input value={quote} onChange={(e) => setQuote(e.target.value)} placeholder="기억에 남는 문장 (선택)"
            className="w-full bg-zinc-950 border border-zinc-700 rounded-xl px-3 py-2.5 text-sm" />
        </>)}
        {k === "fit" && (<>
          <p className="text-xs text-zinc-500">기록은 전부 선택입니다 — 측정한 날만 적으세요. 수치는 활성 목표의 같은 이름 수치 KR("체중"·"골격근량")에 자동 반영돼요.</p>
          <input value={workout} onChange={(e) => setWorkout(e.target.value)} placeholder="오늘 운동 — 예: 하체 + 유산소 40분"
            className="w-full bg-zinc-950 border border-zinc-700 rounded-xl px-3 py-2.5 text-sm" />
          <div className="flex gap-2">
            <input value={weight} onChange={(e) => setWeight(e.target.value)} type="number" step="0.1" placeholder="체중 kg"
              className="flex-1 w-0 bg-zinc-950 border border-zinc-700 rounded-xl px-3 py-2.5 text-sm font-mono" />
            <input value={muscle} onChange={(e) => setMuscle(e.target.value)} type="number" step="0.1" placeholder="골격근량 kg"
              className="flex-1 w-0 bg-zinc-950 border border-zinc-700 rounded-xl px-3 py-2.5 text-sm font-mono" />
          </div>
        </>)}
        {err && <p className="text-xs text-rose-400">{err}</p>}
        <button onClick={submit} className="w-full py-3 rounded-xl bg-cyan-500 text-zinc-950 font-black text-sm active:translate-y-0.5">
          {k === "fit" ? "완료 (기록은 선택)" : "기록하고 완료"}
        </button>
        {k === "fit" && <p className="text-xs text-zinc-600">이후의 일일 완료는 원탭이에요. 측정 갱신은 목표 탭의 수치 KR 체크인으로 언제든 가능합니다.</p>}
      </div>
    </Modal>
  );
}

/* ── Study verification modal — output evidence per grade (decided 2026-08-29) ── */
const STUDY_REQ = {
  E: { sum: 30, art: 0, crit: false, label: "요약·새 지식 기재" },
  D: { sum: 30, art: 1, crit: false, label: "기재 + 산출물 1건" },
  C: { sum: 60, art: 1, crit: false, label: "요약 강화(60자+) + 산출물 1건" },
  B: { sum: 100, art: 2, crit: true, label: "요약 강화(100자+) + 한계·비판 + 산출물 2건" },
};
function StudyVerifyModal({ task, onClose, onDone }) {
  const req = STUDY_REQ[task.diff] || STUDY_REQ.D;
  const [summary, setSummary] = useState("");
  const [insight, setInsight] = useState("");
  const [crit, setCrit] = useState("");
  const [photos, setPhotos] = useState([]);
  const [links, setLinks] = useState("");
  const [err, setErr] = useState("");
  const fileRef = useRef(null);
  const [showLinks, setShowLinks] = useState(false);
  const srcName = task.source || task.title;
  const linkList = links.split("\n").map((s) => s.trim()).filter((s) => /^https?:\/\/\S+$/.test(s));
  const artCount = photos.length + linkList.length;
  const onFile = async (e) => {
    const fl = e.target.files?.[0]; e.target.value = "";
    if (!fl || photos.length >= 2) return;
    try {
      const url = await resizeImage(fl);
      setPhotos((p) => [...p, url]);
      setErr("");
    } catch { setErr("이미지를 읽지 못했어요."); }
  };
  const submit = () => {
    if (summary.trim().length < req.sum) { setErr(`요약을 ${req.sum}자 이상으로 적어 주세요 (${task.diff}급 기준).`); return; }
    if (insight.trim().length < 10) { setErr("'새로 알게 된 것'을 구체적으로 적어 주세요."); return; }
    if (req.crit && crit.trim().length < 15) { setErr("B급은 한계·비판 1줄(15자 이상)이 필요해요."); return; }
    if (artCount < req.art) { setErr(`${task.diff}급은 산출물 ${req.art}건이 필요해요 — 정리 사진 또는 정리 링크. (현재 ${artCount}건)`); return; }
    photos.forEach((img, idx) => store.set(`liferpg-img-study-${task.id}-${idx + 1}`, img));
    const bits = ["요약·새 지식 기재", `새 지식: ${insight.trim().slice(0, 40)}`];
    if (req.crit) bits.push(`한계: ${crit.trim().slice(0, 30)}`);
    if (photos.length) bits.push(`📎 정리 사진 ${photos.length}장`);
    if (linkList.length) bits.push(...linkList.map((l) => `🔗 ${l}`));
    onDone(bits.join(" · ") + ` · ${task.diff}급 산출물 검증 통과`);
  };
  return (
    <Modal title={`학습 검증 — ${srcName}`} onClose={onClose}>
      <div className="space-y-3">
        <div className="text-xs bg-violet-500 bg-opacity-10 border border-violet-700 rounded-xl px-3 py-2">
          <span className="font-bold text-violet-300">{task.diff}급 기준</span>
          <span className="text-violet-300"> — {req.label}</span>
        </div>
        <div>
          <div className="flex items-baseline justify-between text-xs text-zinc-400 font-bold mb-1">
            <span>핵심 요약 ({req.sum}자 이상)</span>
            <span className={`font-mono font-bold ${summary.trim().length < req.sum ? "text-rose-400" : "text-emerald-400"}`}>{summary.trim().length}/{req.sum}</span>
          </div>
          <textarea value={summary} onChange={(e) => setSummary(e.target.value)} rows={4}
            placeholder="이 자료의 핵심 주장·내용을 자기 말로"
            className="w-full bg-zinc-950 border border-zinc-700 rounded-xl px-3 py-2.5 text-sm resize-none" />
        </div>
        <div>
          <div className="text-xs text-zinc-500 mb-1">새로 알게 된 것 1가지</div>
          <textarea value={insight} onChange={(e) => setInsight(e.target.value)} rows={2}
            placeholder="읽기 전엔 몰랐던 것"
            className="w-full bg-zinc-950 border border-zinc-700 rounded-xl px-3 py-2.5 text-sm resize-none" />
        </div>
        {req.crit && (
          <div>
            <div className="text-xs text-zinc-500 mb-1">한계·비판 1줄 (B급 필수)</div>
            <input value={crit} onChange={(e) => setCrit(e.target.value)}
              placeholder="이 자료의 한계, 또는 동의하지 않는 지점"
              className="w-full bg-zinc-950 border border-zinc-700 rounded-xl px-3 py-2.5 text-sm" />
          </div>
        )}
        {req.art > 0 && (
          <div className="bg-zinc-950 border border-zinc-800 rounded-xl p-3">
            <div className={`text-xs font-bold mb-2 ${artCount >= req.art ? "text-emerald-400" : "text-rose-400"}`}>
              산출물 {req.art}건 필수 — 현재 {artCount}건
            </div>
            <input ref={fileRef} type="file" accept="image/*" className="hidden" onChange={onFile} />
            <div className="flex gap-2 mb-2">
              {photos.map((img, idx) => (
                <div key={idx} className="relative w-16 h-16 rounded-lg overflow-hidden border border-emerald-700">
                  <img src={img} alt="" className="w-full h-full object-cover" />
                  <button onClick={() => setPhotos((p) => p.filter((_, x) => x !== idx))}
                    className="absolute top-0.5 right-0.5 w-4 h-4 rounded bg-zinc-950 bg-opacity-80 text-xs text-zinc-300">✕</button>
                </div>
              ))}
            </div>
            <div className="flex gap-2 mb-2">
              <button onClick={() => fileRef.current?.click()} disabled={photos.length >= 2}
                className="flex-1 py-3 rounded-lg border-2 border-dashed border-zinc-700 flex items-center justify-center gap-1.5 text-xs text-zinc-400 disabled:opacity-30">
                <Paperclip size={13} /> 사진
              </button>
              <button onClick={() => setShowLinks((v) => !v)}
                className={`flex-1 py-3 rounded-lg border-2 border-dashed flex items-center justify-center gap-1.5 text-xs ${showLinks ? "border-zinc-500 text-zinc-300" : "border-zinc-700 text-zinc-400"}`}>
                <LinkIcon size={13} /> 링크 입력
              </button>
            </div>
            {(showLinks || links.trim().length > 0) && (
            <textarea value={links} onChange={(e) => setLinks(e.target.value)} rows={2}
              placeholder={"정리 링크 (블로그·노션·발표자료, 줄바꿈으로 여러 개)\nhttps://..."}
              className="w-full bg-zinc-900 border border-zinc-700 rounded-lg px-2.5 py-2 text-xs font-mono resize-none" />
            )}
            <p className="text-xs text-zinc-600 mt-1.5">인정: 손필기·정리 사진, 블로그/노션 정리 글, 발표자료. 사진은 기기에, 링크는 기록에 원문 보존.</p>
          </div>
        )}
        {err && <p className="text-xs text-rose-400">{err}</p>}
        <button onClick={submit} className="w-full py-3 rounded-xl bg-violet-500 text-zinc-950 font-black text-sm active:translate-y-0.5">
          검증 제출하고 완료
        </button>
      </div>
    </Modal>
  );
}

/* ───────────────────────── Settings and the achievement wall ───────────────────────── */
/* Two sheets opened from the home CV, each assembled from blocks of the growth tab removed on 2026-09-15.
   `SettingsModal` holds what is set rarely: the role model button and its note from the growth headline, and the
   backup and reset panel moved verbatim. Its import button drives the file input mounted on `Shell`, so the sheet
   declares none of its own. `AchievementWallModal` is the opened wall of the growth tab moved verbatim and read-only:
   the CV states the counts and this sheet holds every earned item, so nothing earned becomes unreachable (rule 13).
   Both live in the one `modal` slot and write nothing to the save (rule 9). */

function SettingsModal({ state, onClose, onRoleModel, onSetBizHours, onExport, onImport, onReset }) {
  const [hours, setHours] = useState(String(bizHoursOf(state)));
  const [hoursErr, setHoursErr] = useState("");
  // The weekly business budget (v28): a whole number of hours in one week, 0 to 168.
  const saveHours = () => {
    const t = hours.trim();
    const n = Number(t);
    if (!/^\d+$/.test(t) || n > 168) { setHoursErr("0 이상 168 이하 정수로 입력해 주세요."); return; }
    setHoursErr("");
    onSetBizHours(n);
  };
  return (
    <Modal title="설정" onClose={onClose}>
      <div className="space-y-4">
        <div>
          <SectionLabel tone="text-cyan-400">롤모델</SectionLabel>
          <button onClick={onRoleModel} className="w-full py-2.5 rounded-xl border border-zinc-700 text-zinc-300 text-xs font-bold">
            {state.role ? "롤모델 수정" : "롤모델 설정"}
          </button>
          <p className="text-xs text-zinc-500 mt-1.5">목표 인물상의 영역별 요구 등급을 정하면, 검증된 등급으로만 근접도를 계산합니다.</p>
        </div>
        <div>
          <SectionLabel tone="text-cyan-400">사업 시간 — 주간 예산</SectionLabel>
          <div className="flex items-center gap-2">
            <span className="text-xs text-zinc-500 shrink-0">주간 시간</span>
            <input type="number" inputMode="numeric" aria-label="주간 사업 시간" value={hours} onChange={(e) => setHours(e.target.value)}
              className="flex-1 w-0 bg-zinc-950 border border-zinc-700 rounded-xl px-3 py-2 text-sm font-mono" />
            <button onClick={saveHours}
              className="shrink-0 px-3 py-2 rounded-xl border border-zinc-700 text-zinc-300 text-xs font-bold active:translate-y-0.5">저장</button>
          </div>
          {hoursErr && <p className="text-xs text-rose-400 mt-1.5">{hoursErr}</p>}
          <p className="text-xs text-zinc-500 mt-1.5">이번 주 사업 시간은 업무 완료 시간과 시간 기록의 합으로 계산돼요.</p>
        </div>
        <div>
          <SectionLabel tone="text-zinc-400">데이터 — 백업 · 초기화</SectionLabel>
          <p className="text-xs text-zinc-500">기록은 이 기기에만 있어요. 저장소가 지워지면 복구할 수 없으니 가끔 파일로 내보내요.</p>
          <div className="flex gap-1.5 mt-2.5">
            <button onClick={onExport} className="flex-1 py-2.5 rounded-xl border border-zinc-700 text-zinc-300 font-bold text-xs">백업 내보내기</button>
            <button onClick={onImport} className="flex-1 py-2.5 rounded-xl border border-zinc-700 text-zinc-300 font-bold text-xs">백업 불러오기</button>
          </div>
          <button onClick={onReset} className="w-full mt-2.5 py-2.5 text-xs text-rose-400 border border-rose-400/30 rounded-xl flex items-center justify-center gap-1.5">
            <RotateCcw size={12} /> 데이터 초기화
          </button>
        </div>
      </div>
    </Modal>
  );
}

function AchievementWallModal({ state, onClose }) {
  const bests = Object.entries(state.exams?.best || {});
  const achTotal = state.areas.reduce((n, p) => n + p.achievements.length, 0);
  return (
    <Modal title="성취의 벽" onClose={onClose}>
      <div className="text-xs font-mono text-zinc-500">트로피 {state.room.trophies.length}개 · 시험 {bests.length}개 · 검증된 성취 {achTotal}건</div>
      <div className="mt-3 space-y-3">
        {state.room.trophies.length === 0 && bests.length === 0 && (
          <div className="text-center py-3">
            <EmptyWallSvg />
            <p className="text-xs text-zinc-600 mt-2">아직 검증된 성취가 없습니다 — 완료는 증거로만 기록됩니다.</p>
          </div>
        )}
        {state.room.trophies.length > 0 && (
          <div className="relative bg-zinc-950 rounded-xl overflow-hidden px-2.5 pt-3 pb-2">
            <WallFrame />
            <div className="relative flex flex-wrap gap-2 justify-center items-end">
              {state.room.trophies.slice(-10).map((t) => (
                <div key={t.id} title={t.label} className="flex flex-col items-center w-12">
                  <TrophySvg kind={t.kind} tier={t.tier} size={26} />
                  <div className="text-xs text-zinc-600 truncate w-full text-center">{t.label}</div>
                </div>
              ))}
            </div>
          </div>
        )}
        {Object.entries(state.exams?.spec || {}).filter(([, v]) => v).map(([l]) => (
          <div key={l} className="text-xs text-amber-300 font-bold">🎖 {LANG_KO[l] || l} 전문화 — 고난도 감쇠 하한 70%</div>
        ))}
        {bests.length > 0 && (
          <div className="space-y-1.5">
            {bests.map(([id, b]) => {
              const fam = examOf(id);
              return (
                <div key={id} className="flex justify-between text-xs bg-zinc-950 rounded-lg px-3 py-2">
                  <span className="text-zinc-300">{fam?.n} <b className="text-cyan-300">{b.label}</b>{b.score ? <> · 점수 <span className="font-mono">{b.score}</span></> : null}</span>
                  <span className="font-mono text-zinc-500">D{b.d} · 누적 {b.p.toLocaleString()}P</span>
                </div>
              );
            })}
          </div>
        )}
        {state.areas.map((p) => (
          <div key={p.id}>
            <div className="flex items-center justify-between gap-2">
              <span className="text-xs text-zinc-400 truncate">{p.name}</span>
              <span className="text-xs font-mono text-zinc-600 shrink-0">검증된 성취 {p.achievements.length}건</span>
            </div>
            {p.achievements.length > 0 && (
              <div className="space-y-1.5 max-h-32 overflow-y-auto pr-1 mt-1.5">
                {p.achievements.slice(-30).reverse().map((ac) => (
                  <div key={ac.id} className="text-xs bg-zinc-950 rounded-lg px-2.5 py-2 flex gap-2">
                    <Star size={11} className="text-cyan-500 shrink-0 mt-0.5" />
                    <div className="min-w-0">
                      <div className="text-zinc-300 break-words">{ac.text}</div>
                      <div className="text-zinc-600 font-mono">{ac.date} · {RANKS[ac.grade].name} 인정</div>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        ))}
      </div>
    </Modal>
  );
}

/* ───────────────────────── Promotion modal (click-driven) ───────────────────────── */

function PromoteModal({ area, onClose, onSubmit }) {
  const next = RANKS[area.grade + 1];
  const [sel, setSel] = useState([]);
  const [memo, setMemo] = useState("");
  const [err, setErr] = useState("");
  if (!next) return null;
  const chips = GATE_CHIPS[area.grade + 1] || [];
  return (
    <Modal title={`승급 심사 — ${next.name}`} onClose={onClose}>
      <div className="bg-zinc-950 rounded-xl p-3 mb-3">
        <div className="text-xs text-zinc-500">'{area.name}' 영역 · {RANKS[area.grade].name} → <span className="text-cyan-300 font-bold">{next.name}</span></div>
        <div className="text-sm text-zinc-200 mt-1">{next.gate}</div>
        <div className="text-xs text-zinc-500 mt-1">필요 증거: {next.req}</div>
      </div>
      <div className="text-xs text-zinc-500 mb-2">해당하는 증거를 선택하세요 (1개 이상)</div>
      <EvidencePicker
        chips={chips}
        selected={sel}
        onToggle={(c) => setSel((s) => (s.includes(c) ? s.filter((x) => x !== c) : [...s, c]))}
        memo={memo} setMemo={setMemo}
      />
      <p className="text-xs text-zinc-600 mt-2">스스로에게 정직하게. 여기서의 상향은 결국 나를 속이는 일이에요.</p>
      {err && <div className="text-xs text-rose-400 mt-2">{err}</div>}
      <button
        onClick={() => { if (!sel.length) { setErr("해당하는 증거가 없다면 아직 이 등급이 아닌 거예요."); return; } onSubmit(composeEvidence(sel, memo)); }}
        className="w-full py-3 rounded-xl bg-cyan-500 text-zinc-950 font-black text-sm mt-3">
        증거 제출 · 승급
      </button>
    </Modal>
  );
}

// A stored stage as the editor holds it: the argument and the threshold are kept as typed strings until save.
const stageDraft = (st) => ({ id: st.id || uid(), name: st.name || "", conds: (st.conds || []).map((c) => ({ type: c.type, arg: c.arg == null ? "" : String(c.arg), min: String(c.min ?? "") })) });
const ROLE_STAGE_PRESET = "의료 AI 솔루션 대표"; // the preset that seeds the nine stages

function RoleModelModal({ state, onClose, onSave }) {
  const [name, setName] = useState(state.role?.name || "");
  const [targets, setTargets] = useState(state.role?.targets || {});
  const [stages, setStages] = useState(() => (state.role?.stages || []).map(stageDraft));
  const [story, setStory] = useState(state.role?.story || "");
  const [err, setErr] = useState("");
  const pickPreset = (r) => {
    setName(r);
    if (r !== ROLE_STAGE_PRESET) return;
    if (stages.length && !window.confirm("단계를 기본 9단계로 바꿔요. 계속할까요?")) return;
    setStages(seedStages().map(stageDraft));
  };
  const editStage = (i, fn) => setStages((list) => list.map((st, k) => (k === i ? fn(st) : st)));
  const editCond = (i, j, patch) => editStage(i, (st) => ({ ...st, conds: st.conds.map((c, k) => (k === j ? { ...c, ...patch } : c)) }));
  const hintOf = (type) => COND_TYPES.find((t) => t[0] === type)?.[2] ?? "";
  const save = () => {
    const out = [];
    for (const [i, st] of stages.entries()) {
      if (!st.name.trim()) { setErr(`단계 이름을 입력해 주세요 — ${i + 1}번째 단계`); return; }
      const conds = [];
      for (const [j, c] of st.conds.entries()) {
        const min = Number(c.min);
        if (String(c.min).trim() === "" || !Number.isFinite(min) || min < 0) { setErr(`기준은 0 이상 숫자예요 — ${i + 1}단계 ${j + 1}번째 조건`); return; }
        const arg = hintOf(c.type) ? c.arg.trim() : "";
        conds.push({ type: c.type, ...(arg ? { arg } : {}), min });
      }
      out.push({ id: st.id, name: st.name.trim(), conds });
    }
    onSave({ name: name.trim() || "롤모델", targets, ...(out.length ? { stages: out } : {}), ...(story.trim() ? { story: story.trim() } : {}) });
  };
  return (
    <Modal title="롤모델 설정" onClose={onClose}>
      {/* The story (2026-09-18): the one free text sent verbatim in the role verdict packet — the caption says so */}
      <SectionLabel>원하는 모습</SectionLabel>
      <textarea value={story} onChange={(e) => setStory(e.target.value)} rows={5} maxLength={ROLE_STORY_MAX} aria-label="원하는 모습"
        placeholder="예: 2029년까지 직원 20명 규모 의료 AI 회사의 대표가 되고 싶어요. / 예: ○○전자 로봇 SW 직무로 2027년 상반기 입사하고 싶어요. — 회사·직무·규모·시기를 적어요"
        className="w-full bg-zinc-950 border border-zinc-700 rounded-xl px-3 py-2.5 text-sm" />
      <div className="text-xs font-mono text-zinc-500 text-right">{story.length} / {ROLE_STORY_MAX}</div>
      <p className="text-xs text-zinc-600 mb-4">여기 적은 글은 그대로 AI 패킷에 실려요 — 이름·연락처는 적지 않아요.</p>
      <SectionLabel>세부 수정</SectionLabel>
      <div className="flex flex-wrap gap-1.5 mb-2">
        {ROLE_PRESETS.map((r) => (
          <Chip key={r} on={name === r} onClick={() => pickPreset(r)}>{r}</Chip>
        ))}
      </div>
      <input value={name} onChange={(e) => setName(e.target.value)}
        placeholder="직접 입력 (예: 연 매출 1억 1인 사업가)"
        className="w-full bg-zinc-950 border border-zinc-700 rounded-xl px-3 py-2.5 text-sm outline-none focus:border-cyan-500 mb-4" />
      <div className="space-y-3">
        {state.areas.map((p) => (
          <div key={p.id}>
            <div className="text-xs text-zinc-500 mb-1.5">{p.name} — 요구 등급 {targets[p.id] ? `: ${RANKS[targets[p.id]].name}` : "(제외)"}</div>
            <div className="flex flex-wrap gap-1">
              <button onClick={() => setTargets((t) => ({ ...t, [p.id]: 0 }))}
                className={`px-2 py-1 rounded text-xs border ${!targets[p.id] ? "bg-zinc-700 text-zinc-200 border-zinc-600" : "bg-zinc-950 text-zinc-500 border-zinc-800"}`}>
                제외
              </button>
              {RANKS.slice(1, 9).map((r, i) => (
                <button key={r.name} onClick={() => setTargets((t) => ({ ...t, [p.id]: i + 1 }))}
                  className={`px-2 py-1 rounded text-xs border ${
                    targets[p.id] === i + 1 ? "bg-cyan-500 text-zinc-950 border-cyan-400" : "bg-zinc-950 text-zinc-500 border-zinc-800"}`}>
                  {r.name}
                </button>
              ))}
            </div>
          </div>
        ))}
      </div>
      {/* Stages are optional fact conditions; the proximity above never reads them (rule 14) */}
      <div className="mt-4">
        <div className="flex items-center justify-between gap-2">
          <SectionLabel>단계 (선택)</SectionLabel>
          <span className="text-xs font-mono text-zinc-500 mb-2">{stages.length} / {ROLE_STAGES_MAX}</span>
        </div>
        <div className="space-y-2">
          {stages.map((st, i) => (
            <div key={st.id} className="bg-zinc-950 border border-zinc-800 rounded-xl p-2.5 space-y-1.5">
              <div className="flex items-center gap-1.5">
                <span className="shrink-0 text-xs font-mono text-cyan-300">{i + 1}단계</span>
                <input value={st.name} maxLength={ROLE_STAGE_NAME} onChange={(e) => editStage(i, (x) => ({ ...x, name: e.target.value }))}
                  placeholder="단계 이름 — 예: 첫 병원 계약" aria-label="단계 이름"
                  className="flex-1 w-0 bg-zinc-900 border border-zinc-700 rounded-lg px-2 py-1 text-xs outline-none focus:border-cyan-500" />
                <button onClick={() => setStages((list) => list.filter((_, k) => k !== i))} aria-label="단계 삭제"
                  className="shrink-0 p-1 text-zinc-500 active:opacity-70"><X size={13} /></button>
              </div>
              {st.conds.map((c, j) => {
                const hint = hintOf(c.type);
                return (
                  <div key={j} className="flex items-center gap-1">
                    <select value={c.type} aria-label="조건 종류"
                      onChange={(e) => editCond(i, j, { type: e.target.value, ...(hintOf(e.target.value) ? {} : { arg: "" }) })}
                      className="flex-1 w-0 bg-zinc-900 border border-zinc-700 rounded-lg px-1 py-1 text-xs outline-none">
                      {COND_TYPES.map(([t, label]) => <option key={t} value={t}>{label}</option>)}
                    </select>
                    <input value={c.arg} disabled={!hint} onChange={(e) => editCond(i, j, { arg: e.target.value })}
                      placeholder={hint || "조건 값 없음"} aria-label="조건 값"
                      className="flex-1 w-0 bg-zinc-900 border border-zinc-700 rounded-lg px-1.5 py-1 text-xs outline-none disabled:opacity-30" />
                    <input value={c.min} type="number" min="0" onChange={(e) => editCond(i, j, { min: e.target.value })} aria-label="기준"
                      className="shrink-0 w-16 bg-zinc-900 border border-zinc-700 rounded-lg px-1.5 py-1 text-xs font-mono outline-none" />
                    <button onClick={() => editStage(i, (x) => ({ ...x, conds: x.conds.filter((_, k) => k !== j) }))} aria-label="조건 삭제"
                      className="shrink-0 p-1 text-zinc-500 active:opacity-70"><X size={13} /></button>
                  </div>
                );
              })}
              <div className="flex items-center gap-2">
                <button disabled={st.conds.length >= STAGE_CONDS_MAX}
                  onClick={() => editStage(i, (x) => ({ ...x, conds: [...x.conds, { type: COND_TYPES[0][0], arg: "", min: "1" }] }))}
                  className="shrink-0 px-2 py-1 rounded-lg border border-zinc-700 text-xs text-zinc-300 disabled:opacity-30">조건 추가</button>
                {st.conds.length >= STAGE_CONDS_MAX && <span className="text-xs text-zinc-500">조건은 단계당 5개까지예요.</span>}
              </div>
            </div>
          ))}
        </div>
        <div className="flex items-center gap-2 mt-2">
          <button disabled={stages.length >= ROLE_STAGES_MAX}
            onClick={() => setStages((list) => [...list, { id: uid(), name: "", conds: [] }])}
            className="shrink-0 px-2.5 py-1.5 rounded-lg border border-zinc-700 text-xs text-zinc-300 disabled:opacity-30">단계 추가</button>
          {stages.length >= ROLE_STAGES_MAX && <span className="text-xs text-zinc-500">단계는 12개까지예요.</span>}
        </div>
        <p className="text-xs text-zinc-600 mt-2">조건은 앱의 기록으로 계산돼요 — 근접도와는 별개예요.</p>
      </div>
      {err && <div className="text-xs text-rose-400 mt-2">{err}</div>}
      <button onClick={save}
        className="w-full py-3 rounded-xl bg-cyan-500 text-zinc-950 font-black text-sm mt-4">
        저장
      </button>
    </Modal>
  );
}

/* ───────────────────────── Schedule tab — appointments and deadlines ───────────────────────── */
/* An event is a record of real life, never a task: nothing here completes, pays, or moves a metric.
   Occurrences are expanded at render and never stored (rule 9); a missed deadline stays listed with
   its D+n instead of disappearing (rule 13). */

const CAL_RANGE_MONTHS = 24; // how far the month grid may be paged either side of today, so `‹` cannot walk into years of empty grids
const WEEKDAY_LABEL = ["일", "월", "화", "수", "목", "금", "토"]; // Sunday first, matching Date#getDay()

/* South Korean public holidays, display only — the grid tints the day number and the selected-day panel names
   the date. A holiday is never an event: it is not stored, counted, briefed, paid, or listed in the to-do list.
   None of it is computable. Lunar new year and the harvest festival follow the lunar calendar, substitute
   holidays are granted per year, and election days are set by their own law, so every row below is copied from
   the government announcement of record — the Gwanbo gazette notices issued under the Presidential Decree on
   the holidays of government offices — and cross-checked against the KASI almanac published the preceding year.
   The Decree amended on 2026-04-30 added Labour Day and restored Constitution Day, both substitute-eligible.
   Add a year only from a cited announcement. Never interpolate a lunar date, never infer a substitute day, and
   never add a temporary holiday that has not been designated: a day painted red is a day the user will not
   schedule. Coverage is derived below, so a month outside it marks nothing and says so under the grid. */
const HOLIDAYS = {
  "2026-01-01": "신정",
  "2026-02-16": "설날 연휴",
  "2026-02-17": "설날",
  "2026-02-18": "설날 연휴",
  "2026-03-01": "삼일절",
  "2026-03-02": "대체공휴일",
  "2026-05-01": "노동절",
  "2026-05-05": "어린이날",
  "2026-05-24": "부처님오신날",
  "2026-05-25": "대체공휴일",
  "2026-06-03": "지방선거일",
  "2026-06-06": "현충일",
  "2026-07-17": "제헌절",
  "2026-08-15": "광복절",
  "2026-08-17": "대체공휴일",
  "2026-09-24": "추석 연휴",
  "2026-09-25": "추석",
  "2026-09-26": "추석 연휴",
  "2026-10-03": "개천절",
  "2026-10-05": "대체공휴일",
  "2026-10-09": "한글날",
  "2026-12-25": "성탄절",
  "2027-01-01": "신정",
  "2027-02-06": "설날 연휴",
  "2027-02-07": "설날",
  "2027-02-08": "설날 연휴",
  "2027-02-09": "대체공휴일",
  "2027-03-01": "삼일절",
  "2027-05-01": "노동절",
  "2027-05-03": "대체공휴일",
  "2027-05-05": "어린이날",
  "2027-05-13": "부처님오신날",
  "2027-06-06": "현충일",
  "2027-07-17": "제헌절",
  "2027-07-19": "대체공휴일",
  "2027-08-15": "광복절",
  "2027-08-16": "대체공휴일",
  "2027-09-14": "추석 연휴",
  "2027-09-15": "추석",
  "2027-09-16": "추석 연휴",
  "2027-10-03": "개천절",
  "2027-10-04": "대체공휴일",
  "2027-10-09": "한글날",
  "2027-10-11": "대체공휴일",
  "2027-12-25": "성탄절",
  "2027-12-27": "대체공휴일",
};
// Derived, never restated: adding a year to the table moves the coverage note by itself.
const HOLIDAY_YEARS = [...new Set(Object.keys(HOLIDAYS).map((d) => d.slice(0, 4)))].sort();

/* One occurrence row, rendered by the calendar's selected-day panel and by the to-do list's event detail sheet.
   The markup exists once so the two surfaces cannot drift apart. */
function EventRow({ ev, date, done, today, onToggleDone, onSkip, onEdit }) {
  const due = ev.kind === "due";
  const lead = due ? ddayStr(date) : ev.time || "시간 미정";
  const leadTone = !due ? "text-zinc-300 border-zinc-700"
    : date < today ? "text-rose-400 border-rose-800"
    : date === today ? "text-amber-300 border-amber-700"
    : "text-zinc-400 border-zinc-700";
  return (
    <div className={`bg-zinc-950 rounded-xl px-3 py-2.5 ${done ? "opacity-50" : ""}`}>
      <div className="flex items-center gap-2.5">
        <span className={`font-mono text-xs font-bold border rounded-lg px-1.5 py-1 bg-zinc-900 shrink-0 ${leadTone}`}>{lead}</span>
        <div className="flex-1 min-w-0">
          <div className={`text-sm font-semibold truncate ${done ? "line-through" : ""}`}>{ev.title}</div>
          <div className="text-xs text-zinc-500 truncate">
            <span className="font-mono">{date}</span>{ev.place ? ` · ${ev.place}` : ""}{ev.note ? ` · ${ev.note}` : ""}
            {ev.repeat && <span className="text-zinc-400"> · 반복 {REPEAT_LABEL[ev.repeat.freq]}</span>}
            {` · ${TRACK_LABEL[trackOf(ev)]}`}
          </div>
        </div>
        <span className={`text-xs font-bold border rounded-lg px-1.5 py-1 bg-zinc-900 shrink-0 ${due ? "text-amber-300 border-amber-700" : "text-zinc-300 border-zinc-700"}`}>
          {EVENT_KIND_LABEL[ev.kind]}
        </span>
      </div>
      <div className="flex gap-1.5 mt-2">
        <button onClick={() => onToggleDone(ev.id, date)}
          className={`px-2.5 py-1.5 rounded-lg border text-xs font-bold active:translate-y-0.5 ${done ? "border-emerald-700 text-emerald-300" : "border-zinc-700 text-zinc-300"}`}>
          {done ? "완료 취소" : "완료 표시"}
        </button>
        {ev.repeat && (
          <button onClick={() => onSkip(ev.id, date)}
            className="px-2.5 py-1.5 rounded-lg border border-zinc-700 text-zinc-400 text-xs font-bold active:translate-y-0.5">이번 회차 취소</button>
        )}
        <button onClick={() => onEdit(ev)}
          className="px-2.5 py-1.5 rounded-lg border border-zinc-700 text-zinc-400 text-xs font-bold active:translate-y-0.5">수정</button>
      </div>
    </div>
  );
}

/* The `확인할 것` checklist of one event (v27), rendered by the meeting-prep card and the event detail sheet, so the two
   surfaces cannot drift apart. `onAdd` answers "" when written or the refusal to show; the typed text is component
   state only. A check pays nothing and completes nothing (rules 1, 18). */
function EventChecks({ ev, onAdd, onToggle, onRemove }) {
  const [text, setText] = useState("");
  const [err, setErr] = useState("");
  const checks = ev.checks || [];
  const open = checks.filter((c) => !c.done).length;
  const atCap = checks.length >= EVENT_CHECKS_MAX;
  const add = () => {
    const refused = onAdd(ev.id, text);
    setErr(refused);
    if (!refused) setText("");
  };
  return (
    <div className="space-y-1.5">
      <div className="flex items-center justify-between gap-2">
        <div className="text-xs tracking-widest font-semibold text-zinc-500">확인할 것</div>
        <span className="text-xs font-mono text-zinc-400 shrink-0">{open}/{checks.length}</span>
      </div>
      {checks.length === 0 ? (
        <p className="text-xs text-zinc-500">확인할 것이 없어요.</p>
      ) : checks.map((c) => (
        <div key={c.id} className="bg-zinc-950 rounded-xl px-3 py-2 flex items-start gap-2">
          <input type="checkbox" aria-label="확인 완료" checked={!!c.done} onChange={() => onToggle(ev.id, c.id)} className="mt-0.5 shrink-0" />
          <span className={`flex-1 min-w-0 text-sm break-words ${c.done ? "line-through text-zinc-500" : ""}`}>{c.text}</span>
          {c.source === "ai" && <span className="text-xs font-mono font-bold text-violet-300 shrink-0">AI</span>}
          <button aria-label="확인할 것 삭제" onClick={() => { if (window.confirm("확인할 것을 삭제해요. 계속할까요?")) onRemove(ev.id, c.id); }}
            className="text-zinc-500 shrink-0 active:opacity-70"><X size={14} /></button>
        </div>
      ))}
      <div className="flex items-center gap-1.5">
        <input value={text} onChange={(e) => setText(e.target.value)} disabled={atCap} placeholder="확인할 것 — 예: 단가표 회신 여부"
          className="flex-1 min-w-0 bg-zinc-950 border border-zinc-700 rounded-lg px-2.5 py-1 text-sm disabled:opacity-30" />
        <button onClick={add} disabled={atCap}
          className="shrink-0 px-2.5 py-1.5 rounded-lg border border-zinc-700 text-zinc-300 text-xs font-bold disabled:opacity-30 active:translate-y-0.5">추가</button>
      </div>
      {err && <p className="text-xs text-rose-400">{err}</p>}
      {atCap && <p className="text-xs text-zinc-400">확인할 것은 {EVENT_CHECKS_MAX}건까지예요.</p>}
    </div>
  );
}

/* Month grid plus the selected day's rows. The month's occurrences are expanded once per render into a
   date-keyed map: `upcomingEvents` already loops `eventsOn` over a window, so one call per cell would
   re-implement that loop 28-31 times and let the grid and the panel disagree. The month, the selection and
   the map are render state only — nothing derived reaches the save (rule 9). */
function ScheduleCalendar({ state, today, onAdd, onEdit, onToggleDone, onSkip }) {
  const [month, setMonth] = useState(today.slice(0, 7));
  const [sel, setSel] = useState(today);
  const y = Number(month.slice(0, 4));
  const m = Number(month.slice(5, 7)) - 1;
  const monthStart = `${month}-01`;
  const daysInMonth = new Date(y, m + 1, 0).getDate(); // day 0 of the next month, the idiom occurrencesOf uses to clamp a monthly repeat
  const byDate = useMemo(() => {
    const map = new Map();
    for (const o of upcomingEvents(state, monthStart, daysInMonth)) {
      const day = map.get(o.date);
      if (day) day.push(o); else map.set(o.date, [o]);
    }
    return map;
  }, [state, monthStart, daysInMonth]);

  const firstDow = new Date(monthStart + "T12:00:00").getDay(); // noon-anchored like shiftDay, never toISOString; 0 = Sunday
  const cells = Math.ceil((firstDow + daysInMonth) / 7) * 7;    // whole weeks, so the last row is never empty
  const monthOf = (base, delta) => dstr(new Date(Number(base.slice(0, 4)), Number(base.slice(5, 7)) - 1 + delta, 1, 12)).slice(0, 7);
  const minMonth = monthOf(today, -CAL_RANGE_MONTHS);
  const maxMonth = monthOf(today, CAL_RANGE_MONTHS);
  // Paging keeps the selection inside the shown month, so the panel is always exactly eventsOn(state, sel).
  const goMonth = (delta) => { const next = monthOf(month, delta); setMonth(next); setSel(`${next}-01`); };
  const selOcc = byDate.get(sel) || [];

  return (
    <>
      <section className="bg-zinc-900 border border-zinc-800 rounded-2xl p-4">
        <div className="flex items-center justify-between gap-2 mb-3">
          <div className="text-sm font-mono font-bold text-zinc-100">{y}년 {m + 1}월</div>
          <div className="flex items-center gap-1.5">
            <button onClick={() => goMonth(-1)} disabled={month <= minMonth}
              className="w-8 h-8 rounded-lg border border-zinc-700 text-zinc-300 text-sm font-bold disabled:opacity-30">‹</button>
            <button onClick={() => goMonth(1)} disabled={month >= maxMonth}
              className="w-8 h-8 rounded-lg border border-zinc-700 text-zinc-300 text-sm font-bold disabled:opacity-30">›</button>
            <button onClick={() => { setMonth(today.slice(0, 7)); setSel(today); }}
              className="px-2.5 py-1.5 rounded-lg border border-zinc-700 text-zinc-300 text-xs font-bold active:translate-y-0.5">오늘</button>
          </div>
        </div>
        <div className="grid grid-cols-7 gap-1 mb-1">
          {WEEKDAY_LABEL.map((d) => <div key={d} className="text-xs text-zinc-500 text-center">{d}</div>)}
        </div>
        <div className="grid grid-cols-7 gap-1">
          {Array.from({ length: cells }, (_, i) => {
            const day = i - firstDow + 1;
            // Leading and trailing cells only hold the seven-column alignment: no day number, no marker, no tap target.
            if (day < 1 || day > daysInMonth) return <div key={`pad${i}`} className="h-14" />;
            const date = `${month}-${String(day).padStart(2, "0")}`;
            const occ = byDate.get(date) || [];
            const dow = (firstDow + day - 1) % 7; // this cell's column, so Sunday and Saturday are read off the grid itself
            // One tone per day number, in the order a Korean calendar reads it. Today wins: it is a state mark and has to
            // stay one unambiguous colour, and the fact is not lost — selecting today still names the holiday in the panel.
            // The holiday tint cannot be confused with the deadline marker below it: this is text, that is a filled dot.
            const tone = date === today ? "text-amber-300 font-bold"
              : HOLIDAYS[date] || dow === 0 ? "text-rose-400"
              : dow === 6 ? "text-sky-400"
              : "text-zinc-300";
            return (
              <button key={date} onClick={() => setSel(date)}
                className={`h-14 rounded-lg overflow-hidden flex flex-col items-center justify-center gap-1 ${
                  sel === date ? "bg-zinc-800 border border-cyan-500" : "bg-zinc-950 border border-transparent"}`}>
                <span className={`text-xs font-mono ${tone}`}>{day}</span>
                <span className="h-4 flex items-center justify-center gap-0.5">
                  {/* At most three dots — a cell is about 43 px wide at 390 px, so the rest is counted instead */}
                  {occ.slice(0, 3).map((o) => (
                    <span key={o.ev.id}
                      className={`w-1.5 h-1.5 rounded-full shrink-0 ${o.ev.kind === "due" ? "bg-rose-400" : "bg-cyan-400"} ${o.done ? "opacity-50" : ""}`} />
                  ))}
                  {occ.length > 3 && <span className="text-xs font-mono text-zinc-500 leading-none">+{occ.length - 3}</span>}
                </span>
              </button>
            );
          })}
        </div>
        {/* Outside the table's years nothing is marked, so the grid says which years it knows rather than
            letting an unmarked lunar new year read as a working day. Weekend colours still apply: those come from the date. */}
        {!HOLIDAY_YEARS.includes(month.slice(0, 4)) && (
          <p className="text-xs text-zinc-500 mt-2">{`공휴일은 ${HOLIDAY_YEARS[0]}~${HOLIDAY_YEARS[HOLIDAY_YEARS.length - 1]}년만 표시해요.`}</p>
        )}
      </section>

      <section className="bg-zinc-900 border border-zinc-800 rounded-2xl p-4">
        <SectionLabel>선택한 날짜</SectionLabel>
        <p className="text-xs font-mono text-zinc-400">{sel} · {selOcc.length}건</p>
        {HOLIDAYS[sel] && <p className="text-xs text-rose-400">공휴일 · {HOLIDAYS[sel]}</p>}
        {selOcc.length === 0 ? (
          <p className="text-sm text-zinc-500 mt-3">이 날짜에는 일정이 없어요.</p>
        ) : (
          <div className="space-y-1.5 mt-3">
            {selOcc.map((o) => (
              <EventRow key={`${o.ev.id}-${o.date}`} ev={o.ev} date={o.date} done={o.done} today={today}
                onToggleDone={onToggleDone} onSkip={onSkip} onEdit={onEdit} />
            ))}
          </div>
        )}
        <button onClick={() => onAdd(sel)}
          className="w-full mt-3 px-3.5 py-2.5 rounded-xl bg-cyan-400 text-zinc-950 text-sm font-bold flex items-center justify-center gap-1 active:translate-y-0.5">
          <Plus size={14} /> 일정 추가
        </button>
      </section>
    </>
  );
}

/* The schedule tab is the month calendar under a header (2026-09-16: the list view and its chips were removed).
   Missed deadlines stay visible as the counts line figure and as `기한 지남` rows in the to-do list. */
function ScheduleTab({ state, today, onAdd, onEdit, onToggleDone, onSkip, onExport }) {
  const weekEnd = shiftDay(mondayOf(today), 6);
  const counts = useMemo(() => {
    // Past window: deadlines only — an appointment that already happened is not actionable, a missed deadline is.
    const past = upcomingEvents(state, shiftDay(today, -EVENT_PAST_DAYS), EVENT_PAST_DAYS).filter((o) => o.ev.kind === "due");
    const ahead = upcomingEvents(state, today, EVENT_HORIZON_DAYS);
    // The week count runs from today to Sunday, so it covers today and tomorrow too: it answers how much is
    // left this week.
    return { today: ahead.filter((o) => o.date === today).length, week: ahead.filter((o) => o.date <= weekEnd).length, past: past.length };
  }, [state, today, weekEnd]);

  return (
    <>
      <section className="bg-zinc-900 border border-zinc-800 rounded-2xl p-4">
        {/* The calendar panel owns the add button, so exactly one `일정 추가` button exists */}
        <div className="flex items-center justify-between gap-2">
          <SectionLabel tone="text-cyan-400">다가오는 일정</SectionLabel>
          <button onClick={() => onExport()}
            className="shrink-0 px-3 py-1.5 rounded-xl border border-zinc-700 text-zinc-300 text-xs font-bold">캘린더로 내보내기</button>
        </div>
        <p className="text-xs font-mono text-zinc-400">
          오늘 {counts.today}건 · 이번 주 {counts.week}건 · 지난 마감 {counts.past}건
        </p>
      </section>

      <ScheduleCalendar state={state} today={today}
        onAdd={onAdd} onEdit={onEdit} onToggleDone={onToggleDone} onSkip={onSkip} />
    </>
  );
}

/* ── Event modal — one form for add and edit. No goal, no difficulty, no evidence: an event is only a record ── */
function EventModal({ event, initialDate, projects, onClose, onAdd, onUpdate, onRemove }) {
  const [title, setTitle] = useState(event?.title || "");
  const [kind, setKind] = useState(event?.kind || "appt");
  const [date, setDate] = useState(event?.date || initialDate || ""); // add mode opened from a calendar day starts on that day
  const [time, setTime] = useState(event?.time || "");
  const [freq, setFreq] = useState(event?.repeat?.freq || "");
  const [until, setUntil] = useState(event?.repeat?.until || "");
  const [place, setPlace] = useState(event?.place || "");
  const [note, setNote] = useState(event?.note || "");
  const [projectId, setProjectId] = useState(event?.projectId || "");
  // v28: picking a project follows its track until a track chip is tapped in this form (component state only).
  const [track, setTrack] = useState(event?.track || "work");
  const [trackTouched, setTrackTouched] = useState(false);
  const pickProject = (id) => {
    setProjectId(id);
    const p = id ? projects.find((x) => x.id === id) : null;
    if (p && !trackTouched) setTrack(trackOf(p));
  };
  const [err, setErr] = useState("");
  // A project deleted later stays selectable as itself, so saving the form does not silently drop the reference.
  const staleProject = projectId && !projects.some((p) => p.id === projectId) ? projectId : "";

  const submit = () => {
    if (!title.trim()) { setErr("일정 이름을 입력해 주세요."); return; }
    if (!date) { setErr("날짜를 선택해 주세요."); return; }
    if (freq && until && until <= date) { setErr("반복 종료일은 날짜 이후여야 해요."); return; }
    const next = {
      title: title.trim(), kind, date,
      ...(time ? { time } : {}),
      ...(place.trim() ? { place: place.trim() } : {}),
      ...(note.trim() ? { note: note.trim() } : {}),
      ...(freq ? { repeat: { freq, ...(until ? { until } : {}) } } : {}),
      ...(projectId ? { projectId } : {}),
      track,
    };
    if (event) onUpdate(event.id, next); else onAdd(next);
  };

  return (
    <Modal title={event ? "일정 수정" : "새 일정"} onClose={onClose}>
      <div className="space-y-3">
        <input value={title} onChange={(e) => setTitle(e.target.value)} placeholder="일정 이름 — 예: 1차 면접"
          className="w-full bg-zinc-950 border border-zinc-700 rounded-xl px-3 py-2.5 text-sm" />
        <div className="flex gap-1.5">
          {["appt", "due"].map((k) => (
            <Chip key={k} on={kind === k} onClick={() => { setKind(k); setErr(""); }}>{EVENT_KIND_LABEL[k]}</Chip>
          ))}
        </div>
        <input type="date" value={date} onChange={(e) => setDate(e.target.value)}
          className="w-full bg-zinc-950 border border-zinc-700 rounded-xl px-3 py-2.5 text-sm font-mono" />
        <label className="flex items-center gap-2 text-xs text-zinc-500">
          <span className="w-24 shrink-0">시간 (선택)</span>
          <input type="time" value={time} onChange={(e) => setTime(e.target.value)}
            className="flex-1 w-0 bg-zinc-950 border border-zinc-700 rounded-xl px-3 py-2 text-sm font-mono" />
        </label>
        <div className="bg-zinc-950 border border-zinc-800 rounded-xl p-3">
          <div className="flex flex-wrap gap-1.5">
            {[["", "반복 없음"], ["daily", REPEAT_LABEL.daily], ["weekly", REPEAT_LABEL.weekly], ["monthly", REPEAT_LABEL.monthly]].map(([f, label]) => (
              <Chip key={label} on={freq === f} onClick={() => { setFreq(f); setErr(""); }}>{label}</Chip>
            ))}
          </div>
          {freq && (
            <label className="flex items-center gap-2 text-xs text-zinc-500 mt-2.5">
              <span className="w-24 shrink-0">반복 종료 (선택)</span>
              <input type="date" value={until} onChange={(e) => setUntil(e.target.value)}
                className="flex-1 w-0 bg-zinc-900 border border-zinc-700 rounded-lg px-2.5 py-2 text-sm font-mono" />
            </label>
          )}
        </div>
        <input value={place} onChange={(e) => setPlace(e.target.value)} placeholder="장소 (선택)"
          className="w-full bg-zinc-950 border border-zinc-700 rounded-xl px-3 py-2.5 text-sm" />
        <input value={note} onChange={(e) => setNote(e.target.value)} placeholder="메모 (선택)"
          className="w-full bg-zinc-950 border border-zinc-700 rounded-xl px-3 py-2.5 text-sm" />
        {/* The meeting project this event belongs to — a reference the prep card reads, nothing else; the export never
            reads it. `updateEvent` spreads the form's record over the stamps, so a cleared pick leaves the save. */}
        <div>
          <div className="text-xs font-bold tracking-widest text-zinc-500 mb-1.5">프로젝트 (선택)</div>
          {projects.length === 0 && !staleProject ? (
            <p className="text-xs text-zinc-500">프로젝트가 없어요 — 미팅 탭에서 만들어요.</p>
          ) : (
            <select value={projectId} onChange={(e) => pickProject(e.target.value)} aria-label="프로젝트 (선택)"
              className="w-full bg-zinc-950 border border-zinc-700 rounded-xl px-3 py-2.5 text-sm">
              <option value="">연결 안 함</option>
              {staleProject && <option value={staleProject}>연결 대상이 삭제됐어요</option>}
              {projects.map((p) => <option key={p.id} value={p.id}>{p.name}</option>)}
            </select>
          )}
        </div>
        <TrackRow value={track} onPick={(t) => { setTrack(t); setTrackTouched(true); }} />
        {err && <p className="text-xs text-rose-400">{err}</p>}
        <button onClick={submit} className="w-full py-3 rounded-xl bg-cyan-500 text-zinc-950 font-black text-sm active:translate-y-0.5">
          {event ? "저장" : "등록"}
        </button>
        {event && (
          <button onClick={() => onRemove(event.id)}
            className="w-full py-2.5 rounded-xl border border-rose-800 text-rose-300 font-bold text-xs">삭제</button>
        )}
      </div>
    </Modal>
  );
}

/* ── Calendar export sheet — reads records, writes a file, stores nothing ── */
/* The reminder time and the range are component state and reset every time the sheet opens: remembering them would
   be a stored preference, a schema change for two taps (rule 12). The preview reads the same `calendarExportOf` the
   file is built from, so the numbers shown are the entries written. The snapshot limits are stated before anything
   is exported (rule 13), and the validation message is the sheet's only rose text. */
function CalendarExportModal({ state, today, onClose, onExport }) {
  const [remindAt, setRemindAt] = useState(ICS_REMIND_DEFAULT);
  const [days, setDays] = useState(EVENT_HORIZON_DAYS);
  const [err, setErr] = useState("");
  const sel = useMemo(() => calendarExportOf(state, today, days), [state, today, days]);
  const empty = sel.entries.length === 0;

  const submit = () => {
    if (!/^\d{2}:\d{2}$/.test(remindAt)) { setErr("알림 시각을 입력해 주세요."); return; }
    onExport({ days, remindAt });
  };

  return (
    <Modal title="휴대폰 캘린더로 내보내기" onClose={onClose}>
      <div className="space-y-3">
        <p className="text-sm text-zinc-300">이 앱은 알림을 보내지 않아요. 내보낸 파일을 휴대폰 캘린더 앱에서 가져오면 캘린더 앱이 알림을 울려요.</p>
        <label className="flex items-center gap-2 text-xs text-zinc-500">
          <span className="w-24 shrink-0">매일 알림 시각</span>
          <input type="time" value={remindAt} onChange={(e) => { setRemindAt(e.target.value); setErr(""); }}
            className="flex-1 w-0 bg-zinc-950 border border-zinc-700 rounded-xl px-3 py-2 text-sm font-mono" />
        </label>
        <p className="text-xs text-zinc-500">마감·실행 기한·목표 기한·시간 없는 약속과 매일 실행 목록은 이 시각에 알려요. 시간이 있는 약속은 시작 1시간 전에 알려요.</p>
        <p className="text-xs text-zinc-500">후속 기한·마일스톤·입금 예정·공고 마감과 회의 하루 전 확인할 것도 이 시각에 알려요.</p>
        <div>
          <div className="text-xs text-zinc-500 mb-1.5">넣을 기간</div>
          <div className="flex gap-1.5">
            {ICS_RANGE_DAYS.map((d) => (
              <Chip key={d} on={days === d} onClick={() => setDays(d)}>{d === 365 ? "1년" : `${d}일`}</Chip>
            ))}
          </div>
        </div>
        {empty ? (
          <p className="text-xs text-zinc-400">{`넣을 항목이 없어요 — ${today} ~ ${sel.end}에 일정·실행 기한·매일 실행·목표 기한·후속 기한·확인할 것·마일스톤·입금 예정·공고 마감이 없어요.`}</p>
        ) : (
          <div className="space-y-0.5">
            <p className="text-xs font-mono text-zinc-400">{`${today} ~ ${sel.end} · 항목 ${sel.entries.length}건`}</p>
            <p className="text-xs font-mono text-zinc-400">{`일정 ${sel.counts.event} · 실행 기한 ${sel.counts.task} · 매일 실행 ${sel.counts.daily} · 목표 기한 ${sel.counts.goal}`}</p>
            <p className="text-xs font-mono text-zinc-400">{`후속 ${sel.counts.followup} · 확인 ${sel.counts.check} · 마일스톤 ${sel.counts.milestone} · 입금 ${sel.counts.payment} · 공고 ${sel.counts.notice}`}</p>
          </div>
        )}
        {sel.skipped.tasks + sel.skipped.goals + sel.skipped.followups + sel.skipped.milestones + sel.skipped.payments + sel.skipped.notices > 0 && (
          <p className="text-xs text-zinc-400">{`기한이 지난 실행 ${sel.skipped.tasks}건 · 목표 ${sel.skipped.goals}건 · 후속 ${sel.skipped.followups}건 · 마일스톤 ${sel.skipped.milestones}건 · 입금 ${sel.skipped.payments}건 · 공고 ${sel.skipped.notices}건은 날짜가 지나 넣지 않아요.`}</p>
        )}
        {sel.skipped.checks > 0 && <p className="text-xs text-zinc-400">{`확인할 것 ${sel.skipped.checks}건은 하루 전이 지나 넣지 않아요.`}</p>}
        <p className="text-xs text-zinc-500">넣지 않는 것: 이름·생년월일·연락처·학력·경력, 사업 금액·단가·포트폴리오·리드, 일정의 장소·메모, 녹취록·문서.</p>
        <div className="bg-zinc-950 border border-zinc-800 rounded-xl p-3 space-y-1">
          <p className="text-xs text-zinc-300">내보낸 순간의 기록만 들어가요. 앱에서 추가·수정·완료·삭제해도 휴대폰 캘린더는 바뀌지 않아요 — 바뀐 내용은 다시 내보내야 들어가요.</p>
          <p className="text-xs text-zinc-300">앱에서 완료해도 캘린더의 알림은 꺼지지 않아요.</p>
          <p className="text-xs text-zinc-300">매일 알림에는 내보낼 때의 매일 실행 목록이 그대로 남아요.</p>
          <p className="text-xs text-zinc-300">{`${sel.end} 뒤로는 알림이 없어요.`}</p>
        </div>
        <div className="space-y-1">
          <p className="text-xs text-zinc-500">다시 가져올 때 같은 항목을 바꿔 넣을지 하나 더 만들지는 캘린더 앱마다 달라요.</p>
          <p className="text-xs text-zinc-500">파일에 적힌 알림 대신 캘린더 앱의 기본 알림을 쓰는 앱도 있어요.</p>
          <p className="text-xs text-zinc-500">구글 계정 캘린더로 가져오면 제목이 구글 서버에 저장돼요.</p>
        </div>
        <p className="text-xs text-zinc-500">파일은 브라우저의 다운로드로 저장돼요. 휴대폰 캘린더 앱에서 이 파일을 열어 가져와요.</p>
        {err && <p className="text-xs text-rose-400">{err}</p>}
        <button onClick={submit} disabled={empty}
          className="w-full py-3 rounded-xl bg-cyan-500 text-zinc-950 font-black text-sm disabled:opacity-30">파일 내보내기</button>
      </div>
    </Modal>
  );
}

/* ───────────────────────── Business tab — contracts · unit prices · portfolio ───────────────────────── */
/* Everything here renders records, never tasks (rules 1, 18): registering a contract, ticking a payment,
   adding a rate or a portfolio entry pays no P, creates no trophy, moves no goal and touches no streak.
   Every month, total, margin and phase on this tab is computed from the stored billing rule (rule 9). */

// Group order and tone; the heading itself comes from DEAL_PHASE_LABEL, which the packet reads too.
const DEAL_GROUPS = [
  ["active", "text-cyan-400"],
  ["upcoming", "text-zinc-400"],
  ["quote", "text-amber-300"],
  ["lead", "text-zinc-400"],
  ["ended", "text-zinc-500"],
  ["lost", "text-zinc-600"],
];
const BIZ_ADD_LABEL = { deals: "계약 추가", rates: "단가 추가", folio: "포트폴리오 추가", roadmap: "마일스톤 추가", leads: "리드 추가", notices: "공고 추가" };
// The modal each view's add button opens (v28), one per view.
const BIZ_ADD_MODAL = { deals: "deals", rates: "rates", folio: "folio", roadmap: "milestone", leads: "lead", notices: "notice" };
// Toast subject plus its Korean particle, so the one generic handler prints the right sentence per list.
const BIZ_NOUN = { deals: "계약을", rates: "단가를", folio: "포트폴리오를" };
const PAID_CHIP_MAX = 12;   // payment chips shown on one row; the rest are counted, so a 10-year rule cannot flood the card
const FOLIO_LINK_MAX = 4;
const FOLIO_LINK_LABELS = ["GitHub", "Notion", "Figma", "배포", "기타"];

// A number field of a business form: blank means "nothing entered" and stores nothing, a negative or
// non-numeric entry becomes NaN so the caller refuses it. A cost of 0 is a real cost, not an absent one.
const numField = (v) => {
  const t = String(v).trim();
  if (!t) return null;
  const n = Number(t);
  return Number.isFinite(n) && n >= 0 ? n : NaN;
};

// One money line for a deal or a rate. No cost entered means no margin — never a zero cost — so the row
// states that instead; a negative margin is printed as it is, in rose.
function MoneyLine({ lead, price, cost }) {
  const m = marginOf(price, cost);
  return (
    <>
      <p className={`text-xs font-mono ${m && m.amount < 0 ? "text-rose-400" : "text-zinc-300"}`}>
        {lead}{m ? ` · 마진 ${wonText(m.amount)}${m.rate == null ? "" : ` (${Math.round(m.rate * 100)}%)`}` : ""}
      </p>
      {!m && <p className="text-xs text-zinc-500">원가 미입력 — 마진은 계산하지 않아요</p>}
    </>
  );
}

// The first line of every business card: the name, an optional chip and the edit button.
function BizRowHead({ title, chip, tag, onEdit }) {
  return (
    <div className="flex items-center gap-2.5">
      <div className="flex-1 min-w-0"><div className="text-sm font-semibold truncate">{title}</div></div>
      {tag && <TrackTag track={tag} />}
      {chip && <span className="text-xs font-bold border border-zinc-700 text-zinc-300 rounded-lg px-1.5 py-1 bg-zinc-900 shrink-0">{chip}</span>}
      <button onClick={onEdit}
        className="shrink-0 px-2.5 py-1.5 rounded-lg border border-zinc-700 text-zinc-400 text-xs font-bold active:translate-y-0.5">수정</button>
    </div>
  );
}

function DealRow({ deal: d, month, today, onEdit, onTogglePaid, onTogglePayment }) {
  const months = dealMonths(d);
  const billed = billedMonths(d, month);
  const paidSet = d.paidMonths || [];
  const pays = dealPayments(d);
  return (
    <div className="bg-zinc-950 rounded-xl px-3 py-2.5">
      <BizRowHead title={`${d.client} · ${d.title}`} chip={DEAL_STATUS[d.status]} tag={trackOf(d, "biz")} onEdit={() => onEdit("deals", d)} />
      <p className="text-xs font-mono text-zinc-400 mt-1">
        {d.startMonth && months > 0 ? `${d.startMonth} ~ ${dealEnd(d)} · ${months}개월 · 월 ${wonText(d.monthly || 0)}` : "기간 미정"}
      </p>
      {/* A lead or a quote may carry no numbers at all; a total is stated only once there is a rule to total. */}
      {months > 0 && d.monthly != null && (
        <MoneyLine lead={`총 ${wonText(dealTotal(d))}`} price={dealTotal(d)} cost={dealCostTotal(d)} />
      )}
      {billed.length > 0 && (
        <div className="mt-2">
          <div className="text-xs text-zinc-500 mb-1">입금 확인</div>
          <div className="flex flex-wrap gap-1.5">
            {billed.slice(0, PAID_CHIP_MAX).map((m) => (
              <button key={m} onClick={() => onTogglePaid(d.id, m)}
                className={`px-2.5 py-1.5 rounded-lg border text-xs font-mono font-bold active:translate-y-0.5 ${
                  paidSet.includes(m) ? "border-emerald-700 text-emerald-300" : "border-zinc-700 text-zinc-300"}`}>{m}</button>
            ))}
          </div>
          {billed.length > PAID_CHIP_MAX && (
            <p className="text-xs text-zinc-500 mt-1">외 {billed.length - PAID_CHIP_MAX}개월 더 있어요</p>
          )}
        </div>
      )}
      {/* Lump-sum payment lines (v28): emerald when paid, rose when unpaid past its date; a tap flips the paid stamp */}
      {pays.length > 0 && (
        <div className="mt-2">
          <div className="text-xs text-zinc-500 mb-1">입금 예정</div>
          <div className="flex flex-wrap gap-1.5">
            {pays.map((p) => (
              <button key={p.id} onClick={() => onTogglePayment(d.id, p.id)}
                className={`px-2.5 py-1.5 rounded-lg border text-xs font-mono font-bold active:translate-y-0.5 ${
                  p.paidAt ? "border-emerald-700 text-emerald-300" : p.due < today ? "border-rose-800 text-rose-300" : "border-zinc-700 text-zinc-300"}`}>
                {`${PAYMENT_KIND[p.kind] || PAYMENT_KIND.other} ${p.due} · ${wonText(p.amount)}`}</button>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

/* Contracts grouped by the phase `dealPhase` derives from the billing rule, plus the revenue roll-up.
   A group with no row is not rendered at all; a month with nothing contracted still prints its zero. */
function DealsView({ state, month, today, onEdit, onTogglePaid, onTogglePayment }) {
  const deals = state.deals || [];
  const roll = revenueByMonth(state, monthAdd(month, -(BIZ_REVENUE_MONTHS - 1)), BIZ_REVENUE_MONTHS);
  const peak = Math.max(1, ...roll.map((r) => r.amount));
  return (
    <>
      {deals.length === 0 && (
        <section className="bg-zinc-900 border border-zinc-800 rounded-2xl p-6 text-center">
          <p className="text-sm text-zinc-500">등록한 계약이 없어요 — 문의·견적부터 기록해요.</p>
        </section>
      )}
      {DEAL_GROUPS.map(([phase, tone]) => {
        const list = deals.filter((d) => dealPhase(d, month) === phase);
        return list.length > 0 && (
          <section key={phase} className="bg-zinc-900 border border-zinc-800 rounded-2xl p-4">
            <SectionLabel tone={tone}>{DEAL_PHASE_LABEL[phase]}</SectionLabel>
            <div className="space-y-1.5">
              {list.map((d) => <DealRow key={d.id} deal={d} month={month} today={today} onEdit={onEdit} onTogglePaid={onTogglePaid} onTogglePayment={onTogglePayment} />)}
            </div>
          </section>
        );
      })}
      <section className="bg-zinc-900 border border-zinc-800 rounded-2xl p-4">
        <SectionLabel tone="text-zinc-400">최근 {BIZ_REVENUE_MONTHS}개월</SectionLabel>
        <div className="space-y-1.5">
          {roll.map((r) => (
            <div key={r.month} className="flex items-center gap-2">
              <span className="text-xs font-mono text-zinc-400 w-16 shrink-0">{r.month}</span>
              <div className="flex-1"><Bar ratio={r.amount / peak} color="bg-cyan-400" /></div>
              <span className="text-xs font-mono text-zinc-300 w-20 shrink-0 text-right">{wonText(r.amount)}</span>
            </div>
          ))}
        </div>
      </section>
    </>
  );
}

/* Unit prices. No average margin: averaging unrelated rate rows states a number nothing measured. */
function RatesView({ state, onEdit }) {
  const rates = state.rates || [];
  const priced = rates.filter((r) => r.cost != null).length;
  if (!rates.length) {
    return (
      <section className="bg-zinc-900 border border-zinc-800 rounded-2xl p-6 text-center">
        <p className="text-sm text-zinc-500">등록한 단가가 없어요 — 청구가와 원가를 넣으면 마진이 계산돼요.</p>
      </section>
    );
  }
  return (
    <section className="bg-zinc-900 border border-zinc-800 rounded-2xl p-4">
      <div className="space-y-1.5">
        {rates.map((r) => (
          <div key={r.id} className="bg-zinc-950 rounded-xl px-3 py-2.5">
            <BizRowHead title={r.name} chip={RATE_UNIT[r.unit]} onEdit={() => onEdit("rates", r)} />
            <MoneyLine lead={`청구 ${wonText(r.price)}${r.cost == null ? "" : ` · 원가 ${wonText(r.cost)}`}`} price={r.price} cost={r.cost} />
            {r.note && <p className="text-xs text-zinc-500">{r.note}</p>}
          </div>
        ))}
      </div>
      <p className="text-xs font-mono text-zinc-400 mt-2.5">단가 {rates.length}건 · 원가 입력 {priced}건</p>
    </section>
  );
}

/* One column, not a grid: at 390 px a 2-up grid gives 170 px thumbnails, unreadable for a landscape
   diagram. The thumbnails are read once on view entry — a render-time read would rescan storage on
   every keystroke elsewhere — and the same pass records the storage figure the footer states. */
function FolioView({ state, onEdit }) {
  const items = state.folio || [];
  const [thumbs, setThumbs] = useState({});
  const [used, setUsed] = useState(0);
  const ids = items.map((f) => f.id).join(",");
  useEffect(() => {
    let alive = true;
    (async () => {
      const got = {};
      for (const id of ids ? ids.split(",") : []) {
        const v = await store.get(`liferpg-img-folio-${id}`).catch(() => null);
        if (v) got[id] = v;
      }
      if (alive) { setThumbs(got); setUsed(storageUsedBytes()); }
    })();
    return () => { alive = false; };
  }, [ids]);

  if (!items.length) {
    return (
      <section className="bg-zinc-900 border border-zinc-800 rounded-2xl p-6 text-center">
        <p className="text-sm text-zinc-500">등록한 포트폴리오가 없어요 — 링크와 대표 이미지 1장을 넣어요.</p>
      </section>
    );
  }
  return (
    <section className="bg-zinc-900 border border-zinc-800 rounded-2xl p-4">
      <div className="space-y-2">
        {items.map((f) => (
          <div key={f.id} className="bg-zinc-950 rounded-xl px-3 py-2.5">
            <BizRowHead title={f.title} onEdit={() => onEdit("folio", f)} />
            {f.summary && <p className="text-xs text-zinc-400 mt-1">{f.summary}</p>}
            {f.role && <p className="text-xs text-zinc-500">{f.role}</p>}
            {f.period && <p className="text-xs font-mono text-zinc-500">{f.period.from} ~ {f.period.to}</p>}
            {(f.stack || []).length > 0 && (
              <div className="flex flex-wrap gap-1.5 mt-1.5">
                {f.stack.map((t) => (
                  <span key={t} className="px-2 py-1 rounded-full border border-zinc-700 text-zinc-400 text-xs font-medium">{t}</span>
                ))}
              </div>
            )}
            {(f.links || []).length > 0 && (
              <div className="flex flex-wrap gap-1.5 mt-1.5">
                {f.links.map((l, i) => (
                  <a key={`${l.label}-${i}`} href={l.url} target="_blank" rel="noreferrer"
                    className="px-2.5 py-1.5 rounded-full border border-cyan-800 text-cyan-300 text-xs font-bold">{l.label}</a>
                ))}
              </div>
            )}
            <div className="mt-2">
              {thumbs[f.id]
                ? <img src={thumbs[f.id]} alt={f.title} className="w-full max-h-64 object-contain bg-zinc-950 rounded-xl border border-zinc-800" />
                : <p className="text-xs text-zinc-600">대표 이미지 없음</p>}
            </div>
          </div>
        ))}
      </div>
      <p className="text-xs font-mono text-zinc-400 mt-2.5">
        포트폴리오 {items.length}건 · 대표 이미지 {Object.keys(thumbs).length}장 · 저장 공간 {(used / 1048576).toFixed(1)}MB 사용 중 (약 5MB 한도)
      </p>
    </section>
  );
}

/* The roadmap (v28): milestones grouped by the user's status. Every D-day, completion count and the stage-order note are
   derived at render (rule 9); nothing here pays, completes or promotes (rules 1, 18). */
const ROADMAP_GROUPS = [["active", "text-cyan-400"], ["planned", "text-zinc-400"], ["done", "text-zinc-500"]];
function RoadmapView({ state, today, onOpen, onSeed }) {
  const list = state.milestones || [];
  const count = (st) => list.filter((m) => m.status === st).length;
  const note = stageOrderNote(list);
  return (
    <>
      <section className="bg-zinc-900 border border-zinc-800 rounded-2xl p-4">
        <SectionLabel tone="text-cyan-400">로드맵</SectionLabel>
        <p className="text-xs font-mono text-zinc-400">
          <span className="whitespace-nowrap">예정 {count("planned")}</span>{" · "}
          <span className="whitespace-nowrap">진행 중 {count("active")}</span>{" · "}
          <span className="whitespace-nowrap">완료 {count("done")}</span>
        </p>
        {note && <p className="text-xs text-amber-300 mt-1">{note}</p>}
        {list.length === 0 && (
          <div className="mt-2.5 space-y-2">
            <p className="text-sm text-zinc-500">로드맵이 비어 있어요.</p>
            <button onClick={onSeed}
              className="w-full py-2.5 rounded-xl border border-zinc-700 text-zinc-300 font-bold text-xs active:translate-y-0.5">기본 로드맵 채우기</button>
            <p className="text-xs text-zinc-600">상황에 맞춘 9단계를 넣어요 — 날짜·조건은 수정할 수 있어요.</p>
          </div>
        )}
      </section>
      {ROADMAP_GROUPS.map(([st, tone]) => {
        const rows = list.filter((m) => m.status === st).slice().sort(milestoneOrder);
        return rows.length > 0 && (
          <section key={st} className="bg-zinc-900 border border-zinc-800 rounded-2xl p-4">
            <SectionLabel tone={tone}>{MILESTONE_STATUS[st]}</SectionLabel>
            <div className="space-y-1.5">
              {rows.map((m) => {
                const w = milestoneWork(state, m);
                const late = st !== "done" && m.due && m.due < today;
                return (
                  <TodoRow key={m.id} done={st === "done"} title={m.title} onOpen={() => onOpen(m.id)}
                    lead={{ text: Number.isFinite(m.stage) ? `${m.stage}단계` : "단계 없음",
                      tone: st === "active" ? "text-cyan-300 border-cyan-800" : "text-zinc-400 border-zinc-700" }}
                    marker={<span className={`text-xs font-mono whitespace-nowrap shrink-0 ${late ? "text-rose-400" : "text-zinc-400"}`}>
                      {m.due ? ddayStr(m.due) : "기한 없음"} · 업무 {w.done}/{w.total}</span>} />
                );
              })}
            </div>
          </section>
        );
      })}
      {list.length > 0 && (
        <p className="text-xs text-zinc-600 px-1">마일스톤은 기록이에요 — 상태는 직접 바꾸고, 기한·연결 업무·페이스는 계산돼요.</p>
      )}
    </>
  );
}

/* The sales pipeline (v28): hospital leads grouped by the user's stage. The overdue count and the D-day markers are
   derived at render (rule 9); a lead pays nothing and becomes no task (rules 1, 18). */
function LeadsView({ state, today, onOpen }) {
  const list = state.leads || [];
  const overdue = list.filter((l) => leadOverdue(l, today)).length;
  return (
    <>
      <section className="bg-zinc-900 border border-zinc-800 rounded-2xl p-4">
        <SectionLabel tone="text-cyan-400">리드</SectionLabel>
        <p className="text-xs font-mono text-zinc-400">
          <span className="whitespace-nowrap">리드 {list.length}건</span>{" · "}
          <span className={`whitespace-nowrap ${overdue > 0 ? "text-rose-400" : ""}`}>다음 액션 기한 지남 {overdue}건</span>
        </p>
        {list.length === 0 && <p className="text-sm text-zinc-500 mt-2.5">등록한 리드가 없어요 — 병원 이름부터 적어요.</p>}
      </section>
      {LEAD_STAGES.map((st) => {
        const rows = list.filter((l) => l.stage === st).slice().sort(leadOrder);
        return rows.length > 0 && (
          <section key={st} className="bg-zinc-900 border border-zinc-800 rounded-2xl p-4">
            <SectionLabel tone={st === "won" ? "text-cyan-400" : "text-zinc-400"}>{LEAD_STAGE_LABEL[st]}</SectionLabel>
            <div className="space-y-1.5">
              {rows.map((l) => (
                <TodoRow key={l.id} title={l.name} onOpen={() => onOpen(l.id)}
                  lead={{ text: LEAD_STAGE_LABEL[st], tone: st === "won" ? "text-cyan-300 border-cyan-800" : "text-zinc-400 border-zinc-700" }}
                  marker={l.nextDue ? <span className={`text-xs font-mono whitespace-nowrap shrink-0 ${leadOverdue(l, today) ? "text-rose-400" : "text-zinc-400"}`}>
                    {ddayStr(l.nextDue)}</span> : null} />
              ))}
            </div>
          </section>
        );
      })}
      <p className="text-xs text-zinc-600 px-1">리드는 기록이에요 — 견적·계약 단계에서 계약을 만들어 연결해요.</p>
    </>
  );
}

/* National-project notices (v28): open first, then by deadline. The near-deadline count and the markers are derived. */
const NOTICE_TONE = { submitted: "text-cyan-300 border-cyan-800", selected: "text-emerald-300 border-emerald-800", rejected: "text-zinc-600 border-zinc-800" };
function NoticesView({ state, today, onOpen }) {
  const list = (state.notices || []).slice().sort(noticeOrder);
  const soon = list.filter((n) => noticeSoon(n, today)).length;
  return (
    <>
      <section className="bg-zinc-900 border border-zinc-800 rounded-2xl p-4">
        <SectionLabel tone="text-cyan-400">공고</SectionLabel>
        <p className="text-xs font-mono text-zinc-400">
          <span className="whitespace-nowrap">공고 {list.length}건</span>{" · "}
          <span className="whitespace-nowrap">마감 {NOTICE_SOON_DAYS}일 이내 {soon}건</span>
        </p>
        {list.length === 0 && <p className="text-sm text-zinc-500 mt-2.5">등록한 공고가 없어요.</p>}
      </section>
      {list.length > 0 && (
        <section className="bg-zinc-900 border border-zinc-800 rounded-2xl p-4">
          <div className="space-y-1.5">
            {list.map((n) => (
              <TodoRow key={n.id} title={n.title} onOpen={() => onOpen(n.id)}
                lead={{ text: NOTICE_STATUS_LABEL[n.status] || n.status, tone: NOTICE_TONE[n.status] || "text-zinc-400 border-zinc-700" }}
                marker={<span className={`text-xs font-mono whitespace-nowrap shrink-0 ${noticeOpen(n) && n.deadline < today ? "text-rose-400" : "text-zinc-400"}`}>
                  {ddayStr(n.deadline)}</span>} />
            ))}
          </div>
        </section>
      )}
      <p className="text-xs text-zinc-600 px-1">공고는 기록이에요 — 마감은 캘린더 내보내기에 들어가요.</p>
    </>
  );
}

function BizTab({ state, today, view, onView, onAdd, onEdit, onTogglePaid, onTogglePayment, onOpenMilestone, onSeedRoadmap, onOpenLead, onOpenNotice }) {
  // Any other value, including a save written before v20, opens the contracts.
  const v = ["rates", "folio", "roadmap", "leads", "notices"].includes(view) ? view : "deals";
  const sum = useMemo(() => bizSummary(state, today), [state, today]);
  return (
    <>
      <section className="bg-zinc-900 border border-zinc-800 rounded-2xl p-4">
        <div className="flex items-center justify-between gap-2">
          <SectionLabel tone="text-cyan-400">사업</SectionLabel>
          <button onClick={() => onAdd(v)}
            className="shrink-0 px-3.5 py-2.5 rounded-xl bg-cyan-400 text-zinc-950 text-sm font-bold flex items-center gap-1 active:translate-y-0.5">
            <Plus size={14} /> {BIZ_ADD_LABEL[v]}
          </button>
        </div>
        {/* Full width, not beside the button: at 390 px a summary line sharing the header row wraps mid-word.
            Each fragment is nowrap for the same reason — measured at 390 px, the plain line broke after
            `입금 미확`, so the only break opportunities left are the separators between the fragments. */}
        <p className="text-xs font-mono text-zinc-400">
          <span className="whitespace-nowrap">이번 달 계약 {wonText(sum.thisMonth)}</span>{" · "}
          <span className="whitespace-nowrap">입금 확인 {wonText(sum.collected)}</span>
        </p>
        <p className="text-xs font-mono text-zinc-400">
          <span className="whitespace-nowrap">남은 계약 {wonText(sum.backlog)}</span>{" · "}
          <span className="whitespace-nowrap">견적 대기 {wonText(sum.pipeline)}</span>{" · "}
          <span className={`whitespace-nowrap ${sum.counts.unpaid > 0 ? "text-rose-400" : ""}`}>입금 미확인 {sum.counts.unpaid}건</span>
        </p>
        {/* Lump sums on their own line (v28), never added to the two lines above; always printed (rule 13) */}
        <p className="text-xs font-mono text-zinc-400">
          <span className={`whitespace-nowrap ${sum.payOverdue > 0 ? "text-rose-400" : ""}`}>일시금 미확인 {sum.payDue.length}건</span>{" · "}
          <span className="whitespace-nowrap">이번 달 일시금 입금 {wonText(sum.payPaidMonth)}</span>
        </p>
        <div className="flex flex-wrap gap-1.5 mt-2.5">
          <Chip on={v === "deals"} onClick={() => onView("deals")}>계약</Chip>
          <Chip on={v === "rates"} onClick={() => onView("rates")}>단가</Chip>
          <Chip on={v === "folio"} onClick={() => onView("folio")}>포트폴리오</Chip>
          <Chip on={v === "roadmap"} onClick={() => onView("roadmap")}>로드맵</Chip>
          <Chip on={v === "leads"} onClick={() => onView("leads")}>리드</Chip>
          <Chip on={v === "notices"} onClick={() => onView("notices")}>공고</Chip>
        </div>
      </section>

      {v === "deals" && <DealsView state={state} month={sum.month} today={today} onEdit={onEdit} onTogglePaid={onTogglePaid} onTogglePayment={onTogglePayment} />}
      {v === "rates" && <RatesView state={state} onEdit={onEdit} />}
      {v === "folio" && <FolioView state={state} onEdit={onEdit} />}
      {v === "roadmap" && <RoadmapView state={state} today={today} onOpen={onOpenMilestone} onSeed={onSeedRoadmap} />}
      {v === "leads" && <LeadsView state={state} today={today} onOpen={onOpenLead} />}
      {v === "notices" && <NoticesView state={state} today={today} onOpen={onOpenNotice} />}
    </>
  );
}

/* ── The three business forms. Same shape as EventModal: a record, no goal, no difficulty, no evidence ── */

function BizField({ value, onChange, placeholder, num }) {
  return (
    <input value={value} onChange={(e) => onChange(e.target.value)} placeholder={placeholder}
      {...(num ? { type: "number", inputMode: "numeric" } : {})}
      className={`w-full bg-zinc-950 border border-zinc-700 rounded-xl px-3 py-2.5 text-sm${num ? " font-mono" : ""}`} />
  );
}

function BizChips({ options, value, onPick }) {
  return (
    <div className="flex flex-wrap gap-1.5">
      {options.map(([k, label]) => <Chip key={k} on={value === k} onClick={() => onPick(k)}>{label}</Chip>)}
    </div>
  );
}

// The `트랙` chip row of every record form (v28): the day job, the business or private life. One row for six forms.
function TrackRow({ value, onPick, caption = "직장 트랙은 AI 패킷에 실리지 않아요." }) {
  return (
    <div>
      <div className="text-xs font-bold tracking-widest text-zinc-500 mb-1.5">트랙</div>
      <BizChips options={TRACK_OPTIONS} value={trackOf({ track: value })} onPick={onPick} />
      {caption && <p className="text-xs text-zinc-600 mt-1.5">{caption}</p>}
    </div>
  );
}
// A record's track as a small mono tag (v28) — the meetings tab heads and the contract rows.
function TrackTag({ track }) {
  const t = trackOf({ track });
  return <span className={`text-xs font-mono font-bold border rounded px-1 shrink-0 ${TRACK_TONE[t]}`}>{TRACK_LABEL[t]}</span>;
}

function BizFormFoot({ err, edit, onSubmit, onRemove }) {
  return (
    <>
      {err && <p className="text-xs text-rose-400">{err}</p>}
      <button onClick={onSubmit} className="w-full py-3 rounded-xl bg-cyan-500 text-zinc-950 font-black text-sm active:translate-y-0.5">
        {edit ? "저장" : "등록"}
      </button>
      {edit && (
        <button onClick={onRemove} className="w-full py-2.5 rounded-xl border border-rose-800 text-rose-300 font-bold text-xs">삭제</button>
      )}
    </>
  );
}

// `prefill` (v28) seeds a new contract from a lead (`makeDealFromLead`); an existing deal ignores it.
function DealModal({ deal, prefill, onClose, onAdd, onUpdate, onRemove }) {
  const seed = deal || prefill;
  const [client, setClient] = useState(seed?.client || "");
  const [title, setTitle] = useState(seed?.title || "");
  const [status, setStatus] = useState(seed?.status || "lead");
  const [startMonth, setStartMonth] = useState(deal?.startMonth || "");
  const [months, setMonths] = useState(deal?.months == null ? "" : String(deal.months));
  const [monthly, setMonthly] = useState(deal?.monthly == null ? "" : String(deal.monthly));
  const [costMonthly, setCostMonthly] = useState(deal?.costMonthly == null ? "" : String(deal.costMonthly));
  const [note, setNote] = useState(deal?.note || "");
  const [track, setTrack] = useState(seed?.track || "biz");
  // Payment lines (v28): the form's rows keep their `id` and `paidAt`; the amount is edited as text.
  const [pays, setPays] = useState(() => dealPayments(deal).map((p) => ({ ...p, amount: p.amount == null ? "" : String(p.amount) })));
  const [err, setErr] = useState("");
  const setPay = (id, patch) => setPays((cur) => cur.map((p) => (p.id === id ? { ...p, ...patch } : p)));

  const submit = () => {
    if (!client.trim()) { setErr("고객사를 입력해 주세요."); return; }
    if (!title.trim()) { setErr("일감 이름을 입력해 주세요."); return; }
    if (status === "won" && !(startMonth && months.trim())) { setErr("계약 상태에서는 시작 월과 개월 수가 필요해요."); return; }
    const n = numField(months);
    if (months.trim() && !(Number.isInteger(n) && n >= 1 && n <= DEAL_MAX_MONTHS)) {
      setErr(`개월 수는 1 이상 ${DEAL_MAX_MONTHS} 이하로 입력해 주세요.`); return;
    }
    const price = numField(monthly);
    if (Number.isNaN(price)) { setErr("월 청구액은 0 이상 숫자로 입력해 주세요."); return; }
    const cost = numField(costMonthly);
    if (Number.isNaN(cost)) { setErr("월 원가는 0 이상 숫자로 입력해 주세요."); return; }
    const bad = pays.findIndex((p) => !p.due || !(numField(p.amount) > 0));
    if (bad >= 0) { setErr(`입금 예정 ${bad + 1}번째 항목의 날짜와 금액을 입력해 주세요.`); return; }
    const payments = pays.map((p) => ({ id: p.id, kind: p.kind, due: p.due, amount: numField(p.amount), ...(p.paidAt ? { paidAt: p.paidAt } : {}) }));
    // A blank number field stores nothing at all — a lead and a quote may carry no numbers. A cleared payment list drops the key.
    const next = {
      client: client.trim(), title: title.trim(), status,
      ...(startMonth ? { startMonth } : {}),
      ...(n == null ? {} : { months: n }),
      ...(price == null ? {} : { monthly: price }),
      ...(cost == null ? {} : { costMonthly: cost }),
      ...(note.trim() ? { note: note.trim() } : {}),
      ...(payments.length ? { payments } : {}),
      track,
    };
    const refused = deal ? onUpdate(deal.id, next) : onAdd(next);
    if (refused) setErr(refused);
  };

  return (
    <Modal title={deal ? "계약 수정" : "새 계약"} onClose={onClose}>
      <div className="space-y-3">
        <BizField value={client} onChange={setClient} placeholder="고객사 — 예: ○○테크" />
        <BizField value={title} onChange={setTitle} placeholder="일감 이름 — 예: 사내 문서 검색 AI 구축" />
        <BizChips options={Object.entries(DEAL_STATUS)} value={status} onPick={(k) => { setStatus(k); setErr(""); }} />
        <label className="flex items-center gap-2 text-xs text-zinc-500">
          <span className="w-24 shrink-0">시작 월</span>
          <input type="month" value={startMonth} onChange={(e) => setStartMonth(e.target.value)}
            className="flex-1 w-0 bg-zinc-950 border border-zinc-700 rounded-xl px-3 py-2 text-sm font-mono" />
        </label>
        <BizField value={months} onChange={setMonths} placeholder="개월 수" num />
        <BizField value={monthly} onChange={setMonthly} placeholder="월 청구액 (원)" num />
        <BizField value={costMonthly} onChange={setCostMonthly} placeholder="월 원가 (원, 선택)" num />
        <BizField value={note} onChange={setNote} placeholder="메모 (선택)" />
        <div>
          <div className="flex items-center justify-between mb-1.5">
            <span className="text-xs font-bold tracking-widest text-zinc-500">입금 예정 (선택)</span>
            <span className="text-xs font-mono text-zinc-500">{pays.length} / {DEAL_PAYMENTS_MAX}</span>
          </div>
          <div className="space-y-1.5">
            {pays.map((p) => (
              <div key={p.id} className="bg-zinc-950 rounded-xl p-2 space-y-1.5">
                <div className="flex items-center gap-1.5">
                  <BizChips options={Object.entries(PAYMENT_KIND)} value={p.kind} onPick={(k) => setPay(p.id, { kind: k })} />
                  {p.paidAt && <span className="ml-auto shrink-0 text-xs font-mono text-emerald-300">입금 확인 {p.paidAt}</span>}
                </div>
                <div className="flex items-center gap-1.5">
                  <input type="date" aria-label="입금 예정일" value={p.due} onChange={(e) => setPay(p.id, { due: e.target.value })}
                    className="flex-1 w-0 bg-zinc-900 border border-zinc-700 rounded-xl px-2 py-2 text-sm font-mono" />
                  <div className="flex-1 min-w-0"><BizField value={p.amount} onChange={(v) => setPay(p.id, { amount: v })} placeholder="금액 (원)" num /></div>
                  <button aria-label="입금 예정 삭제" onClick={() => setPays((cur) => cur.filter((x) => x.id !== p.id))}
                    className="shrink-0 w-8 h-8 rounded-lg border border-zinc-700 text-zinc-400 flex items-center justify-center active:translate-y-0.5"><X size={14} /></button>
                </div>
              </div>
            ))}
          </div>
          <button onClick={() => setPays((cur) => [...cur, { id: uid(), kind: "deposit", due: "", amount: "" }])} disabled={pays.length >= DEAL_PAYMENTS_MAX}
            className="w-full mt-1.5 py-2 rounded-xl border border-zinc-700 text-zinc-300 text-xs font-bold disabled:opacity-30 active:translate-y-0.5">항목 추가</button>
          {pays.length >= DEAL_PAYMENTS_MAX && <p className="text-xs text-zinc-500 mt-1">입금 예정은 12건까지예요.</p>}
        </div>
        <TrackRow value={track} onPick={setTrack} />
        <BizFormFoot err={err} edit={!!deal} onSubmit={submit} onRemove={() => onRemove(deal.id)} />
      </div>
    </Modal>
  );
}

function RateModal({ rate, onClose, onAdd, onUpdate, onRemove }) {
  const [name, setName] = useState(rate?.name || "");
  const [unit, setUnit] = useState(rate?.unit || "month");
  const [price, setPrice] = useState(rate?.price == null ? "" : String(rate.price));
  const [cost, setCost] = useState(rate?.cost == null ? "" : String(rate.cost));
  const [note, setNote] = useState(rate?.note || "");
  const [err, setErr] = useState("");

  const submit = () => {
    if (!name.trim()) { setErr("단가 이름을 입력해 주세요."); return; }
    const p = numField(price);
    if (p == null || Number.isNaN(p)) { setErr("청구가는 0 이상 숫자로 입력해 주세요."); return; }
    const c = numField(cost);
    if (Number.isNaN(c)) { setErr("원가는 0 이상 숫자로 입력해 주세요."); return; }
    const next = { name: name.trim(), unit, price: p, ...(c == null ? {} : { cost: c }), ...(note.trim() ? { note: note.trim() } : {}) };
    if (rate) onUpdate(rate.id, next); else onAdd(next);
  };

  return (
    <Modal title={rate ? "단가 수정" : "새 단가"} onClose={onClose}>
      <div className="space-y-3">
        <BizField value={name} onChange={setName} placeholder="단가 이름 — 예: 웹 앱 개발 (월)" />
        <BizChips options={Object.entries(RATE_UNIT)} value={unit} onPick={(k) => { setUnit(k); setErr(""); }} />
        <BizField value={price} onChange={setPrice} placeholder="청구가 (원)" num />
        <BizField value={cost} onChange={setCost} placeholder="원가 (원, 선택)" num />
        <BizField value={note} onChange={setNote} placeholder="메모 (선택)" />
        <BizFormFoot err={err} edit={!!rate} onSubmit={submit} onRemove={() => onRemove(rate.id)} />
      </div>
    </Modal>
  );
}

/* Owns its own file input, like EvidenceModal — nothing outside this modal touches that ref. The image is
   written only on submit, under the id carried inside the record, so a cancelled form leaves no orphan key. */
function FolioModal({ folio, onClose, onAdd, onUpdate, onRemove }) {
  const [title, setTitle] = useState(folio?.title || "");
  const [summary, setSummary] = useState(folio?.summary || "");
  const [role, setRole] = useState(folio?.role || "");
  const [stack, setStack] = useState((folio?.stack || []).join(", "));
  const [from, setFrom] = useState(folio?.period?.from || "");
  const [to, setTo] = useState(folio?.period?.to || "");
  const [links, setLinks] = useState(folio?.links || []);
  const [url, setUrl] = useState("");
  const [img, setImg] = useState(null);
  const [imgDirty, setImgDirty] = useState(false);
  const [err, setErr] = useState("");
  const fileRef = useRef(null);

  useEffect(() => {
    if (!folio) return undefined;
    let alive = true;
    (async () => {
      const v = await store.get(`liferpg-img-folio-${folio.id}`).catch(() => null);
      if (alive && v) setImg(v);
    })();
    return () => { alive = false; };
  }, [folio]);

  const addLink = (label) => {
    const u = url.trim();
    if (!/^https?:\/\//.test(u)) { setErr("링크는 http:// 또는 https:// 로 시작해야 해요."); return; }
    if (links.length >= FOLIO_LINK_MAX) { setErr(`링크는 ${FOLIO_LINK_MAX}개까지 등록돼요.`); return; }
    setLinks([...links, { label, url: u }]);
    setUrl(""); setErr("");
  };

  // File size is checked before decoding: an 80 MB photo must not be handed to the browser at all.
  const pickFile = async (e) => {
    const fl = e.target.files?.[0];
    e.target.value = "";
    if (!fl) return;
    if (fl.size > IMG_FILE_MAX) {
      setErr(`이미지가 너무 커요 — ${IMG_FILE_MAX / 1048576}MB 이하 파일만 등록돼요. (선택한 파일 ${(fl.size / 1048576).toFixed(1)}MB)`);
      return;
    }
    try { setImg(await resizeImageFit(fl)); setImgDirty(true); setErr(""); }
    catch (e2) { setErr(e2?.message === "too-big" ? "이미지를 줄이지 못했어요 — 더 작은 이미지를 골라 주세요." : "이미지를 읽지 못했어요."); }
  };

  const submit = async () => {
    if (!title.trim()) { setErr("제목을 입력해 주세요."); return; }
    const id = folio?.id || uid();
    let imgWarn = null;
    // The record is saved whatever storage does; a failed write hands its reason back for the second toast.
    if (imgDirty) {
      if (img) { const r = await saveImageChecked(`liferpg-img-folio-${id}`, img); if (!r.ok) imgWarn = r; }
      else await store.del(`liferpg-img-folio-${id}`);
    }
    const tech = stack.split(",").map((t) => t.trim()).filter(Boolean);
    const next = {
      id, title: title.trim(), links,
      ...(summary.trim() ? { summary: summary.trim() } : {}),
      ...(role.trim() ? { role: role.trim() } : {}),
      ...(tech.length ? { stack: tech } : {}),
      ...(from && to ? { period: { from, to } } : {}),
    };
    if (folio) onUpdate(folio.id, next, imgWarn); else onAdd(next, imgWarn);
  };

  return (
    <Modal title={folio ? "포트폴리오 수정" : "새 포트폴리오"} onClose={onClose}>
      <div className="space-y-3">
        <BizField value={title} onChange={setTitle} placeholder="제목 — 예: 사내 문서 검색 AI" />
        <BizField value={summary} onChange={setSummary} placeholder="한 줄 설명 (선택)" />
        <BizField value={role} onChange={setRole} placeholder="역할 (선택) — 예: 기획·개발 단독" />
        <BizField value={stack} onChange={setStack} placeholder="기술 (선택, 쉼표로 구분) — 예: React, FastAPI, pgvector" />
        <div className="flex items-center gap-2">
          <input type="month" value={from} onChange={(e) => setFrom(e.target.value)}
            className="flex-1 w-0 bg-zinc-950 border border-zinc-700 rounded-xl px-3 py-2.5 text-sm font-mono" />
          <span className="text-xs text-zinc-500">~</span>
          <input type="month" value={to} onChange={(e) => setTo(e.target.value)}
            className="flex-1 w-0 bg-zinc-950 border border-zinc-700 rounded-xl px-3 py-2.5 text-sm font-mono" />
        </div>
        <div className="bg-zinc-950 border border-zinc-800 rounded-xl p-3">
          <input value={url} onChange={(e) => setUrl(e.target.value)} placeholder="링크 주소 — https://…"
            className="w-full bg-zinc-900 border border-zinc-700 rounded-lg px-2.5 py-2 text-sm" />
          <div className="flex flex-wrap gap-1.5 mt-2">
            {FOLIO_LINK_LABELS.map((l) => <Chip key={l} onClick={() => addLink(l)}>{l}</Chip>)}
          </div>
          {links.length > 0 && (
            <div className="flex flex-wrap gap-1.5 mt-2">
              {links.map((l, i) => (
                <button key={`${l.label}-${i}`} onClick={() => setLinks(links.filter((_, j) => j !== i))}
                  className="px-2.5 py-1.5 rounded-full border border-zinc-700 text-zinc-300 text-xs font-bold">{l.label} ✕</button>
              ))}
            </div>
          )}
        </div>
        <div>
          <input ref={fileRef} type="file" accept="image/*" className="hidden" onChange={pickFile} />
          {img ? (
            <div className="relative rounded-xl overflow-hidden border border-zinc-700">
              <img src={img} alt={title} className="w-full max-h-48 object-contain bg-zinc-950" />
              <button onClick={() => { setImg(null); setImgDirty(true); }}
                className="absolute top-1.5 right-1.5 w-6 h-6 rounded-md bg-zinc-950 bg-opacity-80 text-xs text-zinc-300">✕</button>
            </div>
          ) : (
            <button onClick={() => fileRef.current?.click()}
              className="w-full py-7 rounded-xl border-2 border-dashed border-zinc-700 flex flex-col items-center gap-1.5 active:border-cyan-600">
              <Paperclip size={20} className="text-zinc-500" />
              <span className="text-xs font-medium text-zinc-400">📎 대표 이미지 1장 (선택)</span>
              <span className="text-xs text-zinc-600">JPG·PNG · 가로세로 비율 그대로 저장돼요</span>
            </button>
          )}
        </div>
        <BizFormFoot err={err} edit={!!folio} onSubmit={submit} onRemove={() => onRemove(folio.id)} />
      </div>
    </Modal>
  );
}

/* ── Milestone form (v28) — a record: no goal, no difficulty, no evidence, no payout (rules 1, 18). The D-day, the linked
   work and the pace in the facts are derived at render (rule 9). ── */
// One link block of the milestone and notice forms: a header with the count against `max` and one checkbox row per record.
function MilestoneLinkList({ label, rows, ids, onToggle, empty, max = MILESTONE_LINKS }) {
  return (
    <div>
      <div className="text-xs font-bold tracking-widest text-zinc-500 mb-1.5">
        {label} <span className={`font-mono ${ids.length > max ? "text-rose-300" : ""}`}>({ids.length}/{max})</span>
      </div>
      {rows.length === 0 ? <p className="text-xs text-zinc-500">{empty}</p> : (
        <div className="space-y-1 max-h-48 overflow-y-auto">
          {rows.map((r) => {
            const on = ids.includes(r.id);
            return (
              <button key={r.id} role="checkbox" aria-checked={on} onClick={() => onToggle(r.id)}
                className={`w-full text-left flex items-center gap-2 rounded-xl px-2.5 py-2 border bg-zinc-950 ${on ? "border-cyan-700" : "border-zinc-800"}`}>
                <span className={`w-4 h-4 shrink-0 rounded border flex items-center justify-center ${on ? "bg-cyan-400 border-cyan-300 text-zinc-950" : "border-zinc-600"}`}>
                  {on && <Check size={12} />}
                </span>
                {r.lead && <span className="font-mono text-xs text-zinc-500 shrink-0">{r.lead}</span>}
                <span className={`flex-1 min-w-0 text-sm truncate ${r.done ? "line-through text-zinc-500" : ""}`}>{r.text}</span>
              </button>
            );
          })}
        </div>
      )}
    </div>
  );
}

function MilestoneModal({ state, milestone, today, onClose, onAdd, onUpdate, onRemove }) {
  const deals = state.deals || [];
  const projects = state.meetingProjects || [];
  const documents = state.documents || [];
  const works = state.work || [];
  // A deleted link target is dropped from the initial selection, so it is never counted.
  const live = (list, pool) => (list || []).filter((id) => pool.some((r) => r.id === id));
  const [title, setTitle] = useState(milestone?.title || "");
  const [stage, setStage] = useState(Number.isFinite(milestone?.stage) ? milestone.stage : null);
  const [due, setDue] = useState(milestone?.due || "");
  const [status, setStatus] = useState(milestone?.status || "planned");
  const [condition, setCondition] = useState(milestone?.condition || "");
  const [dealIds, setDealIds] = useState(() => live(milestone?.dealIds, deals));
  const [projectId, setProjectId] = useState(() => (projects.some((p) => p.id === milestone?.projectId) ? milestone.projectId : ""));
  const [documentIds, setDocumentIds] = useState(() => live(milestone?.documentIds, documents));
  const [workIds, setWorkIds] = useState(() => live(milestone?.workIds, works));
  const [err, setErr] = useState("");
  const toggle = (setter) => (id) => setter((cur) => (cur.includes(id) ? cur.filter((x) => x !== id) : [...cur, id]));
  // The newest MILESTONE_WORK_ROWS items by date then creation, plus every already-linked item whatever its age.
  const workRows = useMemo(() => {
    const newest = works.slice().sort((a, b) => b.date.localeCompare(a.date) || String(b.createdAt || "").localeCompare(String(a.createdAt || "")));
    const older = newest.slice(MILESTONE_WORK_ROWS).filter((w) => (milestone?.workIds || []).includes(w.id));
    return [...newest.slice(0, MILESTONE_WORK_ROWS), ...older].map((w) => ({ id: w.id, lead: w.date.slice(2), text: w.title, done: w.done }));
  }, [works, milestone]);
  const pace = milestone ? milestonePace(state, milestone, today) : null;
  const work = milestone ? milestoneWork(state, milestone) : null;
  const submit = () => {
    const t = title.trim();
    const c = condition.trim();
    if (!t) { setErr("마일스톤 이름을 입력해 주세요."); return; }
    if (t.length > MILESTONE_LIMITS.title) { setErr(`마일스톤 이름은 ${MILESTONE_LIMITS.title}자까지예요 — 지금 ${t.length}자예요.`); return; }
    if (c.length > MILESTONE_LIMITS.condition) { setErr(`달성 조건은 ${MILESTONE_LIMITS.condition}자까지예요 — 지금 ${c.length}자예요.`); return; }
    if ([dealIds, documentIds, workIds].some((l) => l.length > MILESTONE_LINKS)) { setErr(`연결은 종류별 ${MILESTONE_LINKS}개까지예요.`); return; }
    const next = {
      title: t, ...(stage != null ? { stage } : {}), ...(due ? { due } : {}), status,
      ...(status === "done" ? { doneAt: milestone?.doneAt || today } : {}),
      ...(c ? { condition: c } : {}),
      dealIds, ...(projectId ? { projectId } : {}), documentIds, workIds,
    };
    const refused = milestone ? onUpdate(milestone.id, next) : onAdd(next);
    if (refused) setErr(refused);
  };
  return (
    <Modal title={milestone ? "마일스톤" : "마일스톤 추가"} onClose={onClose}>
      <div className="space-y-3">
        {milestone && (
          <div className="space-y-1">
            <CvFact label="기한"><span className="font-mono">{milestone.due ? `${milestone.due} (${ddayStr(milestone.due)})` : "없음"}</span></CvFact>
            <CvFact label="연결 업무"><span className="font-mono">{work.done}/{work.total}</span></CvFact>
            <CvFact label="페이스"><span className={pace.cls}>{pace.label}</span></CvFact>
            <CvFact label="완료일"><span className="font-mono">{milestone.doneAt || "-"}</span></CvFact>
          </div>
        )}
        <BizField value={title} onChange={setTitle} placeholder="마일스톤 — 예: 계약금 입금 확인" />
        <div>
          <div className="text-xs font-bold tracking-widest text-zinc-500 mb-1.5">단계</div>
          <BizChips value={stage == null ? "none" : String(stage)} onPick={(k) => setStage(k === "none" ? null : Number(k))}
            options={[["none", "없음"], ...Array.from({ length: ROADMAP_STAGES }, (_, i) => [String(i + 1), String(i + 1)])]} />
        </div>
        <div>
          <div className="text-xs font-bold tracking-widest text-zinc-500 mb-1.5">기한 (선택)</div>
          <input type="date" value={due} onChange={(e) => setDue(e.target.value)} aria-label="기한"
            className="w-full bg-zinc-950 border border-zinc-700 rounded-xl px-3 py-2.5 text-sm font-mono" />
        </div>
        <div>
          <div className="text-xs font-bold tracking-widest text-zinc-500 mb-1.5">상태</div>
          <BizChips options={Object.entries(MILESTONE_STATUS)} value={status} onPick={setStatus} />
        </div>
        <MeetingText value={condition} onChange={setCondition} placeholder="달성 조건 (선택) — 사실로 확인할 수 있는 조건을 적어요" rows={2} cap={MILESTONE_LIMITS.condition} />
        <MilestoneLinkList label="계약 연결" ids={dealIds} onToggle={toggle(setDealIds)} empty="등록한 계약이 없어요."
          rows={deals.map((d) => ({ id: d.id, text: `${d.client} · ${d.title}` }))} />
        <div>
          <div className="text-xs font-bold tracking-widest text-zinc-500 mb-1.5">프로젝트 (선택)</div>
          <select value={projectId} onChange={(e) => setProjectId(e.target.value)} aria-label="프로젝트 (선택)"
            className="w-full bg-zinc-950 border border-zinc-700 rounded-xl px-3 py-2.5 text-sm">
            <option value="">연결 안 함</option>
            {projects.map((p) => <option key={p.id} value={p.id}>{p.name}</option>)}
          </select>
        </div>
        <MilestoneLinkList label="문서 연결" ids={documentIds} onToggle={toggle(setDocumentIds)} empty="등록한 문서가 없어요."
          rows={documents.map((d) => ({ id: d.id, text: d.title }))} />
        <MilestoneLinkList label="업무 연결" ids={workIds} onToggle={toggle(setWorkIds)} empty="등록한 업무가 없어요."
          rows={workRows} />
        <BizFormFoot err={err} edit={!!milestone} onSubmit={submit}
          onRemove={() => { if (window.confirm(`${milestone.title} 마일스톤을 삭제해요. 계속할까요?`)) onRemove(milestone.id); }} />
      </div>
    </Modal>
  );
}

/* ── Lead form (v28) — a record: no goal, no difficulty, no evidence, no payout (rules 1, 18). `stageAt` and the contract
   link are the root's to write; the form writes the name, the stage and the optional fields it shows. ── */
// A form label above a field of the pipeline and notice forms.
function FormLabel({ children }) {
  return <div className="text-xs font-bold tracking-widest text-zinc-500 mb-1.5">{children}</div>;
}

function LeadModal({ state, lead, onClose, onAdd, onUpdate, onRemove, onMakeDeal }) {
  const [name, setName] = useState(lead?.name || "");
  const [stage, setStage] = useState(lead?.stage || "potential");
  const [contact, setContact] = useState(lead?.contact || "");
  const [nextAction, setNextAction] = useState(lead?.nextAction || "");
  const [nextDue, setNextDue] = useState(lead?.nextDue || "");
  const [note, setNote] = useState(lead?.note || "");
  const [err, setErr] = useState("");
  const deal = lead?.dealId ? (state.deals || []).find((d) => d.id === lead.dealId) : null;
  const dealText = !lead?.dealId ? "연결 없음" : deal ? `${deal.client} · ${deal.title}` : "연결 대상이 삭제됐어요";
  const submit = () => {
    const t = { name: name.trim(), contact: contact.trim(), nextAction: nextAction.trim(), note: note.trim() };
    if (!t.name) { setErr("병원·기관 이름을 입력해 주세요."); return; }
    if (t.name.length > LEAD_LIMITS.name) { setErr(`이름은 ${LEAD_LIMITS.name}자까지예요 — 지금 ${t.name.length}자예요.`); return; }
    if (t.contact.length > LEAD_LIMITS.contact) { setErr(`담당자·연락 경로는 ${LEAD_LIMITS.contact}자까지예요 — 지금 ${t.contact.length}자예요.`); return; }
    if (t.nextAction.length > LEAD_LIMITS.nextAction) { setErr(`다음 액션은 ${LEAD_LIMITS.nextAction}자까지예요 — 지금 ${t.nextAction.length}자예요.`); return; }
    if (t.note.length > LEAD_LIMITS.note) { setErr(`메모는 ${LEAD_LIMITS.note}자까지예요 — 지금 ${t.note.length}자예요.`); return; }
    const next = {
      name: t.name, stage,
      ...(t.contact ? { contact: t.contact } : {}),
      ...(t.nextAction ? { nextAction: t.nextAction } : {}),
      ...(nextDue ? { nextDue } : {}),
      ...(t.note ? { note: t.note } : {}),
    };
    const refused = lead ? onUpdate(lead.id, next) : onAdd(next);
    if (refused) setErr(refused);
  };
  return (
    <Modal title={lead ? "리드" : "리드 추가"} onClose={onClose}>
      <div className="space-y-3">
        {lead && (
          <div className="space-y-1">
            <CvFact wide label="단계 변경일"><span className="font-mono">{lead.stageAt || "-"}</span></CvFact>
            <CvFact wide label="계약"><span className={lead.dealId && !deal ? "text-rose-300" : ""}>{dealText}</span></CvFact>
          </div>
        )}
        <BizField value={name} onChange={setName} placeholder="병원·기관 이름 — 예: □□병원" />
        <div>
          <FormLabel>단계</FormLabel>
          <BizChips options={Object.entries(LEAD_STAGE_LABEL)} value={stage} onPick={(k) => { setStage(k); setErr(""); }} />
        </div>
        <BizField value={contact} onChange={setContact} placeholder="담당자·연락 경로 (선택)" />
        <BizField value={nextAction} onChange={setNextAction} placeholder="다음 액션 (선택) — 예: 시연 일정 제안" />
        <div>
          <FormLabel>다음 액션 기한 (선택)</FormLabel>
          <input type="date" value={nextDue} onChange={(e) => setNextDue(e.target.value)} aria-label="다음 액션 기한"
            className="w-full bg-zinc-950 border border-zinc-700 rounded-xl px-3 py-2.5 text-sm font-mono" />
        </div>
        <MeetingText value={note} onChange={setNote} placeholder="메모 (선택)" rows={3} cap={LEAD_LIMITS.note} />
        {/* The saved stage decides, so the contract form is prefilled from what the lead record says */}
        {lead && ["quote", "won"].includes(lead.stage) && !deal && (
          <button onClick={() => onMakeDeal(lead)}
            className="w-full py-2.5 rounded-xl border border-zinc-700 text-zinc-300 font-bold text-xs active:translate-y-0.5">계약 만들기 ›</button>
        )}
        <BizFormFoot err={err} edit={!!lead} onSubmit={submit}
          onRemove={() => { if (window.confirm(`${lead.name} 리드를 삭제해요. 계속할까요?`)) onRemove(lead.id); }} />
      </div>
    </Modal>
  );
}

/* ── Notice form (v28) — a record of a national-project call: no goal, no evidence, no payout (rules 1, 18). ── */
function NoticeModal({ state, notice, onClose, onAdd, onUpdate, onRemove }) {
  const documents = state.documents || [];
  const [title, setTitle] = useState(notice?.title || "");
  const [agency, setAgency] = useState(notice?.agency || "");
  const [postedAt, setPostedAt] = useState(notice?.postedAt || "");
  const [deadline, setDeadline] = useState(notice?.deadline || "");
  const [status, setStatus] = useState(notice?.status || "review");
  // A deleted document is dropped from the initial selection, so it is never counted.
  const [documentIds, setDocumentIds] = useState(() => (notice?.documentIds || []).filter((id) => documents.some((d) => d.id === id)));
  const [note, setNote] = useState(notice?.note || "");
  const [err, setErr] = useState("");
  const submit = () => {
    const t = title.trim(), a = agency.trim(), n = note.trim();
    if (!t) { setErr("공고 이름을 입력해 주세요."); return; }
    if (!a) { setErr("기관을 입력해 주세요."); return; }
    if (!deadline) { setErr("마감일을 선택해 주세요."); return; }
    if (t.length > NOTICE_LIMITS.title) { setErr(`공고 이름은 ${NOTICE_LIMITS.title}자까지예요 — 지금 ${t.length}자예요.`); return; }
    if (a.length > NOTICE_LIMITS.agency) { setErr(`기관은 ${NOTICE_LIMITS.agency}자까지예요 — 지금 ${a.length}자예요.`); return; }
    if (n.length > NOTICE_LIMITS.note) { setErr(`메모는 ${NOTICE_LIMITS.note}자까지예요 — 지금 ${n.length}자예요.`); return; }
    if (documentIds.length > NOTICE_DOCS_MAX) { setErr(`문서 연결은 ${NOTICE_DOCS_MAX}개까지예요.`); return; }
    const next = { title: t, agency: a, ...(postedAt ? { postedAt } : {}), deadline, status, documentIds, ...(n ? { note: n } : {}) };
    const refused = notice ? onUpdate(notice.id, next) : onAdd(next);
    if (refused) setErr(refused);
  };
  return (
    <Modal title={notice ? "공고" : "공고 추가"} onClose={onClose}>
      <div className="space-y-3">
        <BizField value={title} onChange={setTitle} placeholder="공고 이름 — 예: AI 바우처 지원사업" />
        <BizField value={agency} onChange={setAgency} placeholder="기관 — 예: ○○진흥원" />
        <div>
          <FormLabel>공고일 (선택)</FormLabel>
          <input type="date" value={postedAt} onChange={(e) => setPostedAt(e.target.value)} aria-label="공고일"
            className="w-full bg-zinc-950 border border-zinc-700 rounded-xl px-3 py-2.5 text-sm font-mono" />
        </div>
        <div>
          <FormLabel>마감일</FormLabel>
          <input type="date" value={deadline} onChange={(e) => setDeadline(e.target.value)} aria-label="마감일"
            className="w-full bg-zinc-950 border border-zinc-700 rounded-xl px-3 py-2.5 text-sm font-mono" />
        </div>
        <div>
          <FormLabel>상태</FormLabel>
          <BizChips options={Object.entries(NOTICE_STATUS_LABEL)} value={status} onPick={setStatus} />
        </div>
        <MilestoneLinkList label="문서 연결" max={NOTICE_DOCS_MAX} ids={documentIds} empty="등록한 문서가 없어요."
          onToggle={(id) => setDocumentIds((cur) => (cur.includes(id) ? cur.filter((x) => x !== id) : [...cur, id]))}
          rows={documents.map((d) => ({ id: d.id, text: `${d.title} · ${TRACK_LABEL[trackOf(d)]}` }))} />
        <MeetingText value={note} onChange={setNote} placeholder="메모 (선택)" rows={3} cap={NOTICE_LIMITS.note} />
        <BizFormFoot err={err} edit={!!notice} onSubmit={submit}
          onRemove={() => { if (window.confirm(`${notice.title} 공고를 삭제해요. 계속할까요?`)) onRemove(notice.id); }} />
      </div>
    </Modal>
  );
}

/* ───────────────────────── Meetings — project minutes (schema v23) ───────────────────────── */
/* A meeting is a record of what was said, never a task and never an appointment: no payout, no trophy, no goal, no
   streak, no evidence gate (rules 1, 18), and nothing here reaches the briefing, the to-do list or the assistant packet
   (rule 7). The time of a meeting lives only in `일정`; a meeting stores its date and, optionally, the id of the event
   whose occurrence falls on that date, and reads that event's time and title at render. A meeting may have no project
   (`projectId: null`, 2026-09-17): an urgent memo, listed under `프로젝트 없음 · 긴급 메모` after the project sections.
   A pasted transcription may be kept as pasted in `transcript` (2026-09-17, capped below) — stored, never processed:
   no summary, split or judgement is made from it, and nothing but the form and the view reads it (rule 7, SECURITY.md).
   Storage arithmetic (the budget is counted in string length, like `storageUsedBytes`: 3.5 × 1,048,576 = 3,672,064
   chars shared with the rest of the save and every thumbnail). An empty record costs about 190 chars (ids, both
   dates, keys, the comma); a record with every field full costs 40 + 80 + 5,000 + 600 + 600 + 190 = 6,510 chars plus one
   per newline (caps widened at the user's request on 2026-09-16 and twice on 2026-09-17, from 800 / 200 / 200); a typical one (25 / 30 / 400 / 100 /
   100) stays about 850, since a higher cap does not make minutes longer. At three a working day (750 a year) typical
   minutes use 0.64 M chars a year — 52 % of the budget after three years, 87 % after five; completely full records use
   4.88 M a year and cross the budget in about nine months.
   So the caps alone promise nothing, and two facts guard the rest: the tab always states the storage in use, and a
   save that would cross the budget is refused with the form kept open (`recordFits` in the root).
   Task links (v24) add `,"taskIds":[]` = 13 chars to every record and 12 per linked id (a 10-char uid, two quotes,
   a comma), so ten links cost 13 + 120 − 1 = 132 chars: a full record reaches about 6,642. `recordFits` measures the
   serialised record, `taskIds` included, so the same guard covers it.
   Progress entries and the AI flag (v25) add `,"progress":[]` (14) + `,"aiHidden":false` (17) = 31 chars to every
   record. One entry is `{"id":"…","date":"YYYY-MM-DD","text":""}` ≈ 45 chars + its text (+ 1 comma): a typical
   80-char entry ≈ 125, a full 300-char entry ≈ 345, and thirty full entries ≈ 10,380 — so a completely full meeting
   with ten links and thirty full entries ≈ 6,642 + 31 + 10,380 ≈ 17,050 chars. Typical minutes with three typical
   entries ≈ 850 + 31 + 375 ≈ 1,260 chars; three a working day ≈ 0.95 M chars a year (26 % of the budget a year,
   about 3 years 10 months before the guard applies). `recordFits` measures the whole record, `progress` included.
   Follow-up items (v26) add `,"followUps":[]` = 15 chars to every record. One item is
   `{"id":"…","text":"","mine":false,"done":false}` ≈ 50 chars + its text (+ 1 comma); `,"due":"YYYY-MM-DD"` adds 19 and
   `,"workId":"…"` adds 22, so a fully-keyed item is ≈ 92 chars + text: a typical 40-char item ≈ 90 without a due date,
   ≈ 132 with a due date and a work link; a full 200-char item with both ≈ 292, and thirty of them ≈ 8,760. A completely
   full meeting with thirty full follow-ups ≈ 17,050 + 15 + 8,760 ≈ 25,825 chars. Typical minutes with three typical
   progress entries and four typical follow-ups ≈ 850 + 375 + 31 + 15 + 520 ≈ 1,810 chars; three a working day ≈ 1.36 M
   chars a year (37 % of the budget a year, about 2 years 8 months before `recordFits` refuses). Each mine follow-up
   also creates a work item — the v25 overhead (~100) + title (≤ 60) + a meeting link with `followUpId` (≈ 66) ≈ 210
   chars for a 40-char text; a text over 60 chars is copied whole into `note` (≤ 200), so the largest such item ≈ 436.
   `commitMeeting` measures the meeting record plus every work item the reconcile creates before either is written.
   A transcript (2026-09-17) adds `,"transcript":""` = 15 chars only when one exists; `"projectId":null` (16) against
   `"projectId":"xxxxxxxxxx"` (24) makes a memo 8 chars smaller. `JSON.stringify` writes every line break as two chars
   and escapes every double quote, so a full 30,000-char transcript with ~300 line breaks stores as ≈ 30,315 chars, and
   a completely full meeting with one ≈ 25,825 + 15 + 30,315 ≈ 56,140. Full transcripts alone: 3,672,064 / 30,315 ≈ 121
   by the guard's own unit; browsers meter localStorage in UTF-16 units (commonly 5 MiB an origin ≈ 2.6 M chars), so
   the physical bound is nearer 55 — the guard is a heuristic ceiling and overstates the room (TD-59). Typical: a
   ten-minute voice memo ≈ 2,500 Korean chars ≈ 2,540 stored; three a week ≈ 0.4 M chars a year (11 % of the budget);
   one on every one of three meetings a working day turns the v26 horizon (1,810 each, 37 % a year) into ≈ 4,350 × 750
   ≈ 3.26 M a year (89 %), about 1 year 1 month before `recordFits` refuses. `recordFits` already measures the whole
   record, transcript included, and the tab's storage line already counts it; `clearTranscript` (`녹취록 지우기`) is
   the in-app way to reclaim it.
   Documents (v27) add `,"documents":[]` = 15 chars once. One document is
   `{"id":"…","projectId":"…","title":"","summary":"","addedAt":"YYYY-MM-DD"}` ≈ 91 chars + title + summary (+ 1 comma);
   `,"source":""` adds 12 + the source and `"projectId":null` is 8 chars smaller. A full document (60 + 120 + 5,000) ≈
   5,283 chars (+ 1 per line break in the summary); a typical one (title 20, source 30, summary 600) ≈ 753. Two a week ≈
   100 a year ≈ 75 k chars (2 % of the budget a year); one full document every working day ≈ 250 × 5,283 ≈ 1.32 M (36 %
   a year). Checks (v27) on an event: one item `{"id":"…","text":"","done":false,"source":"manual"}` ≈ 60 chars + text,
   and `,"checks":[]` adds 12 the first time; a typical 40-char check ≈ 100, thirty full 200-char checks ≈ 30 × 260 + 29 ≈
   7,829 chars on one event, ten such events ≈ 78 k (2 %). `recordFits` measures a document record whole, and a check
   write measures the event as it will be written against the stored one, so ticking or deleting never trips the guard. */
const MEETING_LIMITS = { title: 40, attendees: 80, summary: 5000, decisions: 600, actions: 600, tasks: 10, progress: 300, followUp: 200, transcript: 30000 };
const MEETING_PROGRESS_MAX = 30;   // progress entries per meeting before `진행사항은 30건까지예요.`
const MEETING_FOLLOWUPS_MAX = 30;  // follow-up items per meeting before `후속 항목은 30건까지예요.`
const MEETING_TASK_ROWS = 30;      // candidate rows rendered before `할 일 {n}건 더 있음 — 검색어로 좁혀요`
const PROJECT_LIMITS = { name: 40, note: 200 };
const DOC_LIMITS = { title: 60, source: 120, summary: 5000 };
const DOC_SUMMARY_CLIP = 100;    // chars of a document's summary on the prep card and the reader
const MEETING_ROWS_SHOWN = 5; // rows per project before `{n}건 더 보기`
// The meeting-prep card (`오늘 회의 준비`): the window and how much of the last meeting it states.
const PREP_DAYS = 2;             // today and tomorrow
const PREP_FOLLOWUPS = 10;       // open follow-up lines before `{k}건 더`
const PREP_PROGRESS = 3;         // newest progress entries
const PREP_TASKS = 5;            // linked task lines
const PREP_DECISION_CLIP = 200;  // chars of the last meeting's decisions
const PREP_DOCS = 5;             // document lines on the prep card before `{k}건 더`
// Pre-meeting checks (v27) on one schedule event.
const EVENT_CHECKS_MAX = 30;     // `확인할 것` items per event before `확인할 것은 30건까지예요.`
const EVENT_CHECK_TEXT = 200;    // chars of one check item
const mbText = (chars) => (chars / 1048576).toFixed(1);
const meetingOrder = (a, b) => b.date.localeCompare(a.date) || (b.createdAt || "").localeCompare(a.createdAt || "");
// Documents newest first; a stable sort keeps the handler's prepend order within one day.
const docOrder = (a, b) => b.addedAt.localeCompare(a.addedAt);

// Candidate follow-up items split out of the free-text `actions`, on demand only — the text itself is never rewritten
// (rule 12). Splits on newlines, on ` / `, before every circled number and before ` 1) ` / ` 1. `; strips one leading
// list marker per piece; trims, drops empties, clips to the item cap and drops exact duplicates (the first is kept).
// A number not followed by `)` or `.` is not a marker, and a decimal (`1.5`) is not one either.
const splitFollowUpText = (text) => {
  const seen = new Set();
  return String(text || "").replace(/\r\n?/g, "\n")
    .replace(/[①-⑳]/g, "\n$&")
    .replace(/ (?=\d{1,2}[.)] )/g, "\n")
    .split(/\n| \/ /)
    .map((t) => t.replace(/^\s*(?:[-•*·]|[①-⑳]|\(\d{1,2}\)|\d{1,2}[.)](?!\d))/, "").trim().slice(0, MEETING_LIMITS.followUp))
    .filter((t) => t && !seen.has(t) && seen.add(t));
};
// The date of the work item a mine follow-up registers: the meeting's date when it is today or later, otherwise today.
const followUpWorkDate = (meetingDate, today) => (meetingDate >= today ? meetingDate : today);
// The work item mirroring a mine follow-up: a record with no goal, difficulty or points (rule 18); only `done` mirrors.
// `track` (v28) is the meeting's track at creation; the item keeps its own field afterwards.
const followUpWorkItem = (fu, m, today, track) => ({
  id: uid(), date: followUpWorkDate(m.date, today), title: fu.text.slice(0, WORK_LIMITS.title),
  ...(fu.text.length > WORK_LIMITS.title ? { note: fu.text.slice(0, WORK_LIMITS.note) } : {}),
  done: fu.done === true, link: { kind: "meeting", id: m.id, followUpId: fu.id }, source: "meeting", track: trackOf({ track }), createdAt: today,
});
// Reconciles the work items with a meeting record about to be written (`prev` = the stored record, or null). Pure:
// answers `{ work, meeting }` and writes nothing. Per follow-up, in order: a `workId` naming no live item is dropped; a
// mine item without a live item is registered only when it is new or was not mine before (an item the user deleted is
// never re-created by a later save); an item no longer mine loses its undone work item (a done one stays linked); a
// live item takes the follow-up's `done` — the meeting side wins, since this runs on meeting writes. A follow-up
// removed from the record takes its undone work item with it; a done one stays (TD-54).
const reconcileFollowUps = (work, rec, prev, today, track) => {
  let out = work.slice();
  const live = (id) => (id ? out.find((w) => w.id === id) : undefined);
  const drop = (id) => { out = out.filter((w) => w.id !== id); };
  const before = new Map((prev?.followUps || []).map((f) => [f.id, f]));
  const followUps = (rec.followUps || []).map((f) => {
    const fu = { ...f };
    let item = live(fu.workId);
    if (!item) delete fu.workId;
    const old = before.get(fu.id);
    if (fu.mine && !item && (!old || !old.mine)) {
      item = followUpWorkItem(fu, rec, today, track);
      out.push(item);
      fu.workId = item.id;
    }
    if (!fu.mine && item && !item.done) { drop(item.id); delete fu.workId; item = null; }
    const done = fu.done === true;
    if (item && item.done !== done) out = out.map((w) => (w.id === item.id ? { ...w, done } : w));
    return fu;
  });
  const kept = new Set(followUps.map((f) => f.id));
  for (const f of prev?.followUps || []) {
    const item = kept.has(f.id) ? null : live(f.workId);
    if (item && !item.done) drop(item.id);
  }
  return { work: out, meeting: { ...rec, followUps } };
};

// The event line of a meeting, read live: a link to an event that no longer exists is stated, never cleaned up.
const meetingEventText = (state, m) => {
  if (!m.eventId) return "연결 없음";
  const ev = (state.events || []).find((e) => e.id === m.eventId);
  return ev ? `${ev.time || "시간 미정"} ${ev.title}` : "연결된 일정이 삭제됐어요";
};

// Whether a task is closed today: a daily task ticked today, or a finished once task.
const taskClosedOn = (q, today) => (q.type === "daily" ? (q.doneDates || []).includes(today) : q.status === "done");

// Link candidates for the meeting form: open tasks in the to-do list's own order, then every completed task, newest
// first — minutes often concern work finished long ago, so no age cut-off (2026-09-16). Each row carries the lead chip
// of its to-do row. The picker's row cap and search keep a long history usable. Derived, never stored.
const meetingTaskCandidates = (state, today) => {
  const open = todoOf(state, today).groups
    .flatMap((g) => g.rows)
    .filter((r) => r.kind === "task" && !r.done && !taskClosedOn(r.task, today))
    .map((r) => ({ q: r.task, lead: todoLeadOf(r, today), done: false }));
  const seen = new Set(open.map((c) => c.q.id));
  const done = (state.tasks || [])
    .filter((q) => !seen.has(q.id) && lastDoneDate(q))
    .sort((a, b) => (lastDoneDate(b) || "").localeCompare(lastDoneDate(a) || "") || a.title.localeCompare(b.title))
    .map((q) => ({ q, lead: todoLeadOf({ kind: "task", task: q, date: q.due || null }, today, true), done: true }));
  return [...open, ...done];
};

// The minutes whose `taskIds` name a task, newest first — the task sheet's reverse list, computed at render (rule 9).
const meetingsOfTask = (state, taskId) => (state.meetings || []).filter((m) => (m.taskIds || []).includes(taskId)).sort(meetingOrder);

// One linked task as a to-do row: `완료` when closed, otherwise the to-do row's own lead chip.
const linkedTaskLead = (q, today) => todoLeadOf({ kind: "task", task: q, date: q.due || null }, today);

// The meeting-prep rows: every open schedule occurrence today and tomorrow that belongs to a live meeting project — by
// the event's own `projectId`, else by a previous meeting whose trimmed title equals the event's (the newest such
// meeting names the project). Each row carries the project's newest meeting, its open follow-ups (mine first, stable),
// its newest progress entries, its live linked tasks and the project's documents (v27). Pure and derived at render, never stored (rule 9); the card
// and the briefing read the same rows. Date ascending, then `eventsOn`'s order.
// The live meeting project an event belongs to, or null: the event's own `projectId` first, else the project of the
// newest meeting whose trimmed title equals the event's. Derived at render, never stored (rule 9).
const eventProjectOf = (state, ev) => {
  const projects = state.meetingProjects || [];
  const liveProject = (id) => (id ? projects.find((p) => p.id === id) || null : null);
  const title = String(ev?.title || "").trim();
  return liveProject(ev?.projectId)
    || liveProject((state.meetings || []).slice().sort(meetingOrder).find((m) => m.title.trim() === title)?.projectId);
};
// A meeting's track (v28): a project-less memo carries its own; a project meeting inherits its project's and stores
// none. A missing or unknown value reads as `work`, the safe default. Derived at render, never stored (rule 9).
const meetingTrack = (state, m) => (m?.projectId == null
  ? trackOf(m)
  : trackOf((state.meetingProjects || []).find((p) => p.id === m.projectId)));
// The contracts of a project's client: a deal whose trimmed `client` is part of the project name. No stored link (TD-63).
const dealsOfProject = (state, project) => (state.deals || []).filter((d) => String(d.client || "").trim() && project.name.includes(d.client.trim()));
// The duplicate key of an event's checks — the same normalisation the work reply uses: trimmed, spaces removed, lower-cased.
const checkTexts = (ev) => new Set((ev.checks || []).map((c) => normWorkTitle(c.text)));

const meetingPrepOf = (state, today) => {
  const meetings = (state.meetings || []).slice().sort(meetingOrder);
  const documents = state.documents || [];
  return upcomingEvents(state, today, PREP_DAYS).filter((o) => !o.done).flatMap(({ ev, date }) => {
    const project = eventProjectOf(state, ev);
    if (!project) return [];
    const last = meetings.find((m) => m.projectId === project.id) || null;
    const fus = (last?.followUps || []).filter((f) => !f.done);
    return [{
      ev, date, project, last,
      followUps: [...fus.filter((f) => f.mine), ...fus.filter((f) => !f.mine)],
      progress: (last?.progress || []).slice().sort((a, b) => b.date.localeCompare(a.date)).slice(0, PREP_PROGRESS),
      tasks: (last?.taskIds || []).map((id) => (state.tasks || []).find((q) => q.id === id)).filter(Boolean)
        .map((q) => ({ q, closed: taskClosedOn(q, today) })),
      docs: documents.filter((d) => d.projectId === project.id).sort(docOrder),
    }];
  });
};

// A minutes row's marker: `진행 {n}건` and `후속 {open}/{total}`, each only when its total is above zero. Derived (rule 9).
// `lead` (v28), when given, is stated first — a memo's track label.
const meetingRowMarker = (m, lead = "") => {
  const fus = m.followUps || [];
  const parts = [
    lead,
    m.progress?.length ? `진행 ${m.progress.length}건` : "",
    fus.length ? `후속 ${fus.filter((f) => !f.done).length}/${fus.length}` : "",
  ].filter(Boolean);
  return parts.length ? <span className="text-xs text-zinc-500 shrink-0">{parts.join(" · ")}</span> : null;
};

function MeetingsTab({ state, onAddProject, onEditProject, onAddMeeting, onOpenMeeting, onAddDocument, onOpenDocument }) {
  const [expanded, setExpanded] = useState({}); // which projects show every row — view state only, never stored (rule 9)
  const projects = state.meetingProjects || [];
  const meetings = state.meetings || [];
  const documents = state.documents || [];
  const used = useMemo(() => storageUsedWith(state), [state]);
  // Projects by their newest minutes; projects without minutes last, newest first. Derived at render (rule 9).
  const groups = useMemo(() => {
    const by = new Map(projects.map((p) => [p.id, []]));
    for (const m of meetings) by.get(m.projectId)?.push(m);
    const list = projects.map((p) => ({ p, rows: (by.get(p.id) || []).slice().sort(meetingOrder),
      docs: documents.filter((d) => d.projectId === p.id).sort(docOrder) }));
    return list.sort((a, b) => {
      const da = a.rows[0]?.date, db = b.rows[0]?.date;
      if (da && db) return db.localeCompare(da) || (b.p.createdAt || "").localeCompare(a.p.createdAt || "");
      if (da || db) return da ? -1 : 1;
      return (b.p.createdAt || "").localeCompare(a.p.createdAt || "");
    });
  }, [projects, meetings, documents]);
  // Project-less minutes (`projectId: null`, 2026-09-17): the urgent memos, one group after every project section.
  const memos = useMemo(() => meetings.filter((m) => m.projectId == null).sort(meetingOrder), [meetings]);
  // Project-less documents (v27), listed in the same group after the memo rows.
  const memoDocs = useMemo(() => documents.filter((d) => d.projectId == null).sort(docOrder), [documents]);
  const meetingRow = (m) => (
    <TodoRow key={m.id} lead={{ text: m.date.slice(2), tone: "text-zinc-400 border-zinc-700" }} title={m.title}
      marker={meetingRowMarker(m)} onOpen={() => onOpenMeeting(m.id)} />
  );
  // A memo carries its own track (v28), so its marker leads with it; a project meeting's track is on the section head.
  const memoRow = (m) => (
    <TodoRow key={m.id} lead={{ text: m.date.slice(2), tone: "text-zinc-400 border-zinc-700" }} title={m.title}
      marker={meetingRowMarker(m, TRACK_LABEL[trackOf(m)])}
      onOpen={() => onOpenMeeting(m.id)} />
  );
  const docRow = (d) => (
    <TodoRow key={d.id} lead={{ text: "문서", tone: "text-violet-300 border-violet-700" }} title={d.title}
      marker={<span className="text-xs font-mono text-zinc-500 shrink-0">{`${TRACK_LABEL[trackOf(d)]} · ${d.addedAt.slice(2)}`}</span>} onOpen={() => onOpenDocument(d.id)} />
  );
  // One group's rows — the first MEETING_ROWS_SHOWN, the rest behind `{n}건 더 보기` / `접기` — for a project and the memo
  // group; `rowOf` renders one row (minutes by default, documents for the documents block).
  const rowsBlock = (key, rows, emptyText, rowOf = meetingRow) => {
    const open = !!expanded[key];
    const shown = open ? rows : rows.slice(0, MEETING_ROWS_SHOWN);
    return (
      <>
        {rows.length === 0 ? (
          <p className="text-sm text-zinc-500 mt-3">{emptyText}</p>
        ) : (
          <div className="space-y-1.5 mt-3">
            {shown.map(rowOf)}
          </div>
        )}
        {rows.length > MEETING_ROWS_SHOWN && (
          <button onClick={() => setExpanded((x) => ({ ...x, [key]: !open }))}
            className="mt-2 text-xs font-bold text-zinc-400 active:opacity-70">
            {open ? "접기" : `${rows.length - MEETING_ROWS_SHOWN}건 더 보기`}
          </button>
        )}
      </>
    );
  };

  // A group's documents under its minutes rows, only when there is one — the head's `문서 {n}건` states a zero.
  const docsBlock = (key, docs) => docs.length > 0 && (
    <>
      <div className="text-xs font-bold text-zinc-500 mt-3">문서 {docs.length}건</div>
      {rowsBlock(key, docs, "", docRow)}
    </>
  );
  const groupHead = (name, rowCount, docCount, track) => (
    <div className="flex items-baseline gap-2">
      <div className="flex-1 min-w-0 text-sm font-bold truncate">{name}</div>
      {track && <TrackTag track={track} />}
      <span className="text-xs font-mono text-zinc-500 shrink-0">회의록 {rowCount}건 · 문서 {docCount}건</span>
    </div>
  );
  const smallBtn = (label, onClick) => (
    <button onClick={onClick}
      className="px-2.5 py-1.5 rounded-lg border border-zinc-700 text-zinc-300 text-xs font-bold active:translate-y-0.5">{label}</button>
  );

  return (
    <>
      <section className="bg-zinc-900 border border-zinc-800 rounded-2xl p-4">
        <div className="flex items-center justify-between gap-2">
          <SectionLabel tone="text-cyan-400">미팅 — 프로젝트별 회의록</SectionLabel>
          <button onClick={onAddProject}
            className="shrink-0 px-3.5 py-2.5 rounded-xl bg-cyan-400 text-zinc-950 text-sm font-bold flex items-center gap-1 active:translate-y-0.5">
            <Plus size={14} /> 프로젝트 추가
          </button>
        </div>
        <p className="text-xs text-zinc-600 mt-0.5">회의 시간은 일정 탭에, 회의에서 나온 내용은 여기에 적어요. 회의록은 목표·실행·점수에 반영되지 않아요. 문서는 요약 글만 저장돼요 — 파일은 저장되지 않아요.</p>
        {/* Fragments are nowrap so a 390 px line breaks only between them */}
        <p className="text-xs font-mono text-zinc-400 mt-2">
          <span className="whitespace-nowrap">프로젝트 {projects.length}개</span>{" · "}
          <span className="whitespace-nowrap">회의록 {meetings.length}건</span>{" · "}
          <span className="whitespace-nowrap">문서 {documents.length}건</span>{" · "}
          <span className="whitespace-nowrap">저장 공간 {mbText(used)}MB / 3.5MB</span>
        </p>
      </section>

      {projects.length === 0 && (
        <section className="bg-zinc-900 border border-zinc-800 rounded-2xl p-6 text-center">
          <p className="text-sm text-zinc-500">프로젝트가 없어요 — 프로젝트를 먼저 만들어요.</p>
        </section>
      )}

      {groups.map(({ p, rows, docs }) => (
        <section key={p.id} className="bg-zinc-900 border border-zinc-800 rounded-2xl p-4">
          {groupHead(p.name, rows.length, docs.length, trackOf(p))}
          <div className="flex gap-1.5 mt-2">
            {smallBtn("프로젝트 수정", () => onEditProject(p.id))}
            {smallBtn("회의록 추가", () => onAddMeeting(p.id))}
            {smallBtn("문서 추가", () => onAddDocument(p.id))}
          </div>
          {rowsBlock(p.id, rows, "회의록이 없어요.")}
          {docsBlock("doc:" + p.id, docs)}
        </section>
      ))}
      {/* Urgent memos — minutes with no project. Always rendered, after every project section: its `긴급 메모 추가` is
          the one way to start a memo (a project's `회의록 추가` preselects that project). */}
      <section className="bg-zinc-900 border border-zinc-800 rounded-2xl p-4">
        {groupHead("프로젝트 없음 · 긴급 메모", memos.length, memoDocs.length)}
        <p className="text-xs text-zinc-600 mt-0.5">프로젝트 없이 적은 회의록이에요 — 나중에 수정에서 프로젝트를 고르면 그 프로젝트로 옮겨져요.</p>
        <div className="flex gap-1.5 mt-2">
          {smallBtn("긴급 메모 추가", () => onAddMeeting(null))}
          {smallBtn("문서 추가", () => onAddDocument(null))}
        </div>
        {rowsBlock("none", memos, "긴급 메모가 없어요.", memoRow)}
        {docsBlock("doc:none", memoDocs)}
      </section>
    </>
  );
}

/* ── Project form. Deleting is offered only for a project without minutes or documents: nothing is lost, so nothing is
   asked. ── */
function ProjectModal({ project, meetingCount, documentCount, onClose, onAdd, onUpdate, onRemove }) {
  const [name, setName] = useState(project?.name || "");
  const [note, setNote] = useState(project?.note || "");
  const [track, setTrack] = useState(project?.track || "work");
  const [err, setErr] = useState("");
  const submit = () => {
    const n = name.trim(), t = note.trim();
    if (!n) { setErr("프로젝트 이름을 입력해 주세요."); return; }
    if (n.length > PROJECT_LIMITS.name) { setErr(`프로젝트 이름은 ${PROJECT_LIMITS.name}자까지예요 — 지금 ${n.length}자예요.`); return; }
    if (t.length > PROJECT_LIMITS.note) { setErr(`메모는 ${PROJECT_LIMITS.note}자까지예요 — 지금 ${t.length}자예요.`); return; }
    const next = { name: n, ...(t ? { note: t } : {}), track };
    if (project) onUpdate(project.id, next); else onAdd(next);
  };
  return (
    <Modal title={project ? "프로젝트 수정" : "새 프로젝트"} onClose={onClose}>
      <div className="space-y-3">
        <BizField value={name} onChange={setName} placeholder="프로젝트 이름 — 예: ○○물산 재고 관리" />
        <BizField value={note} onChange={setNote} placeholder="메모 (선택)" />
        <TrackRow value={track} onPick={setTrack} />
        {err && <p className="text-xs text-rose-400">{err}</p>}
        <button onClick={submit} className="w-full py-3 rounded-xl bg-cyan-500 text-zinc-950 font-black text-sm active:translate-y-0.5">
          {project ? "저장" : "등록"}
        </button>
        {project && (
          <>
            <button onClick={() => onRemove(project.id)} disabled={meetingCount > 0 || documentCount > 0}
              className="w-full py-2.5 rounded-xl border border-rose-800 text-rose-300 font-bold text-xs disabled:opacity-30">삭제</button>
            {meetingCount > 0 && <p className="text-xs text-zinc-500">회의록 {meetingCount}건이 있어 삭제할 수 없어요 — 회의록을 먼저 지워요.</p>}
            {meetingCount === 0 && documentCount > 0 && <p className="text-xs text-zinc-500">문서 {documentCount}건이 있어 삭제할 수 없어요 — 문서를 먼저 지워요.</p>}
          </>
        )}
      </div>
    </Modal>
  );
}

// A textarea with its `{n} / {cap}` counter. No `maxLength`: a paste is never silently truncated, the submit refuses
// instead. The over-cap tone is rose-300 so the form's one rose-400 line stays its validation message.
function MeetingText({ value, onChange, placeholder, rows, cap }) {
  return (
    <div>
      <textarea value={value} onChange={(e) => onChange(e.target.value)} placeholder={placeholder} rows={rows}
        className="w-full bg-zinc-950 border border-zinc-700 rounded-xl px-3 py-2.5 text-sm" />
      <div className={`text-xs font-mono text-right ${value.trim().length > cap ? "text-rose-300" : "text-zinc-600"}`}>{value.trim().length} / {cap}</div>
    </div>
  );
}

// The `프로젝트` chip row of the meeting and document forms: `없음 (긴급 메모)` first, then one chip per project. `note`
// is the caption shown while no project is chosen, when the form has one.
function ProjectPicker({ projects, pid, onPick, note }) {
  return (
    <div>
      <div className="text-xs font-bold tracking-widest text-zinc-500 mb-1.5">프로젝트</div>
      <div className="flex flex-wrap gap-1.5">
        <Chip on={pid === null} onClick={() => onPick(null)}>없음 (긴급 메모)</Chip>
        {projects.map((p) => <Chip key={p.id} on={pid === p.id} onClick={() => onPick(p.id)}>{p.name}</Chip>)}
      </div>
      {pid === null && note && <p className="text-xs text-zinc-600 mt-1.5">{note}</p>}
    </div>
  );
}

/* ── Document form (v27) — view and edit in one sheet. A document is a record of what a file says, in the user's words:
   no file is stored, `source` is text only, and nothing here pays, completes or moves a goal (rules 1, 18). `onAdd` /
   `onUpdate` answer with an error string ("" = saved), so the storage refusal keeps the form open. ── */
function DocumentModal({ state, doc, projectId, onClose, onAdd, onUpdate, onRemove }) {
  const projects = state.meetingProjects || [];
  // An explicit null (the memo group's button) is a document with no project.
  const [pid, setPid] = useState(doc?.projectId ?? projectId ?? null);
  // v28: the document's own track, else the picked project's, else `work`; a project chip sets it until a track chip is tapped.
  const [track, setTrack] = useState(() => doc?.track || trackOf(projects.find((p) => p.id === (doc?.projectId ?? projectId))));
  const [trackTouched, setTrackTouched] = useState(false);
  const [title, setTitle] = useState(doc?.title || "");
  const [source, setSource] = useState(doc?.source || "");
  const [summary, setSummary] = useState(doc?.summary || "");
  const [err, setErr] = useState("");
  const project = doc ? projects.find((p) => p.id === doc.projectId) : null;
  const submit = () => {
    const v = { title: title.trim(), source: source.trim(), summary: summary.trim() };
    if (pid !== null && !projects.some((p) => p.id === pid)) { setErr("프로젝트를 골라 주세요."); return; }
    if (!v.title) { setErr("문서 제목을 입력해 주세요."); return; }
    if (!v.summary) { setErr("문서 요약을 입력해 주세요."); return; }
    const names = { title: "문서 제목은", source: "출처는", summary: "문서 요약은" };
    for (const k of Object.keys(names)) {
      if (v[k].length > DOC_LIMITS[k]) { setErr(`${names[k]} ${DOC_LIMITS[k]}자까지예요 — 지금 ${v[k].length}자예요.`); return; }
    }
    // Only the ends are trimmed; a cleared source disappears from the record.
    const next = { projectId: pid, title: v.title, ...(v.source ? { source: v.source } : {}), summary: v.summary, track };
    const refused = doc ? onUpdate(doc.id, next) : onAdd(next);
    if (refused) setErr(refused);
  };
  return (
    <Modal title={doc ? "문서" : "문서 추가"} onClose={onClose}>
      <div className="space-y-3">
        {doc && (
          <div className="space-y-1">
            <CvFact label="프로젝트">{project?.name || "없음 (긴급 메모)"}</CvFact>
            <CvFact label="추가일"><span className="font-mono">{doc.addedAt}</span></CvFact>
          </div>
        )}
        <ProjectPicker projects={projects} pid={pid} onPick={(id) => {
          setPid(id); setErr("");
          const p = id ? projects.find((x) => x.id === id) : null;
          if (p && !trackTouched) setTrack(trackOf(p));
        }} />
        <TrackRow value={track} onPick={(t) => { setTrack(t); setTrackTouched(true); }} />
        <BizField value={title} onChange={setTitle} placeholder="문서 제목 — 예: 요구사항 정의서 v2" />
        <BizField value={source} onChange={setSource} placeholder="출처 (선택) — 파일 이름이나 링크" />
        <MeetingText value={summary} onChange={setSummary} placeholder="문서 요약 — 핵심 내용을 요점으로 적어요" rows={8} cap={DOC_LIMITS.summary} />
        <p className="text-xs text-zinc-600">파일은 저장되지 않아요 — 요약 글만 저장돼요. 문서는 목표·실행·점수에 반영되지 않아요.</p>
        {err && <p className="text-xs text-rose-400">{err}</p>}
        <button onClick={submit} className="w-full py-3 rounded-xl bg-cyan-500 text-zinc-950 font-black text-sm active:translate-y-0.5">
          {doc ? "저장" : "등록"}
        </button>
        {doc && (
          <button onClick={() => { if (window.confirm(`${doc.title} 문서를 삭제해요. 계속할까요?`)) onRemove(doc.id); }}
            className="w-full py-2.5 rounded-xl border border-rose-800 text-rose-300 font-bold text-xs">삭제</button>
        )}
      </div>
    </Modal>
  );
}

/* ── Meeting form — one form for add and edit. `onAdd` / `onUpdate` answer with an error string ("" = saved), so a
   refusal from the storage guard keeps the form open with everything typed. ── */
function MeetingModal({ state, meeting, projectId, today, onClose, onAdd, onUpdate, onRemove }) {
  const projects = state.meetingProjects || [];
  const [pid, setPid] = useState(meeting?.projectId || projectId || null);
  const [date, setDate] = useState(meeting?.date || today);
  const [title, setTitle] = useState(meeting?.title || "");
  const [attendees, setAttendees] = useState(meeting?.attendees || "");
  const [summary, setSummary] = useState(meeting?.summary || "");
  const [decisions, setDecisions] = useState(meeting?.decisions || "");
  const [actions, setActions] = useState(meeting?.actions || "");
  // The pasted transcription (2026-09-17), kept as pasted. The block is collapsed while empty so a paste-first flow
  // starts under the title and the summary stays the first textarea of a new form; a saved transcript opens it at once.
  const [transcript, setTranscript] = useState(meeting?.transcript || "");
  const [transcriptOpen, setTranscriptOpen] = useState(!!meeting?.transcript);
  const [eventId, setEventId] = useState(meeting?.eventId || null);
  const [aiHidden, setAiHidden] = useState(meeting?.aiHidden === true); // v25: keeps this meeting's body out of the work packet
  const [track, setTrack] = useState(meeting?.track || "work"); // v28: a memo's own track; a project meeting inherits and stores none
  // Linked task ids. A link whose task was deleted before this edit is dropped here, so it never counts toward the cap.
  const [taskIds, setTaskIds] = useState(() => (meeting?.taskIds || []).filter((id) => (state.tasks || []).some((q) => q.id === id)));
  const [taskQuery, setTaskQuery] = useState(""); // the picker's text filter — view state only, never stored
  // Follow-up rows (v26), shallow copies: `done` and `workId` pass through untouched — the form never edits them.
  const [followUps, setFollowUps] = useState(() => (meeting?.followUps || []).map((f) => ({ ...f })));
  const fuAtCap = followUps.length >= MEETING_FOLLOWUPS_MAX;
  const editFollowUp = (id, patch) => setFollowUps((cur) => cur.map((r) => (r.id === id ? { ...r, ...patch } : r)));
  // `확인할 것 가져오기` (v27): copies the linked event's checks into follow-up rows — form state only; the event's checks
  // are never written. A check whose trimmed text already names a row is skipped; the row cap stops the copy.
  const linkedChecks = ((state.events || []).find((e) => e.id === eventId)?.checks) || [];
  const [pulled, setPulled] = useState("");
  const pullChecks = () => {
    const have = new Set(followUps.map((r) => r.text.trim()));
    const rows = [];
    let skipped = 0;
    for (const c of linkedChecks) {
      const t = c.text.trim();
      if (have.has(t)) { skipped += 1; continue; }
      if (followUps.length + rows.length >= MEETING_FOLLOWUPS_MAX) break;
      have.add(t);
      rows.push({ id: uid(), text: c.text, mine: false, done: false });
    }
    if (!rows.length && followUps.length >= MEETING_FOLLOWUPS_MAX) { setPulled(`후속 항목은 ${MEETING_FOLLOWUPS_MAX}건까지예요.`); return; }
    setFollowUps((cur) => [...cur, ...rows]);
    setPulled(`확인할 것 ${rows.length}건을 가져왔어요 — 이미 있는 ${skipped}건은 건너뛰었어요.`);
  };
  const [err, setErr] = useState("");
  const dayEvents = date ? eventsOn(state, date) : [];
  const candidates = useMemo(() => meetingTaskCandidates(state, today), [state, today]);
  // Rows offered: the filtered candidates, plus any linked task that is not a candidate (a finished task with no
  // completion date on record), so a selected link always stays in view and can be unticked.
  const taskRows = useMemo(() => {
    const qy = taskQuery.trim().toLowerCase();
    const hit = (q) => !qy || q.title.toLowerCase().includes(qy);
    const listed = new Set(candidates.map((c) => c.q.id));
    const extra = (state.tasks || []).filter((q) => taskIds.includes(q.id) && !listed.has(q.id))
      .map((q) => ({ q, lead: todoLeadOf({ kind: "task", task: q, date: q.due || null }, today, true), done: true }));
    const all = [...candidates, ...extra].filter((c) => hit(c.q) || taskIds.includes(c.q.id));
    const shown = all.slice(0, MEETING_TASK_ROWS);
    for (const c of all.slice(MEETING_TASK_ROWS)) if (taskIds.includes(c.q.id)) shown.push(c);
    return { shown, more: all.length - shown.length };
  }, [candidates, state.tasks, taskIds, taskQuery, today]);
  const atCap = taskIds.length >= MEETING_LIMITS.tasks;
  const toggleTask = (id) => setTaskIds((cur) => (cur.includes(id)
    ? cur.filter((x) => x !== id)
    : cur.length >= MEETING_LIMITS.tasks ? cur : [...cur, id]));

  // A link is kept only while its event still has an occurrence on the chosen date.
  const pickDate = (d) => {
    setDate(d);
    if (eventId && !(d && eventsOn(state, d).some((o) => o.ev.id === eventId))) setEventId(null);
  };

  const submit = () => {
    const v = { title: title.trim(), attendees: attendees.trim(), summary: summary.trim(), decisions: decisions.trim(), actions: actions.trim(),
      transcript: transcript.trim() };
    // A null id is a memo (no project); a non-null id must name a live project.
    if (pid !== null && !projects.some((p) => p.id === pid)) { setErr("프로젝트를 골라 주세요."); return; }
    if (!date) { setErr("날짜를 선택해 주세요."); return; }
    if (!v.title) { setErr("회의 이름을 입력해 주세요."); return; }
    if (!v.summary) { setErr("회의 요약을 입력해 주세요."); return; }
    const names = { title: "회의 이름은", attendees: "참석자는", summary: "회의 요약은", decisions: "결정 사항은", actions: "후속 조치는", transcript: "녹취록은" };
    for (const k of Object.keys(names)) {
      if (v[k].length > MEETING_LIMITS[k]) { setErr(`${names[k]} ${MEETING_LIMITS[k]}자까지예요 — 지금 ${v[k].length}자예요.`); return; }
    }
    // Follow-up rows: trimmed; an empty row is dropped; the position in the refusal is the row as shown (1-based).
    const over = followUps.findIndex((r) => r.text.trim().length > MEETING_LIMITS.followUp);
    if (over >= 0) {
      setErr(`후속 항목은 ${MEETING_LIMITS.followUp}자까지예요 — ${over + 1}번째 항목이 지금 ${followUps[over].text.trim().length}자예요.`);
      return;
    }
    const fuRows = followUps.map((r) => ({ ...r, text: r.text.trim() })).filter((r) => r.text)
      .map(({ id, text, mine, due, done, workId }) => ({ id, text, mine: !!mine, ...(due ? { due } : {}), done: done === true, ...(workId ? { workId } : {}) }));
    // Only non-empty optional fields are written, so a cleared field disappears from the save.
    const next = {
      projectId: pid, date, title: v.title,
      ...(v.attendees ? { attendees: v.attendees } : {}),
      summary: v.summary,
      ...(v.decisions ? { decisions: v.decisions } : {}),
      ...(v.actions ? { actions: v.actions } : {}),
      // Only the ends are trimmed; the interior is byte-identical to the paste. An all-whitespace transcript is not written.
      ...(v.transcript ? { transcript: v.transcript } : {}),
      ...(eventId ? { eventId } : {}),
      // Linking stores ids only and never changes a task (rules 1, 9, 18).
      taskIds: taskIds.filter((id) => (state.tasks || []).some((q) => q.id === id)).slice(0, MEETING_LIMITS.tasks),
      // The form never edits progress entries (the view owns them); the flag is always written as a boolean (v25).
      progress: meeting?.progress || [],
      aiHidden,
      // Always an array (v26); the root reconciles the mirrored work items when it writes the record.
      followUps: fuRows,
      ...(pid === null ? { track } : {}),
    };
    const refused = meeting ? onUpdate(meeting.id, next) : onAdd(next);
    if (refused) setErr(refused);
  };

  return (
    <Modal title={meeting ? "회의록 수정" : "새 회의록"} onClose={onClose}>
      <div className="space-y-3">
        <ProjectPicker projects={projects} pid={pid} onPick={(id) => { setPid(id); setErr(""); }}
          note="프로젝트 없이 저장돼요 — 미팅 탭의 '프로젝트 없음 · 긴급 메모'에 실려요." />
        {pid === null && <TrackRow value={track} onPick={setTrack} />}
        <div>
          <div className="text-xs font-bold tracking-widest text-zinc-500 mb-1.5">날짜</div>
          <input type="date" value={date} onChange={(e) => pickDate(e.target.value)}
            className="w-full bg-zinc-950 border border-zinc-700 rounded-xl px-3 py-2.5 text-sm font-mono" />
        </div>
        {/* Directly under the date, above the long text fields: the link picker is the part of the form the user
            reaches for first, and at the bottom it sat below the fold on a phone (reported 2026-09-16). */}
        <div>
          <div className="flex items-baseline justify-between gap-2 mb-1.5">
            <div className="text-xs font-bold tracking-widest text-zinc-500">할 일 연결</div>
            <span className="text-xs font-mono text-zinc-500 shrink-0">{taskIds.length} / {MEETING_LIMITS.tasks}</span>
          </div>
          {candidates.length === 0 && taskRows.shown.length === 0 ? (
            <p className="text-xs text-zinc-500">연결할 할 일이 없어요.</p>
          ) : (
            <>
              <input value={taskQuery} onChange={(e) => setTaskQuery(e.target.value)} placeholder="할 일 검색"
                className="w-full bg-zinc-950 border border-zinc-700 rounded-xl px-3 py-2 text-sm" />
              <div className="space-y-1 mt-1.5">
                {taskRows.shown.map(({ q, lead, done }) => {
                  const on = taskIds.includes(q.id);
                  return (
                    <button key={q.id} role="checkbox" aria-checked={on} onClick={() => toggleTask(q.id)} disabled={!on && atCap}
                      className={`w-full text-left flex items-center gap-2 rounded-xl px-2.5 py-2 border disabled:opacity-30 ${
                        on ? "border-cyan-700 bg-zinc-950" : "border-zinc-800 bg-zinc-950"}`}>
                      <span className={`w-4 h-4 shrink-0 rounded border flex items-center justify-center ${on ? "bg-cyan-400 border-cyan-300 text-zinc-950" : "border-zinc-600"}`}>
                        {on && <Check size={12} />}
                      </span>
                      {/* rose-300, not rose-400: inside a form rose-400 is reserved for the one validation line */}
                      <span className={`font-mono text-xs font-bold border rounded-lg px-1.5 py-0.5 bg-zinc-900 shrink-0 ${lead.tone.replace("text-rose-400", "text-rose-300")}`}>{lead.text}</span>
                      <span className={`flex-1 min-w-0 text-sm truncate ${done ? "line-through text-zinc-500" : ""}`}>{q.title}</span>
                    </button>
                  );
                })}
              </div>
              {taskRows.shown.length === 0 && <p className="text-xs text-zinc-500 mt-1.5">검색 결과가 없어요.</p>}
              {taskRows.more > 0 && <p className="text-xs text-zinc-500 mt-1.5">할 일 {taskRows.more}건 더 있음 — 검색어로 좁혀요</p>}
              {atCap && <p className="text-xs text-zinc-400 mt-1.5">할 일은 {MEETING_LIMITS.tasks}개까지 연결돼요.</p>}
            </>
          )}
          <p className="text-xs text-zinc-600 mt-1.5">연결은 기록이에요 — 할 일의 상태·점수·목표는 바뀌지 않아요.</p>
        </div>
        <BizField value={title} onChange={setTitle} placeholder="회의 이름 — 예: 2차 요구사항 회의" />
        <BizField value={attendees} onChange={setAttendees} placeholder="참석자 (선택) — 예: 김OO, 박OO" />
        {transcriptOpen ? (
          <MeetingText value={transcript} onChange={setTranscript} placeholder="녹취록 (선택) — 급히 녹음한 내용을 옮겨 적은 글을 그대로 붙여넣어요" rows={6} cap={MEETING_LIMITS.transcript} />
        ) : (
          <div>
            <button onClick={() => setTranscriptOpen(true)}
              className="px-2.5 py-1.5 rounded-lg border border-zinc-700 text-zinc-300 text-xs font-bold active:translate-y-0.5">녹취록 붙여넣기</button>
          </div>
        )}
        <MeetingText value={summary} onChange={setSummary} placeholder="회의 요약 — 논의한 내용을 요점으로 적어요" rows={8} cap={MEETING_LIMITS.summary} />
        <MeetingText value={decisions} onChange={setDecisions} placeholder="결정 사항 (선택)" rows={3} cap={MEETING_LIMITS.decisions} />
        <MeetingText value={actions} onChange={setActions} placeholder="후속 조치 (선택)" rows={3} cap={MEETING_LIMITS.actions} />
        {/* Follow-up items (v26): two lines per row, so the text, the owner chip and the due date fit 390 px */}
        <div>
          <div className="flex items-baseline justify-between gap-2 mb-1.5">
            <div className="text-xs font-bold tracking-widest text-zinc-500">후속 항목</div>
            <span className="text-xs font-mono text-zinc-500 shrink-0">{followUps.length} / {MEETING_FOLLOWUPS_MAX}</span>
          </div>
          {followUps.length > 0 && (
            <div className="space-y-1.5 mb-1.5">
              {followUps.map((r) => (
                <div key={r.id} className="bg-zinc-950 border border-zinc-800 rounded-xl p-2.5 space-y-1.5">
                  <div className="flex items-center gap-2">
                    <input value={r.text} onChange={(e) => editFollowUp(r.id, { text: e.target.value })} placeholder="후속 항목 — 예: 견적서 송부"
                      className="flex-1 min-w-0 bg-zinc-900 border border-zinc-700 rounded-lg px-2.5 py-2 text-sm" />
                    <button aria-label="후속 항목 삭제" onClick={() => setFollowUps((cur) => cur.filter((x) => x.id !== r.id))}
                      className="text-zinc-500 shrink-0 active:opacity-70"><X size={14} /></button>
                  </div>
                  <div className="flex items-center gap-2">
                    <div className="shrink-0"><Chip on={!!r.mine} onClick={() => editFollowUp(r.id, { mine: !r.mine })}>내 담당</Chip></div>
                    <input type="date" aria-label="후속 기한" value={r.due || ""} onChange={(e) => editFollowUp(r.id, { due: e.target.value })}
                      className="flex-1 w-0 bg-zinc-900 border border-zinc-700 rounded-lg px-2.5 py-1.5 text-sm font-mono" />
                    {r.done && <span className="text-xs font-mono text-emerald-400 shrink-0">완료</span>}
                  </div>
                </div>
              ))}
            </div>
          )}
          <button onClick={() => setFollowUps((cur) => (cur.length >= MEETING_FOLLOWUPS_MAX ? cur : [...cur, { id: uid(), text: "", mine: false, done: false }]))}
            disabled={fuAtCap}
            className="px-2.5 py-1.5 rounded-lg border border-zinc-700 text-zinc-300 text-xs font-bold disabled:opacity-30 active:translate-y-0.5">항목 추가</button>
          {linkedChecks.length > 0 && (
            <div className="mt-1.5">
              <button onClick={pullChecks}
                className="px-2.5 py-1.5 rounded-lg border border-zinc-700 text-zinc-300 text-xs font-bold active:translate-y-0.5">확인할 것 가져오기 ({linkedChecks.length}건)</button>
              {pulled && <p className="text-xs text-zinc-400 mt-1.5">{pulled}</p>}
            </div>
          )}
          {fuAtCap && <p className="text-xs text-zinc-400 mt-1.5">후속 항목은 {MEETING_FOLLOWUPS_MAX}건까지예요.</p>}
          <p className="text-xs text-zinc-600 mt-1.5">내 담당을 켜면 업무 탭에 등록돼요 — 회의 날짜가 지났으면 오늘 업무로요.</p>
        </div>
        <div>
          <div className="text-xs font-bold tracking-widest text-zinc-500 mb-1.5">일정 연결 (선택)</div>
          {dayEvents.length === 0 ? (
            <p className="text-xs text-zinc-500">이 날짜에는 일정이 없어요.</p>
          ) : (
            <div className="flex flex-wrap gap-1.5">
              <Chip on={!eventId} onClick={() => setEventId(null)}>연결 안 함</Chip>
              {dayEvents.map((o) => (
                <Chip key={o.ev.id} on={eventId === o.ev.id} onClick={() => setEventId(o.ev.id)}>{o.ev.time || "시간 미정"} {o.ev.title}</Chip>
              ))}
            </div>
          )}
        </div>
        <label className="flex items-start gap-2">
          <input type="checkbox" checked={aiHidden} onChange={(e) => setAiHidden(e.target.checked)} className="mt-1 shrink-0" />
          <span className="text-sm text-zinc-200">
            AI에 보내지 않기
            <span className="block text-xs text-zinc-600">켜면 오늘 업무 만들기 패킷에 이 회의록의 날짜와 제목만 실려요.</span>
          </span>
        </label>
        <p className="text-xs text-zinc-500">녹취록은 붙여넣은 그대로 저장돼요 — AI 패킷에는 실리지 않아요.</p>
        {err && <p className="text-xs text-rose-400">{err}</p>}
        <button onClick={submit} className="w-full py-3 rounded-xl bg-cyan-500 text-zinc-950 font-black text-sm active:translate-y-0.5">
          {meeting ? "저장" : "등록"}
        </button>
        {meeting && (
          <button onClick={() => onRemove(meeting.id)} className="w-full py-2.5 rounded-xl border border-rose-800 text-rose-300 font-bold text-xs">삭제</button>
        )}
      </div>
    </Modal>
  );
}

/* ── Meeting view — the full minutes, read from the live record. The progress log (v25) is added and deleted only
   here: `onAddProgress(meetingId, text)` answers with an error string ("" = saved) like the meeting form's handlers. ── */
function MeetingViewModal({ state, meetingId, today, onClose, onEdit, onOpenTask, onAddProgress, onRemoveProgress,
  onToggleFollowUp, onSetFollowUpMine, onAppendFollowUps, onClearTranscript }) {
  const [entry, setEntry] = useState(""); // the progress textarea — view state only, never stored
  const [showTranscript, setShowTranscript] = useState(false); // the transcript block, collapsed by default — view state only
  const [err, setErr] = useState("");
  // The split panel's candidates `[{ text, on, mine, dup, blocked }]`, or null when closed — component state only.
  const [split, setSplit] = useState(null);
  const [splitErr, setSplitErr] = useState("");
  const m = (state.meetings || []).find((x) => x.id === meetingId);
  if (!m) return null;
  const fus = m.followUps || [];
  const fuOpen = fus.filter((f) => !f.done).length;
  const fuRoom = Math.max(0, MEETING_FOLLOWUPS_MAX - fus.length);
  // Candidates from the free text: a text already on the meeting starts unticked; past the remaining room a candidate
  // starts unticked and disabled. The text in `actions` is never changed (rule 12).
  const openSplit = () => {
    const have = new Set(fus.map((f) => f.text));
    let room = fuRoom;
    setSplit(splitFollowUpText(m.actions).map((text) => {
      const dup = have.has(text);
      const blocked = !dup && room <= 0;
      if (!dup && !blocked) room -= 1;
      return { text, on: !dup && !blocked, mine: false, dup, blocked };
    }));
    setSplitErr("");
  };
  const editSplit = (i, patch) => setSplit((cur) => cur.map((c, j) => (j === i ? { ...c, ...patch } : c)));
  const ticked = (split || []).filter((c) => c.on && !c.blocked);
  const appendSplit = () => {
    const refused = onAppendFollowUps(m.id, ticked.map((c) => ({ text: c.text, mine: c.mine })));
    if (refused) { setSplitErr(refused); return; }
    setSplit(null); setSplitErr("");
  };
  // The work state of one follow-up: stated for a mine item or a live link, nothing otherwise.
  const fuWorkText = (fu) => {
    const w = fu.workId ? (state.work || []).find((x) => x.id === fu.workId) : null;
    if (w) return w.done ? "업무 완료" : "업무 미완료";
    return fu.mine ? "업무 삭제됨" : "";
  };
  // A linked id whose task no longer exists is skipped and counted, never cleaned up from here.
  const linked = (m.taskIds || []).map((id) => (state.tasks || []).find((q) => q.id === id)).filter(Boolean);
  const missing = (m.taskIds || []).length - linked.length;
  const project = (state.meetingProjects || []).find((p) => p.id === m.projectId);
  // Newest first: by date, then the stored order (the handler prepends, so a same-day entry added later comes first).
  const progress = (m.progress || []).slice().sort((a, b) => b.date.localeCompare(a.date));
  const addEntry = () => {
    const t = entry.trim();
    if (!t) { setErr("진행사항을 입력해 주세요."); return; }
    if (t.length > MEETING_LIMITS.progress) { setErr(`진행사항은 ${MEETING_LIMITS.progress}자까지예요 — 지금 ${t.length}자예요.`); return; }
    if (progress.length >= MEETING_PROGRESS_MAX) { setErr(`진행사항은 ${MEETING_PROGRESS_MAX}건까지예요.`); return; }
    const refused = onAddProgress(m.id, t);
    if (refused) { setErr(refused); return; }
    setEntry(""); setErr("");
  };
  const removeEntry = (entryId) => {
    if (!window.confirm("진행사항을 삭제해요. 계속할까요?")) return;
    onRemoveProgress(m.id, entryId);
  };
  const askClearTranscript = () => {
    if (!window.confirm("녹취록만 지워요. 요약·결정·후속·진행사항은 남아요. 계속할까요?")) return;
    onClearTranscript(m.id);
  };
  const block = (label, text) => (
    <div>
      <SectionLabel>{label}</SectionLabel>
      <p className="text-sm text-zinc-200 whitespace-pre-wrap break-words">{text || "없음"}</p>
    </div>
  );
  return (
    <Modal title={m.title} onClose={onClose}>
      <div className="space-y-3">
        <div className="space-y-1.5">
          <CvFact label="프로젝트" wrap>{project?.name || "없음 (긴급 메모)"}</CvFact>
          <CvFact label="날짜"><span className="font-mono">{m.date}</span></CvFact>
          <CvFact label="참석자" wrap>{m.attendees || "기록 없음"}</CvFact>
          <CvFact label="일정" wrap>{meetingEventText(state, m)}</CvFact>
          <CvFact label="AI 전송">{m.aiHidden ? "보내지 않음" : "요약·진행사항 포함"}</CvFact>
        </div>
        {/* The transcript (2026-09-17): collapsed by default because it is long; its length is stated so nothing is
            hidden (rule 13). On-device only — never in a packet or file. */}
        {m.transcript ? (
          <div>
            <div className="flex items-baseline justify-between gap-2">
              <SectionLabel>녹취록</SectionLabel>
              <button onClick={() => setShowTranscript((x) => !x)} aria-label={showTranscript ? "녹취록 접기" : "녹취록 펼치기"}
                className="shrink-0 px-2.5 py-1.5 rounded-lg border border-zinc-700 text-zinc-300 text-xs font-mono active:translate-y-0.5">
                {showTranscript ? "접기" : `녹취록 ${m.transcript.length}자 · 펼치기`}
              </button>
            </div>
            {showTranscript && (
              <>
                <p className="text-sm text-zinc-200 whitespace-pre-wrap break-words">{m.transcript}</p>
                <button onClick={askClearTranscript}
                  className="mt-2 px-2.5 py-1.5 rounded-lg border border-rose-800 text-rose-300 text-xs font-bold active:translate-y-0.5">녹취록 지우기</button>
              </>
            )}
          </div>
        ) : block("녹취록", "")}
        {block("요약", m.summary)}
        {block("결정 사항", m.decisions)}
        {block("후속 조치", m.actions)}
        <div>
          <div className="flex items-baseline justify-between gap-2">
            <div className="flex items-baseline gap-2 min-w-0">
              <SectionLabel>후속 항목</SectionLabel>
              <span className="text-xs font-mono text-zinc-500 shrink-0">{fuOpen}/{fus.length}</span>
            </div>
            {String(m.actions || "").trim() && (
              <button onClick={openSplit}
                className="shrink-0 px-2.5 py-1.5 rounded-lg border border-zinc-700 text-zinc-300 text-xs font-bold active:translate-y-0.5">항목으로 나누기</button>
            )}
          </div>
          {split && (
            <div className="border border-cyan-800 rounded-xl p-3 space-y-2 mb-2 mt-1">
              <div className="text-sm font-bold">후속 조치에서 항목 나누기 — {split.length}건</div>
              {split.length === 0 ? (
                <p className="text-xs text-zinc-500">나눌 항목이 없어요.</p>
              ) : (
                <div className="space-y-1.5">
                  {split.map((c, i) => (
                    <div key={i} className={`flex items-center gap-2 bg-zinc-950 rounded-xl px-2.5 py-2 ${c.blocked ? "opacity-50" : ""}`}>
                      <input type="checkbox" checked={c.on} disabled={c.blocked} onChange={(e) => editSplit(i, { on: e.target.checked })} className="shrink-0" />
                      <span className="flex-1 min-w-0 text-sm break-words">
                        {c.text}{c.dup && <span className="ml-1.5 text-xs text-zinc-500 whitespace-nowrap">이미 있어요</span>}
                      </span>
                      <div className="shrink-0"><Chip on={c.mine} disabled={c.blocked} onClick={() => editSplit(i, { mine: !c.mine })}>내 담당</Chip></div>
                    </div>
                  ))}
                </div>
              )}
              {split.some((c) => c.blocked) && (
                <p className="text-xs text-zinc-400">후속 항목은 {MEETING_FOLLOWUPS_MAX}건까지예요 — {fuRoom}건만 추가할 수 있어요.</p>
              )}
              {splitErr && <p className="text-xs text-rose-400">{splitErr}</p>}
              <div className="flex gap-1.5">
                <button onClick={appendSplit} disabled={!ticked.length}
                  className="flex-1 py-2.5 rounded-xl bg-cyan-500 text-zinc-950 font-black text-sm disabled:opacity-30 active:translate-y-0.5">추가</button>
                <button onClick={() => { setSplit(null); setSplitErr(""); }}
                  className="flex-1 py-2.5 rounded-xl border border-zinc-700 text-zinc-300 text-sm font-bold active:translate-y-0.5">취소</button>
              </div>
            </div>
          )}
          {fus.length === 0 ? (
            <p className="text-sm text-zinc-500">후속 항목이 없어요.</p>
          ) : (
            <div className="space-y-1.5">
              {fus.map((fu) => {
                const late = fu.due && fu.due < today && !fu.done;
                const work = fuWorkText(fu);
                return (
                  <div key={fu.id} className="bg-zinc-950 rounded-xl px-3 py-2 flex items-start gap-2">
                    <input type="checkbox" aria-label="후속 완료" checked={fu.done === true} onChange={() => onToggleFollowUp(m.id, fu.id)} className="mt-1 shrink-0" />
                    <div className="flex-1 min-w-0">
                      <p className={`text-sm break-words ${fu.done ? "line-through text-zinc-500" : "text-zinc-200"}`}>{fu.text}</p>
                      <p className="text-xs font-mono text-zinc-500">
                        <span className={fu.mine ? "text-cyan-300" : "text-zinc-500"}>{fu.mine ? "내 담당" : "타인"}</span>
                        {" · "}<span className={late ? "text-rose-400" : ""}>{fu.due ? `기한 ${fu.due}` : "기한 없음"}</span>
                        {work && <>{" · "}{work}</>}
                      </p>
                    </div>
                    <div className="shrink-0"><Chip on={!!fu.mine} onClick={() => onSetFollowUpMine(m.id, fu.id, !fu.mine)}>내 담당</Chip></div>
                  </div>
                );
              })}
            </div>
          )}
        </div>
        <div>
          <div className="flex items-baseline justify-between gap-2">
            <SectionLabel>진행사항</SectionLabel>
            <span className="text-xs font-mono text-zinc-500 shrink-0">{progress.length}건</span>
          </div>
          {progress.length === 0 ? (
            <p className="text-sm text-zinc-500">진행사항이 없어요.</p>
          ) : (
            <div className="space-y-1.5">
              {progress.map((e) => (
                <div key={e.id} className="flex items-start gap-2 bg-zinc-950 rounded-xl px-3 py-2">
                  <span className="font-mono text-xs text-zinc-500 shrink-0 leading-5">{e.date}</span>
                  <p className="flex-1 min-w-0 whitespace-pre-wrap break-words text-sm text-zinc-200">{e.text}</p>
                  <button aria-label="진행사항 삭제" onClick={() => removeEntry(e.id)} className="text-zinc-500 shrink-0 mt-0.5 active:opacity-70"><X size={14} /></button>
                </div>
              ))}
            </div>
          )}
          <div className="mt-2 space-y-2">
            <MeetingText value={entry} onChange={setEntry} placeholder="진행사항 추가 — 이 회의 뒤에 이어간 업무를 적어요" rows={2} cap={MEETING_LIMITS.progress} />
            {err && <p className="text-xs text-rose-400">{err}</p>}
            <button onClick={addEntry} className="w-full py-2.5 rounded-xl bg-cyan-500 text-zinc-950 font-black text-sm active:translate-y-0.5">추가</button>
          </div>
        </div>
        <div>
          <SectionLabel>연결된 할 일</SectionLabel>
          {linked.length === 0 && missing === 0 ? (
            <p className="text-sm text-zinc-500">연결된 할 일이 없어요.</p>
          ) : (
            <div className="space-y-1.5">
              {linked.map((q) => (
                <TodoRow key={q.id} lead={linkedTaskLead(q, today)} title={q.title} done={taskClosedOn(q, today)}
                  onOpen={() => onOpenTask(q.id)} />
              ))}
            </div>
          )}
          {missing > 0 && <p className="text-xs text-zinc-500 mt-1.5">삭제된 할 일 {missing}건</p>}
        </div>
        <button onClick={() => onEdit(m.id)}
          className="w-full py-2.5 rounded-xl border border-zinc-700 text-zinc-300 text-sm font-bold active:translate-y-0.5">수정</button>
      </div>
    </Modal>
  );
}

/* ───────────────────────── Daily work — dated work items (schema v25) ───────────────────────── */
/* A work item is a dated record of what the user did or means to do that day — typed by hand or proposed by the
   assistant and confirmed per item — and never a task: no payout, no trophy, no goal, no KR, no streak, no evidence
   gate, and nothing here reaches `todoOf`, `agendaOf`, `computeGrades` or `krProgress`; `buildBriefing` reads only the
   carried count and the oldest age, never a title (rules 1, 7, 8, 9, 18). `done` is the one stored fact; the day view, the carried rows and the link label are derived at render.
   An item keeps its date: the tab pages by day, and today's view is prefixed by every undone item from earlier days,
   oldest first, each stating its age as `이월 {n}일` — carry-forward is derived and never writes `date` (rule 9), and a
   carried item stays listed on its own day too (rule 13 — nothing is hidden or moved). A link to a goal, a meeting or
   a project is a reference only; a target deleted later is stated as `연결 대상이 삭제됐어요` and never cleaned up
   (the same policy as a meeting's eventId).
   Storage arithmetic (string length, the same 3.5 MB budget as the meetings region): the record overhead
   `{"id":"…","date":"…","title":"","done":false,"source":"manual","createdAt":"…"}` is about 100 chars; with a
   20-char title, a 30-char note (`,"note":""` + 30) and a link (`,"link":{"kind":"meeting","id":"…"}` ≈ 45) an item
   is about 200 chars, about 150 without a link. Eight items a day for a year ≈ 2,920 × 150 ≈ 0.44 M chars (12 % of
   the budget a year); at the cap of 20 a day with every field full (60 + 200 + link ≈ 400 chars) ≈ 2.9 M a year —
   the tab states the storage in use, the backup path covers the rest, and `recordFits` refuses a save over the
   budget. */
// No per-day count cap (removed 2026-09-17 at the user's request: undone items are carried to the next day, so a day's
// list grows); `recordFits` still refuses a save past the storage budget.
// `result` (added 2026-09-17, optional, no migration): how a finished item was done, written in the sheet.
const WORK_LIMITS = { title: 60, note: 200, result: 1000 };
const WORK_LINK_MEETINGS = 20; // meetings offered by the link picker, newest first
const WORK_KIND_WORD = { goal: "목표", meeting: "회의록", project: "프로젝트" };
// The title as the duplicate check sees it: trimmed, every space removed, lower-cased (`parseWorkReply`).
const normWorkTitle = (t) => String(t || "").trim().replace(/\s+/g, "").toLowerCase();

/* ── Time budget and time log (v28) ── */
/* The weekly business budget is a setting the user types (`settings.bizHoursPerWeek`), never a measure (rule 8). The
   time log is the single source of every weekly sum: a completion with minutes writes one entry (`workId`) and the
   quick entry writes one without; the sums never read `work[].minutes`, so nothing is counted twice. Every sum is
   derived at render (rule 9). Storage: an entry ≈ 85 chars (+ 22 with `workId`); one a working day ≈ 27 k a year. */
const TIME_LOG_MAX_MINUTES = 1440;
// Minutes logged from `weekOf` (a Monday) to the Sunday after it, of one track when `track` is given.
const weekMinutes = (state, weekOf, track) => {
  const end = shiftDay(weekOf, 6);
  return (state?.timeLog || [])
    .filter((e) => e.date >= weekOf && e.date <= end && (!track || trackOf(e) === track))
    .reduce((sum, e) => sum + (Number(e.minutes) || 0), 0);
};
// Days from today to Sunday, both included.
const weekDaysLeft = (today) => daysBetween(today, shiftDay(mondayOf(today), 6)) + 1;
// Hours with one decimal when not whole: `12.5h`, `20h`.
const hoursText = (min) => { const h = Math.round((Number(min) || 0) / 6) / 10; return Number.isInteger(h) ? `${h}h` : `${h.toFixed(1)}h`; };
const bizHoursOf = (state) => (Number.isFinite(state?.settings?.bizHoursPerWeek) ? state.settings.bizHoursPerWeek : 20);
// The one line the work tab, the time-log sheet and the reader print.
const timeLine = (state, today) =>
  `이번 주 사업 ${hoursText(weekMinutes(state, mondayOf(today), "biz"))}/${bizHoursOf(state)}h · 남은 날 ${weekDaysLeft(today)}`;

// The day's items: `createdAt` ascending, then stored order (a stable sort keeps a done item in its place). On today's
// view (`date === today`) every undone item dated earlier comes first — `date` ascending, then `createdAt` — so the
// oldest carried item leads. Derived only: nothing is moved or rewritten (rule 9).
const byCreated = (a, b) => (a.createdAt || "").localeCompare(b.createdAt || "");
const workOn = (state, date, today) => {
  const list = state.work || [];
  const own = list.filter((w) => w.date === date).sort(byCreated);
  if (date !== today) return own;
  const carried = list.filter((w) => !w.done && w.date < today).sort((a, b) => a.date.localeCompare(b.date) || byCreated(a, b));
  return [...carried, ...own];
};
// The lead chip of one work row: an item dated before today states its age in the overdue tone; otherwise its source —
// the assistant (violet), a meeting follow-up (cyan, v26) or the user's own hand (zinc). One builder for the tab.
const workLeadOf = (w, today) => {
  if (w.date < today) return { text: `이월 ${daysBetween(w.date, today)}일`, tone: `${TODO_TONE.overdue} border-zinc-700` };
  if (w.source === "ai") return { text: "AI", tone: "text-violet-300 border-violet-700" };
  if (w.source === "meeting") return { text: "회의", tone: "text-cyan-300 border-cyan-800" };
  return { text: "수기", tone: "text-zinc-400 border-zinc-700" };
};
// The label of one link target, or null when the target no longer exists. One builder for the picker and the rows.
const workLinkLabel = (state, link) => {
  if (!link) return null;
  if (link.kind === "goal") { const g = (state.goals || []).find((x) => x.id === link.id); return g ? `목표 · ${g.title}` : null; }
  if (link.kind === "meeting") { const m = (state.meetings || []).find((x) => x.id === link.id); return m ? `회의록 · ${m.date} ${m.title}` : null; }
  if (link.kind === "project") { const p = (state.meetingProjects || []).find((x) => x.id === link.id); return p ? `프로젝트 · ${p.name}` : null; }
  return null;
};
const workLinkText = (state, item) => (item.link ? workLinkLabel(state, item.link) || "연결 대상이 삭제됐어요" : "");
// The link picker's rows: active goals, the newest meetings, every project — `{ kind, id, label }`.
const workLinkOptions = (state) => {
  const row = (kind, id) => ({ kind, id, label: workLinkLabel(state, { kind, id }) });
  return [
    ...(state.goals || []).filter((g) => g.status === "active").map((g) => row("goal", g.id)),
    ...(state.meetings || []).slice().sort(meetingOrder).slice(0, WORK_LINK_MEETINGS).map((m) => row("meeting", m.id)),
    ...(state.meetingProjects || []).map((p) => row("project", p.id)),
  ];
};

/* ── Meeting-prep card (`오늘 회의 준비`) — the first section of the `업무` tab: one block per open schedule occurrence
   today and tomorrow that belongs to a meeting project (`meetingPrepOf`), stating the last meeting's decisions, open
   follow-ups, progress and linked tasks, the project's documents and the event's `확인할 것` checklist. The block is a
   `div` with an explicit `회의록 열기 ›` button, since the checklist's controls cannot nest inside a button (TD-64).
   On-device only, so a meeting flagged `aiHidden` is stated in full here. Derived at render; the checks are the only
   thing written from here, through the root's handlers (rule 9); renders nothing without a row. ── */
function MeetingPrepCard({ state, today, onOpenMeeting, onOpenDocument, onAddCheck, onToggleCheck, onRemoveCheck, onAskAi }) {
  const prep = useMemo(() => meetingPrepOf(state, today), [state, today]);
  if (!prep.length) return null;
  const head = "block text-xs font-bold text-zinc-500 pt-1";
  const line = "block text-xs text-zinc-300 break-words";
  const border = "px-2.5 py-1.5 rounded-lg border border-zinc-700 text-zinc-300 text-xs font-bold active:translate-y-0.5";
  const workState = (f) => {
    const w = f.workId ? (state.work || []).find((x) => x.id === f.workId) : null;
    return w ? (w.done ? "완료" : "미완료") : "없음";
  };
  return (
    <section className="bg-zinc-900 border border-zinc-800 rounded-2xl p-4">
      <div className="flex items-center justify-between gap-2">
        <SectionLabel tone="text-cyan-400">오늘 회의 준비</SectionLabel>
        <span className="text-xs font-mono text-zinc-400 mb-2">{prep.length}건</span>
      </div>
      <p className="text-xs text-zinc-600 mb-2">확인할 것은 이 일정에 저장돼요 — 회의록을 쓸 때 후속 항목으로 가져올 수 있어요.</p>
      <div className="space-y-2">
        {prep.map((row) => {
          const { ev, date, project, last } = row;
          const hidden = row.followUps.length - PREP_FOLLOWUPS;
          const moreDocs = row.docs.length - PREP_DOCS;
          return (
            <div key={`${ev.id}|${date}`} className="bg-zinc-950 rounded-xl p-3 space-y-1.5 w-full block">
              <span className="block text-sm font-bold truncate">{project.name}</span>
              <span className="block font-mono text-xs text-zinc-400 break-words">{`${date === today ? "오늘" : "내일"} ${ev.time || "시간 미정"} · ${ev.title} · ${TRACK_LABEL[trackOf(ev)]}`}</span>
              <span className={line}>{last ? <>마지막 회의 <span className="font-mono">{last.date}</span> · {last.title}</> : "이전 회의록 없음"}</span>
              {last && <div><button onClick={() => onOpenMeeting(last.id)} className={border}>회의록 열기 ›</button></div>}
              {last && (
                <>
                  <span className={line}>{`결정: ${oneLineText(last.decisions, PREP_DECISION_CLIP) || "없음"}`}</span>
                  <span className={head}>후속 <span className="font-mono">{row.followUps.length}</span>건</span>
                  {row.followUps.slice(0, PREP_FOLLOWUPS).map((f) => (
                    <span key={f.id} className={line}>
                      {`${f.mine ? "내 담당" : "타인"} · ${f.text} · 기한 ${f.due || "없음"} · 업무 ${workState(f)}`}</span>
                  ))}
                  {hidden > 0 && <span className="block text-xs font-mono text-zinc-500">{hidden}건 더</span>}
                  <span className={head}>진행</span>
                  {row.progress.length === 0 ? <span className="block text-xs text-zinc-500">진행사항 없음</span>
                    : row.progress.map((e) => (
                      <span key={e.id} className={line}><span className="font-mono">{e.date}</span> {oneLineText(e.text, 100)}</span>
                    ))}
                  {row.tasks.length > 0 && (
                    <>
                      <span className={head}>할 일</span>
                      {row.tasks.slice(0, PREP_TASKS).map(({ q, closed }) => (
                        <span key={q.id} className={line}>{`${q.title} · ${closed ? "완료" : "미완료"}`}</span>
                      ))}
                    </>
                  )}
                </>
              )}
              <span className={head}>문서 <span className="font-mono">{row.docs.length}</span>건</span>
              {row.docs.length === 0 ? <span className="block text-xs text-zinc-500">문서 없음</span>
                : row.docs.slice(0, PREP_DOCS).map((d) => (
                  <button key={d.id} onClick={() => onOpenDocument(d.id)} className="block text-xs text-zinc-300 break-words text-left w-full active:opacity-70">
                    {`${d.title} — ${oneLineText(d.summary, DOC_SUMMARY_CLIP)}`}</button>
                ))}
              {moreDocs > 0 && <span className="block text-xs font-mono text-zinc-500">{moreDocs}건 더</span>}
              <div className="pt-1.5">
                <EventChecks ev={ev} onAdd={onAddCheck} onToggle={onToggleCheck} onRemove={onRemoveCheck} />
              </div>
              {/* v28: a day-job event never enters a packet, so its block states that in place of the button */}
              {PACKET_TRACKS.includes(trackOf(ev))
                ? <button onClick={() => onAskAi(ev.id, date)} className={`w-full ${border}`}>AI에게 회의 준비 묻기</button>
                : <span className="block text-xs text-zinc-500">직장 트랙 — AI 패킷에 실리지 않아요</span>}
            </div>
          );
        })}
      </div>
    </section>
  );
}

function WorkTab({ state, today, onAdd, onOpen, onBridge, onTimeLog, onRemoveMany, onOpenMeeting, onOpenDocument, onAddCheck, onToggleCheck, onRemoveCheck, onAskAi }) {
  const [viewDate, setViewDate] = useState(today); // the day shown — component state only, never stored (rule 9)
  // Select mode for deleting several items at once: component state only, cleared when the day changes.
  const [selecting, setSelecting] = useState(false);
  const [picked, setPicked] = useState(() => new Set());
  const showDate = (d) => { setViewDate(d); setPicked(new Set()); };
  const isToday = viewDate === today;
  const used = useMemo(() => storageUsedWith(state), [state]);
  const items = useMemo(() => workOn(state, viewDate, today), [state, viewDate, today]);
  const carried = isToday ? items.filter((w) => w.date < today).length : 0;
  const done = items.filter((w) => w.done).length;
  const ai = items.filter((w) => w.source === "ai").length;
  // The track label, then the link word only when linked (v28).
  const marker = (w) => (
    <span className="text-xs text-zinc-600 shrink-0">{TRACK_LABEL[trackOf(w)]}{WORK_KIND_WORD[w.link?.kind] ? ` · ${WORK_KIND_WORD[w.link.kind]}` : ""}</span>
  );
  // The day's rows grouped by track in reading order (v28) — the day job first, the business second, private life last;
  // `workOn`'s order (carried first) holds inside each group. Empty groups are omitted. Derived at render (rule 9).
  const groups = TRACKS.map((t) => ({ t, rows: items.filter((w) => trackOf(w) === t) })).filter((g) => g.rows.length > 0);
  const pager = "w-8 h-8 rounded-lg border border-zinc-700 text-zinc-300 text-sm font-bold active:translate-y-0.5";
  const chip = "shrink-0 px-2.5 py-1.5 rounded-lg border border-zinc-700 text-zinc-300 text-xs font-bold active:translate-y-0.5";
  const selectable = items; // select-all covers the carried rows on today's view
  const allPicked = selectable.length > 0 && selectable.every((w) => picked.has(w.id));
  const flip = (id) => setPicked((cur) => { const next = new Set(cur); if (next.has(id)) next.delete(id); else next.add(id); return next; });
  const endSelect = () => { setSelecting(false); setPicked(new Set()); };
  const removePicked = () => { if (onRemoveMany([...picked])) endSelect(); };
  // In select mode a row is a checkbox label instead of a button that opens the sheet.
  const row = (w, lead, done = false) => (selecting ? (
    <label key={w.id} className={`w-full flex items-center gap-2.5 bg-zinc-950 rounded-xl px-3 py-2.5 ${picked.has(w.id) ? "ring-1 ring-rose-500" : ""}`}>
      <input type="checkbox" checked={picked.has(w.id)} onChange={() => flip(w.id)} className="shrink-0" />
      <span className={`font-mono text-xs font-bold border rounded-lg px-1.5 py-1 bg-zinc-900 shrink-0 ${lead.tone}`}>{lead.text}</span>
      <span className={`flex-1 min-w-0 text-sm font-semibold truncate ${done ? "line-through text-zinc-500" : ""}`}>{w.title}</span>
    </label>
  ) : (
    <TodoRow key={w.id} lead={lead} title={w.title} done={done} marker={marker(w)} onOpen={() => onOpen(w.id)} />
  ));

  return (
    <>
      <MeetingPrepCard state={state} today={today} onOpenMeeting={onOpenMeeting} onOpenDocument={onOpenDocument}
        onAddCheck={onAddCheck} onToggleCheck={onToggleCheck} onRemoveCheck={onRemoveCheck} onAskAi={onAskAi} />
      <section className="bg-zinc-900 border border-zinc-800 rounded-2xl p-4">
        <div className="flex items-center justify-between gap-2">
          <SectionLabel tone="text-cyan-400">{isToday ? `오늘 업무 — ${today}` : `업무 — ${viewDate}`}</SectionLabel>
          <button onClick={() => onAdd(viewDate)}
            className="shrink-0 px-3.5 py-2.5 rounded-xl bg-cyan-400 text-zinc-950 text-sm font-bold flex items-center gap-1 active:translate-y-0.5">
            <Plus size={14} /> 업무 추가
          </button>
        </div>
        <div className="flex items-center gap-1.5">
          <button onClick={() => showDate(shiftDay(viewDate, -1))} className={pager}>‹</button>
          <button onClick={() => showDate(today)} disabled={isToday}
            className="px-2.5 py-1.5 rounded-lg border border-zinc-700 text-zinc-300 text-xs font-bold disabled:opacity-30 active:translate-y-0.5">오늘</button>
          <button onClick={() => showDate(shiftDay(viewDate, 1))} className={pager}>›</button>
          {/* On the pager row, not beside `업무 추가`: the label, both buttons and their gaps exceed the 326 px a 390 px screen leaves */}
          <button onClick={onBridge}
            className="ml-auto shrink-0 px-3 py-1.5 rounded-lg border border-zinc-700 text-zinc-300 text-xs font-bold active:translate-y-0.5">AI로 만들기 ›</button>
        </div>
        <p className="text-xs text-zinc-600 mt-2">업무는 기록이에요 — 목표·실행·점수에 반영되지 않아요.</p>
        {/* Fragments are nowrap so a 390 px line breaks only between them */}
        <p className="text-xs font-mono text-zinc-400 mt-2">
          <span className="whitespace-nowrap">남음 {items.length - done}건</span>{" · "}
          {isToday && <><span className="whitespace-nowrap">이월 {carried}건</span>{" · "}</>}
          <span className="whitespace-nowrap">완료 {done}건</span>{" · "}
          <span className="whitespace-nowrap">AI 제안 {ai}건</span>{" · "}
          <span className="whitespace-nowrap">저장 공간 {mbText(used)}MB / 3.5MB</span>
        </p>
        {/* This week's business time against the budget (v28) — always today's week, whatever day the pager shows */}
        <button onClick={onTimeLog} className="w-full text-left text-xs font-mono text-zinc-400 mt-1.5 active:opacity-70">
          {`${timeLine(state, today)} ›`}</button>
      </section>

      <section className="bg-zinc-900 border border-zinc-800 rounded-2xl p-4">
        {selectable.length > 0 && (selecting ? (
          <div className="flex flex-wrap items-center gap-1.5 mb-3">
            <button onClick={() => setPicked(allPicked ? new Set() : new Set(selectable.map((w) => w.id)))} className={chip}>
              {allPicked ? "선택 해제" : "전체 선택"}</button>
            <button onClick={removePicked} disabled={!picked.size}
              className="shrink-0 px-2.5 py-1.5 rounded-lg bg-rose-500 text-zinc-950 text-xs font-bold disabled:opacity-30 active:translate-y-0.5">선택 삭제 {picked.size}건</button>
            <button onClick={endSelect} className={`ml-auto ${chip}`}>취소</button>
          </div>
        ) : (
          <div className="flex justify-end mb-3">
            <button onClick={() => setSelecting(true)} className={chip}>선택</button>
          </div>
        ))}
        {items.length === 0 ? (
          <p className="text-sm text-zinc-500">{isToday ? "오늘 업무가 없어요." : "이 날짜에는 업무가 없어요."}</p>
        ) : (
          <div className="space-y-1.5">
            {/* The shown day, not today: an item on its own past day keeps its source chip; only the today view carries age */}
            {groups.flatMap((g) => [
              <div key={`head:${g.t}`} className="text-xs font-bold text-zinc-500 mt-1">{TRACK_LABEL[g.t]} {g.rows.length}건</div>,
              ...g.rows.map((w) => row(w, workLeadOf(w, viewDate), w.done)),
            ])}
          </div>
        )}
      </section>
    </>
  );
}

/* ── Work sheet — one form for add, edit, completion and deletion. `onAdd` / `onUpdate` answer with an error string
   ("" = saved), so the per-day cap or the storage guard keeps the form open with everything typed. ── */
function WorkModal({ state, work, date, today, onClose, onAdd, onUpdate, onToggle, onRemove, onOpenMeeting }) {
  const linkKey = (l) => (l ? `${l.kind}:${l.id}` : "");
  const [title, setTitle] = useState(work?.title || "");
  const [note, setNote] = useState(work?.note || "");
  const [result, setResult] = useState(work?.result || "");
  const [link, setLink] = useState(linkKey(work?.link));
  const [track, setTrack] = useState(work?.track || "work");
  const [minutes, setMinutes] = useState(work?.minutes ? String(work.minutes) : "");
  const [err, setErr] = useState("");
  const options = useMemo(() => workLinkOptions(state), [state]);
  // A link whose target was deleted stays selectable as itself, so saving the sheet does not silently drop it.
  const stale = link && !options.some((o) => linkKey(o) === link) ? link : "";
  // The record the sheet would save, or an error string. the done toggle saves it first, so a result typed before
  // completing is kept.
  const draft = () => {
    const t = title.trim(), n = note.trim(), r = result.trim();
    if (!t) return "업무 제목을 입력해 주세요.";
    if (t.length > WORK_LIMITS.title) return `업무 제목은 ${WORK_LIMITS.title}자까지예요 — 지금 ${t.length}자예요.`;
    if (n.length > WORK_LIMITS.note) return `메모는 ${WORK_LIMITS.note}자까지예요 — 지금 ${n.length}자예요.`;
    if (r.length > WORK_LIMITS.result) return `처리 내용은 ${WORK_LIMITS.result}자까지예요 — 지금 ${r.length}자예요.`;
    // Minutes (v28): a whole number 1..1440, or nothing.
    const mt = minutes.trim();
    if (mt && !(/^\d+$/.test(mt) && Number(mt) >= 1 && Number(mt) <= TIME_LOG_MAX_MINUTES)) return "걸린 시간은 1 이상 1440 이하 분으로 입력해 주세요.";
    const sep = link.indexOf(":");
    const picked = sep > 0 ? { kind: link.slice(0, sep), id: link.slice(sep + 1) } : null;
    // Only non-empty optional fields are written, so a cleared note, result, link or minutes disappears from the record.
    return { date: work?.date || date || today, title: t, ...(n ? { note: n } : {}), ...(r ? { result: r } : {}), ...(picked ? { link: picked } : {}),
      ...(mt ? { minutes: Number(mt) } : {}), track };
  };
  const submit = () => {
    const next = draft();
    if (typeof next === "string") { setErr(next); return; }
    const refused = work ? onUpdate(work.id, next) : onAdd(next);
    if (refused) setErr(refused);
  };
  const toggle = () => {
    const next = draft();
    if (typeof next === "string") { setErr(next); return; }
    const refused = onToggle(work.id, next);
    if (refused) setErr(refused);
  };
  return (
    <Modal title={work ? "업무" : "업무 추가"} onClose={onClose}>
      <div className="space-y-3">
        {work && (
          <div className="space-y-1.5">
            <CvFact label="날짜"><span className="font-mono">{work.date}{!work.done && work.date < today ? ` · 이월 ${daysBetween(work.date, today)}일` : ""}</span></CvFact>
            <CvFact label="출처">{work.source === "ai" ? "AI 제안" : work.source === "meeting" ? "회의 후속" : "수기"}</CvFact>
            <CvFact label="상태">{work.done ? "완료" : "미완료"}{work.minutes ? <span className="font-mono">{` · ${work.minutes}분`}</span> : null}</CvFact>
            <CvFact label="연결" wrap>{workLinkText(state, work) || "연결 없음"}</CvFact>
            {/* Opens the meeting's view in place of this sheet — the root has one modal slot — so the transcript and the
                progress notes are one tap from the item; closing the view lands on the tab (TD-58). Live links only. */}
            {work.link?.kind === "meeting" && workLinkLabel(state, work.link) && (
              <div>
                <button onClick={() => onOpenMeeting(work.link.id)}
                  className="px-2.5 py-1.5 rounded-lg border border-zinc-700 text-zinc-300 text-xs font-bold active:translate-y-0.5">회의록 열기</button>
              </div>
            )}
          </div>
        )}
        <BizField value={title} onChange={setTitle} placeholder="업무 제목 — 예: 견적서 송부" />
        <MeetingText value={note} onChange={setNote} placeholder="메모 (선택)" rows={3} cap={WORK_LIMITS.note} />
        {work && (
          <MeetingText value={result} onChange={setResult} placeholder="처리 내용 (선택) — 어떻게 처리했는지 적어요" rows={4} cap={WORK_LIMITS.result} />
        )}
        {work && (
          <label className="flex items-center gap-2 text-xs text-zinc-500">
            <span className="shrink-0">걸린 시간 (분, 선택)</span>
            <input type="number" inputMode="numeric" aria-label="걸린 시간" value={minutes} onChange={(e) => setMinutes(e.target.value)}
              className="flex-1 w-0 bg-zinc-950 border border-zinc-700 rounded-xl px-3 py-2 text-sm font-mono" />
          </label>
        )}
        {work?.source === "meeting" ? (
          // A follow-up's item: the link is owned by the follow-up, so the sheet offers no picker (v26).
          <p className="text-xs text-zinc-500">연결은 회의록의 후속 항목을 따라요.</p>
        ) : (
          <div>
            <div className="text-xs font-bold tracking-widest text-zinc-500 mb-1.5">연결 (선택)</div>
            <select value={link} onChange={(e) => setLink(e.target.value)}
              className="w-full bg-zinc-950 border border-zinc-700 rounded-xl px-3 py-2.5 text-sm">
              <option value="">연결 안 함</option>
              {stale && <option value={stale}>연결 대상이 삭제됐어요</option>}
              {options.map((o) => <option key={linkKey(o)} value={linkKey(o)}>{o.label}</option>)}
            </select>
          </div>
        )}
        <TrackRow value={track} onPick={setTrack} />
        <p className="text-xs text-zinc-600">업무는 기록이에요 — 목표·실행·점수에 반영되지 않아요.</p>
        {err && <p className="text-xs text-rose-400">{err}</p>}
        <button onClick={submit} className="w-full py-3 rounded-xl bg-cyan-500 text-zinc-950 font-black text-sm active:translate-y-0.5">
          {work ? "저장" : "등록"}
        </button>
        {work && (
          <>
            <button onClick={toggle}
              className="w-full py-2.5 rounded-xl border border-zinc-700 text-zinc-300 text-sm font-bold active:translate-y-0.5">
              {work.done ? "완료 취소" : "완료로 표시"}
            </button>
            <button onClick={() => onRemove(work.id)} className="w-full py-2.5 rounded-xl border border-rose-800 text-rose-300 font-bold text-xs">삭제</button>
          </>
        )}
      </div>
    </Modal>
  );
}

/* ── Work bridge — `오늘 업무 만들기`: the work packet out, the reply's `work` proposals back, each ticked by the user
   before it becomes a record with `source: "ai"` (rule 7 amendment 2026-09-17). The raw reply is not stored: it would
   overwrite the day's journal reply, and nothing derived is stored (rule 9). Shares the send and paste panes with
   `BridgeModal`; the confirm view is its own, since a work proposal has no goal, difficulty or type to pick.
   Generalised in v28: the root renders it for `workBridge` (`buildWorkPacket`, dated today, the link's track) and for
   `reviewBridge` (`buildReviewPacket`, dated next Monday, the business track) — one confirm view for both packets. ── */
function WorkBridgeModal({ state, today, build, title, caption, importDate, importTrack, onClose, onImport, onToast }) {
  const [mode, setMode] = useState("send");
  const [reply, setReply] = useState("");
  const [parsed, setParsed] = useState(null);
  const [picked, setPicked] = useState({});
  const taRef = useRef(null);
  const packet = useMemo(() => build(state, today), [build, state, today]);
  const check = () => {
    const r = parseWorkReply(reply, state, today);
    setParsed(r);
    setPicked(Object.fromEntries(r.proposals.filter((p) => !p.reject).map((p) => [p.key, true])));
  };
  const confirm = () => onImport((parsed?.proposals || []).filter((p) => picked[p.key] && !p.reject), importDate, importTrack);

  return (
    <Modal title={mode === "send" ? title : "AI 답변 붙여넣기"} onClose={onClose}>
      {mode === "send" ? (
        <PacketSendPane packet={packet} taRef={taRef} onCopy={() => copyPacket(taRef, packet, onToast)} onPaste={() => setMode("paste")}
          caption={caption} />
      ) : !parsed ? (
        <ReplyPastePane reply={reply} setReply={setReply} onCheck={check} />
      ) : (
        <div className="space-y-3">
          <div className="text-sm font-bold">제안 업무 확인 — {parsed.proposals.length}건</div>
          {parsed.note && <p className="text-xs text-zinc-400">{parsed.note}</p>}
          {parsed.proposals.length ? parsed.proposals.map((p) => (
            <label key={p.key} className={`flex items-start gap-2 bg-zinc-950 rounded-xl p-3 ${p.reject ? "opacity-50" : ""}`}>
              <input type="checkbox" disabled={!!p.reject} checked={!!picked[p.key]}
                onChange={(e) => setPicked((s) => ({ ...s, [p.key]: e.target.checked }))} className="mt-0.5" />
              <span className="flex-1 min-w-0">
                <span className="block text-sm font-semibold truncate">{p.title}</span>
                <span className="block text-xs text-zinc-500 break-words">{p.linkText || "연결 없음"}{p.note ? ` · ${p.note}` : ""}</span>
                {p.reject && <span className="block text-xs text-rose-400 mt-0.5">{p.reject}</span>}
              </span>
            </label>
          )) : (
            <p className="text-xs text-zinc-500">제안 업무 없음 — 등록할 항목이 없어요.</p>
          )}
          <button onClick={confirm} className="w-full py-3 rounded-xl bg-cyan-500 text-zinc-950 font-black text-sm">선택한 업무 등록</button>
        </div>
      )}
    </Modal>
  );
}

/* ── Time log — `사업 시간 기록` (v28): this week's line, a quick entry by date, minutes and track, and this week's
   entries. An entry a work completion wrote (`workId`) is edited on the work sheet, never here. A record only: it pays
   nothing and moves no goal, grade or streak (rules 1, 8, 18); every sum is derived at render (rule 9). ── */
function TimeLogModal({ state, today, onClose, onAdd, onRemove }) {
  const [date, setDate] = useState(today);
  const [minutes, setMinutes] = useState("");
  const [track, setTrack] = useState("biz");
  const [err, setErr] = useState("");
  const week = mondayOf(today);
  const weekEnd = shiftDay(week, 6);
  const entries = (state.timeLog || []).filter((e) => e.date >= week && e.date <= weekEnd)
    .slice().sort((a, b) => b.date.localeCompare(a.date) || String(b.createdAt || "").localeCompare(String(a.createdAt || "")));
  const titleOf = (e) => (state.work || []).find((w) => w.id === e.workId)?.title || "연결 대상이 삭제됐어요";
  const submit = () => {
    const t = minutes.trim();
    if (!date) { setErr("날짜를 선택해 주세요."); return; }
    if (!(/^\d+$/.test(t) && Number(t) >= 1 && Number(t) <= TIME_LOG_MAX_MINUTES)) { setErr("분을 1 이상 1440 이하로 입력해 주세요."); return; }
    const refused = onAdd({ date, track, minutes: Number(t) });
    if (refused) { setErr(refused); return; }
    setErr("");
    setMinutes("");
  };
  return (
    <Modal title="사업 시간 기록" onClose={onClose}>
      <div className="space-y-3">
        <div className="space-y-0.5">
          <p className="text-xs font-mono text-zinc-300">{timeLine(state, today)}</p>
          <p className="text-xs font-mono text-zinc-500">
            {`직장 ${hoursText(weekMinutes(state, week, "work"))} · 개인 ${hoursText(weekMinutes(state, week, "personal"))}`}</p>
        </div>
        <input type="date" value={date} onChange={(e) => setDate(e.target.value)}
          className="w-full bg-zinc-950 border border-zinc-700 rounded-xl px-3 py-2.5 text-sm font-mono" />
        <BizField value={minutes} onChange={setMinutes} placeholder="분 — 예: 90" num />
        <TrackRow value={track} onPick={setTrack} />
        {err && <p className="text-xs text-rose-400">{err}</p>}
        <button onClick={submit} className="w-full py-3 rounded-xl bg-cyan-500 text-zinc-950 font-black text-sm active:translate-y-0.5">기록</button>
        <div className="space-y-1.5">
          {entries.length === 0 ? <p className="text-xs text-zinc-500">이번 주 기록이 없어요.</p> : entries.map((e) => (
            <div key={e.id} className="flex items-center gap-2 bg-zinc-950 rounded-xl px-3 py-2">
              <span className="flex-1 min-w-0 text-xs font-mono text-zinc-300 break-words">
                {`${e.date} · ${TRACK_LABEL[trackOf(e)]} · ${e.minutes}분 · ${e.workId ? titleOf(e) : "직접 기록"}`}</span>
              {e.workId ? <span className="shrink-0 text-xs text-zinc-500">업무에서 기록</span> : (
                <button aria-label="시간 기록 삭제" onClick={() => { if (window.confirm("시간 기록을 삭제해요. 계속할까요?")) onRemove(e.id); }}
                  className="shrink-0 w-8 h-8 rounded-lg border border-zinc-700 text-zinc-400 flex items-center justify-center active:translate-y-0.5"><X size={14} /></button>
              )}
            </div>
          ))}
        </div>
      </div>
    </Modal>
  );
}

/* ── Prep bridge — `AI에게 회의 준비 묻기`: the prep packet of one project event out, the reply's `checks` proposals back,
   each ticked by the user before it becomes a check with `source: "ai"` (rule 7 amendment 2026-09-17, the third packet).
   The raw reply is not stored (rule 9). Shares the send and paste panes; the confirm view states each proposal's basis. ── */
function PrepBridgeModal({ state, today, eventId, date, onClose, onImport, onToast }) {
  const ev = (state.events || []).find((x) => x.id === eventId);
  const [step, setStep] = useState("send");
  const [reply, setReply] = useState("");
  const [result, setResult] = useState(null);
  const [ticked, setTicked] = useState({});
  const [err, setErr] = useState("");
  const packetRef = useRef(null);
  const packet = useMemo(() => (ev ? buildPrepPacket(state, ev, today, date) : ""), [state, ev, today, date]);
  if (!ev) return null;
  const read = () => {
    const r = parsePrepReply(reply, ev);
    setResult(r);
    setErr("");
    setTicked(Object.fromEntries(r.proposals.filter((x) => !x.reject).map((x) => [x.key, true])));
  };
  const register = () => setErr(onImport(eventId, result.proposals.filter((x) => ticked[x.key] && !x.reject)) || "");
  let body;
  if (step === "send" && !PACKET_TRACKS.includes(trackOf(ev))) {
    // v28: a day-job event has no send pane — the card offers no button for it; this covers any other route in.
    body = <p className="text-sm text-zinc-400">직장 트랙 일정 — AI 패킷에 실리지 않아요</p>;
  } else if (step === "send") {
    body = (
      <PacketSendPane packet={packet} taRef={packetRef} onCopy={() => copyPacket(packetRef, packet, onToast)} onPaste={() => setStep("paste")}
        caption="아래 글을 복사해 Claude·ChatGPT 채팅에 붙여넣고, 답변을 받아 다시 붙여넣어요. 앱은 네트워크를 쓰지 않아요. 이 프로젝트의 회의록 요약·후속·진행사항과 문서 요약이 실려요 — 녹취록·이름·연락처·문서 출처는 실리지 않아요. 직장 트랙 문서·계약은 실리지 않아요." />
    );
  } else if (!result) {
    body = <ReplyPastePane reply={reply} setReply={setReply} onCheck={read} />;
  } else {
    body = (
      <div className="space-y-3">
        <div className="text-sm font-bold">확인할 것 제안 — {result.proposals.length}건</div>
        {result.note && <p className="text-xs text-zinc-400 break-words">{result.note}</p>}
        {result.proposals.length === 0 && <p className="text-xs text-zinc-500">제안 없음 — 등록할 항목이 없어요.</p>}
        {result.proposals.map((x) => (
          <label key={x.key} className={`flex items-start gap-2 bg-zinc-950 rounded-xl p-3 ${x.reject ? "opacity-50" : ""}`}>
            <input type="checkbox" className="mt-0.5" disabled={Boolean(x.reject)} checked={Boolean(ticked[x.key])}
              onChange={(e) => setTicked((cur) => ({ ...cur, [x.key]: e.target.checked }))} />
            <span className="flex-1 min-w-0">
              <span className="block text-sm break-words">{x.text || "내용 없음"}</span>
              <span className="block text-xs text-zinc-500 break-words">{x.basis ? `근거: ${x.basis}` : "근거 없음"}</span>
              {x.reject && <span className="block text-xs text-rose-400 mt-0.5">{x.reject}</span>}
            </span>
          </label>
        ))}
        {err && <p className="text-xs text-rose-400">{err}</p>}
        <button onClick={register} className="w-full py-3 rounded-xl bg-cyan-500 text-zinc-950 font-black text-sm">선택한 항목 등록</button>
      </div>
    );
  }
  return <Modal title={step === "send" ? "AI에게 회의 준비 묻기" : "AI 답변 붙여넣기"} onClose={onClose}>{body}</Modal>;
}

/* The role verdict sheet (2026-09-18, the fifth packet): send · paste · confirm, sharing the panes above. The confirm
   view shows the verdict verbatim under `AI 판단 · 검증되지 않음` — an AI-stated, unverified opinion, no encouragement
   added (rule 13) — and lists the proposed stages and requirement grades as tickable rows; a rejected row states why
   and cannot be ticked. Replacing existing stages is user data, so the save asks `window.confirm` first; nothing is
   written without a tick or a verdict. Every proposal is a component draft until `onImport` writes `role` (rule 7). */
function RoleVerdictModal({ state, today, onClose, onImport, onToast }) {
  const packetRef = useRef(null);
  const packet = useMemo(() => buildRoleVerdictPacket(state, today), [state, today]);
  const [step, setStep] = useState("send");
  const [reply, setReply] = useState("");
  const [result, setResult] = useState(null);
  const [ticked, setTicked] = useState({});
  const [err, setErr] = useState("");
  const read = () => {
    const r = parseRoleVerdictReply(reply, state, today);
    setResult(r);
    setErr("");
    setTicked(Object.fromEntries([...r.stages, ...r.areas].filter((x) => !x.reject).map((x) => [x.key, true])));
  };
  const tickedStages = result ? result.stages.filter((x) => ticked[x.key] && !x.reject) : [];
  const tickedAreas = result ? result.areas.filter((x) => ticked[x.key] && !x.reject) : [];
  const existing = state.role?.stages?.length || 0;
  const save = () => {
    if (tickedStages.length && existing && !window.confirm("단계를 AI 제안으로 바꿔요. 계속할까요?")) return;
    setErr(onImport({ verdict: result.verdict, stages: tickedStages, areas: tickedAreas }) || "");
  };
  const tick = (key) => (e) => setTicked((cur) => ({ ...cur, [key]: e.target.checked }));
  let body;
  if (step === "send") {
    body = (
      <PacketSendPane packet={packet} taRef={packetRef} onCopy={() => copyPacket(packetRef, packet, onToast)} onPaste={() => setStep("paste")}
        caption="아래 글을 복사해 Claude·ChatGPT 채팅에 붙여넣고, 답변을 받아 다시 붙여넣어요. 앱은 네트워크를 쓰지 않아요. 원하는 모습에 적은 글은 그대로 실려요 — 이름·생년월일·연락처·학교·회사명·고객사 이름·직장 트랙 기록은 실리지 않아요. 답변은 AI 판단이고 검증되지 않아요." />
    );
  } else if (!result) {
    body = <ReplyPastePane reply={reply} setReply={setReply} onCheck={read} />;
  } else {
    const v = result.verdict;
    body = (
      <div className="space-y-3">
        <div className="bg-zinc-950 rounded-xl p-3 space-y-1">
          {v ? (
            <>
              <div className="text-xs font-mono text-zinc-500">AI 판단 · 검증되지 않음 · {today}</div>
              <div className="font-mono text-cyan-300 text-sm">{probText(v.probability)}</div>
              <div className="text-sm text-zinc-200 break-words">{v.summary || "요약 없음"}</div>
              <div className="text-xs text-zinc-400 break-words">근거: {v.basis || "없음"}</div>
              <div className="text-xs text-zinc-400 break-words">현재 위치: {v.position || "없음"}</div>
              <div className="text-xs text-zinc-500">{v.gaps.length ? "부족한 것" : "부족한 것 없음"}</div>
              {v.gaps.map((g, i) => <div key={i} className="text-xs text-zinc-400 break-words">- {g}</div>)}
            </>
          ) : (
            <div className="text-sm text-zinc-400">판정 없음 — 답변에 verdict가 없어요</div>
          )}
        </div>
        {result.note && <p className="text-xs text-zinc-400 break-words">{result.note}</p>}
        <div>
          <SectionLabel>제안 단계 — {result.stages.length}건</SectionLabel>
          {result.stages.length === 0 && <p className="text-xs text-zinc-500">제안 단계 없음</p>}
          <div className="space-y-2">
            {result.stages.map((x, i) => (
              <label key={x.key} className={`flex items-start gap-2 bg-zinc-950 rounded-xl p-3 ${x.reject ? "opacity-50" : ""}`}>
                <input type="checkbox" className="mt-0.5" disabled={Boolean(x.reject)} checked={Boolean(ticked[x.key])} onChange={tick(x.key)} />
                <span className="flex-1 min-w-0">
                  <span className="block text-sm font-bold break-words">{i + 1}단계 {x.name || "이름 없음"}</span>
                  <span className="block text-xs text-zinc-500 break-words">{x.why || "근거 없음"}</span>
                  {x.conds.map((c, j) => <span key={j} className="block text-xs font-mono text-zinc-300 break-words">- {c.text}</span>)}
                  {x.reject && <span className="block text-xs text-rose-400 mt-0.5">{x.reject}</span>}
                </span>
              </label>
            ))}
          </div>
        </div>
        <div>
          <SectionLabel>제안 요구 등급 — {result.areas.length}건</SectionLabel>
          {result.areas.length === 0 && <p className="text-xs text-zinc-500">제안 등급 없음</p>}
          <div className="space-y-2">
            {result.areas.map((x) => (
              <label key={x.key} className={`flex items-start gap-2 bg-zinc-950 rounded-xl p-3 ${x.reject ? "opacity-50" : ""}`}>
                <input type="checkbox" className="mt-0.5" disabled={Boolean(x.reject)} checked={Boolean(ticked[x.key])} onChange={tick(x.key)} />
                <span className="flex-1 min-w-0">
                  <span className="block text-sm break-words">
                    {x.name}{x.need ? <> 요구 {RANKS[x.need].name} (지금 {x.current ? RANKS[x.current].name : "제외"})</> : null}
                  </span>
                  {x.reject && <span className="block text-xs text-rose-400 mt-0.5">{x.reject}</span>}
                </span>
              </label>
            ))}
          </div>
        </div>
        {tickedStages.length > 0 && existing > 0 && <p className="text-xs text-zinc-400">저장하면 지금 단계 {existing}개가 선택한 단계로 바뀌어요.</p>}
        <button onClick={save} disabled={!v && !tickedStages.length && !tickedAreas.length}
          className="w-full py-3 rounded-xl bg-cyan-500 text-zinc-950 font-black text-sm disabled:opacity-30">선택한 항목 저장</button>
        {err && <p className="text-xs text-rose-400">{err}</p>}
      </div>
    );
  }
  return <Modal title={step === "send" ? "AI에게 판정 묻기" : result ? "AI 판정 확인" : "AI 답변 붙여넣기"} onClose={onClose}>{body}</Modal>;
}

/* ───────────────────────── Overlay effects ───────────────────────── */

function Overlay({ data, onClose }) {
  useEffect(() => {
    const t = setTimeout(onClose, 2400);
    return () => clearTimeout(t);
  }, [data, onClose]);
  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/75 p-6" onClick={onClose}>
      {data.type === "gradeup" && (
        <div className="anim-bigpop text-center bg-zinc-900 border-2 border-cyan-500 rounded-3xl px-8 py-8 max-w-xs shadow-2xl shadow-cyan-500/25">
          <div className="text-xs tracking-widest text-zinc-500 font-mono">RANK UP</div>
          <div className="flex justify-center my-3"><div className="rounded-xl overflow-hidden border border-zinc-800"><PortraitSprite look={data.look} gender={data.gender} size={64} /></div></div>
          <div className="text-sm text-zinc-400">{data.area}</div>
          <div className="text-2xl font-black text-cyan-300 mt-1">{data.rank}</div>
          {data.roleTo != null && (
            data.roleTo !== data.roleFrom ? (
              <div className="text-xs font-mono text-cyan-300 mt-3">롤모델 근접도 {data.roleFrom}% → {data.roleTo}%</div>
            ) : (
              <div className="text-xs text-zinc-600 mt-3">
                {data.roleTargeted ? "롤모델 근접도 변화 없음 — 이미 요구를 충족한 영역" : "롤모델 요구 외 영역 — 근접도 변화 없음"}
              </div>
            )
          )}
          <p className="text-xs text-zinc-500 mt-3">증거로 증명된 승급입니다.</p>
        </div>
      )}
      {data.type === "achieve" && (
        <div className="anim-bigpop text-center bg-zinc-900 border-2 border-amber-500 rounded-3xl px-8 py-8 max-w-xs shadow-2xl shadow-amber-500/20">
          <div className="text-xs tracking-widest text-zinc-500 font-mono">ACHIEVEMENT</div>
          <div className="flex justify-center my-3"><TrophySvg kind={data.kind || "ach"} tier={data.tier} size={34} /></div>
          <div className="text-lg font-black text-amber-300">{data.name}</div>
          {data.p != null && <div className="text-sm text-zinc-300 font-mono font-bold mt-1.5">{data.d != null ? `D${data.d} · ` : ""}+{(data.p || 0).toLocaleString()}P</div>}
          {data.jwTier && (
            <div className={`text-xs font-mono mt-1 ${TIER_CLS[data.jwTier]}`}>직무 적합 {data.jwTier} · {data.jwField}{data.jwInter ? " 기준(교집합)" : ""} ×{data.jwMult}</div>
          )}
          {data.deltas?.length > 0 ? (
            <div className="mt-3 space-y-1">
              {data.deltas.map((d) => (
                <div key={d.id} className="text-xs font-mono text-cyan-300">🎯 {d.title} {d.from}% → {d.to}%</div>
              ))}
            </div>
          ) : data.deltas ? (
            <div className="mt-3 text-xs text-zinc-600">연결된 목표 없음 — 목표 진행에 기여하지 않은 성취입니다</div>
          ) : null}
          <p className="text-xs text-zinc-500 mt-3">기록에 남았습니다.</p>
        </div>
      )}
      {/* Stage completion (2026-09-18, user decision): no portrait, no trophy — the completed stage, the next one, and
          the fact that records computed it. Raised once per stage by the root effect on `role.seenStageK`. */}
      {data.type === "stage" && (
        <div className="anim-bigpop text-center bg-zinc-900 border-2 border-cyan-500 rounded-3xl px-8 py-8 max-w-xs shadow-2xl shadow-cyan-500/25">
          <div className="text-xs tracking-widest text-zinc-500 font-mono">STAGE</div>
          <div className="text-sm text-zinc-400">단계 완료</div>
          <div className="text-lg font-black text-cyan-300 mt-1 break-words">{data.name}</div>
          <div className="text-xs font-mono text-zinc-400 mt-3">{data.next ? `다음: ${data.next}` : "모든 단계 충족"}</div>
          <p className="text-xs text-zinc-500 mt-3">기록으로 계산된 완료입니다.</p>
        </div>
      )}
    </div>
  );
}

/* ───────────────────────── App root ───────────────────────── */
export default function LifeManager() {
  const [phase, setPhase] = useState("loading");
  const [state, setState] = useState(null);
  const [tab, setTab] = useState("home");
  const [modal, setModal] = useState(null);
  const [overlay, setOverlay] = useState(null);
  const toastRef = useRef(null);
  const readyRef = useRef(false);
  const [imgs, setImgs] = useState({});
  const fileRef = useRef(null);
  const slotRef = useRef(null);
  const importRef = useRef(null);
  const [day, setDay] = useState(dstr());
  const dayRef = useRef(null);
  const today = day;

  const showToast = (t) => toastRef.current?.show(t);

  useEffect(() => {
    (async () => {
      const saved = await store.get(KEY).catch(() => null);
      const m = saved ? migrate(saved) : null;
      if (m) {
        setState(applyDailyTick(m));
        setPhase("main");
        // The first load of a day opens the daily reader once; the briefing is reached from it (`브리핑 ›`).
        if (m.act?.briefingSeen !== dstr()) setModal({ type: "reader" });
      }
      else setPhase("onboard");
      readyRef.current = true;
      const p = await store.get("liferpg-img-profile").catch(() => null);
      setImgs({ profile: p || null });
    })();
  }, []);

  // The app can stay open past midnight; re-read the date on focus and on a slow tick so `today` stays real.
  useEffect(() => {
    const check = () => setDay((d) => (dstr() === d ? d : dstr()));
    const id = setInterval(check, 60000);
    window.addEventListener("visibilitychange", check);
    window.addEventListener("focus", check);
    return () => { clearInterval(id); window.removeEventListener("visibilitychange", check); window.removeEventListener("focus", check); };
  }, []);

  // A new day opens the daily reader once, the same way boot does; the briefing is reached from it.
  useEffect(() => {
    if (!dayRef.current) { dayRef.current = day; return; }
    if (dayRef.current === day) return;
    dayRef.current = day;
    if (state && state.act?.briefingSeen !== day) setModal({ type: "reader" });
  }, [day, state]);

  // A stage completion shows the overlay once: `role.seenStageK` is the seen-stamp (like act.briefingSeen), `k` is always
  // derived. A missing stamp or a lower `k` (a deleted record) is stamped silently; every role write stamps the new `k`
  // itself, so only a record write that raises `k` fires. The stamp write is idempotent under StrictMode's double run,
  // and this effect is the single place the stage overlay is raised.
  useEffect(() => {
    if (!readyRef.current || !state?.role?.stages?.length) return;
    const rs = roleStageOf(state, today);
    const seen = Number.isFinite(state.role.seenStageK) ? state.role.seenStageK : null;
    if (seen === rs.k) return;
    if (seen != null && rs.k > seen) {
      const done = rs.stages[rs.k - 2]?.s.name || "";
      setOverlay({ type: "stage", name: done, next: rs.current ? rs.current.s.name : null });
    }
    setState((prev) => (prev.role?.seenStageK === rs.k ? prev : { ...prev, role: { ...prev.role, seenStageK: rs.k } }));
  }, [state, today]);

  useEffect(() => {
    if (!readyRef.current || !state) return;
    store.set(KEY, state);
    // `store.set` awaits nothing before its write, so the state either reached localStorage by this line or
    // never will; the memory fallback would otherwise show a session a reload cannot find.
    if (!persisted(KEY)) showToast({ msg: "저장에 실패했어요 — 저장 공간이 가득 찼어요. 백업을 내보낸 뒤 사진을 지워요." });
  }, [state]);

  /* Photos */
  const askUpload = (slot) => { slotRef.current = slot; fileRef.current?.click(); };
  const onFile = async (e) => {
    const fl = e.target.files?.[0];
    e.target.value = "";
    if (!fl || !slotRef.current) return;
    try {
      const url = await resizeImage(fl);
      const slot = slotRef.current;
      setImgs((p) => ({ ...p, [slot]: url }));
      store.set(`liferpg-img-${slot}`, url);
      showToast({ msg: "📷 사진이 등록됐어요" });
    } catch { showToast({ msg: "이미지를 읽지 못했어요" }); }
  };
  const clearImg = (slot) => { setImgs((p) => ({ ...p, [slot]: null })); store.del(`liferpg-img-${slot}`); };

  /* Tasks */
  const addQuest = (q) => {
    if (q.isCert && state.tasks.some((x) => x.isCert && x.title === q.title)) {
      setModal(null);
      showToast({ msg: `${q.title} — 이미 등록된 자격입니다. 자격 지급은 영역과 무관하게 1회입니다.` });
      return;
    }
    setState((prev) => {
      const s = structuredClone(prev);
      s.tasks = [{ status: "todo", doneDates: [], createdAt: dstr(), ...q, id: uid() }, ...s.tasks];
      return s;
    });
    setModal(null);
    showToast({ msg: "실행이 추가됐어요" });
  };
  const removeTask = (id) => {
    // Also clears the evidence photo keys (rule 16) — left behind they keep piling up in storage.
    store.del(`liferpg-img-ev-${id}`);
    for (let n = 1; n <= 2; n++) store.del(`liferpg-img-study-${id}-${n}`);
    // The same update drops the id from every meeting's `taskIds`, so a link never outlives its task (v24).
    setState((prev) => {
      const s = structuredClone(prev);
      s.tasks = s.tasks.filter((q) => q.id !== id);
      for (const m of s.meetings || []) if ((m.taskIds || []).includes(id)) m.taskIds = m.taskIds.filter((x) => x !== id);
      return s;
    });
  };

  const applyMeasures = (ms) => {
    if (!ms) return;
    for (const [label, value] of Object.entries(ms)) {
      if (!Number.isFinite(value)) continue;
      outer: for (const g of state.goals || []) {
        if (g.status !== "active") continue;
        for (const kr of g.krs || []) {
          if (kr.type === "metric" && kr.title.includes(label)) { checkinKR(g.id, kr.id, value); break outer; }
        }
      }
    }
  };

  const tryComplete = (q) => {
    if (q.isStudy && !q.evidence) { setModal({ type: "study", task: q }); return; }
    if (q.kind && !q.evidence) { setModal({ type: "activity", task: q }); return; }
    if (needsEvidence(q) && !q.evidence) { setModal({ type: "evidence", task: q }); return; }
    completeTask(q.id, null);
  };

  const completeTask = (id, evidence, score) => {
    setState((prev) => {
      const s = structuredClone(prev);
      const beforeP = Object.fromEntries((prev.goals || []).filter((g) => g.status === "active").map((g) => [g.id, goalProgress(g, prev)]));
      const q = s.tasks.find((x) => x.id === id);
      if (!q) return prev;
      if (q.type === "daily") {
        if (q.doneDates?.includes(today)) return prev;
        q.doneDates = [...(q.doneDates || []), today];
      } else {
        if (q.status === "done") return prev;
        q.status = "done"; q.doneAt = today;
      }
      if (evidence) q.evidence = evidence;
      if (q.isExam && score) q.score = score; // display only — nothing below reads it for P, grade or D (rules 1, 2)

      /* Streak (shields consumed automatically) */
      const a = s.act;
      let shield = false;
      if (a.lastActive !== today) {
        if (a.lastActive === shiftDay(today, -1)) a.streak += 1;
        else if (a.lastActive === shiftDay(today, -2) && a.shieldsLeft > 0) { a.shieldsLeft -= 1; a.streak += 1; shield = true; }
        else a.streak = 1;
        a.lastActive = today;
      }

      const area = s.areas.find((x) => x.id === q.areaId);
      let ach = null;
      let specGain = null;

      if (q.isExam) {
        const fam = examOf(q.famId);
        const r = calcExamPayout(s.exams, fam, q.band);
        if (s.exams.dim[q.famId] === undefined) s.exams.dim[q.famId] = r.mult;
        const prevBest = s.exams.best[q.famId];
        if (!prevBest || q.band.p > prevBest.p) {
          s.exams.best[q.famId] = { label: q.band.label, d: q.band.d, p: q.band.p, ver: POINT_POLICY_VERSION, date: today, ...(score ? { score } : {}) };
        } else if (score && q.band.p === prevBest.p && examScoreBetter(fam, score, prevBest.score)) s.exams.best[q.famId] = { ...prevBest, score };
        if (area) area.achievements = [...area.achievements, {
          id: uid(), grade: area.grade, date: today,
          text: `${fam.n} ${q.band.label} — D${q.band.d} · +${r.payout.toLocaleString()}P${r.mult < 1 ? ` (감쇠 ×${r.mult})` : ""}`,
        }];
        s.room.trophies = [...s.room.trophies, { id: uid(), kind: "ach", label: `${fam.n} ${q.band.label}`, tier: examGrade(q.band.d), date: today }];
        const lang = fam.lang;
        if (lang !== "Academic" && !s.exams.spec[lang]) {
          const highs = Object.entries(s.exams.best).filter(([fid, b]) => {
            const e2 = examOf(fid);
            return e2 && e2.lang === lang && b.d >= 75;
          });
          if (highs.length >= 2) {
            s.exams.spec[lang] = true;
            specGain = LANG_KO[lang];
            s.room.trophies = [...s.room.trophies, { id: uid(), kind: "spec", label: `${specGain} 전문화`, date: today }];
            const lp = s.areas.find((x) => x.name === "어학");
            if (lp && lp.grade < 5) {
              lp.grade = 5;
              lp.achievements = [...lp.achievements, { id: uid(), text: `🎖 ${specGain} 전문화 — 고난도 시험(D75+) 2종 달성`, date: today, grade: 5 }];
            }
          }
        }
        ach = { name: `${fam.n} ${q.band.label}`, d: q.band.d, p: r.payout, tier: examGrade(q.band.d), kind: "ach" };
      } else if (q.isCert) {
        const cp = q.certD != null ? certP(q.certD) : (q.pts ?? 0);
        const prevP = q.sg ? (s.certBest?.[q.sg]?.p || 0) : 0;
        const jw = jobWeightForCert(s, q.areaId, certByTitle(q.title));
        const basePay = Math.max(0, cp - prevP);
        const pay = jw ? Math.round(basePay * jw.mult / 10) * 10 : basePay;
        if (q.sg && (!s.certBest[q.sg] || cp > s.certBest[q.sg].p)) s.certBest[q.sg] = { p: cp, name: q.title, d: q.certD ?? null };
        if (area) area.achievements = [...area.achievements, {
          id: uid(), grade: area.grade, date: today,
          text: `${q.title} — ${q.certD != null ? `D${q.certD} · ` : ""}+${pay.toLocaleString()}P${prevP > 0 ? " (단계 차액)" : ""}${jw ? ` · 직무 ${jw.tier} ×${jw.mult} (${jw.field}${jw.inter ? " 기준·교집합" : ""})` : ""}`,
        }];
        const tier = q.certD != null ? achGrade(q.certD) : legacyCertGrade(cp);
        s.room.trophies = [...s.room.trophies, { id: uid(), kind: "ach", label: q.title, tier, date: today }];
        for (const g of s.goals || []) for (const kr of g.krs || []) {
          if (kr.type === "cert" && !kr.done && kr.certName && q.title.includes(kr.certName)) kr.done = true;
        }
        ach = { name: q.title, d: q.certD, p: pay, tier, kind: "ach", jwTier: jw?.tier, jwField: jw?.field, jwMult: jw?.mult, jwInter: jw?.inter };
      } else if (q.isStudy) {
        const pts = q.pts ?? DIFFS[q.diff].pts;
        if (area) area.achievements = [...area.achievements, {
          id: uid(), grade: area.grade, date: today,
          text: `📖 ${q.title}${q.scope ? ` (${q.scope})` : ""} — ${evidence || "학습 검증"}`,
        }];
        if (pts >= EVIDENCE_MIN) {
          s.room.trophies = [...s.room.trophies, { id: uid(), kind: "spec", label: `📖 ${q.title}`, date: today }];
        }
        ach = { name: q.title, p: pts, kind: "spec" };
      } else if (q.kind) {
        if (evidence && area) {
          const icon = q.kind === "book" ? "📚" : "💪";
          area.achievements = [...area.achievements, { id: uid(), grade: area.grade, date: today, text: `${icon} ${q.title} — ${evidence}` }];
        }
      } else if ((q.pts ?? DIFFS[q.diff].pts) >= EVIDENCE_MIN) {
        const pts = q.pts ?? DIFFS[q.diff].pts;
        if (area) area.achievements = [...area.achievements, { id: uid(), grade: area.grade, date: today, text: `${q.title} — 증거와 함께 완료`, }];
        const tier = legacyCertGrade(pts);
        s.room.trophies = [...s.room.trophies, { id: uid(), kind: "ach", label: q.title, tier, date: today }];
        ach = { name: q.title, p: pts, tier, kind: "ach" };
      }

      const deltas = (s.goals || [])
        .filter((g) => g.status === "active" && beforeP[g.id] !== undefined)
        .map((g) => ({ id: g.id, title: g.title, from: Math.round(beforeP[g.id] * 100), to: Math.round(goalProgress(g, s) * 100) }))
        .filter((d) => d.to !== d.from);
      queueMicrotask(() => {
        if (ach) setOverlay({ type: "achieve", ...ach, deltas });
        else if (deltas.length) showToast({ msg: `완료 · 🎯 ${deltas.map((d) => `${d.title} ${d.from}→${d.to}%`).join(" · ")}${shield ? " · 보호권 사용" : ""}` });
        else showToast({ msg: `완료 · 목표 기여 없음 · 🔥 ${a.streak}일${shield ? " · 보호권 사용" : ""}` });
        if (specGain) setTimeout(() => showToast({ msg: `🎖 ${specGain} 전문화 — 고난도 감쇠 하한 70% 적용` }), 2700);
      });
      return s;
    });
    setModal(null);
  };

  /* Promotion */
  const promoteArea = (areaId, evidenceText) => {
    setState((prev) => {
      const s = structuredClone(prev);
      const rBefore = roleGap(prev)?.match ?? null;
      const p = s.areas.find((x) => x.id === areaId);
      if (!p || p.grade >= RANKS.length - 1) return prev;
      p.grade += 1;
      p.achievements = [...p.achievements, { id: uid(), text: evidenceText, date: dstr(), grade: p.grade }];
      s.room.trophies = [...s.room.trophies, { id: uid(), kind: "rank", label: `${p.name} ${RANKS[p.grade].name}`, date: dstr() }];
      const rAfter = roleGap(s)?.match ?? null;
      const roleTargeted = (prev.role?.targets?.[areaId] || 0) > 0;
      queueMicrotask(() => setOverlay({ type: "gradeup", area: p.name, rank: RANKS[p.grade].name, look: s.profile?.look, gender: s.profile?.gender, roleFrom: rBefore, roleTo: rAfter, roleTargeted }));
      return s;
    });
    setModal(null);
  };

  /* Goals */
  const addGoal = (g) => {
    setState((prev) => {
      const p0 = Math.round(goalProgress(g, prev) * 100);
      queueMicrotask(() => showToast({ msg: `목표 생성 · 시작 진행률 ${p0}%${g.deadline ? ` · ${ddayStr(g.deadline)}` : " · 기한 없음"}` }));
      return { ...prev, goals: [g, ...(prev.goals || [])] };
    });
    setModal(null);
  };
  // `기록에서 제거` (done) removes a record and destroys nothing. `목표 삭제` (active) is the destructive path:
  // the work that never happened goes with the goal, and anything already completed stays — it carries evidence,
  // paid points and an achievement entry (rules 4, 16), and shows up in `미분류` afterwards (rule 18).
  const removeGoal = (id) => {
    const g = (state.goals || []).find((x) => x.id === id);
    if (!g) return;
    if (g.status !== "active") { setState((prev) => ({ ...prev, goals: prev.goals.filter((x) => x.id !== id) })); return; }
    const mine = (state.tasks || []).filter((q) => q.goalId === id);
    const drop = mine.filter((q) => q.status !== "done" && !(q.doneDates || []).length);
    const kept = mine.length - drop.length;
    if (!window.confirm(`${g.title} 목표를 삭제해요. 연결된 미완료 실행 ${drop.length}건도 함께 사라져요. 완료 기록 ${kept}건은 미분류로 남아요. 계속할까요?`)) return;
    for (const q of drop) { store.del(`liferpg-img-ev-${q.id}`); for (let n = 1; n <= 2; n++) store.del(`liferpg-img-study-${q.id}-${n}`); }
    const dropIds = new Set(drop.map((q) => q.id));
    setState((prev) => {
      const s = structuredClone(prev);
      s.goals = (s.goals || []).filter((x) => x.id !== id);
      s.tasks = (s.tasks || []).filter((q) => !dropIds.has(q.id));
      // Dropped tasks leave no meeting link behind, the same as `removeTask` (v24).
      for (const m of s.meetings || []) if ((m.taskIds || []).some((x) => dropIds.has(x))) m.taskIds = m.taskIds.filter((x) => !dropIds.has(x));
      return s;
    });
    showToast({ msg: `목표를 삭제했어요 · 미완료 실행 ${drop.length}건 삭제 · 완료 기록 ${kept}건 유지` });
  };
  const goalStatus = (id, status) => {
    setState((prev) => {
      const s = structuredClone(prev);
      const g = s.goals.find((x) => x.id === id);
      if (g) g.status = status;
      if (status === "done" && g) {
        queueMicrotask(() => setOverlay({ type: "achieve", name: g.title, tier: "A", kind: "rank" }));
      }
      return s;
    });
  };
  const checkinKR = (goalId, krId, value) => {
    setState((prev) => {
      const s = structuredClone(prev);
      const g = s.goals.find((x) => x.id === goalId);
      const kr = g?.krs.find((k) => k.id === krId);
      if (!(kr && kr.type === "metric" && Number.isFinite(value)) || kr.current === value) return prev;
      const from = Math.round(goalProgress(g, prev) * 100);
      kr.current = value;
      const to = Math.round(goalProgress(g, s) * 100);
      if (to !== from) queueMicrotask(() => showToast({ msg: `체크인 · 🎯 ${g.title} ${from}% → ${to}%` }));
      return s;
    });
  };

  /* Schedule — appointments and deadlines. An event is a record, never a task: no points, no trophy,
     no metric, no evidence gate, no goalId. Ticking writes to doneDates, cancelling writes to skip. */
  const addEvent = (ev) => {
    setState((prev) => {
      const s = structuredClone(prev);
      s.events = [{ id: uid(), createdAt: today, ...ev }, ...(s.events || [])];
      return s;
    });
    setModal(null);
    showToast({ msg: "일정을 등록했어요" });
  };
  const updateEvent = (id, next) => {
    setState((prev) => {
      const s = structuredClone(prev);
      const i = (s.events || []).findIndex((x) => x.id === id);
      if (i < 0) return prev;
      // The form replaces the record: a place, note or repeat cleared in the modal has to disappear from the save; the user's own stamps stay.
      const e = s.events[i];
      s.events[i] = { id: e.id, createdAt: e.createdAt, ...(e.skip ? { skip: e.skip } : {}), ...(e.doneDates ? { doneDates: e.doneDates } : {}), ...next };
      return s;
    });
    setModal(null);
    showToast({ msg: "일정을 수정했어요" });
  };
  const removeEvent = (id) => {
    setState((prev) => {
      const s = structuredClone(prev);
      s.events = (s.events || []).filter((e) => e.id !== id);
      return s;
    });
    setModal(null);
    showToast({ msg: "일정을 삭제했어요" });
  };
  const toggleEventDone = (id, date) => {
    const wasDone = ((state.events || []).find((e) => e.id === id)?.doneDates || []).includes(date);
    setState((prev) => {
      const s = structuredClone(prev);
      const e = (s.events || []).find((x) => x.id === id);
      if (!e) return prev;
      e.doneDates = wasDone ? (e.doneDates || []).filter((d) => d !== date) : [...(e.doneDates || []), date].sort();
      return s;
    });
    if (!wasDone) showToast({ msg: "일정을 완료로 표시했어요" });
  };
  const skipOccurrence = (id, date) => {
    setState((prev) => {
      const s = structuredClone(prev);
      const e = (s.events || []).find((x) => x.id === id);
      if (!e || (e.skip || []).includes(date)) return prev;
      e.skip = [...(e.skip || []), date].sort();
      return s;
    });
    showToast({ msg: "이번 회차를 취소했어요" });
  };
  /* Pre-meeting checks (v27) — `확인할 것` on a schedule event: a checklist, never a task or a work item (rules 1, 9, 18).
     These handlers write one event's `checks` and nothing else; a repeating event carries one list for every occurrence. */
  const writeChecks = (eventId, fn) => setState((prev) => {
    const s = structuredClone(prev);
    const e = (s.events || []).find((x) => x.id === eventId);
    if (!e) return prev;
    e.checks = fn(e.checks || []);
    return s;
  });
  // Answers "" when written, or the refusal the caller shows.
  const addCheck = (eventId, raw, source = "manual") => {
    const ev = (state.events || []).find((x) => x.id === eventId);
    if (!ev) return "";
    const text = String(raw || "").trim();
    const checks = ev.checks || [];
    if (!text) return "확인할 것을 입력해 주세요.";
    if (text.length > EVENT_CHECK_TEXT) return `확인할 것은 ${EVENT_CHECK_TEXT}자까지예요 — 지금 ${text.length}자예요.`;
    if (checks.length >= EVENT_CHECKS_MAX) return `확인할 것은 ${EVENT_CHECKS_MAX}건까지예요.`;
    const item = { id: uid(), text, done: false, source };
    const refused = recordFits({ ...ev, checks: [...checks, item] }, JSON.stringify(ev).length, "확인할 것을");
    if (refused) return refused;
    writeChecks(eventId, (list) => [...list, item]);
    showToast({ msg: "확인할 것을 추가했어요" });
    return "";
  };
  const toggleCheck = (eventId, checkId) => {
    const was = (state.events || []).find((x) => x.id === eventId)?.checks?.find((c) => c.id === checkId)?.done === true;
    writeChecks(eventId, (list) => list.map((c) => (c.id === checkId ? { ...c, done: !c.done } : c)));
    showToast({ msg: was ? "확인 완료를 취소했어요" : "확인 완료로 표시했어요" });
  };
  // The caller has confirmed.
  const removeCheck = (eventId, checkId) => {
    writeChecks(eventId, (list) => list.filter((c) => c.id !== checkId));
    showToast({ msg: "확인할 것을 삭제했어요" });
  };
  // Registers every ticked, non-rejected prep proposal with `source: "ai"`; over the cap nothing is written.
  const importChecks = (eventId, list) => {
    const ev = (state.events || []).find((x) => x.id === eventId);
    if (!ev) return "";
    const checks = ev.checks || [];
    const room = Math.max(0, EVENT_CHECKS_MAX - checks.length);
    if (list.length > room) return `확인할 것은 ${EVENT_CHECKS_MAX}건까지예요 — ${room}건만 등록할 수 있어요.`;
    const made = list.map((p) => ({ id: uid(), text: p.text, done: false, source: "ai" }));
    const refused = recordFits({ ...ev, checks: [...checks, ...made] }, JSON.stringify(ev).length, "확인할 것을");
    if (refused) return refused;
    if (made.length) writeChecks(eventId, (cur) => [...cur, ...made]);
    setModal(null);
    showToast({ msg: `AI 제안 확인할 것 ${made.length}건 등록` });
    return "";
  };

  /* Role model (2026-09-18): the editor and the verdict sheet both write `role` and nothing else. `verdicts` pass through
     the editor untouched; every write stamps `seenStageK` with the stage index computed on the new state, so a stage set
     the user just wrote never fires the completion overlay — only a record that raises `k` afterwards does. */
  const saveRole = (rm) => {
    setState((prev) => {
      const s = structuredClone(prev);
      const next = { ...(s.role || {}), name: rm.name, targets: rm.targets };
      if (rm.stages) next.stages = rm.stages; else delete next.stages;
      if (rm.story) next.story = rm.story; else delete next.story;
      s.role = next;
      const rs = roleStageOf(s, today);
      if (rs) next.seenStageK = rs.k; else delete next.seenStageK;
      return s;
    });
    setModal(null);
    showToast({ msg: "롤모델 기준 저장 — 근접도는 검증된 등급으로만 계산됩니다" });
  };
  // Saves what the user ticked on the verdict sheet: ticked stages replace `role.stages` (the sheet has confirmed), ticked
  // grades update `role.targets` (a requirement, never `areas[].grade`), and the verdict is prepended to `role.verdicts`
  // dated today — `stageK` read from the stages just saved, `why` never stored, the raw reply never stored, `upsertReply`
  // never called (rule 7 amendment 2026-09-18). Returns a refusal string or "" like `importChecks`.
  const importRoleVerdict = ({ verdict, stages, areas }) => {
    const role = { ...(state.role || { name: "롤모델", targets: {} }) };
    if (stages.length) {
      role.stages = stages.map((p) => ({ id: uid(), name: p.name, conds: p.conds.map((c) => ({ type: c.type, ...(c.arg ? { arg: c.arg } : {}), min: c.min })) }));
    }
    for (const a of areas) role.targets = { ...role.targets, [a.areaId]: a.need };
    const rs = roleStageOf({ ...state, role }, today);
    if (verdict) {
      role.verdicts = [{
        id: uid(), date: today, ...(Number.isFinite(verdict.probability) ? { probability: verdict.probability } : {}),
        summary: verdict.summary, basis: verdict.basis, position: verdict.position, gaps: verdict.gaps,
        stageK: rs ? rs.k : null, stageN: rs ? rs.n : 0, source: "ai",
      }, ...(role.verdicts || [])].slice(0, ROLE_VERDICTS_MAX);
    }
    if (rs) role.seenStageK = rs.k; else delete role.seenStageK;
    const refused = recordFits(role, JSON.stringify(state.role || {}).length, "판정을");
    if (refused) return refused;
    setState((prev) => ({ ...prev, role }));
    setModal(null);
    showToast({ msg: `${verdict ? "AI 판정 저장" : "AI 제안 저장"} · 단계 ${stages.length}건 · 요구 등급 ${areas.length}건` });
    return "";
  };

  /* Business — portfolio, unit prices and period contracts. A business record is a record, never a task:
     no points, no trophy, no goal, no streak, no evidence gate (rules 1, 18). One generic trio keyed by
     the list name, because the three lists differ only in their form and their toast. */
  const warnImage = (w) => {
    if (!w) return;
    // Delayed like the specialisation toast in completeTask, so the record toast is read before this one.
    const msg = w.reason === "quota"
      ? "대표 이미지를 저장하지 못했어요 — 저장 공간이 가득 찼어요. 포트폴리오 이미지를 지우고 다시 시도해요."
      : `저장 공간이 부족해요 — 현재 ${w.usedMB}MB 사용 중이라 이미지를 추가하지 않았어요. 기존 이미지를 지운 뒤 다시 시도해요.`;
    setTimeout(() => showToast({ msg }), 2700);
  };
  // A deal carrying payment lines (v28) runs the storage guard first; the form stays open with the refusal.
  const bizRefusal = (list, rec, prevLen) => (list === "deals" && rec.payments ? recordFits(rec, prevLen, "계약을") : "");
  // `leadId` (v28): a contract registered from a lead's `계약 만들기 ›` sets that lead's `dealId` in the same update, so the
  // write touches `deals` and `leads` only; a lead deleted meanwhile is skipped.
  const addBiz = (list, item, imgWarn, leadId) => {
    const refused = bizRefusal(list, item, 0);
    if (refused) return refused;
    const rec = { id: uid(), createdAt: today, ...item };
    const linked = list === "deals" && !!leadId && (state.leads || []).some((l) => l.id === leadId);
    setState((prev) => {
      const s = structuredClone(prev);
      s[list] = [rec, ...(s[list] || [])];
      const lead = linked ? (s.leads || []).find((l) => l.id === leadId) : null;
      if (lead) lead.dealId = rec.id;
      return s;
    });
    setModal(null);
    showToast({ msg: `${BIZ_NOUN[list]} 등록했어요${linked ? " · 리드 연결" : ""}` });
    warnImage(imgWarn);
    return "";
  };
  const updateBiz = (list, id, next, imgWarn) => {
    const old = (state[list] || []).find((x) => x.id === id);
    const refused = bizRefusal(list, next, old ? JSON.stringify(old).length : 0);
    if (refused) return refused;
    setState((prev) => {
      const s = structuredClone(prev);
      const i = (s[list] || []).findIndex((x) => x.id === id);
      if (i < 0) return prev;
      // The form replaces the record: a field cleared in the modal has to disappear from the save. The id,
      // the creation date and the user's own payment stamps are not the form's to rewrite.
      const cur = s[list][i];
      s[list][i] = { id: cur.id, createdAt: cur.createdAt, ...(cur.paidMonths ? { paidMonths: cur.paidMonths } : {}), ...next };
      return s;
    });
    setModal(null);
    showToast({ msg: `${BIZ_NOUN[list]} 수정했어요` });
    warnImage(imgWarn);
    return "";
  };
  const removeBiz = (list, id) => {
    const item = (state[list] || []).find((x) => x.id === id);
    if (!item) return;
    // A rate carries neither a picture nor a stamp, so only these two ask first (the removeGoal precedent).
    if (list === "folio" && !window.confirm(`${item.title} 포트폴리오를 삭제해요. 등록한 대표 이미지도 함께 사라져요. 계속할까요?`)) return;
    const payNote = (item.payments || []).length ? ` 입금 예정 ${item.payments.length}건도 함께 사라져요.` : "";
    if (list === "deals" && !window.confirm(`${item.client} ${item.title} 계약 기록을 삭제해요. 입금 확인 표시 ${(item.paidMonths || []).length}건도 함께 사라져요.${payNote} 계속할까요?`)) return;
    if (list === "folio") store.del(`liferpg-img-folio-${id}`);
    setState((prev) => ({ ...prev, [list]: (prev[list] || []).filter((x) => x.id !== id) }));
    setModal(null);
    showToast({ msg: `${BIZ_NOUN[list]} 삭제했어요` });
  };
  const toggleDealPaid = (id, month) => {
    const wasPaid = ((state.deals || []).find((d) => d.id === id)?.paidMonths || []).includes(month);
    setState((prev) => {
      const s = structuredClone(prev);
      const d = (s.deals || []).find((x) => x.id === id);
      if (!d) return prev;
      d.paidMonths = wasPaid ? (d.paidMonths || []).filter((m) => m !== month) : [...(d.paidMonths || []), month].sort();
      return s;
    });
    showToast({ msg: `${month} 입금 확인${wasPaid ? "을 취소했어요" : "으로 표시했어요"}` });
  };
  // A payment line's paid stamp (v28): `paidAt: today`, or removed. Writes `deals` only.
  const toggleDealPayment = (dealId, paymentId) => {
    const p = ((state.deals || []).find((d) => d.id === dealId)?.payments || []).find((x) => x.id === paymentId);
    if (!p) return;
    setState((prev) => {
      const s = structuredClone(prev);
      const line = ((s.deals || []).find((d) => d.id === dealId)?.payments || []).find((x) => x.id === paymentId);
      if (!line) return prev;
      if (p.paidAt) delete line.paidAt; else line.paidAt = today;
      return s;
    });
    const kind = PAYMENT_KIND[p.kind] || PAYMENT_KIND.other;
    showToast({ msg: p.paidAt ? `${kind} 입금 확인을 취소했어요` : `${kind} 입금 확인으로 표시했어요` });
  };
  // The chosen business view is a preference, not derived data: only the string is stored (schema v20).
  const setBizView = (v) => setState((prev) => ({ ...prev, ui: { ...(prev.ui || {}), bizView: v } }));

  /* Meetings — project minutes. A record, never a task: these handlers write `meetingProjects` and `meetings`, plus the
     `work` items a mine follow-up mirrors (v26), and nothing else — no act, tasks, goals, areas, room, exams or events
     (rules 1, 18). */
  // Whether a record (minutes, a progress entry, a work item) still fits the storage budget, counted in string length
  // like `storageUsedBytes`: the storage in use with the current state, plus the record, minus the record it replaces
  // when editing. `noun` is the object-marked word of the refusal (`회의록을` / `진행사항을` / `업무를`) — no grammar here.
  const recordFits = (next, prevLen = 0, noun = "회의록을") => {
    const used = storageUsedWith(state);
    return used + JSON.stringify(next).length - prevLen <= STORAGE_BUDGET
      ? ""
      : `저장 공간이 부족해요 — 현재 ${mbText(used)}MB 사용 중이라 ${noun} 저장하지 않았어요. 백업을 내보낸 뒤 오래된 회의록이나 사진을 지워요.`;
  };
  // Replaces one meeting record in place; the caller has already built and budget-checked it.
  const putMeeting = (rec) => setState((prev) => {
    const s = structuredClone(prev);
    const i = (s.meetings || []).findIndex((m) => m.id === rec.id);
    if (i < 0) return prev;
    s.meetings[i] = rec;
    return s;
  });
  const addProject = (p) => {
    setState((prev) => {
      const s = structuredClone(prev);
      s.meetingProjects = [{ id: uid(), ...p, createdAt: today }, ...(s.meetingProjects || [])];
      return s;
    });
    setModal(null);
    showToast({ msg: "프로젝트를 등록했어요" });
  };
  const updateProject = (id, next) => {
    setState((prev) => {
      const s = structuredClone(prev);
      const i = (s.meetingProjects || []).findIndex((x) => x.id === id);
      if (i < 0) return prev;
      const cur = s.meetingProjects[i];
      s.meetingProjects[i] = { id: cur.id, ...next, createdAt: cur.createdAt }; // the form replaces the record; a cleared note disappears
      return s;
    });
    setModal(null);
    showToast({ msg: "프로젝트를 수정했어요" });
  };
  const removeProject = (id) => {
    const n = (state.meetings || []).filter((m) => m.projectId === id).length;
    // Refused here too, not only by the disabled button: deleting a project must never orphan or take minutes with it.
    if (n > 0) { showToast({ msg: `회의록 ${n}건이 있어 삭제할 수 없어요 — 회의록을 먼저 지워요.` }); return; }
    const d = (state.documents || []).filter((x) => x.projectId === id).length;
    if (d > 0) { showToast({ msg: "문서 " + d + "건이 있어 삭제할 수 없어요 — 문서를 먼저 지워요." }); return; }
    setState((prev) => ({ ...prev, meetingProjects: (prev.meetingProjects || []).filter((p) => p.id !== id) }));
    setModal(null);
    showToast({ msg: "프로젝트를 삭제했어요" });
  };
  // Writes a meeting record (`prev` = the stored one, or null for a new record) together with the work items its
  // follow-ups mirror (v26), in one clone update. The reconcile runs against the render's `state.work` — for a
  // user-driven write it is the same object the updater's `prev.work` would be, the pattern `addMeeting` already used
  // to build its record (TD-56). The budget check covers the record plus every work item created. Answers
  // `{ refused, created, removed }`; nothing is written when `refused` is non-empty.
  const commitMeeting = (rec, prev) => {
    const cur = state.work || [];
    // v28: a memo moved into a project stops carrying its own track; a project meeting never stores one.
    if (rec.projectId != null) delete rec.track;
    const { work, meeting } = reconcileFollowUps(cur, rec, prev, today, meetingTrack(state, rec));
    const created = work.filter((w) => !cur.some((x) => x.id === w.id));
    const removed = cur.filter((x) => !work.some((w) => w.id === x.id)).length;
    const refused = recordFits([meeting, ...created], prev ? JSON.stringify(prev).length : 0, "회의록을");
    if (refused) return { refused, created: 0, removed: 0 };
    setState((p) => {
      const s = structuredClone(p);
      if (prev) {
        const i = (s.meetings || []).findIndex((m) => m.id === meeting.id);
        if (i < 0) return p;
        s.meetings[i] = meeting;
      } else {
        s.meetings = [meeting, ...(s.meetings || [])];
      }
      s.work = work;
      return s;
    });
    return { refused: "", created: created.length, removed };
  };
  const workMadeText = (n) => (n > 0 ? ` · 업무 ${n}건 등록` : "");
  const addMeeting = (next) => {
    const r = commitMeeting({ id: uid(), ...next, createdAt: today }, null);
    if (r.refused) return r.refused;
    setModal(null);
    showToast({ msg: `회의록을 등록했어요${workMadeText(r.created)}` });
    return "";
  };
  const updateMeeting = (id, next) => {
    const cur = (state.meetings || []).find((m) => m.id === id);
    if (!cur) return "";
    // The form replaces the record, keeping id and createdAt.
    const r = commitMeeting({ id: cur.id, ...next, createdAt: cur.createdAt }, cur);
    if (r.refused) return r.refused;
    setModal(null);
    showToast({ msg: `회의록을 수정했어요${workMadeText(r.created)}` });
    return "";
  };
  // Follow-up items (v26), from the meeting view; the view stays open. Only `done` mirrors to the linked work item.
  const toggleFollowUp = (meetingId, fuId) => {
    const fu = ((state.meetings || []).find((m) => m.id === meetingId)?.followUps || []).find((f) => f.id === fuId);
    if (!fu) return;
    const done = fu.done !== true;
    setState((prev) => {
      const s = structuredClone(prev);
      const f = ((s.meetings || []).find((m) => m.id === meetingId)?.followUps || []).find((x) => x.id === fuId);
      if (!f) return prev;
      f.done = done;
      const w = f.workId ? (s.work || []).find((x) => x.id === f.workId) : null;
      if (w) { w.done = done; syncTimeLog(s, w); } // v28: the mirrored item's time-log entry follows its done state
      return s;
    });
    showToast({ msg: done ? "후속 항목을 완료로 표시했어요" : "후속 항목 완료를 취소했어요" });
  };
  const setFollowUpMine = (meetingId, fuId, mine) => {
    const cur = (state.meetings || []).find((m) => m.id === meetingId);
    if (!cur) return;
    const r = commitMeeting({ ...cur, followUps: (cur.followUps || []).map((f) => (f.id === fuId ? { ...f, mine } : f)) }, cur);
    if (r.refused) { showToast({ msg: r.refused }); return; }
    showToast({ msg: mine
      ? `내 담당으로 표시했어요${r.created > 0 ? " · 업무 등록" : ""}`
      : `내 담당을 해제했어요${r.removed > 0 ? " · 미완료 업무 삭제" : ""}` });
  };
  // Appends split candidates (`[{ text, mine }]`, trimmed and non-empty); answers a refusal string or "" when saved.
  const appendFollowUps = (meetingId, items) => {
    const cur = (state.meetings || []).find((m) => m.id === meetingId);
    if (!cur) return "";
    const have = (cur.followUps || []).length;
    if (have + items.length > MEETING_FOLLOWUPS_MAX) {
      return `후속 항목은 ${MEETING_FOLLOWUPS_MAX}건까지예요 — ${Math.max(0, MEETING_FOLLOWUPS_MAX - have)}건만 추가할 수 있어요.`;
    }
    const added = items.map((t) => ({ id: uid(), text: t.text, mine: !!t.mine, done: false }));
    const r = commitMeeting({ ...cur, followUps: [...(cur.followUps || []), ...added] }, cur);
    if (r.refused) return r.refused;
    showToast({ msg: `후속 항목 ${added.length}건을 추가했어요${workMadeText(r.created)}` });
    return "";
  };
  const removeMeeting = (id) => {
    const m = (state.meetings || []).find((x) => x.id === id);
    if (!m) return;
    if (!window.confirm(`${m.title} 회의록을 삭제해요. 계속할까요?`)) return;
    setState((prev) => ({ ...prev, meetings: (prev.meetings || []).filter((x) => x.id !== id) }));
    setModal(null);
    showToast({ msg: "회의록을 삭제했어요" });
  };
  // Progress entries (v25) grow an existing meeting record and touch nothing else — no tasks, goals, act, room,
  // events or work. The view stays open, so the sheet shows the new entry at once.
  const addProgress = (meetingId, text) => {
    const cur = (state.meetings || []).find((m) => m.id === meetingId);
    if (!cur) return "";
    if ((cur.progress || []).length >= MEETING_PROGRESS_MAX) return `진행사항은 ${MEETING_PROGRESS_MAX}건까지예요.`;
    const rec = { ...cur, progress: [{ id: uid(), date: today, text }, ...(cur.progress || [])] };
    const refused = recordFits(rec, JSON.stringify(cur).length, "진행사항을");
    if (refused) return refused;
    putMeeting(rec);
    showToast({ msg: "진행사항을 추가했어요" });
    return "";
  };
  const removeProgress = (meetingId, entryId) => {
    const cur = (state.meetings || []).find((m) => m.id === meetingId);
    if (!cur) return;
    putMeeting({ ...cur, progress: (cur.progress || []).filter((e) => e.id !== entryId) });
    showToast({ msg: "진행사항을 삭제했어요" });
  };
  // Removes only a meeting's transcript (2026-09-17); every other field stays. Confirmed in the view; the record
  // shrinks, so no budget check.
  const clearTranscript = (meetingId) => {
    const cur = (state.meetings || []).find((m) => m.id === meetingId);
    if (!cur || !cur.transcript) return;
    const { transcript, ...rest } = cur;
    putMeeting(rest);
    showToast({ msg: "녹취록을 지웠어요" });
  };

  /* Documents (v27) — records of what a file says; a record, never a task (rules 1, 18). These handlers write `documents`
     and nothing else. */
  const addDocument = (next) => {
    const rec = { id: uid(), ...next, addedAt: today };
    const refused = recordFits(rec, 0, "문서를");
    if (refused) return refused;
    setState((prev) => ({ ...prev, documents: [rec, ...(prev.documents || [])] }));
    setModal(null);
    showToast({ msg: "문서를 등록했어요" });
    return "";
  };
  const updateDocument = (id, next) => {
    const cur = (state.documents || []).find((d) => d.id === id);
    if (!cur) return "";
    const rec = { id: cur.id, ...next, addedAt: cur.addedAt }; // the form replaces the record; a cleared source disappears
    const refused = recordFits(rec, JSON.stringify(cur).length, "문서를");
    if (refused) return refused;
    setState((prev) => ({ ...prev, documents: (prev.documents || []).map((d) => (d.id === id ? rec : d)) }));
    setModal(null);
    showToast({ msg: "문서를 수정했어요" });
    return "";
  };
  // Confirmed in the sheet by title.
  const removeDocument = (id) => {
    setState((prev) => ({ ...prev, documents: (prev.documents || []).filter((d) => d.id !== id) }));
    setModal(null);
    showToast({ msg: "문서를 삭제했어요" });
  };

  /* Roadmap (v28) — milestones are records, never tasks (rules 1, 18). These handlers write `milestones` and nothing
     else; the status is the user's own field and `doneAt` is stamped only while it is done. */
  const addMilestone = (next) => {
    const { doneAt, ...rest } = next;
    const rec = { id: uid(), ...rest, ...(next.status === "done" ? { doneAt: doneAt || today } : {}), createdAt: today };
    const refused = recordFits(rec, 0, "마일스톤을");
    if (refused) return refused;
    setState((prev) => ({ ...prev, milestones: [rec, ...(prev.milestones || [])] }));
    setModal(null);
    showToast({ msg: "마일스톤을 등록했어요" });
    return "";
  };
  const updateMilestone = (id, next) => {
    const cur = (state.milestones || []).find((m) => m.id === id);
    if (!cur) return "";
    const { doneAt, ...rest } = next;
    const rec = { id: cur.id, ...rest, ...(next.status === "done" ? { doneAt: cur.doneAt || today } : {}), createdAt: cur.createdAt };
    const refused = recordFits(rec, JSON.stringify(cur).length, "마일스톤을");
    if (refused) return refused;
    setState((prev) => ({ ...prev, milestones: (prev.milestones || []).map((m) => (m.id === id ? rec : m)) }));
    setModal(null);
    showToast({ msg: "마일스톤을 수정했어요" });
    return "";
  };
  // Confirmed in the sheet by title.
  const removeMilestone = (id) => {
    setState((prev) => ({ ...prev, milestones: (prev.milestones || []).filter((m) => m.id !== id) }));
    setModal(null);
    showToast({ msg: "마일스톤을 삭제했어요" });
  };
  /* Pipeline and notices (v28) — records, never tasks (rules 1, 18). The lead handlers write `leads`, the notice handlers
     `notices`, and nothing else; `stageAt` is stamped when a lead is registered and whenever its stage changes, and
     `dealId` is written only by `addBiz` when a contract is registered from the lead. */
  const addLead = (next) => {
    const rec = { id: uid(), ...next, stageAt: today, createdAt: today };
    const refused = recordFits(rec, 0, "리드를");
    if (refused) return refused;
    setState((prev) => ({ ...prev, leads: [rec, ...(prev.leads || [])] }));
    setModal(null);
    showToast({ msg: "리드를 등록했어요" });
    return "";
  };
  const updateLead = (id, next) => {
    const cur = (state.leads || []).find((l) => l.id === id);
    if (!cur) return "";
    const rec = { id: cur.id, ...next, stageAt: next.stage === cur.stage && cur.stageAt ? cur.stageAt : today,
      ...(cur.dealId ? { dealId: cur.dealId } : {}), createdAt: cur.createdAt };
    const refused = recordFits(rec, JSON.stringify(cur).length, "리드를");
    if (refused) return refused;
    setState((prev) => ({ ...prev, leads: (prev.leads || []).map((l) => (l.id === id ? rec : l)) }));
    setModal(null);
    showToast({ msg: "리드를 수정했어요" });
    return "";
  };
  // Confirmed in the sheet by name.
  const removeLead = (id) => {
    setState((prev) => ({ ...prev, leads: (prev.leads || []).filter((l) => l.id !== id) }));
    setModal(null);
    showToast({ msg: "리드를 삭제했어요" });
  };
  // Opens the contract form prefilled from the lead; nothing is written until that form registers.
  const makeDealFromLead = (lead) => setModal({ type: "deals",
    prefill: { client: lead.name, title: "", status: lead.stage === "won" ? "won" : "quote", track: "biz" }, leadId: lead.id });
  const addNotice = (next) => {
    const rec = { id: uid(), ...next, createdAt: today };
    const refused = recordFits(rec, 0, "공고를");
    if (refused) return refused;
    setState((prev) => ({ ...prev, notices: [rec, ...(prev.notices || [])] }));
    setModal(null);
    showToast({ msg: "공고를 등록했어요" });
    return "";
  };
  const updateNotice = (id, next) => {
    const cur = (state.notices || []).find((n) => n.id === id);
    if (!cur) return "";
    const rec = { id: cur.id, ...next, createdAt: cur.createdAt };
    const refused = recordFits(rec, JSON.stringify(cur).length, "공고를");
    if (refused) return refused;
    setState((prev) => ({ ...prev, notices: (prev.notices || []).map((n) => (n.id === id ? rec : n)) }));
    setModal(null);
    showToast({ msg: "공고를 수정했어요" });
    return "";
  };
  // Confirmed in the sheet by title.
  const removeNotice = (id) => {
    setState((prev) => ({ ...prev, notices: (prev.notices || []).filter((n) => n.id !== id) }));
    setModal(null);
    showToast({ msg: "공고를 삭제했어요" });
  };
  // One tap fills the nine seeds, and only into an empty roadmap.
  const seedRoadmap = () => {
    if ((state.milestones || []).length) return;
    const seeds = seedMilestones(today);
    const refused = recordFits(seeds, 0, "마일스톤을");
    if (refused) { showToast({ msg: refused }); return; }
    setState((prev) => ((prev.milestones || []).length ? prev : { ...prev, milestones: seeds }));
    showToast({ msg: `기본 로드맵 ${ROADMAP_STAGES}건을 채웠어요` });
  };

  /* Daily work — dated work items (v25). A record, never a task: these handlers write `work`, plus the `done` state or
     the `workId` of the follow-up an item mirrors (v26), plus the item's own `timeLog` entry (v28, `syncTimeLog`), and
     nothing else — no act, tasks, goals, areas, room, exams or events (rules 1, 9, 18). No streak, no trophy, no KR. */
  const writeWork = (fn) => setState((prev) => {
    const s = structuredClone(prev);
    s.work = fn(s.work || []);
    return s;
  });
  const addWork = (next) => {
    const rec = { id: uid(), ...next, done: false, source: "manual", track: trackOf(next), createdAt: today };
    const refused = recordFits(rec, 0, "업무를");
    if (refused) return refused;
    writeWork((list) => [rec, ...list]);
    setModal(null);
    showToast({ msg: "업무를 등록했어요" });
    return "";
  };
  const updateWork = (id, next) => {
    const cur = (state.work || []).find((w) => w.id === id);
    if (!cur) return "";
    // The sheet replaces title, note and link; id, date, done, source and createdAt are kept. A follow-up's item keeps
    // its link whatever the sheet sends: the link is owned by the follow-up (v26).
    const link = cur.source === "meeting" ? cur.link : next.link;
    const rec = { id: cur.id, date: cur.date, title: next.title, ...(next.note ? { note: next.note } : {}),
      ...(next.result ? { result: next.result } : {}), ...(link ? { link } : {}), ...(next.minutes ? { minutes: next.minutes } : {}),
      done: cur.done, source: cur.source, track: trackOf(next, cur.track), createdAt: cur.createdAt };
    const refused = recordFits(rec, JSON.stringify(cur).length, "업무를");
    if (refused) return refused;
    setState((prev) => {
      const s = structuredClone(prev);
      s.work = (s.work || []).map((w) => (w.id === id ? rec : w));
      syncTimeLog(s, rec);
      return s;
    });
    setModal(null);
    showToast({ msg: "업무를 수정했어요" });
    return "";
  };
  // The follow-up a work item mirrors, found in a cloned state, or null (v26: a `meeting` link with `followUpId`).
  const mirroredFollowUp = (s, w) => (w?.link?.kind === "meeting" && w.link.followUpId
    ? ((s.meetings || []).find((m) => m.id === w.link.id)?.followUps || []).find((f) => f.id === w.link.followUpId) || null
    : null);
  // The time log follows a work item (v28): every entry naming the item is removed and, when the item is done with
  // minutes, exactly one entry is written — the stored one kept when its date, track and minutes already match, so a
  // plain re-save does not churn ids. Runs inside a clone update; `w` is the item as it now stands.
  const syncTimeLog = (s, w) => {
    const log = s.timeLog || [];
    const had = log.find((e) => e.workId === w.id);
    const kept = log.filter((e) => e.workId !== w.id);
    if (w.done && w.minutes > 0) {
      const same = had && had.date === w.date && had.track === trackOf(w) && had.minutes === w.minutes;
      kept.push(same ? had : { id: uid(), date: w.date, track: trackOf(w), minutes: w.minutes, workId: w.id, createdAt: today });
    }
    if (had || kept.length !== log.length) s.timeLog = kept;
  };
  // Flips done. From the sheet, `next` carries what the sheet shows (title, note, result, link, minutes), written in the
  // same update so a result or minutes typed before completing are kept; answers an error string when storage refuses it.
  const toggleWork = (id, next) => {
    const cur = (state.work || []).find((w) => w.id === id);
    if (!cur) return "";
    const fields = next ? { title: next.title, note: next.note, result: next.result, minutes: next.minutes, track: trackOf(next, cur.track), ...(cur.source === "meeting" ? {} : { link: next.link }) } : {};
    if (next) {
      const refused = recordFits({ ...cur, ...fields }, JSON.stringify(cur).length, "업무를");
      if (refused) return refused;
    }
    setState((prev) => {
      const s = structuredClone(prev);
      const w = (s.work || []).find((x) => x.id === id);
      if (!w) return prev;
      for (const [key, value] of Object.entries(fields)) { if (value) w[key] = value; else delete w[key]; }
      w.done = !w.done;
      const fu = mirroredFollowUp(s, w);
      if (fu) fu.done = w.done;
      syncTimeLog(s, w);
      return s;
    });
    setModal(null);
    showToast({ msg: cur.done ? "완료를 취소했어요" : "완료로 표시했어요" });
    return "";
  };
  // Deletes the given work items; a follow-up one of them mirrored stays on its meeting, unlinked (`mine` and `done` kept).
  const dropWork = (drop) => setState((prev) => {
    const s = structuredClone(prev);
    for (const w of (s.work || []).filter((x) => drop.has(x.id))) {
      const fu = mirroredFollowUp(s, w);
      if (fu && fu.workId === w.id) delete fu.workId;
    }
    s.work = (s.work || []).filter((x) => !drop.has(x.id));
    // v28: the time-log entries of the deleted items go with them.
    if ((s.timeLog || []).some((e) => drop.has(e.workId))) s.timeLog = s.timeLog.filter((e) => !drop.has(e.workId));
    return s;
  });
  /* Time log and budget (v28) — records and a setting, never measures (rules 8, 9). `addTimeLog` / `removeTimeLog` write
     `timeLog` only; `setBizHours` writes `settings` only. */
  const addTimeLog = (next) => {
    const rec = { id: uid(), date: next.date, track: trackOf(next, "biz"), minutes: next.minutes, createdAt: today };
    const refused = recordFits(rec, 0, "시간 기록을");
    if (refused) return refused;
    setState((prev) => ({ ...prev, timeLog: [...(prev.timeLog || []), rec] }));
    showToast({ msg: `시간 ${rec.minutes}분을 기록했어요` });
    return "";
  };
  // Confirmed in the sheet.
  const removeTimeLog = (id) => {
    setState((prev) => ({ ...prev, timeLog: (prev.timeLog || []).filter((e) => e.id !== id) }));
    showToast({ msg: "시간 기록을 삭제했어요" });
  };
  const setBizHours = (n) => {
    setState((prev) => ({ ...prev, settings: { ...(prev.settings || {}), bizHoursPerWeek: n } }));
    setModal(null);
    showToast({ msg: `주간 사업 시간을 ${n}시간으로 저장했어요` });
  };
  const removeWork = (id) => {
    const cur = (state.work || []).find((w) => w.id === id);
    if (!cur) return;
    if (!window.confirm(`${cur.title} 업무를 삭제해요. 계속할까요?`)) return;
    dropWork(new Set([id]));
    setModal(null);
    showToast({ msg: "업무를 삭제했어요" });
  };
  // Deletes several work items after one confirmation; answers true when they were deleted, so the tab leaves select mode.
  const removeWorkMany = (ids) => {
    const drop = new Set(ids);
    const n = (state.work || []).filter((w) => drop.has(w.id)).length;
    if (!n || !window.confirm(`업무 ${n}건을 삭제해요. 계속할까요?`)) return false;
    dropWork(drop);
    showToast({ msg: `업무 ${n}건을 삭제했어요` });
    return true;
  };
  // Registers every ticked work proposal as today's item with `source: "ai"`. An
  // unresolved link is simply omitted. The raw reply is not stored anywhere — it would overwrite the day's journal reply.
  // v28: an item takes the track of the project or meeting its proposal resolved to, else `biz` — the packet carries only
  // `biz` / `personal` records, so a proposal cannot originate from the day job.
  const importTrackOf = (link) => {
    if (link?.kind === "project") return trackOf((state.meetingProjects || []).find((p) => p.id === link.id), "biz");
    if (link?.kind === "meeting") { const m = (state.meetings || []).find((x) => x.id === link.id); return m ? meetingTrack(state, m) : "biz"; }
    return "biz";
  };
  // v28: `date` dates every item (the review packet's reply: next Monday) and `track`, when given, replaces the link rule
  // (the review packet's reply: `biz`). A date other than today is appended to the toast.
  const importWork = (list, date = today, track = null) => {
    const made = list.map((p) => ({ id: uid(), date, title: p.title, ...(p.note ? { note: p.note } : {}),
      ...(p.link ? { link: p.link } : {}), done: false, source: "ai", track: track || importTrackOf(p.link), createdAt: today }));
    const refused = recordFits(made, 0, "업무를");
    if (refused) { showToast({ msg: refused }); return; }
    if (made.length) writeWork((items) => [...made, ...items]);
    setModal(null);
    showToast({ msg: `AI 제안 업무 ${made.length}건 등록${date !== today ? ` · ${date}` : ""}` });
  };

  /* Daily assistant */
  const markBriefingSeen = () => setState((prev) => (prev.act?.briefingSeen === today ? prev : { ...prev, act: { ...prev.act, briefingSeen: today } }));
  // Also the daily reader's close and route path: `{ type: "reader" }` and `{ type: "briefing" }` fall through to
  // `setModal({ type })`, so switching between the two screens stamps the day like closing either does.
  const closeBriefing = (next) => {
    markBriefingSeen();
    setModal(null);
    if (!next) return;
    if (next.type === "task") { const q = state.tasks.find((x) => x.id === next.id); if (q) tryComplete(q); return; }
    if (TAB_ACTIONS.includes(next.type)) { setTab(next.type); return; }
    setModal(next.type === "bridge" ? { type: "bridge", mode: next.mode } : { type: next.type });
  };
  // Stores the pasted reply on today's journal entry. Text only — it never changes a score (rule 7 amendment).
  const upsertReply = (s, raw) => {
    if (!raw) return;
    const e = (s.journal || []).find((x) => x.date === today);
    if (e) { e.ai = raw.slice(0, 4000); e.aiDate = today; }
    else s.journal = [{ id: uid(), date: today, text: "", ai: raw.slice(0, 4000), aiDate: today }, ...(s.journal || [])];
  };
  const importTasks = (list, raw) => {
    // The title decides the kind here too: `parseAssistantReply` already refuses a proposal that names no
    // activity, and a caller that skipped it must not be able to import one (rules 17, 19).
    const kept = list.map((p) => ({ ...p, kind: detectKind(p.title) })).filter((p) => p.kind);
    setState((prev) => {
      const s = structuredClone(prev);
      const made = kept.map((p) => {
        const goal = s.goals.find((g) => g.id === p.goalId);
        return {
          id: uid(), title: p.title, areaId: goal?.areaId || s.areas[0]?.id, goalId: p.goalId,
          diff: p.diff, pts: DIFFS[p.diff].pts, type: p.type, status: "todo", doneDates: [], createdAt: today,
          ...(p.due ? { due: p.due } : {}), kind: p.kind,
        };
      });
      s.tasks = [...made, ...s.tasks];
      upsertReply(s, raw);
      return s;
    });
    setModal(null);
    showToast({ msg: kept.length ? `AI 제안 ${kept.length}건 등록 · 일지에 답변 저장` : "AI 답변을 일지에 저장했어요 — 제안 실행 없음" });
  };
  const storeReply = (raw, msg) => {
    if (raw) setState((prev) => { const s = structuredClone(prev); upsertReply(s, raw); return s; });
    if (msg) showToast({ msg });
  };
  const saveReview = ({ wins, blocks }) => {
    setState((prev) => {
      const s = structuredClone(prev);
      const weekOf = mondayOf(today);
      const r = (s.reviews || []).find((x) => x.weekOf === weekOf);
      if (r) { r.wins = wins; r.blocks = blocks; r.date = today; }
      else s.reviews = [{ id: uid(), weekOf, wins, blocks, date: today }, ...(s.reviews || [])];
      s.act = { ...s.act, lastReview: today };
      return s;
    });
    setModal(null);
    showToast({ msg: "주간 리뷰를 저장했어요" });
  };
  const saveJournal = (text, silent) => {
    setState((prev) => {
      const s = structuredClone(prev);
      const e = (s.journal || []).find((x) => x.date === today);
      if (e) e.text = text;
      else s.journal = [{ id: uid(), date: today, text }, ...(s.journal || [])];
      return s;
    });
    if (!silent) { setModal(null); showToast({ msg: "일지를 저장했어요" }); }
  };

  /* A CV edit records facts and nothing else. The nine fields below are the whole write: `profile.edu` and
     `profile.career` — the snapshot inputs of the starting grade computed once at onboarding — and every
     `areas[].grade` are deliberately absent, so adding a degree here moves no area (rules 4, 11). The photo
     is not part of this: it is written under `liferpg-img-profile` by `askUpload` / `clearImg` (rule 16). */
  const saveProfile = (next) => {
    setState((prev) => {
      const s = structuredClone(prev);
      const { name, nick, birth, gender, status, email, phone, edus, careers } = next;
      s.profile = { ...s.profile, name, nick, birth, gender, status, email, phone, edus, careers };
      return s;
    });
    setModal(null);
    showToast({ msg: "프로필을 저장했어요" });
  };

  const setAreaDir = (areaId, dirs) => {
    setState((prev) => {
      const s = structuredClone(prev);
      const p = s.areas.find((x) => x.id === areaId);
      if (p) p.dir = dirs;
      return s;
    });
  };

  /* The one path every exported file takes: an in-memory blob URL on a temporary anchor, clicked under the user's
     tap, revoked a second later. The browser's download manager saves it; no request leaves the device (rule 7). */
  const downloadBlob = (blob, fileName) => {
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url; a.download = fileName;
    document.body.appendChild(a); a.click(); a.remove();
    setTimeout(() => URL.revokeObjectURL(url), 1000);
  };

  /* Backup — the save plus its evidence and portfolio photos in one file. The app has no cloud copy, so this is
     the only way back from a cleared browser. Import replaces everything and asks first. */
  const exportBackup = async () => {
    const images = {};
    for (const t of state?.tasks || []) {
      for (const k of [`liferpg-img-ev-${t.id}`, `liferpg-img-study-${t.id}-1`, `liferpg-img-study-${t.id}-2`]) {
        const v = await store.get(k).catch(() => null);
        if (v) images[k] = v;
      }
    }
    for (const f of state?.folio || []) {
      const v = await store.get(`liferpg-img-folio-${f.id}`).catch(() => null);
      if (v) images[`liferpg-img-folio-${f.id}`] = v;
    }
    const prof = await store.get("liferpg-img-profile").catch(() => null);
    if (prof) images["liferpg-img-profile"] = prof;
    downloadBlob(new Blob([JSON.stringify({ app: "life-manager", exportedAt: today, state, images }, null, 2)], { type: "application/json" }), `life-manager-backup-${today}.json`);
    showToast({ msg: `백업 파일을 내보냈어요 · 사진 ${Object.keys(images).length}장` });
  };
  /* Calendar export — the phone's calendar raises the alarms from this file once the user imports it. Built from the
     records at this instant and handed to the browser: no setState, no store call, no request (rules 7, 9, 18). */
  const exportCalendar = ({ days, remindAt }) => {
    const out = buildIcs(state, today, { days, remindAt, now: Date.now() });
    if (!out.entries.length) return;
    downloadBlob(new Blob([out.text], { type: "text/calendar;charset=utf-8" }), `life-manager-calendar-${today}.ics`);
    setModal(null);
    showToast({ msg: `캘린더 파일을 내보냈어요 · ${out.entries.length}건 · ${out.end}까지` });
  };
  const importBackup = async (file) => {
    let data;
    try { data = JSON.parse(await file.text()); } catch { showToast({ msg: "백업 파일을 읽지 못했어요" }); return; }
    const next = migrate(data?.state);
    if (!next || data?.app !== "life-manager") { showToast({ msg: "이 앱의 백업 파일이 아니에요" }); return; }
    const when = data.exportedAt || "날짜 미상";
    if (!window.confirm(`${when}에 내보낸 백업으로 되돌려요. 지금 이 기기의 기록은 모두 사라져요. 계속할까요?`)) return;
    for (const [k, v] of Object.entries(data.images || {})) store.set(k, v);
    setState(applyDailyTick(next));
    setImgs({ profile: data.images?.["liferpg-img-profile"] || null });
    setPhase("main"); setTab("home"); setModal(null);
    showToast({ msg: `백업을 불러왔어요 · ${when} 기록` });
  };
  const askImport = () => importRef.current?.click();

  const resetAll = async () => {
    // Clears the evidence photo keys (rule 16), the portfolio images and the profile photo along with the
    // state — left behind they keep piling up in storage under a save that no longer names them.
    for (const t of state?.tasks || []) {
      store.del(`liferpg-img-ev-${t.id}`);
      for (let n = 1; n <= 2; n++) store.del(`liferpg-img-study-${t.id}-${n}`);
    }
    for (const f of state?.folio || []) store.del(`liferpg-img-folio-${f.id}`);
    store.del("liferpg-img-profile");
    await store.del(KEY);
    setState(null); setImgs({}); setPhase("onboard"); setTab("home");
  };

  if (phase === "loading") return <Shell><div className="p-10 text-center text-zinc-600 text-sm">불러오는 중...</div></Shell>;
  if (phase === "onboard" || !state?.profile) {
    return (
      <Onboarding
        onStart={({ areas, profile, exams, certBest }) => {
          const s = freshState(areas);
          s.profile = profile;
          if (exams) s.exams = exams;
          if (certBest) s.certBest = certBest;
          setState(s); setPhase("main");
        }}
        onDemo={() => { setState(demoState()); setPhase("main"); }}
      />
    );
  }

  const NAV = [
    ["home", "프로필", IdCard],
    ["goals", "목표", Target],
    ["tasks", "할 일", ClipboardList],
    ["work", "업무", ListChecks],
    ["schedule", "일정", CalendarDays],
    ["meetings", "미팅", MessagesSquare],
    ["biz", "사업", Briefcase],
  ];

  return (
    <Shell>
      <input ref={fileRef} type="file" accept="image/*" className="hidden" onChange={onFile} />
      <input ref={importRef} type="file" accept="application/json,.json" className="hidden"
        onChange={(e) => { const f = e.target.files?.[0]; e.target.value = ""; if (f) importBackup(f); }} />
      <header className="px-5 pt-5 pb-3 flex items-center justify-between">
        <div>
          <div className="text-xs tracking-widest text-cyan-400 font-mono font-bold">LIFE MANAGER</div>
          <div className="font-black">{displayName(state.profile)}<span className="text-zinc-600 text-xs font-normal"> · {state.profile.status}</span></div>
        </div>
        <div className="flex items-center gap-2 bg-zinc-900 border border-zinc-800 rounded-xl px-3 py-2 text-xs font-mono font-bold">
          <span className="text-amber-300">🔥 {state.act.streak}일</span>
          <span className="w-px h-3 bg-zinc-700" />
          <span className="text-zinc-300">🛡 {state.act.shieldsLeft}</span>
        </div>
      </header>

      <main className="px-4 pb-24 space-y-4">
        {tab === "home" && (
          <HomeTab state={state} today={today} imgs={imgs} onProfile={() => setModal({ type: "profile" })}
            onSettings={() => setModal({ type: "settings" })}
            onPromote={(area) => setModal({ type: "promote", area })}
            onRoleAdvice={() => setModal({ type: "roleAdvice" })}
            onWall={() => setModal({ type: "wall" })}
            onReader={() => setModal({ type: "reader" })} />
        )}
        {tab === "goals" && (
          <GoalsTab state={state}
            onAddGoal={() => setModal({ type: "addGoal" })}
            onCheckin={checkinKR}
            onGoalStatus={goalStatus} onRemoveGoal={removeGoal}
            onAddQuestFor={(gid) => setModal({ type: "addQuest", goalId: gid })} />
        )}
        {tab === "tasks" && (
          <TaskTab state={state} today={today}
            onOpenTask={(taskId) => setModal({ type: "taskDetail", taskId })}
            onOpenEvent={(eventId, date) => setModal({ type: "eventDetail", eventId, date })}
            onOpenBiz={(row) => setModal({ type: "bizDetail", row })}
            onCatalog={() => setModal({ type: "catalog" })}
            onGoGoals={() => setTab("goals")}
            onGoBiz={() => { setBizView("deals"); setTab("biz"); }}
            onBriefing={() => setModal({ type: "briefing" })} />
        )}
        {tab === "work" && (
          <WorkTab state={state} today={today}
            onAdd={(date) => setModal({ type: "work", date })}
            onOpen={(workId) => setModal({ type: "work", workId })}
            onBridge={() => setModal({ type: "workBridge" })} onTimeLog={() => setModal({ type: "timeLog" })} onRemoveMany={removeWorkMany}
            onOpenMeeting={(meetingId) => setModal({ type: "meetingView", meetingId })}
            onOpenDocument={(docId) => setModal({ type: "document", docId })}
            onAddCheck={addCheck} onToggleCheck={toggleCheck} onRemoveCheck={removeCheck}
            onAskAi={(eventId, date) => setModal({ type: "prepBridge", eventId, date })} />
        )}
        {tab === "schedule" && (
          <ScheduleTab state={state} today={today}
            onAdd={(date) => setModal({ type: "event", date })}
            onEdit={(ev) => setModal({ type: "event", event: ev })}
            onToggleDone={toggleEventDone} onSkip={skipOccurrence}
            onExport={() => setModal({ type: "calExport" })} />
        )}
        {tab === "meetings" && (
          <MeetingsTab state={state}
            onAddProject={() => setModal({ type: "project" })}
            onEditProject={(projectId) => setModal({ type: "project", projectId })}
            onAddMeeting={(projectId) => setModal({ type: "meeting", projectId })}
            onOpenMeeting={(meetingId) => setModal({ type: "meetingView", meetingId })}
            onAddDocument={(projectId) => setModal({ type: "document", projectId })}
            onOpenDocument={(docId) => setModal({ type: "document", docId })} />
        )}
        {tab === "biz" && (
          <BizTab state={state} today={today}
            view={state.ui?.bizView} onView={setBizView}
            onAdd={(list) => setModal({ type: BIZ_ADD_MODAL[list] })}
            onEdit={(list, item) => setModal({ type: list, item })}
            onTogglePaid={toggleDealPaid} onTogglePayment={toggleDealPayment}
            onOpenMilestone={(id) => setModal({ type: "milestone", milestoneId: id })}
            onSeedRoadmap={seedRoadmap}
            onOpenLead={(id) => setModal({ type: "lead", leadId: id })}
            onOpenNotice={(id) => setModal({ type: "notice", noticeId: id })} />
        )}
      </main>

      <nav className="fixed bottom-2 inset-x-3 max-w-md mx-auto grid grid-cols-7 bg-zinc-900 border border-zinc-800 rounded-2xl px-1 py-2">
        {NAV.map(([k, label, Icon]) => (
          <button key={k} onClick={() => setTab(k)}
            className={`py-1.5 flex flex-col items-center gap-1 text-xs ${tab === k ? "text-cyan-300 font-bold" : "text-zinc-500 font-medium"}`}>
            <Icon size={18} /> <span className="whitespace-nowrap leading-4">{label}</span>
          </button>
        ))}
      </nav>

      {modal?.type === "addQuest" && (
        <AddTaskModal areas={state.areas} exams={state.exams} certBest={state.certBest} tasks={state.tasks}
          goalId={modal.goalId} goal={state.goals.find((g) => g.id === modal.goalId)}
          onClose={() => setModal(null)} onAdd={addQuest} />
      )}
      {modal?.type === "addGoal" && (
        <AddGoalModal areas={state.areas} onClose={() => setModal(null)} onAdd={addGoal} />
      )}
      {modal?.type === "evidence" && (
        <EvidenceModal task={modal.task} onClose={() => setModal(null)}
          onSubmit={(ev, score) => completeTask(modal.task.id, ev, score)} />
      )}
      {modal?.type === "promote" && (
        <PromoteModal area={modal.area} onClose={() => setModal(null)}
          onSubmit={(ev) => promoteArea(modal.area.id, ev)} />
      )}
      {modal?.type === "role" && (
        <RoleModelModal state={state} onClose={() => setModal(null)} onSave={saveRole} />
      )}
      {modal?.type === "activity" && (
        <ActivityLogModal task={modal.task} onClose={() => setModal(null)}
          onDone={(ev, measures) => { completeTask(modal.task.id, ev); applyMeasures(measures); }} />
      )}
      {modal?.type === "study" && (
        <StudyVerifyModal task={modal.task} onClose={() => setModal(null)}
          onDone={(ev) => completeTask(modal.task.id, ev)} />
      )}
      {/* The to-do sheets. The task sheet's completion button reaches `tryComplete` and nothing else. */}
      {modal?.type === "taskDetail" && (
        <TaskDetailModal state={state} taskId={modal.taskId} today={today} onClose={() => setModal(null)}
          onComplete={tryComplete}
          onRemove={(id) => { removeTask(id); setModal(null); }}
          onViewEvidence={(q) => setModal({ type: "evidenceView", task: q })}
          onOpenMeeting={(meetingId) => setModal({ type: "meetingView", meetingId })} />
      )}
      {modal?.type === "eventDetail" && (
        <EventDetailModal state={state} eventId={modal.eventId} date={modal.date} today={today} onClose={() => setModal(null)}
          onToggleDone={toggleEventDone}
          onSkip={(id, d) => { skipOccurrence(id, d); setModal(null); }}
          onEdit={(ev) => setModal({ type: "event", event: ev })}
          onAddCheck={addCheck} onToggleCheck={toggleCheck} onRemoveCheck={removeCheck} />
      )}
      {modal?.type === "bizDetail" && (
        <BizTodoModal row={modal.row} onClose={() => setModal(null)}
          onOpen={() => { setModal(null); setBizView("deals"); setTab("biz"); }} />
      )}
      {modal?.type === "evidenceView" && (
        <EvidenceViewModal task={modal.task} onClose={() => setModal(null)} />
      )}
      {modal?.type === "catalog" && (
        <CatalogModal state={state} initialCat={modal.cat} onClose={() => setModal(null)} />
      )}
      {modal?.type === "roleAdvice" && (
        <RoleAdviceModal state={state} today={today} onClose={() => setModal(null)}
          onOpenCatalog={(cat) => setModal({ type: "catalog", cat })} onSetDir={setAreaDir}
          onOpenRoadmap={() => { setModal(null); setBizView("roadmap"); setTab("biz"); }}
          onAskVerdict={() => setModal({ type: "roleVerdict" })} />
      )}
      {modal?.type === "roleVerdict" && (
        <RoleVerdictModal state={state} today={today} onClose={() => setModal(null)} onImport={importRoleVerdict} onToast={(msg) => showToast({ msg })} />
      )}
      {modal?.type === "event" && (
        <EventModal event={modal.event} initialDate={modal.date} projects={state.meetingProjects || []} onClose={() => setModal(null)}
          onAdd={addEvent} onUpdate={updateEvent} onRemove={removeEvent} />
      )}
      {modal?.type === "deals" && (
        <DealModal deal={modal.item} prefill={modal.prefill} onClose={() => setModal(null)}
          onAdd={(d) => addBiz("deals", d, null, modal.leadId)} onUpdate={(id, next) => updateBiz("deals", id, next)}
          onRemove={(id) => removeBiz("deals", id)} />
      )}
      {modal?.type === "rates" && (
        <RateModal rate={modal.item} onClose={() => setModal(null)}
          onAdd={(r) => addBiz("rates", r)} onUpdate={(id, next) => updateBiz("rates", id, next)}
          onRemove={(id) => removeBiz("rates", id)} />
      )}
      {modal?.type === "folio" && (
        <FolioModal folio={modal.item} onClose={() => setModal(null)}
          onAdd={(f, warn) => addBiz("folio", f, warn)} onUpdate={(id, next, warn) => updateBiz("folio", id, next, warn)}
          onRemove={(id) => removeBiz("folio", id)} />
      )}
      {modal?.type === "milestone" && (
        <MilestoneModal state={state} today={today} milestone={(state.milestones || []).find((m) => m.id === modal.milestoneId)}
          onClose={() => setModal(null)} onAdd={addMilestone} onUpdate={updateMilestone} onRemove={removeMilestone} />
      )}
      {modal?.type === "lead" && (
        <LeadModal state={state} lead={(state.leads || []).find((l) => l.id === modal.leadId)}
          onClose={() => setModal(null)} onAdd={addLead} onUpdate={updateLead} onRemove={removeLead} onMakeDeal={makeDealFromLead} />
      )}
      {modal?.type === "notice" && (
        <NoticeModal state={state} notice={(state.notices || []).find((n) => n.id === modal.noticeId)}
          onClose={() => setModal(null)} onAdd={addNotice} onUpdate={updateNotice} onRemove={removeNotice} />
      )}
      {/* Meeting records — no payout, no goal, no streak (rules 1, 18) */}
      {modal?.type === "project" && (
        <ProjectModal project={(state.meetingProjects || []).find((p) => p.id === modal.projectId)}
          meetingCount={(state.meetings || []).filter((m) => m.projectId === modal.projectId).length}
          documentCount={(state.documents || []).filter((d) => d.projectId === modal.projectId).length}
          onClose={() => setModal(null)} onAdd={addProject} onUpdate={updateProject} onRemove={removeProject} />
      )}
      {modal?.type === "meeting" && (
        <MeetingModal state={state} today={today} projectId={modal.projectId}
          meeting={(state.meetings || []).find((m) => m.id === modal.meetingId)}
          onClose={() => setModal(null)} onAdd={addMeeting} onUpdate={updateMeeting} onRemove={removeMeeting} />
      )}
      {modal?.type === "meetingView" && (
        <MeetingViewModal state={state} meetingId={modal.meetingId} today={today} onClose={() => setModal(null)}
          onEdit={(meetingId) => setModal({ type: "meeting", meetingId })}
          onOpenTask={(taskId) => setModal({ type: "taskDetail", taskId })}
          onAddProgress={addProgress} onRemoveProgress={removeProgress}
          onToggleFollowUp={toggleFollowUp} onSetFollowUpMine={setFollowUpMine} onAppendFollowUps={appendFollowUps}
          onClearTranscript={clearTranscript} />
      )}
      {modal?.type === "document" && (
        <DocumentModal state={state} projectId={modal.projectId} doc={(state.documents || []).find((d) => d.id === modal.docId)}
          onClose={() => setModal(null)} onAdd={addDocument} onUpdate={updateDocument} onRemove={removeDocument} />
      )}
      {/* Work items — records outside the goal ladder: no payout, no goal, no streak (rules 1, 9, 18) */}
      {modal?.type === "work" && (
        <WorkModal state={state} today={today} date={modal.date} work={(state.work || []).find((w) => w.id === modal.workId)}
          onClose={() => setModal(null)} onAdd={addWork} onUpdate={updateWork} onToggle={toggleWork} onRemove={removeWork}
          onOpenMeeting={(meetingId) => setModal({ type: "meetingView", meetingId })} />
      )}
      {modal?.type === "workBridge" && (
        <WorkBridgeModal state={state} today={today} build={buildWorkPacket} title="오늘 업무 만들기"
          caption="아래 글을 복사해 Claude·ChatGPT 채팅에 붙여넣고, 답변을 받아 다시 붙여넣어요. 앱은 네트워크를 쓰지 않아요. 회의록 요약과 진행사항이 실려요 — 녹취록은 실리지 않아요. 보내지 않을 회의록은 회의록 수정에서 'AI에 보내지 않기'를 켜요. 직장 트랙 기록은 실리지 않아요."
          importDate={today} importTrack={null} onClose={() => setModal(null)} onImport={importWork} onToast={(msg) => showToast({ msg })} />
      )}
      {modal?.type === "reviewBridge" && (
        <WorkBridgeModal state={state} today={today} build={buildReviewPacket} title="주간 회고 — AI에게 묻기"
          caption="아래 글을 복사해 Claude·ChatGPT 채팅에 붙여넣고, 답변을 받아 다시 붙여넣어요. 앱은 네트워크를 쓰지 않아요. 사업 트랙의 이번 주 업무·후속·로드맵·파이프라인·공고·입금 예정과 저장된 리뷰가 실려요 — 직장·개인 트랙, 녹취록, 이름·연락처는 실리지 않아요. 답변의 제안은 다음 주 월요일 업무로 등록돼요."
          importDate={shiftDay(mondayOf(today), 7)} importTrack="biz" onClose={() => setModal(null)} onImport={importWork} onToast={(msg) => showToast({ msg })} />
      )}
      {modal?.type === "timeLog" && (
        <TimeLogModal state={state} today={today} onClose={() => setModal(null)} onAdd={addTimeLog} onRemove={removeTimeLog} />
      )}
      {modal?.type === "prepBridge" && (
        <PrepBridgeModal state={state} today={today} eventId={modal.eventId} date={modal.date} onClose={() => setModal(null)}
          onImport={importChecks} onToast={(msg) => showToast({ msg })} />
      )}
      {modal?.type === "briefing" && (
        <BriefingModal state={state} today={today} onClose={() => closeBriefing()} onAction={closeBriefing} />
      )}
      {modal?.type === "reader" && (
        <DailyReaderModal state={state} today={today} onClose={() => closeBriefing()} onAction={closeBriefing} />
      )}
      {modal?.type === "journal" && (
        <JournalModal state={state} today={today} onClose={() => setModal(null)} onSave={saveJournal} />
      )}
      {modal?.type === "bridge" && (
        <BridgeModal state={state} today={today} initialMode={modal.mode} onClose={() => setModal(null)}
          onImport={importTasks} onStoreReply={storeReply} />
      )}
      {modal?.type === "review" && (
        <ReviewModal state={state} today={today} onClose={() => setModal(null)} onSave={saveReview} onReviewBridge={() => setModal({ type: "reviewBridge" })} />
      )}
      {modal?.type === "profile" && (
        <ProfileModal profile={state.profile} state={state} img={imgs?.profile} today={today}
          onUpload={() => askUpload("profile")} onClearImg={() => clearImg("profile")}
          onSave={saveProfile} onClose={() => setModal(null)} />
      )}
      {modal?.type === "calExport" && (
        <CalendarExportModal state={state} today={today} onClose={() => setModal(null)} onExport={exportCalendar} />
      )}
      {/* `resetAll` never clears `modal`, so the sheet is closed first — otherwise it would reappear over the app
          after the next onboarding or demo entry. The reset itself still asks nothing (TD-26). */}
      {modal?.type === "settings" && (
        <SettingsModal state={state} onClose={() => setModal(null)}
          onRoleModel={() => setModal({ type: "role" })} onSetBizHours={setBizHours}
          onExport={exportBackup} onImport={askImport}
          onReset={() => { setModal(null); resetAll(); }} />
      )}
      {modal?.type === "wall" && (
        <AchievementWallModal state={state} onClose={() => setModal(null)} />
      )}

      {overlay && <Overlay data={overlay} onClose={() => setOverlay(null)} />}
      <ToastHost ref={toastRef} />
    </Shell>
  );
}
